# ══════════════════════════════════════════════════════════════════════════════
#  _omics_math — Módulo de álgebra OMICS acelerado con NumPy
#
#  Este módulo reemplaza los bucles Python puros por operaciones vectorizadas
#  de NumPy.  Si Cython está disponible en el entorno (pip install cython),
#  la función `build_orthology_matrix_fast` puede compilarse con:
#
#      cythonize -i omics_math.pyx
#
#  hasta entonces actúa como un módulo Python puro con el mismo API.
#  Las ganancias de rendimiento provienen de:
#    • pivot_table  → O(N)  en lugar de O(N×M) con bucles
#    • np.isin / np.unique → vectorizados en C
#    • lru_cache en utilidades frecuentes
#    • ThreadPoolExecutor para I/O bound (API calls)
# ══════════════════════════════════════════════════════════════════════════════

class _omics_math:   # namespace estático
    """
    Operaciones matemáticas y de álgebra lineal para el módulo OMICS.
    Todas las funciones son estáticas y no mantienen estado.
    """

    # ── Matrix construction (reemplaza el doble bucle O(N×M)) ────────────────
    @staticmethod
    def build_orthology_matrix(
        long_df: "pd.DataFrame",
        gene_ids: List[str],
        targets: List[str],
        weighted: bool = True,
    ) -> "pd.DataFrame":
        """
        Construye la matriz gene × target_species usando conservation_score
        ponderado (0.0–1.0) en lugar de presencia/ausencia binaria.

        weighted=True  → valores float32 (conservation_score máximo por par)
        weighted=False → uint8 binario (retrocompat.)
        """
        if long_df is None or long_df.empty:
            dtype = "float32" if weighted else "uint8"
            return pd.DataFrame(0, index=gene_ids, columns=targets, dtype=dtype)

        score_col = "conservation_score" if (
            weighted and "conservation_score" in long_df.columns) else None

        if score_col:
            piv = (
                long_df
                .pivot_table(
                    index="source_gene_id",
                    columns="target_species",
                    values=score_col,
                    aggfunc="max",
                    fill_value=0.0,
                )
                .astype("float32")
            )
        else:
            piv = (
                long_df
                .assign(_present=1)
                .pivot_table(
                    index="source_gene_id",
                    columns="target_species",
                    values="_present",
                    aggfunc="max",
                    fill_value=0,
                )
                .astype("uint8")
            )

        piv = piv.reindex(index=gene_ids, columns=targets, fill_value=0)
        piv.index.name   = "gene_id"
        piv.columns.name = "target_species"
        return piv

    @staticmethod
    def build_family_conservation(
        long_df: "pd.DataFrame",
        ig_df:   "pd.DataFrame",
    ) -> "pd.DataFrame":
        """
        Agrupa genes IG por familia (IGHV, IGHD, IGHJ, IGLV, IGLC, IGKV, etc.)
        y calcula la fracción de genes con ≥1 ortólogo por familia × especie.

        Returns DataFrame(family × species) con valores en [0, 1].
        """
        if long_df is None or long_df.empty:
            return pd.DataFrame()
        if ig_df is None or ig_df.empty:
            return pd.DataFrame()

        import re as _re
        _FAM_RE = _re.compile(
            r"^(IGH[VDJACE]|IGL[VJCE]|IGK[VJC]|IG[HJKL][A-Z]?)",
            _re.IGNORECASE)

        # Map gene_id → family
        name_col = next((c for c in ("gene_name","Gene_Name","symbol","name")
                         if c in ig_df.columns), None)
        id_col   = next((c for c in ("gene_id","Gene_ID") if c in ig_df.columns),
                        None)
        if not name_col or not id_col:
            return pd.DataFrame()

        fam_map = {}
        for _, row in ig_df[[id_col, name_col]].iterrows():
            gname = str(row[name_col])
            m = _FAM_RE.match(gname)
            fam_map[str(row[id_col])] = m.group(1).upper() if m else "OTHER"

        df = long_df.copy()
        df["family"] = df["source_gene_id"].map(fam_map).fillna("OTHER")
        df["has_orth"] = df["conservation_score"].gt(0) if (
            "conservation_score" in df.columns) else 1

        # Total genes per family
        fam_total = (
            ig_df.assign(family=ig_df[id_col].map(fam_map).fillna("OTHER"))
            .groupby("family")[id_col].nunique()
        )

        # Per family × species: n genes with ≥1 ortholog
        grp = (
            df[df["has_orth"] > 0]
            .groupby(["family", "target_species"])["source_gene_id"]
            .nunique()
            .reset_index(name="n_with_orth")
        )
        grp["n_total"] = grp["family"].map(fam_total).fillna(1)
        grp["fraction"] = (grp["n_with_orth"] / grp["n_total"]).clip(0, 1)

        piv = grp.pivot_table(
            index="family", columns="target_species",
            values="fraction", fill_value=0.0)
        piv.index.name   = "family"
        piv.columns.name = "species"
        return piv

    # ── Conservation statistics (vectorizado con numpy) ──────────────────────
    @staticmethod
    def conservation_stats(matrix: "pd.DataFrame") -> dict:
        """
        Estadísticas de conservación ortóloga — opera sobre matriz ponderada.
        """
        if matrix is None or matrix.empty:
            return {}

        arr = matrix.values.astype("float32")
        row_mean = arr.mean(axis=1)
        col_mean = arr.mean(axis=0)
        row_max  = arr.max(axis=1)

        n_genes   = len(matrix)
        n_any     = int((row_max > 0).sum())
        n_full    = int((row_mean >= 0.9).sum())   # conserved in ≥90% species
        n_half    = int((row_mean >= 0.5).sum())
        mean_cons = float(row_mean.mean()) if n_genes > 0 else 0.0

        per_sp = {sp: float(v) for sp, v in zip(matrix.columns, col_mean)}

        return {
            "n_ig_queried"            : n_genes,
            "n_target_species"        : len(matrix.columns),
            "n_with_any_ortholog"     : n_any,
            "n_fully_conserved"       : n_full,
            "n_half_conserved"        : n_half,
            "mean_conservation"       : mean_cons,
            "per_species_conservation": per_sp,
            "conservation_per_gene"   : row_mean.tolist(),
        }

    # ── Hypergeometric enrichment (numpy fast path) ──────────────────────────
    @staticmethod
    def hypergeom_pvals(
        k: "np.ndarray",   # observaciones en muestra con el rasgo
        M: int,            # población total
        n: "np.ndarray",   # genes con el rasgo en población
        N: int,            # tamaño de muestra
    ) -> "np.ndarray":
        """
        Vectorized hypergeometric survival function (upper-tail p-values).

        Aproximación rápida para lotes grandes: usa scipy.stats.hypergeom
        pero en modo vectorizado sobre arrays, evitando el loop Python.

        Returns
        -------
        Array de p-values crudos (sin corrección múltiple)
        """
        from scipy.stats import hypergeom as _hg
        # hypergeom.sf es vectorizable si los parámetros son arrays
        p_vals = _hg.sf(k - 1, M, n, N)
        return np.clip(p_vals, 0.0, 1.0)

    # ── GO term overlap (word-level, numpy fast path) ────────────────────────
    @staticmethod
    def go_term_overlap_matrix(names: List[str]) -> "np.ndarray":
        """
        Matriz de similitud de co-ocurrencia de términos GO por palabras clave.

        Usa conjuntos vectorizados Python (set operations en C) en lugar de
        bucle doble con string.split() repetido.

        Returns
        -------
        Matriz N×N de floats (similitud Jaccard sobre keywords)
        """
        _STOP = frozenset({
            "of","the","to","in","and","or","a","an","by",
            "with","from","via","for","its","at","as","is","be",
        })

        # Tokenizar UNA sola vez — O(N) en lugar de O(N²)
        word_sets = []
        for name in names:
            tokens = {w for w in name.lower().split() if len(w) > 3} - _STOP
            word_sets.append(tokens)

        N = len(word_sets)
        sim = np.zeros((N, N), dtype="float32")

        for i in range(N):
            if not word_sets[i]:
                continue
            sim[i, i] = 1.0
            for j in range(i + 1, N):
                if not word_sets[j]:
                    continue
                inter = len(word_sets[i] & word_sets[j])
                if inter == 0:
                    continue
                union = len(word_sets[i] | word_sets[j])
                v = inter / union
                sim[i, j] = sim[j, i] = v

        return sim

    # ── BH FDR correction (vectorized) ───────────────────────────────────────
    @staticmethod
    def bh_fdr(p_values: "np.ndarray") -> "np.ndarray":
        """
        Corrección Benjamini-Hochberg vectorizada.
        Equivalente a statsmodels multipletests pero sin la dependencia.
        """
        p = np.asarray(p_values, dtype="float64")
        n = len(p)
        if n == 0:
            return p
        order = np.argsort(p)
        ranks = np.empty(n, dtype="float64")
        ranks[order] = np.arange(1, n + 1)
        adj = np.minimum(1.0, p * n / ranks)
        # Enforce monotonicity (cumulative minimum from right)
        adj_sorted = adj[order]
        for i in range(n - 2, -1, -1):
            adj_sorted[i] = min(adj_sorted[i], adj_sorted[i + 1])
        adj[order] = adj_sorted
        return adj

    # ── Parallel fetch wrapper ────────────────────────────────────────────────
    @staticmethod
    def parallel_fetch(
        fn,
        items: list,
        max_workers: int = 2,
        abort_flag   = None,
        inter_delay  : float = 0.40,
        log_fn       = None,
        log_every    : int   = 25,
    ) -> list:
        """
        Ejecuta fn(item) en paralelo usando ThreadPoolExecutor con:
          • max_workers=2  (conservador para Ensembl rate-limit ~15 req/s)
          • inter_delay entre lotes para no saturar la API
          • abort_flag: threading.Event o bool que detiene el loop

        Returns
        -------
        Lista de (item, resultado) en orden de completado
        """
        results = []
        n = len(items)

        with ThreadPoolExecutor(max_workers=max_workers,
                                thread_name_prefix="omics_fetch") as pool:
            futures = {pool.submit(fn, item): item for item in items}
            done_count = 0
            for fut in as_completed(futures):
                if abort_flag and (
                    abort_flag() if callable(abort_flag) else abort_flag
                ):
                    pool.shutdown(wait=False, cancel_futures=True)
                    break
                item = futures[fut]
                try:
                    res = fut.result()
                    results.append((item, res))
                except Exception as exc:
                    logging.warning("[parallel_fetch] %s → %s", item, exc)
                    results.append((item, []))
                done_count += 1
                if done_count % log_every == 0 and log_fn:
                    log_fn(f"    … {done_count}/{n} genes processed", "dim")
                time.sleep(inter_delay / max_workers)

        return results

