#  NTv3 ENGINE  —  Nucleotide Transformer v3  (cerebro local compartido)
#
#  Carga el modelo desde disco de manera lazy (la primera vez que se necesita).
#  Si el modelo no está disponible, todas las funciones retornan None y el
#  pipeline continúa sin interrupción — el módulo NTv3 queda simplemente
#  desactivado (degradación elegante).
#
#  Variables de entorno relevantes:
#    NTV3_MODEL_PATH  — ruta al directorio local del modelo (default: ./nt-v3)
#    NTV3_DEVICE      — 'cuda' | 'mps' | 'cpu'  (auto-detectado si no se fija)
#
#  Uso desde PipelineRunner:
#    embs = ntv3_encode(sequences)          → tensor [N, hidden] o None
#    pred = ntv3_predict_class(sequences)   → lista de dicts o None
# ══════════════════════════════════════════════════════════════════════════════

# ── Estado global del motor NTv3 ──────────────────────────────────────────────
_NTV3_MODEL     = None   # transformers PreTrainedModel
_NTV3_TOKENIZER = None   # transformers PreTrainedTokenizer
_NTV3_DEVICE    = None   # torch.device activo
_NTV3_READY     = False  # True cuando el modelo está cargado y verificado
_NTV3_ERROR     = None   # Último mensaje de error (str) o None
_NTV3_LOCK      = threading.Lock()

# Ruta por defecto: carpeta "nt-v3" junto al script, o variable de entorno.
# En Jupyter/IPython __file__ no existe → se usa el directorio de trabajo actual.
def _ntv3_script_dir() -> str:
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except NameError:
        return os.getcwd()


def _ntv3_get_drives() -> List[str]:
    """
    Devuelve la lista de raíces de disco disponibles en el sistema.
    Compatible con Windows, Linux y macOS.
    """
    roots: List[str] = []
    if sys.platform.startswith("win"):
        import string
        for letter in string.ascii_uppercase:
            drive = f"{letter}:\\"
            if os.path.exists(drive):
                roots.append(drive)
    else:
        # Linux / macOS: raíz del sistema + puntos de montaje habituales
        roots.append("/")
        mount_dirs = ["/mnt", "/media", "/Volumes", "/run/media"]
        for mdir in mount_dirs:
            if os.path.isdir(mdir):
                try:
                    for sub in os.listdir(mdir):
                        full = os.path.join(mdir, sub)
                        if os.path.isdir(full):
                            roots.append(full)
                except PermissionError:
                    pass
    return roots


def _ntv3_is_valid_model_dir(path: str) -> bool:
    """
    Comprueba si un directorio contiene los archivos mínimos de un modelo
    HuggingFace (config.json + algún archivo de pesos o tokenizador).
    """
    if not os.path.isdir(path):
        return False
    has_config = os.path.isfile(os.path.join(path, "config.json"))
    if not has_config:
        return False
    weight_files = (
        "pytorch_model.bin", "model.safetensors",
        "tf_model.h5", "flax_model.msgpack",
        "tokenizer_config.json", "tokenizer.json",
        "spiece.model", "vocab.txt",
    )
    return any(os.path.isfile(os.path.join(path, f)) for f in weight_files)


# Nombres de carpeta que puede tener el modelo (en orden de preferencia)
_NTV3_FOLDER_NAMES = ["nt-v3", "nt_v3", "NTv3", "NT-v3",
                       "nucleotide-transformer-v3", "nucleotide_transformer_v3"]

# Directorios "ancla" donde buscar primero (rápido)
_NTV3_ANCHOR_DIRS = [
    _ntv3_script_dir(),
    os.getcwd(),
    os.path.expanduser("~"),
    os.path.expanduser("~/models"),
    os.path.expanduser("~/huggingface"),
    os.path.expanduser("~/.cache/huggingface/hub"),
]


def _ntv3_search_model() -> Optional[str]:
    """
    Busca automáticamente el directorio del modelo NTv3 en todos los discos
    disponibles del sistema.

    Estrategia de búsqueda (de más rápida a más exhaustiva):
      1. Variable de entorno NTV3_MODEL_PATH.
      2. Carpetas ancla conocidas (script, cwd, home, ~/.cache/huggingface/hub).
      3. Exploración recursiva de cada disco detectado (hasta 8 niveles de
         profundidad), omitiendo rutas de sistema para no tardar demasiado.

    Returns
    -------
    str | None  — Ruta al directorio del modelo, o None si no se encontró.
    """
    # 1 — Variable de entorno (prioridad máxima)
    env_path = os.environ.get("NTV3_MODEL_PATH", "")
    if env_path and _ntv3_is_valid_model_dir(env_path):
        print(f"[NTv3] Model found via NTV3_MODEL_PATH: '{env_path}'")
        return env_path

    # 2 — Carpetas ancla: busca los nombres conocidos directamente
    for anchor in _NTV3_ANCHOR_DIRS:
        for name in _NTV3_FOLDER_NAMES:
            candidate = os.path.join(anchor, name)
            if _ntv3_is_valid_model_dir(candidate):
                print(f"[NTv3] Model found (anchor): '{candidate}'")
                return candidate
        # También acepta que el ancla misma sea el directorio del modelo
        if _ntv3_is_valid_model_dir(anchor):
            # Solo si la carpeta se llama como el modelo
            base = os.path.basename(anchor).lower().replace("-", "_")
            if any(n.lower().replace("-", "_") in base for n in _NTV3_FOLDER_NAMES):
                print(f"[NTv3] Model found (direct anchor): '{anchor}'")
                return anchor

    # 3 — Búsqueda exhaustiva en todos los discos
    _SKIP_DIRS = {
        # Windows
        "windows", "winnt", "system32", "syswow64", "program files",
        "program files (x86)", "$recycle.bin", "recovery",
        # Linux / macOS
        "proc", "sys", "dev", "run", "snap", "boot",
        "lost+found", "var", "tmp", "etc",
    }
    MAX_DEPTH = 8

    def _walk(root: str, depth: int) -> Optional[str]:
        if depth > MAX_DEPTH:
            return None
        try:
            entries = os.scandir(root)
        except (PermissionError, OSError):
            return None
        dirs = []
        for entry in entries:
            if not entry.is_dir(follow_symlinks=False):
                continue
            name_lower = entry.name.lower()
            if name_lower in _SKIP_DIRS or name_lower.startswith("."):
                continue
            # Coincidencia exacta con nombre de modelo
            if entry.name in _NTV3_FOLDER_NAMES and _ntv3_is_valid_model_dir(entry.path):
                return entry.path
            dirs.append(entry.path)
        for d in dirs:
            result = _walk(d, depth + 1)
            if result:
                return result
        return None

    drives = _ntv3_get_drives()
    print(f"[NTv3] Searching for model in {len(drives)} drive(s): {drives}")
    for drive in drives:
        found = _walk(drive, 0)
        if found:
            print(f"[NTv3] Model found (exhaustive search): '{found}'")
            return found

    return None


_NTV3_DEFAULT_PATH = os.environ.get(
    "NTV3_MODEL_PATH",
    os.path.join(_ntv3_script_dir(), "nt-v3")
)

# Longitud máxima de secuencia que acepta el tokenizador sin truncar
_NTV3_MAX_LEN = 1000   # NTv3 usa ventanas de 1 kbp por defecto


def _ntv3_detect_device() -> str:
    """Elige el dispositivo más potente disponible.

    IMPORTANTE (macOS): MPS (Metal GPU) + PyTorch + el event loop de Tkinter
    es una combinación que produce 'segmentation fault' intermitentes — MPS no
    es thread-safe con el loop de Cocoa que usa la GUI. Por eso en macOS
    forzamos CPU por defecto, salvo que el usuario pida MPS explícitamente con
    la variable de entorno NTV3_FORCE_MPS=1 (bajo su propio riesgo).

    En Linux/Windows con CUDA no hay este conflicto y se usa la GPU.
    """
    import os as _os
    try:
        import torch
        if torch.cuda.is_available():
            return "cuda"
        # macOS: evitar MPS por el segfault con Tkinter (ver docstring).
        if sys.platform == "darwin":
            if _os.environ.get("NTV3_FORCE_MPS") == "1":
                if (getattr(torch.backends, "mps", None)
                        and torch.backends.mps.is_available()):
                    logging.warning("[NTv3] NTV3_FORCE_MPS=1 — usando MPS "
                                    "(riesgo de segfault con la GUI)")
                    return "mps"
            return "cpu"
        # Otras plataformas: MPS si existe (raro fuera de macOS) o CPU.
        if getattr(torch.backends, "mps", None) and torch.backends.mps.is_available():
            return "mps"
    except Exception:
        pass
    return "cpu"


# Modelos NTv3 disponibles en HuggingFace (de más potente a menor)
_NTV3_HF_MODELS = [
    "InstaDeepAI/nucleotide-transformer-v2-500m-multi-species",
    "InstaDeepAI/nucleotide-transformer-v2-250m-multi-species",
    "InstaDeepAI/nucleotide-transformer-500m-human-ref",
    "InstaDeepAI/nucleotide-transformer-500m-1000g",
]


def _ntv3_auto_download(dest_dir: str) -> bool:
    """
    Descarga automáticamente el modelo NTv3 más potente disponible
    en HuggingFace Hub hacia dest_dir.
    Requiere: pip install huggingface_hub
    """
    try:
        from huggingface_hub import snapshot_download
    except ImportError:
        print("[NTv3] huggingface_hub no instalado — ejecuta: pip install huggingface_hub")
        return False

    os.makedirs(dest_dir, exist_ok=True)
    for repo_id in _NTV3_HF_MODELS:
        try:
            print(f"[NTv3] Downloading '{repo_id}' → '{dest_dir}' ...")
            snapshot_download(repo_id=repo_id, local_dir=dest_dir)
            print(f"[NTv3] ✓ Descarga completa: '{repo_id}'")
            return True
        except Exception as e:
            print(f"[NTv3] Could not download '{repo_id}': {e}")
    print("[NTv3] Could not download any model.")
    return False



# ── Metadatos del modelo real (detectados del checkpoint) ─────────────────────
_NTV3_ARCH: dict = {}


def _ntv3_fix_config_from_weights(path: str) -> None:
    """
    Verifica coherencia del checkpoint.
    NOTA: Este modelo usa una FFN Gated (SwiGLU) donde intermediate.dense
    almacena [gate_proj || up_proj] concatenadas → shape [2*intermediate,hidden].
    Por eso intermediate.dense.weight=[8192,1024] con intermediate_size=4096.
    El config.json con intermediate_size=4096 es CORRECTO para esta arquitectura.
    No modificamos config.json; cargamos con ignore_mismatched_sizes=True.
    """
    import json
    cfg_path = os.path.join(path, "config.json")
    if not os.path.isfile(cfg_path):
        return
    try:
        with open(cfg_path, "r", encoding="utf-8") as f:
            cfg = json.load(f)
        inter = cfg.get("intermediate_size", 0)
        hidden = cfg.get("hidden_size", 1024)
        print(f"[NTv3] ✓ config.json — intermediate_size: {inter}  hidden_size: {hidden}")
        print(f"[NTv3]   Arquitectura: FFN Gated (SwiGLU) — intermediate.dense=[{2*inter},{hidden}]")
    except Exception as e:
        print(f"[NTv3] config.json: {e}")


def ntv3_load(model_path: Optional[str] = None,
              device: Optional[str] = None) -> bool:
    """
    Carga NTv3 con arquitectura correcta (auto-repair de config.json).

    Novedades vs versión anterior:
      • Corrige intermediate_size en config.json ANTES de cargar
        → Garantiza que el 100% de los pesos entrenados se usen
      • Detecta modelo 100M / 250M / 500M / 2.5B automáticamente
      • fp16 en GPU (2× velocidad, ½ VRAM)
      • Rellena _NTV3_ARCH para mostrar metadatos en la UI
    """
    global _NTV3_MODEL, _NTV3_TOKENIZER, _NTV3_DEVICE, _NTV3_READY, _NTV3_ERROR, _NTV3_ARCH

    with _NTV3_LOCK:
        if _NTV3_READY:
            return True

        path = model_path or _NTV3_DEFAULT_PATH
        dev  = device or _ntv3_detect_device()

        if not os.path.isdir(path):
            print(f"[NTv3] Default path not found: '{path}'")
            print("[NTv3] Starting automatic search across all drives...")
            found = _ntv3_search_model()
            if found:
                path = found
            else:
                default_dl = os.path.join(_ntv3_script_dir(), "nt-v3")
                print(f"[NTv3] Attempting automatic download to '{default_dl}' ...")
                if _ntv3_auto_download(default_dl):
                    path = default_dl
                else:
                    _NTV3_ERROR = (
                        "[NTv3] No se encontro ni descargo el modelo.\n"
                        "  pip install huggingface_hub\n"
                        "  snapshot_download("
                        "  'InstaDeepAI/nucleotide-transformer-v2-500m-multi-species',"
                        "  local_dir='C:/Users/USER/nt-v3')"
                    )
                    print(_NTV3_ERROR)
                    return False

        try:
            from transformers import AutoTokenizer, AutoModel, AutoConfig
            import torch

            # ── 1. Reparar config.json si hay mismatch ────────────────────────
            print(f"[NTv3] Verificando coherencia checkpoint ↔ config.json ...")
            _ntv3_fix_config_from_weights(path)

            # ── 2. Tokenizador ────────────────────────────────────────────────
            print(f"[NTv3] Loading tokenizer...")
            _NTV3_ERROR = None
            tokenizer = AutoTokenizer.from_pretrained(
                path, local_files_only=True, trust_remote_code=True)
            print(f"[NTv3] Tokenizer ready — vocab: {tokenizer.vocab_size:,} tokens")

            # ── 3. Config (ya corregida) ──────────────────────────────────────
            cfg = AutoConfig.from_pretrained(
                path, local_files_only=True, trust_remote_code=True)

            # ── 4. Modelo completo sin reinicializaciones ─────────────────────
            dtype = torch.float16 if dev == "cuda" else torch.float32
            print(f"[NTv3] Loading model on {dev} ({dtype}) ...")
            # ignore_mismatched_sizes=True is correct here:
            # This model uses a Gated FFN (SwiGLU) where intermediate.dense
            # stores [gate||up] concatenated. The shape mismatch is expected
            # and harmless — all weights are loaded correctly.
            import logging as _logging
            _hf_logger = _logging.getLogger("transformers.modeling_utils")
            _prev_level = _hf_logger.level
            _hf_logger.setLevel(_logging.ERROR)   # suppress expected warnings
            model = AutoModel.from_pretrained(
                path, config=cfg,
                local_files_only=True, trust_remote_code=True,
                dtype=dtype,
                ignore_mismatched_sizes=True)
            _hf_logger.setLevel(_prev_level)

            model = model.to(dev)
            model.eval()

            # ── 5. Metadatos del modelo ───────────────────────────────────────
            hidden     = getattr(cfg, "hidden_size", 1024)
            n_layers   = getattr(cfg, "num_hidden_layers", 29)
            inter_size = getattr(cfg, "intermediate_size", 8192)
            total_p    = sum(p.numel() for p in model.parameters()) / 1e6
            _NTV3_ARCH = {
                "hidden_size"      : hidden,
                "num_layers"       : n_layers,
                "intermediate_size": inter_size,
                "total_params_M"   : round(total_p, 1),
                "dtype"            : str(dtype).replace("torch.", ""),
                "device"           : dev,
                "path"             : path,
                "model_id"         : ("500M" if total_p > 400 else
                                      "250M" if total_p > 200 else "100M"),
            }

            _NTV3_TOKENIZER = tokenizer
            _NTV3_MODEL     = model
            _NTV3_DEVICE    = dev
            _NTV3_READY     = True
            _NTV3_ERROR     = None
            print(f"[NTv3] ✓ NTv3-{_NTV3_ARCH['model_id']} listo en {dev}")
            print(f"         layers={n_layers} | hidden={hidden} | "
                  f"intermediate={inter_size} | params={total_p:.0f}M | {_NTV3_ARCH['dtype']}")
            return True

        except ImportError as ie:
            _NTV3_ERROR = f"[NTv3] Dependencia faltante: {ie}\n  → pip install transformers torch"
            print(_NTV3_ERROR)
            return False
        except Exception as exc:
            _NTV3_ERROR = f"[NTv3] Error al cargar: {exc}"
            print(_NTV3_ERROR)
            return False


def ntv3_encode(
    sequences: List[str],
    batch_size: int    = 4,
    max_len: int       = _NTV3_MAX_LEN,
    pooling: str       = "mean",   # "mean" | "cls" | "weighted_mean"
    return_attentions: bool = False,
) -> Optional[object]:
    """
    Codifica secuencias de ADN con el máximo potencial de NTv3.

    Parameters
    ----------
    sequences         : lista de strings ACGTN
    batch_size        : lote por inferencia (reducir si hay OOM en GPU)
    max_len           : truncación en tokens (máx 1000 para NTv3)
    pooling           : "mean"          → promedio sobre todos los tokens no-pad
                        "cls"           → token [CLS] únicamente
                        "weighted_mean" → promedio ponderado por posición (foco 5')
    return_attentions : si True, devuelve también attention weights de la última capa

    Returns
    -------
    torch.Tensor [N, hidden_size] en CPU (fp32 siempre)
    Si return_attentions=True: (embeddings, attentions_last_layer)
    """
    if not _NTV3_READY:
        return None
    try:
        import torch

        all_embs  = []
        all_attns = [] if return_attentions else None

        for i in range(0, len(sequences), batch_size):
            batch = sequences[i: i + batch_size]
            enc = _NTV3_TOKENIZER(
                batch, return_tensors="pt",
                padding=True, truncation=True, max_length=max_len)
            enc = {k: v.to(_NTV3_DEVICE) for k, v in enc.items()}

            with torch.no_grad():
                out = _NTV3_MODEL(
                    **enc,
                    output_attentions=return_attentions)

            hidden = out.last_hidden_state.float()   # [B, L, H] — siempre fp32
            attn_mask = enc["attention_mask"].float().unsqueeze(-1)  # [B, L, 1]

            if pooling == "cls":
                emb = hidden[:, 0, :]
            elif pooling == "weighted_mean":
                # Ponderación decreciente por posición: enfatiza región 5'
                L = hidden.shape[1]
                weights = torch.linspace(1.0, 0.4, L, device=hidden.device).unsqueeze(0).unsqueeze(-1)
                weights = weights * attn_mask
                emb = (hidden * weights).sum(1) / weights.sum(1).clamp(min=1e-9)
            else:
                # "mean" — promedio sobre tokens no-padding
                emb = (hidden * attn_mask).sum(1) / attn_mask.sum(1).clamp(min=1e-9)

            all_embs.append(emb.cpu())

            if return_attentions and out.attentions is not None:
                # Última capa de atención: [B, heads, L, L] — promedio sobre heads
                last_attn = out.attentions[-1].float().mean(dim=1).cpu()  # [B, L, L]
                all_attns.append(last_attn)

        embeddings = torch.cat(all_embs, dim=0)  # [N, H]
        if return_attentions and all_attns:
            return embeddings, torch.cat(all_attns, dim=0)
        return embeddings

    except Exception as exc:
        print(f"[NTv3] Error in encode: {exc}")
        return None


def ntv3_analyze_sequences(
    ig_seqs:  List[str],
    meg_seqs: List[str],
    ui_seqs:  List[str]  = None,
    batch_size: int      = 4,
    pooling: str         = "mean",
) -> Optional[dict]:
    """
    ANÁLISIS COMPLETO NTv3 — máximo potencial para IGFinder.

    Calcula:
      1. Embeddings de cada clase (IG / MEG / ui-SEG)
      2. Centroide de cada clase en el espacio de embeddings
      3. Distancia coseno inter-clase (IG↔MEG, IG↔SEG, MEG↔SEG)
      4. Score de probabilidad por gen (distancia al centroide IG vs MEG)
      5. Cohesión intra-clase (compacidad del cluster)
      6. Gene-level confidence score (0–1, cuánto se parece cada gen a su clase)
      7. Outlier score: genes de cada clase que son atípicos
      8. Métricas de separabilidad: índice de Davies-Bouldin, silhouette aproximada
      9. Top-k genes más representativos de cada clase

    Parameters
    ----------
    ig_seqs  : secuencias de genes IG  (ACGTN)
    meg_seqs : secuencias de genes MEG (ACGTN)
    ui_seqs  : secuencias de genes ui-SEG (opcional)
    batch_size: tamaño de lote
    pooling  : estrategia de pooling

    Returns
    -------
    dict con todas las métricas y tensores de embeddings
    """
    if not _NTV3_READY:
        return {"error": "NTv3 no está listo — verifica la carga del modelo"}

    try:
        import torch
        import torch.nn.functional as F

        ui_seqs = ui_seqs or []

        # ── 1. Computar embeddings por clase ──────────────────────────────
        print(f"[NTv3] Encoding {len(ig_seqs)} IG + "
              f"{len(meg_seqs)} MEG + {len(ui_seqs)} ui-SEG sequences...")

        def _encode_safe(seqs, label):
            if not seqs:
                return None
            emb = ntv3_encode(seqs, batch_size=batch_size, pooling=pooling)
            if emb is not None:
                print(f"[NTv3]   {label}: {emb.shape[0]} embeddings [{emb.shape[1]}-dim]")
            return emb

        emb_ig  = _encode_safe(ig_seqs,  "IG")
        emb_meg = _encode_safe(meg_seqs, "MEG")
        emb_ui  = _encode_safe(ui_seqs,  "ui-SEG")

        if emb_ig is None or emb_meg is None:
            return {"error": "No se pudieron generar embeddings (secuencias vacías o error)"}

        # ── 2. Centroides por clase ───────────────────────────────────────
        c_ig  = F.normalize(emb_ig.mean(dim=0, keepdim=True), dim=-1)   # [1, H]
        c_meg = F.normalize(emb_meg.mean(dim=0, keepdim=True), dim=-1)
        c_ui  = F.normalize(emb_ui.mean(dim=0, keepdim=True), dim=-1) if emb_ui is not None else None

        # ── 3. Distancias coseno inter-clase ─────────────────────────────
        ig_meg_cos = float(F.cosine_similarity(c_ig, c_meg).item())
        ig_ui_cos  = float(F.cosine_similarity(c_ig, c_ui).item()) if c_ui is not None else None
        meg_ui_cos = float(F.cosine_similarity(c_meg, c_ui).item()) if c_ui is not None else None

        ig_meg_dist = 1.0 - ig_meg_cos   # distancia coseno (0=idéntico, 2=opuestos)

        # ── 4. Confidence scores por gen ─────────────────────────────────
        # Para cada gen, score = P(IG) = cos(g, c_ig) / (cos(g, c_ig) + cos(g, c_meg) + ε)
        def _confidence(embs, c_pos, c_neg):
            e_norm = F.normalize(embs, dim=-1)
            s_pos  = F.cosine_similarity(e_norm, c_pos.expand(e_norm.shape[0], -1), dim=-1)
            s_neg  = F.cosine_similarity(e_norm, c_neg.expand(e_norm.shape[0], -1), dim=-1)
            # Temperatura softmax 0.5 para polarizar
            logits = torch.stack([s_pos / 0.5, s_neg / 0.5], dim=-1)
            probs  = torch.softmax(logits, dim=-1)
            return probs[:, 0].tolist()   # P(pertenecer a c_pos)

        ig_conf   = _confidence(emb_ig,  c_ig, c_meg)    # P(IG) para cada gen IG
        meg_conf  = _confidence(emb_meg, c_meg, c_ig)    # P(MEG) para cada gen MEG
        ui_conf   = _confidence(emb_ui,  c_ui, c_ig) if emb_ui is not None else []

        # ── 5. Cohesión intra-clase (compacidad) ─────────────────────────
        def _cohesion(embs, centroid):
            e_norm = F.normalize(embs, dim=-1)
            sims   = F.cosine_similarity(e_norm, centroid.expand(e_norm.shape[0], -1))
            return float(sims.mean().item()), float(sims.std().item())

        ig_coh_mean,  ig_coh_std  = _cohesion(emb_ig,  c_ig)
        meg_coh_mean, meg_coh_std = _cohesion(emb_meg, c_meg)
        ui_coh_mean,  ui_coh_std  = (_cohesion(emb_ui, c_ui) if emb_ui is not None
                                      else (None, None))

        # ── 6. Outlier score por gen ──────────────────────────────────────
        # Un gen es outlier si su similitud a su centroide clase es baja
        def _outlier_scores(embs, centroid, threshold_pct=20):
            e_norm = F.normalize(embs, dim=-1)
            sims   = F.cosine_similarity(e_norm, centroid.expand(e_norm.shape[0], -1))
            threshold = float(torch.quantile(sims, threshold_pct/100.0).item())
            outliers  = (sims < threshold).nonzero(as_tuple=True)[0].tolist()
            return sims.tolist(), outliers

        ig_sims,  ig_outliers  = _outlier_scores(emb_ig,  c_ig)
        meg_sims, meg_outliers = _outlier_scores(emb_meg, c_meg)

        # ── 7. Top genes más representativos ─────────────────────────────
        def _top_representative(sims, n=5):
            sorted_idx = sorted(range(len(sims)), key=lambda i: sims[i], reverse=True)
            return sorted_idx[:n]

        ig_top  = _top_representative(ig_sims)
        meg_top = _top_representative(meg_sims)

        # ── 8. Índice de separabilidad IG vs MEG ─────────────────────────
        # Davies-Bouldin proxy: mayor es peor separación
        if ig_coh_mean > 0 and meg_coh_mean > 0:
            db_proxy = (ig_coh_std + meg_coh_std) / max(ig_meg_dist, 1e-6)
        else:
            db_proxy = None

        # Silhouette aproximada (basado en centroides, no pairwise)
        silh_ig  = (ig_meg_dist - (1.0 - ig_coh_mean))  / max(ig_meg_dist, 1.0 - ig_coh_mean, 1e-6)
        silh_meg = (ig_meg_dist - (1.0 - meg_coh_mean)) / max(ig_meg_dist, 1.0 - meg_coh_mean, 1e-6)
        silh_avg = (silh_ig + silh_meg) / 2.0

        print(f"[NTv3] ✓ Analysis complete")
        print(f"         IG↔MEG separation (cosine dist.): {ig_meg_dist:.4f}")
        print(f"         Approximate silhouette: {silh_avg:.4f}  "
              f"({'good' if silh_avg > 0.4 else 'moderate' if silh_avg > 0.2 else 'low'} separability)")
        print(f"         IG cohesion: {ig_coh_mean:.4f}±{ig_coh_std:.4f}  |  "
              f"MEG: {meg_coh_mean:.4f}±{meg_coh_std:.4f}")
        print(f"         Outliers IG: {len(ig_outliers)}  |  Outliers MEG: {len(meg_outliers)}")

        return {
            # Embeddings
            "embeddings_ig"    : emb_ig.numpy(),
            "embeddings_meg"   : emb_meg.numpy(),
            "embeddings_ui"    : emb_ui.numpy() if emb_ui is not None else None,
            # Centroides
            "centroid_ig"      : c_ig.numpy(),
            "centroid_meg"     : c_meg.numpy(),
            "centroid_ui"      : c_ui.numpy() if c_ui is not None else None,
            # Distancias inter-clase
            "ig_meg_cosine_sim": ig_meg_cos,
            "ig_meg_cosine_dist": ig_meg_dist,
            "ig_ui_cosine_sim" : ig_ui_cos,
            "meg_ui_cosine_sim": meg_ui_cos,
            # Confidence por gen
            "ig_confidence"    : ig_conf,       # list[float], len = n_ig
            "meg_confidence"   : meg_conf,      # list[float], len = n_meg
            "ui_confidence"    : ui_conf,
            # Cohesión
            "ig_cohesion_mean" : ig_coh_mean,
            "ig_cohesion_std"  : ig_coh_std,
            "meg_cohesion_mean": meg_coh_mean,
            "meg_cohesion_std" : meg_coh_std,
            "ui_cohesion_mean" : ui_coh_mean,
            "ui_cohesion_std"  : ui_coh_std,
            # Similitudes individuales
            "ig_similarities"  : ig_sims,
            "meg_similarities" : meg_sims,
            # Outliers (índices de genes atípicos)
            "ig_outlier_idx"   : ig_outliers,
            "meg_outlier_idx"  : meg_outliers,
            # Genes más representativos (índices)
            "ig_top_idx"       : ig_top,
            "meg_top_idx"      : meg_top,
            # Separabilidad global
            "silhouette_approx": silh_avg,
            "davies_bouldin_proxy": db_proxy,
            # Metadatos
            "n_ig"             : len(ig_seqs),
            "n_meg"            : len(meg_seqs),
            "n_ui"             : len(ui_seqs),
            "pooling"          : pooling,
            "model_id"         : _NTV3_ARCH.get("model_id", "?"),
            "hidden_size"      : _NTV3_ARCH.get("hidden_size", 1024),
        }

    except Exception as exc:
        import traceback
        print(f"[NTv3] Analysis error: {exc}")
        traceback.print_exc()
        return {"error": str(exc)}


def ntv3_predict_class(
    sequences:  List[str],
    labels:     Optional[List[str]] = None,
    batch_size: int = 4,
    max_len:    int = _NTV3_MAX_LEN,
) -> Optional[List[dict]]:
    """
    Devuelve métricas de embedding por secuencia (retrocompatibilidad).
    Para análisis completo usa ntv3_analyze_sequences().
    """
    embs = ntv3_encode(sequences, batch_size=batch_size, max_len=max_len)
    if embs is None:
        return None
    try:
        import torch, torch.nn.functional as F
        results = []
        for i in range(embs.shape[0]):
            e = embs[i]
            results.append({
                "sequence_idx"   : i,
                "label"          : labels[i] if labels and i < len(labels) else f"seq_{i}",
                "embedding_norm" : float(e.norm().item()),
                "embedding_mean" : float(e.mean().item()),
                "embedding_std"  : float(e.std().item()),
                "embedding_dim"  : e.shape[0],
            })
        return results
    except Exception as exc:
        print(f"[NTv3] Error in predict_class: {exc}")
        return None


def ntv3_cosine_similarity(seq_a: str, seq_b: str) -> Optional[float]:
    embs = ntv3_encode([seq_a, seq_b])
    if embs is None:
        return None
    try:
        import torch.nn.functional as F
        return float(F.cosine_similarity(embs[0].unsqueeze(0), embs[1].unsqueeze(0)).item())
    except Exception:
        return None


def ntv3_status() -> dict:
    return {
        "ready"      : _NTV3_READY,
        "device"     : _NTV3_DEVICE,
        "model_path" : _NTV3_DEFAULT_PATH,
        "error"      : _NTV3_ERROR,
        "max_len"    : _NTV3_MAX_LEN,
        "arch"       : _NTV3_ARCH,
    }


# ── Carga asíncrona al inicio (no bloquea la GUI) ─────────────────────────────
def _ntv3_autoload():
    threading.Thread(target=ntv3_load, daemon=True, name="NTv3-Loader").start()

_ntv3_autoload()



# ══════════════════════════════════════════════════════════════════════════════
#  CYTHON ACCELERATION — embedded source, auto-compile, fallback to pure Python
# ══════════════════════════════════════════════════════════════════════════════

_CYTHON_PYX = r'''
# cython: language_level=3, boundscheck=False, wraparound=False, cdivision=True
from libc.math cimport sin, cos, M_PI
import numpy as np
cimport numpy as np
np.import_array()

cdef inline int _clamp(int v) noexcept nogil:
    if v < 0:   return 0
    if v > 255: return 255
    return v

cdef inline (int, int, int) _parse_hex_c(str h):
    cdef str s = h.lstrip("#")
    return (int(s[0:2], 16), int(s[2:4], 16), int(s[4:6], 16))

cpdef str fast_blend(str fg_hex, double alpha, str bg_hex):
    cdef int fr, fg, fb, br, bg, bb
    cdef double inv_a = 1.0 - alpha
    fr, fg, fb = _parse_hex_c(fg_hex)
    br, bg, bb = _parse_hex_c(bg_hex)
    return f"#{_clamp(<int>(fr*alpha+br*inv_a)):02x}{_clamp(<int>(fg*alpha+bg*inv_a)):02x}{_clamp(<int>(fb*alpha+bb*inv_a)):02x}"

cpdef str fast_hx(double v):
    cdef int iv = <int>v
    if iv < 0:   iv = 0
    if iv > 255: iv = 255
    return f"{iv:02x}"

cdef dict _color_cache = {}

cpdef str fast_ca(str fg_hex, str alpha_hex, str bg_hex):
    cdef tuple key = (fg_hex, alpha_hex)
    cdef object cached = _color_cache.get(key)
    if cached is not None:
        return <str>cached
    cdef int a
    try:
        a = int(alpha_hex, 16)
        if a < 0:   a = 0
        if a > 255: a = 255
    except (ValueError, TypeError):
        _color_cache[key] = fg_hex
        return fg_hex
    cdef str result = fast_blend(fg_hex, a / 255.0, bg_hex)
    _color_cache[key] = result
    return result

cpdef void clear_color_cache():
    _color_cache.clear()

cpdef tuple sincos(double angle_deg):
    cdef double rad = angle_deg * M_PI / 180.0
    return (sin(rad), cos(rad))

cpdef list sincos_batch(int n, double start_deg, double step_deg, double offset):
    cdef list result = []
    cdef double deg, rad
    cdef int i
    for i in range(n):
        deg = start_deg + i * step_deg + offset
        rad = deg * M_PI / 180.0
        result.append((sin(rad), cos(rad)))
    return result

cpdef double fast_cliffs_delta(np.ndarray[np.float64_t, ndim=1] x,
                                np.ndarray[np.float64_t, ndim=1] y):
    cdef Py_ssize_t nx = x.shape[0], ny = y.shape[0]
    cdef Py_ssize_t i, j
    cdef double xi
    cdef long long gt = 0, lt = 0
    if nx == 0 or ny == 0:
        return float("nan")
    for i in range(nx):
        xi = x[i]
        for j in range(ny):
            if xi > y[j]:   gt += 1
            elif xi < y[j]: lt += 1
    return <double>(gt - lt) / <double>(nx * ny)

cpdef list fast_benjamini_hochberg(list pvalues):
    cdef int n_total = len(pvalues)
    if n_total == 0:
        return []
    cdef np.ndarray[np.float64_t, ndim=1] pvals = np.array(pvalues, dtype=np.float64)
    cdef np.ndarray[np.float64_t, ndim=1] out = np.full(n_total, np.nan, dtype=np.float64)
    cdef np.ndarray valid_mask = ~np.isnan(pvals)
    cdef np.ndarray[np.float64_t, ndim=1] valid = pvals[valid_mask]
    cdef int n = valid.shape[0]
    if n == 0:
        return out.tolist()
    cdef np.ndarray[np.intp_t, ndim=1] order = np.argsort(valid)
    cdef np.ndarray[np.float64_t, ndim=1] sorted_p = valid[order]
    cdef np.ndarray[np.float64_t, ndim=1] adjusted = np.empty(n, dtype=np.float64)
    cdef int i
    cdef double cum_min
    adjusted[n - 1] = sorted_p[n - 1]
    cum_min = sorted_p[n - 1]
    for i in range(n - 2, -1, -1):
        adjusted[i] = sorted_p[i] * n / (i + 1)
        if adjusted[i] > cum_min: adjusted[i] = cum_min
        else:                     cum_min = adjusted[i]
        if adjusted[i] > 1.0:    adjusted[i] = 1.0
    cdef np.ndarray[np.float64_t, ndim=1] result = np.empty(n, dtype=np.float64)
    for i in range(n):
        result[order[i]] = adjusted[i]
    out[valid_mask] = result
    return out.tolist()

cpdef list fast_enrichment_window(
    np.ndarray[np.float64_t, ndim=1] gene_starts,
    np.ndarray[np.float64_t, ndim=1] gene_ends,
    np.ndarray[np.int8_t, ndim=1] is_ig,
    double w_start, double w_end):
    cdef Py_ssize_t n = gene_starts.shape[0], i
    cdef int count = 0, ig_count = 0
    for i in range(n):
        if gene_starts[i] <= w_end and gene_ends[i] >= w_start:
            count += 1
            if is_ig[i]: ig_count += 1
    return [count, ig_count]
'''

def _try_build_cython():
    """Auto-compile embedded Cython source → importable .so/.pyd."""
    import tempfile, importlib, importlib.util, shutil, subprocess
    try:
        import Cython   # noqa: F401
    except ImportError:
        return None

    cache_dir = os.path.join(tempfile.gettempdir(), "igfinder_cython_cache")
    os.makedirs(cache_dir, exist_ok=True)

    pyx_path = os.path.join(cache_dir, "igfinder_core.pyx")
    setup_path = os.path.join(cache_dir, "setup.py")

    # Check if already compiled — look for .so or .pyd
    for fname in os.listdir(cache_dir):
        if fname.startswith("igfinder_core") and (
                fname.endswith(".so") or fname.endswith(".pyd")):
            # Already compiled — try to import
            spec = importlib.util.spec_from_file_location(
                "igfinder_core", os.path.join(cache_dir, fname))
            if spec and spec.loader:
                mod = importlib.util.module_from_spec(spec)
                try:
                    spec.loader.exec_module(mod)
                    return mod
                except Exception:
                    break  # recompile

    # Write .pyx
    with open(pyx_path, "w", encoding="utf-8") as f:
        f.write(_CYTHON_PYX)

    # Write setup.py
    setup_code = (
        "from setuptools import setup, Extension\n"
        "import numpy as np\n"
        "from Cython.Build import cythonize\n"
        "setup(ext_modules=cythonize([Extension(\n"
        "    'igfinder_core', ['igfinder_core.pyx'],\n"
        "    include_dirs=[np.get_include()],\n"
        "    define_macros=[('NPY_NO_DEPRECATED_API','NPY_1_7_API_VERSION')],\n"
        ")], compiler_directives={'language_level':'3',\n"
        "    'boundscheck':False,'wraparound':False,'cdivision':True}))\n"
    )
    with open(setup_path, "w", encoding="utf-8") as f:
        f.write(setup_code)

    # Compile
    try:
        result = subprocess.run(
            [sys.executable, "setup.py", "build_ext", "--inplace"],
            cwd=cache_dir, capture_output=True, text=True, timeout=120)
        if result.returncode != 0:
            return None
    except Exception:
        return None

    # Import compiled module
    for fname in os.listdir(cache_dir):
        if fname.startswith("igfinder_core") and (
                fname.endswith(".so") or fname.endswith(".pyd")):
            spec = importlib.util.spec_from_file_location(
                "igfinder_core", os.path.join(cache_dir, fname))
            if spec and spec.loader:
                mod = importlib.util.module_from_spec(spec)
                try:
                    spec.loader.exec_module(mod)
                    return mod
                except Exception:
                    return None
    return None

_HAS_CYTHON = False
_cy_mod = _try_build_cython()
if _cy_mod is not None:
    fast_blend = _cy_mod.fast_blend
    fast_hx = _cy_mod.fast_hx
    fast_ca = _cy_mod.fast_ca
    clear_color_cache = _cy_mod.clear_color_cache
    fast_cliffs_delta = _cy_mod.fast_cliffs_delta
    fast_benjamini_hochberg = _cy_mod.fast_benjamini_hochberg
    fast_enrichment_window = _cy_mod.fast_enrichment_window
    sincos = _cy_mod.sincos
    sincos_batch = _cy_mod.sincos_batch
    _HAS_CYTHON = True
    logging.info("[CYTHON] igfinder_core compiled — accelerated mode")
else:
    logging.debug("[CYTHON] Cython not available — pure Python mode")
del _cy_mod

