# ── Color utilities (Cython-accelerated when available) ────────────────────
def _parse_hex(h):
    h = h.lstrip("#")
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)

if _HAS_CYTHON:
    _BG = C["bg"]
    def _blend(fg_hex: str, alpha: float, bg_hex: str = _BG) -> str:
        return fast_blend(fg_hex, alpha, bg_hex)
    def _hx(v):
        return fast_hx(float(v))
    _CC = {}
    def _ca(fg_hex: str, alpha_hex: str) -> str:
        return fast_ca(fg_hex, alpha_hex, _BG)
else:
    def _blend(fg_hex: str, alpha: float, bg_hex: str = C["bg"]) -> str:
        fr, fg_v, fb = _parse_hex(fg_hex)
        br, bgv,  bb = _parse_hex(bg_hex)
        r = max(0, min(255, int(fr*alpha + br*(1-alpha))))
        g = max(0, min(255, int(fg_v*alpha + bgv*(1-alpha))))
        b = max(0, min(255, int(fb*alpha + bb*(1-alpha))))
        return f"#{r:02x}{g:02x}{b:02x}"
    def _hx(v):
        """Clamp a numeric value to [0,255] and return 2-digit hex string."""
        return f"{max(0, min(255, int(v))):02x}"
    _CC = {}
    def _ca(fg_hex: str, alpha_hex: str) -> str:
        key = (fg_hex, alpha_hex)
        if key not in _CC:
            try:
                a = max(0, min(255, int(alpha_hex, 16)))
                _CC[key] = _blend(fg_hex, a / 255)
            except (ValueError, TypeError):
                _CC[key] = fg_hex
        return _CC[key]


# ── Pre-warm color cache — eliminates cache misses during animation ──────────
def _prewarm_color_cache():
    """Pre-compute all common color+alpha pairs used in animations."""
    _colors = [C["cyan"], C["teal"], C["emerald"], C["violet"],
               C["amber"], C["red"], C["border"], C["txt_muted"]]
    _alphas = ["03","05","06","07","08","0a","0c","0e","10","12",
               "15","18","1a","22","28","30","33","44","55","66",
               "77","88","99","aa","bb","cc","dd","ee","ff"]
    for col in _colors:
        for a in _alphas:
            _ca(col, a)
_prewarm_color_cache()


def _draw_dna_static(canvas, bg_col):
    """
    Dibuja una doble hélice de ADN estática en un canvas de 52×52 px.
    Hebra A: lila vibrante (C["cyan"])
    Hebra B: rosa neón (C["teal"])
    Peldaños: lavanda a violet alternados
    Bases:    círculos coloreados en extremos de peldaño
    """
    W = H = 52
    CX = W // 2        # 26
    N_RUNGS = 9        # pares de bases
    Y_TOP   = 4
    Y_BOT   = H - 4
    STEP    = (Y_BOT - Y_TOP) / (N_RUNGS - 1)
    AMP     = 11       # amplitud horizontal de cada hebra

    # Pre-calcular posiciones de las dos hebras (onda sinusoidal)
    pts_a, pts_b = [], []
    for i in range(N_RUNGS):
        y = Y_TOP + i * STEP
        t = i / (N_RUNGS - 1)   # 0..1
        # Hebra A: seno normal, B: seno invertido
        ax = CX + AMP * math.sin(t * math.pi * 2)
        bx = CX - AMP * math.sin(t * math.pi * 2)
        pts_a.append((ax, y))
        pts_b.append((bx, y))

    # ── Backbone hebra A — curva continua (lila) ─────────────────────────
    for i in range(N_RUNGS - 1):
        x0, y0 = pts_a[i];   x1, y1 = pts_a[i+1]
        xm = (x0 + x1) / 2
        canvas.create_line(x0, y0, xm, (y0+y1)/2, x1, y1,
                           fill=_ca(C["cyan"], "cc"), width=2,
                           smooth=True)
    # ── Backbone hebra B — curva continua (rosa) ─────────────────────────
    for i in range(N_RUNGS - 1):
        x0, y0 = pts_b[i];   x1, y1 = pts_b[i+1]
        xm = (x0 + x1) / 2
        canvas.create_line(x0, y0, xm, (y0+y1)/2, x1, y1,
                           fill=_ca(C["teal"], "cc"), width=2,
                           smooth=True)

    # ── Peldaños horizontales (bases nitrogenadas) ────────────────────────
    rung_cols = [C["lavender"], C["violet"], C["orchid"], C["lavender"],
                 C["blush"],   C["violet"], C["lavender"], C["orchid"], C["violet"]]
    for i, (pa, pb) in enumerate(zip(pts_a, pts_b)):
        ax, ay = pa; bx, by = pb
        rc = rung_cols[i % len(rung_cols)]
        # Peldaño — línea horizontal entre las dos hebras
        canvas.create_line(ax, ay, bx, by,
                           fill=_ca(rc, "88"), width=1)
        # Base en hebra A (círculo lila)
        canvas.create_oval(ax-2.8, ay-2.8, ax+2.8, ay+2.8,
                           fill=C["cyan"], outline=_ca(C["lavender"],"66"))
        # Base en hebra B (círculo rosa)
        canvas.create_oval(bx-2.8, by-2.8, bx+2.8, by+2.8,
                           fill=C["teal"], outline=_ca(C["rose"],"66"))

    # ── Punto brillante central (unión) ──────────────────────────────────
    canvas.create_oval(CX-1.5, H//2-1.5, CX+1.5, H//2+1.5,
                       fill=C["white"], outline="")



