#  WIDGET: _SysDial
# ══════════════════════════════════════════════════════════════════════════════

class _SysDial(tk.Canvas):
    """
    Dial de sistema con animación de 60 fps.
    Mejoras:
      • Timer de 16 ms (60 fps objetivo)
      • Fondo estático creado UNA vez — solo se actualizan arcos/partículas
      • Interpolación lineal suave (lerp) para transiciones de valor
      • Sin delete("all") — se usan tags selectivos
    """
    SIZE  = 160
    START = 222
    SWEEP = 276
    FPS16 = 16       # ms entre frames activos
    FPS_IDLE = 120   # ms cuando no es visible

    def __init__(self, parent, **kw):
        super().__init__(parent, width=self.SIZE, height=self.SIZE,
                         bg=C["panel"], highlightthickness=0, **kw)
        s = self.SIZE
        self._cx = self._cy = s / 2
        self._R  = 56
        self._v_target  = 0.05   # valor objetivo
        self._v_current = 0.05   # valor interpolado (suave)
        self._phase  = 0.0
        self._pulse  = 0.0
        self._static_drawn = False
        self._visible_last = True
        # Pre-calcular ángulos de tick marks una sola vez
        self._tick_angles = [math.radians(a) for a in range(0, 360, 6)]
        self._draw_static()
        self._animate()

    def set_value(self, v):
        self._v_target = max(0.0, min(1.0, float(v)))

    def _draw_static(self):
        """Dibuja UNA VEZ los elementos que no cambian."""
        s = self.SIZE; cx = self._cx; cy = self._cy; R = self._R
        col = C["cyan"]

        # ── Fondo circular ────────────────────────────────────────
        self.create_oval(2, 2, s-2, s-2, fill=C["panel"],
                         outline=_ca(C["border"], "55"), width=1,
                         tags="static")
        self.create_oval(5, 5, s-5, s-5, fill="",
                         outline=_ca(col, "10"), width=1, tags="static")
        self.create_oval(8, 8, s-8, s-8, fill="",
                         outline=_ca(col, "08"), width=1, tags="static")

        # ── Micro-puntos de circuito (estáticos) ─────────────────
        for gx in range(18, s-12, 22):
            for gy in range(18, s-12, 22):
                d = math.hypot(gx - cx, gy - cy)
                if d < R + 20:
                    self.create_oval(gx-0.6, gy-0.6, gx+0.6, gy+0.6,
                                     fill=_ca(col, "12"), outline="",
                                     tags="static")

        # ── Tick marks (estáticos) ────────────────────────────────
        for tick_a in range(0, 360, 6):
            ta   = math.radians(tick_a)
            imaj = (tick_a % 90 == 0)
            imid = (tick_a % 30 == 0)
            ti   = R - 1
            to   = R + (10 if imaj else 6 if imid else 3)
            lw   = 2.0 if imaj else 1.2 if imid else 0.7
            alp  = "88" if imaj else "55" if imid else "1a"
            self.create_line(cx+ti*math.cos(ta), cy+ti*math.sin(ta),
                             cx+to*math.cos(ta), cy+to*math.sin(ta),
                             fill=_ca(col, alp), width=lw, tags="static")

        # ── Track arc (estático) ──────────────────────────────────
        S  = self.START; SW = self.SWEEP
        self.create_arc(cx-R, cy-R, cx+R, cy+R,
                        start=S, extent=-SW, style="arc",
                        outline=_ca(col, "0c"), width=18, tags="static")
        self.create_arc(cx-R, cy-R, cx+R, cy+R,
                        start=S, extent=-SW, style="arc",
                        outline=_ca(C["cyan_t"], "88"), width=14, tags="static")
        self.create_arc(cx-R, cy-R, cx+R, cy+R,
                        start=S, extent=-SW, style="arc",
                        outline=_ca(col, "0a"), width=10, tags="static")

        # ── Anillo interior (estático) ────────────────────────────
        r2 = R - 17
        self.create_oval(cx-r2, cy-r2, cx+r2, cy+r2,
                         outline=_ca(col, "22"), width=1, tags="static")
        self.create_oval(cx-r2+4, cy-r2+4, cx+r2-4, cy+r2-4,
                         outline=_ca(col, "0c"), width=1, tags="static")
        self.create_text(cx, cy + r2 + 8, text="SYS",
                         font=("Courier New", 6, "bold"),
                         fill=_ca(C["txt_muted"], "66"), tags="static")
        self._r2 = r2
        self._static_drawn = True

    def _draw_dynamic(self):
        """Solo redibuja los elementos animados. Se llama cada 16 ms."""
        # Eliminar solo elementos dinámicos
        self.delete("dyn")
        cx = self._cx; cy = self._cy; R = self._R
        r2 = self._r2
        col = C["cyan"]
        v   = self._v_current
        ph  = self._phase
        S   = self.START; SW = self.SWEEP

        # ── Partículas orbitales (animadas) ──────────────────────
        r_orbit = R + 16
        for i in range(36):
            a  = math.radians(i*10 + ph * 0.35)
            dist_to_val = abs((i*4 % 360) - ((S - v*SW) % 360))
            brightness = max(10, min(180, int(180 - dist_to_val*0.5)))
            sz = 1.5 if i % 9 == 0 else 0.6
            self.create_oval(cx+r_orbit*math.cos(a)-sz,
                             cy+r_orbit*math.sin(a)-sz,
                             cx+r_orbit*math.cos(a)+sz,
                             cy+r_orbit*math.sin(a)+sz,
                             fill=_ca(col, f"{brightness:02x}"),
                             outline="", tags="dyn")

        # ── Arco de valor con capas de glow ──────────────────────
        if v > 0.001:
            span = v * SW
            for gw, ga in [(28,"03"),(22,"07"),(16,"0e"),(10,"18"),(6,"30")]:
                self.create_arc(cx-R, cy-R, cx+R, cy+R,
                                start=S, extent=-span, style="arc",
                                outline=_ca(col, ga), width=gw, tags="dyn")
            self.create_arc(cx-R, cy-R, cx+R, cy+R,
                            start=S, extent=-span, style="arc",
                            outline=col, width=3, tags="dyn")

            # Partículas en arco
            for pi in range(5):
                pa     = span * (0.15 + 0.15*pi) + ph*2.0*pi
                pa_deg = S - (pa % max(span, 0.01))
                pa_r   = math.radians(pa_deg)
                px     = cx + R*math.cos(pa_r)
                py     = cy + R*math.sin(pa_r)
                p_al   = 0.3 + 0.5*math.sin(ph*0.12 + pi*1.2)
                for pr, pa2 in [(5, _hx(p_al*40)),
                                (3, _hx(p_al*100)),
                                (1.5, _hx(p_al*200))]:
                    self.create_oval(px-pr, py-pr, px+pr, py+pr,
                                     fill=_ca(C["emerald"], pa2),
                                     outline="", tags="dyn")

            # Cabeza brillante del arco
            ea = math.radians(S - span)
            ex = cx + R*math.cos(ea); ey = cy + R*math.sin(ea)
            for rs, rc in [(12, _ca(C["emerald"],"0a")),
                           (8,  _ca(C["emerald"],"22")),
                           (5,  _ca(C["emerald"],"55")),
                           (3,  C["emerald"])]:
                self.create_oval(ex-rs, ey-rs, ex+rs, ey+rs,
                                 fill=rc, outline="", tags="dyn")
            self.create_oval(ex-1.5, ey-1.5, ex+1.5, ey+1.5,
                             fill=C["white"], outline="", tags="dyn")

        # ── Rayos internos rotativos ──────────────────────────────
        for i in range(6):
            a     = math.radians(i*60 - ph*0.48)
            scale = 0.38 + 0.28*math.sin(ph*0.06 + i*0.9)
            r_in  = r2 * 0.18
            r_out = r2 * scale
            self.create_line(cx+r_in*math.cos(a), cy+r_in*math.sin(a),
                             cx+r_out*math.cos(a), cy+r_out*math.sin(a),
                             fill=_ca(col, "44"), width=1.2, tags="dyn")
            ox = cx + r_out*math.cos(a)
            oy = cy + r_out*math.sin(a)
            self.create_oval(ox-1.5, oy-1.5, ox+1.5, oy+1.5,
                             fill=_ca(col, "55"), outline="", tags="dyn")

        # ── Satélites orbitales con estela ────────────────────────
        r_sat = r2 * 0.72
        for i in range(3):
            sa = math.radians(i*120 + ph*1.8)
            sx = cx + r_sat*math.cos(sa)
            sy = cy + r_sat*math.sin(sa)
            for sr, salp in [(5,"08"),(3,"1a"),(1.8,"44")]:
                self.create_oval(sx-sr, sy-sr, sx+sr, sy+sr,
                                 fill=_ca(C["emerald"], salp),
                                 outline="", tags="dyn")
            for trail in range(1, 7):
                ta2  = math.radians(i*120 + ph*1.8 - trail*7)
                tx   = cx + r_sat*math.cos(ta2)
                ty   = cy + r_sat*math.sin(ta2)
                talp = max(4, 32 - trail*5)
                self.create_oval(tx-1, ty-1, tx+1, ty+1,
                                 fill=_ca(C["emerald"], f"{talp:02x}"),
                                 outline="", tags="dyn")

        # ── Núcleo pulsante ───────────────────────────────────────
        pr = 6 + 3*math.sin(self._pulse)
        for hr, ha in [(pr+10,"06"),(pr+6,"10"),(pr+3,"1a")]:
            self.create_oval(cx-hr, cy-hr, cx+hr, cy+hr,
                             fill=_ca(col, ha), outline="", tags="dyn")
        self.create_oval(cx-pr-2, cy-pr-2, cx+pr+2, cy+pr+2,
                         fill="", outline=_ca(col,"44"), width=1, tags="dyn")
        self.create_oval(cx-pr, cy-pr, cx+pr, cy+pr,
                         fill=_ca(col,"22"), outline=_ca(col,"55"),
                         width=1, tags="dyn")
        self.create_oval(cx-3, cy-3, cx+3, cy+3,
                         fill=col, outline="", tags="dyn")
        self.create_oval(cx-1.2, cy-1.2, cx+1.2, cy+1.2,
                         fill=C["white"], outline="", tags="dyn")

    def _animate(self):
        visible = self.winfo_ismapped()
        if visible:
            # Lerp suave hacia el valor objetivo (velocidad de transición: 8%)
            self._v_current += (self._v_target - self._v_current) * 0.08
            self._phase  += 1.1      # velocidad orbital
            self._pulse  += 0.072    # velocidad pulsación núcleo
            self._draw_dynamic()
        rate = self.FPS16 if visible else self.FPS_IDLE
        self.after(rate, self._animate)


# ══════════════════════════════════════════════════════════════════════════════
#  WIDGET: EliteStatusPanel  — 60 fps, tag-based, lerp suave por métrica
# ══════════════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════════════════
#  WIDGET: EliteStatusPanel
# ══════════════════════════════════════════════════════════════════════════════

class EliteStatusPanel(tk.Canvas):
    """
    Panel de métricas IG / MEG / SEG con animación fluida.
    Mejoras:
      • Fondo (grilla + borde) dibujado una vez con tag "static"
      • Arcos, barras y etiquetas de valor en tag "dyn" (solo estos se recrean)
      • Lerp independiente para cada métrica
      • 60 fps activo
    """
    W, H  = 300, 180
    START = 222
    SWEEP = 276
    FPS16 = 16
    FPS_IDLE = 120

    def __init__(self, parent, **kw):
        super().__init__(parent, width=self.W, height=self.H,
                         bg=C["panel"], highlightthickness=0, **kw)
        # Valores objetivo y corrientes para cada métrica
        self._target  = {"ig": 0.0, "meg": 0.0, "seg": 0.0}
        self._current = {"ig": 0.0, "meg": 0.0, "seg": 0.0}
        self._phase = 0.0
        self._draw_static()
        self._animate()

    def set_ig(self,  v): self._target["ig"]  = max(0.0, min(1.0, float(v)))
    def set_meg(self, v): self._target["meg"] = max(0.0, min(1.0, float(v)))
    def set_seg(self, v): self._target["seg"] = max(0.0, min(1.0, float(v)))
    # Compatibilidad retroactiva
    def set_sys(self, v): pass

    def _draw_static(self):
        """Fondo + grilla de puntos: dibujados SOLO una vez."""
        r = 8
        x0, y0, x1, y1 = 0, 0, self.W, self.H
        for color, inset in [
            (_ca(C["border"], "88"), 0),
            (_ca(C["cyan"],   "22"), 1),
        ]:
            xi0 = x0+inset; yi0 = y0+inset
            xi1 = x1-inset; yi1 = y1-inset
            for args in [
                (xi0+r, yi0, xi1-r, yi1),
                (xi0, yi0+r, xi1, yi1-r),
            ]:
                self.create_rectangle(*args, fill=C["panel"],
                                      outline="", tags="static")
            for ox,oy in [(xi0,yi0),(xi1-r*2,yi0),(xi0,yi1-r*2),(xi1-r*2,yi1-r*2)]:
                self.create_oval(ox, oy, ox+r*2, oy+r*2,
                                 fill=C["panel"], outline="", tags="static")

        # Grilla de micro-puntos
        for gx in range(16, self.W-8, 16):
            for gy in range(10, self.H-8, 16):
                self.create_oval(gx-0.7, gy-0.7, gx+0.7, gy+0.7,
                                 fill=_ca(C["cyan"], "12"), outline="",
                                 tags="static")
        self.create_text(self.W-8, self.H-6, text="IGFINDER STATUS",
                         font=("Courier New", 6, "bold"),
                         fill=_ca(C["emerald"], "44"), anchor="e",
                         tags="static")

    def _draw_metric_dyn(self, cx, cy, key, label, col, col_t):
        """Dibuja solo la parte dinámica de una métrica."""
        r   = 24; S = self.START; SW = self.SWEEP
        val = self._current[key]

        # Track (fondo del arco)
        self.create_arc(cx-r, cy-r, cx+r, cy+r,
                        start=S, extent=-SW, style="arc",
                        outline=_ca(col, "1a"), width=8, tags="dyn")
        self.create_arc(cx-r, cy-r, cx+r, cy+r,
                        start=S, extent=-SW, style="arc",
                        outline=_ca(col_t, "cc"), width=6, tags="dyn")

        # Arco de valor
        if val > 0.001:
            span = val * SW
            for gw, ga in [(15,"07"),(10,"14"),(6,"22")]:
                self.create_arc(cx-r, cy-r, cx+r, cy+r,
                                start=S, extent=-span, style="arc",
                                outline=_ca(col, ga), width=gw, tags="dyn")
            self.create_arc(cx-r, cy-r, cx+r, cy+r,
                            start=S, extent=-span, style="arc",
                            outline=col, width=3, tags="dyn")
            # Cabeza luminosa
            ea = math.radians(S - span)
            ex = cx + r*math.cos(ea); ey = cy + r*math.sin(ea)
            self.create_oval(ex-5, ey-5, ex+5, ey+5,
                             fill=_ca(C["emerald"],"33"), outline="", tags="dyn")
            self.create_oval(ex-3, ey-3, ex+3, ey+3,
                             fill=C["emerald"], outline="", tags="dyn")
            self.create_oval(ex-1.5, ey-1.5, ex+1.5, ey+1.5,
                             fill=col, outline="", tags="dyn")

        # Valor numérico en el centro del dial
        self.create_text(cx, cy-5, text=f"{int(val*100)}",
                         font=("Courier New", 10, "bold"),
                         fill=C["txt"], tags="dyn")
        self.create_text(cx, cy+8, text=label,
                         font=("Courier New", 7, "bold"),
                         fill=col, tags="dyn")

        # Barra horizontal (más a la derecha)
        bx = cx + r + 10; bw = 115; bh = 7; by = cy - 4
        self.create_rectangle(bx, by, bx+bw, by+bh,
                               fill=col_t, outline=_ca(col,"33"), tags="dyn")
        if val > 0.001:
            fw = max(int(bw * val), 2)
            # Glow de la barra
            self.create_rectangle(bx, by, bx+fw, by+bh,
                                   fill=_ca(col,"44"), outline="", tags="dyn")
            bw2 = max(int(fw*0.3), 2)
            self.create_rectangle(bx+fw-bw2, by, bx+fw, by+bh,
                                   fill=col, outline="", tags="dyn")
            self.create_rectangle(bx+fw-2, by, bx+fw, by+bh,
                                   fill=C["emerald"], outline="", tags="dyn")
        self.create_text(bx+bw+10, by+bh//2,
                         text=f"{int(val*100)}%",
                         font=("Courier New", 8, "bold"),
                         fill=col, anchor="w", tags="dyn")

    def _animate(self):
        visible = self.winfo_ismapped()
        if visible:
            lerp = 0.09  # velocidad de interpolación
            changed = False
            for k in ("ig", "meg", "seg"):
                diff = self._target[k] - self._current[k]
                if abs(diff) > 0.0005:
                    self._current[k] += diff * lerp
                    changed = True
                else:
                    self._current[k] = self._target[k]
            self._phase += 0.9
            # Solo redibujar si algo cambió o siempre si hay fase activa
            self.delete("dyn")
            self._draw_metric_dyn(38,  30,  "ig",  "IG",  C["teal"],   C["teal_t"])
            self._draw_metric_dyn(38,  90,  "meg", "MEG", C["cyan"],   C["cyan_t"])
            self._draw_metric_dyn(38,  150, "seg", "SEG", C["violet"], C["violet_t"])
        self.after(self.FPS16 if visible else self.FPS_IDLE, self._animate)


# ══════════════════════════════════════════════════════════════════════════════
#  WIDGET: ChromoScope  — 30-60 fps, dirty-rect por sector, ripple suave
# ══════════════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════════════════
#  WIDGET: ChromoScope
# ══════════════════════════════════════════════════════════════════════════════

class ChromoScope(tk.Canvas):
    """
    Mapa cromosómico circular con animación fluida.
    Mejoras:
      • Estructura de anillos, guías, nodos creados UNA vez (tag "static")
      • Sectores de cromosoma con tag individual "sec_N" — solo actualiza
        el que cambió (dirty tracking)
      • Sweep line + estela en tag "sweep" — animación a 16 ms
      • Ripple renderizado con 40 pasos en lugar de 20 (más suave)
      • Lerp de fase del sweep para movimiento verdaderamente fluido
    """
    CHROMS  = [str(i) for i in range(1, 23)] + ["X", "Y"]
    N       = 24
    CHR_LEN = {
        "1":249,"2":242,"3":198,"4":190,"5":182,
        "6":171,"7":159,"8":145,"9":138,"10":134,
        "11":135,"12":133,"13":114,"14":107,"15":102,
        "16":90,"17":83,"18":80,"19":59,"20":64,
        "21":47,"22":51,"X":156,"Y":57,
    }
    FPS_ACTIVE = 16     # 60 fps cuando escanea
    FPS_IDLE   = 80     # 12 fps en reposo
    FPS_HIDDEN = 500    # suspendido

    def __init__(self, parent, size=200, **kw):
        super().__init__(parent, width=size, height=size,
                         bg=C["panel"], highlightthickness=0, **kw)
        self.size            = size
        self._cx = self._cy  = size / 2
        self._R              = size / 2 - 20
        self._r_inner        = self._R * 0.28
        self._angle_float    = -90.0   # ángulo continuo (float) para suavidad
        self._angle_vel      = 0.0     # velocidad angular con aceleración
        self._active         = False
        self._done           = {}      # chrom → gene_count
        self._max_genes      = 1
        self._current_chrom  = None
        self._ripple         = {}      # chrom → float fase 0..1
        self._pulse_phase    = 0.0
        self._dirty_chroms   = set()   # cromosomas que necesitan redibujarse
        self._all_dirty      = True    # primer frame: dibujar todo
        self._labeled_chroms = set()   # se popula en _draw_static
        self._total_chroms   = self.N  # contador real (puede ser > sectores visibles)

        # Pre-calcular sectores
        total_len = sum(self.CHR_LEN[c] for c in self.CHROMS)
        self._sector_start  = {}
        self._sector_extent = {}
        acc = -90.0
        for c in self.CHROMS:
            ext = 360.0 * self.CHR_LEN[c] / total_len
            self._sector_start[c]  = acc
            self._sector_extent[c] = ext
            acc += ext

        self._draw_static()
        self._animate()

    # ── API pública ───────────────────────────────────────────────
    def set_active(self, v):
        self._active = v
        if not v:
            self._current_chrom = None
            self._angle_vel     = 0.0

    def set_chrom_done(self, chrom, gene_count):
        # Siempre cuenta para el contador central, aun si el sector no es visible
        self._done[chrom]    = gene_count
        self._max_genes      = max(self._max_genes, gene_count, 1)
        # Ripple y dirty solo si hay sector dibujado para este cromosoma
        if chrom in self._sector_start:
            self._ripple[chrom]  = 0.0
            self._dirty_chroms.add(chrom)

    def set_current_chrom(self, chrom):
        old = self._current_chrom
        self._current_chrom = chrom
        if old and old in self._sector_start:
            self._dirty_chroms.add(old)
        if chrom and chrom in self._sector_start:
            self._dirty_chroms.add(chrom)

    def set_genome(self, chroms, max_visible: int = 60):
        """
        Reconfigura el ChromoScope para visualizar la especie en curso.

        Args:
            chroms: dict {chrom_name: length_bp} o
                    {chrom_name: {"length": bp, "coord_system": ...}} —
                    formato directo de chromosomes_info().
            max_visible: número máximo de sectores a renderizar. Si la
                especie tiene más cromosomas/scaffolds que esto, se muestran
                los más grandes (por longitud) y el resto sigue contando para
                el contador central X/N pero sin sector propio. Esto mantiene
                la animación fluida y la visualización legible para
                ensamblados muy fragmentados (1000+ scaffolds).

        La lógica de animación, sweep, ripple y dirty-tracking se preserva
        intacta — solo cambia el dato de qué cromosomas mostrar.
        """
        if not chroms:
            return
        # Normalizar entrada (acepta los dos formatos)
        pairs: List[Tuple[str, int]] = []
        for name, value in chroms.items():
            if isinstance(value, dict):
                length = value.get("length", 0) or 0
            else:
                try:    length = int(value)
                except (TypeError, ValueError): length = 0
            if length > 0:
                pairs.append((str(name), int(length)))
        if not pairs:
            return
        total_count = len(pairs)
        # Top-N por longitud (los sectores más grandes son los más informativos)
        pairs.sort(key=lambda p: -p[1])
        visible_pairs = pairs[:max_visible]

        # Sustituir atributos de instancia (sombrean los class-level)
        self.CHROMS  = [n for n, _ in visible_pairs]
        self.CHR_LEN = {n: lng for n, lng in visible_pairs}
        self.N       = total_count          # contador central usa el total real
        self._total_chroms = total_count

        # Recalcular geometría (idéntico al cálculo del __init__)
        total_len = sum(self.CHR_LEN.values()) or 1
        self._sector_start  = {}
        self._sector_extent = {}
        acc = -90.0
        for c in self.CHROMS:
            ext = 360.0 * self.CHR_LEN[c] / total_len
            self._sector_start[c]  = acc
            self._sector_extent[c] = ext
            acc += ext

        # Reset estado dinámico y redibujo del estático
        self._done           = {}
        self._max_genes      = 1
        self._current_chrom  = None
        self._ripple         = {}
        self._dirty_chroms   = set()
        self._angle_float    = -90.0
        self._angle_vel      = 0.0
        self._all_dirty      = True
        self.delete("all")
        self._draw_static()

    def reset(self):
        self._done           = {}
        self._max_genes      = 1
        self._current_chrom  = None
        self._ripple         = {}
        self._angle_float    = -90.0
        self._angle_vel      = 0.0
        self._all_dirty      = True
        self.delete("dyn")
        self.delete("center")

    def _draw_static(self):
        """Infraestructura del mapa: anillos + guías + nodos de borde."""
        cx = self._cx; cy = self._cy
        R  = self._R; r_inner = self._r_inner

        # Fondo circular
        self.create_oval(cx-R-5, cy-R-5, cx+R+5, cy+R+5,
                         fill=C["panel"], outline=C["border_d"],
                         width=1, tags="static")
        self.create_oval(cx-R-2, cy-R-2, cx+R+2, cy+R+2,
                         fill="", outline=_ca(C["emerald"], "22"),
                         width=1, tags="static")

        # Guías radiales (12 líneas)
        for i in range(12):
            a = math.radians(i*30)
            self.create_line(cx, cy, cx+R*math.cos(a), cy+R*math.sin(a),
                             fill=_ca(C["cyan"], "09"), width=1,
                             tags="static")

        # Anillos de referencia
        for frac, alpha in [(1.0,"15"),(0.75,"0f"),(0.50,"0b"),(0.25,"08")]:
            r = R * frac
            self.create_oval(cx-r, cy-r, cx+r, cy+r,
                             outline=_ca(C["teal"], alpha),
                             width=1, tags="static")

        # Divisores de sector
        for chrom in self.CHROMS:
            a_rad = math.radians(self._sector_start[chrom])
            self.create_line(cx+r_inner*math.cos(a_rad),
                             cy+r_inner*math.sin(a_rad),
                             cx+R*math.cos(a_rad),
                             cy+R*math.sin(a_rad),
                             fill=_ca(C["cyan"], "14"), width=1,
                             tags="static")

        # Nodos de borde y etiquetas fijas
        r_lbl  = R + 12
        r_node = R + 2
        # Set de etiquetas adaptado a la especie en curso. Para humano (default)
        # mantiene EXACTAMENTE las etiquetas originales; para cualquier otra
        # especie auto-genera ~8 etiquetas espaciadas más primera y última.
        _HUMAN_DEFAULT_CHROMS = [str(i) for i in range(1, 23)] + ["X", "Y"]
        if list(self.CHROMS) == _HUMAN_DEFAULT_CHROMS:
            _LABEL_SET = {"1","5","10","15","20","X","Y","22"}
        else:
            n = len(self.CHROMS)
            step = max(1, n // 8)
            _LABEL_SET = set(self.CHROMS[::step])
            if self.CHROMS:
                _LABEL_SET.add(self.CHROMS[0])
                _LABEL_SET.add(self.CHROMS[-1])
        # Compartir con _update_sector para que recolore solo las etiquetas
        # que efectivamente fueron dibujadas.
        self._labeled_chroms = _LABEL_SET
        for chrom in self.CHROMS:
            mid_a = math.radians(
                self._sector_start[chrom] + self._sector_extent[chrom]/2)
            nx = cx + r_node*math.cos(mid_a)
            ny = cy + r_node*math.sin(mid_a)
            self.create_oval(nx-2, ny-2, nx+2, ny+2,
                             fill=C["border_d"], outline="",
                             tags=f"node_{chrom}")   # tag individual para actualizar
            if chrom in _LABEL_SET:
                self.create_text(cx+r_lbl*math.cos(mid_a),
                                 cy+r_lbl*math.sin(mid_a),
                                 text=chrom,
                                 font=("Courier New", 7, "bold"),
                                 fill=C["txt_muted"], anchor="center",
                                 tags=f"lbl_{chrom}")

        # Centro vacío (se rellena con tag "center")
        self.create_oval(cx-r_inner, cy-r_inner, cx+r_inner, cy+r_inner,
                         fill=C["panel"],
                         outline=_ca(C["cyan"], "44"), width=2,
                         tags="static")
        ch_r = r_inner - 4
        for a in [0, 90, 180, 270]:
            ar = math.radians(a)
            self.create_line(cx, cy, cx+ch_r*math.cos(ar),
                             cy+ch_r*math.sin(ar),
                             fill=_ca(C["teal"], "33"), width=1,
                             tags="static")

    def _update_sector(self, chrom):
        """Redibuja el sector de UN cromosoma. Solo llamado si _dirty."""
        if chrom not in self._sector_start:
            return  # cromosoma no visible (excede max_visible o no del genoma)
        cx = self._cx; cy = self._cy; R = self._R
        r_inner = self._r_inner
        r_outer = R - 2
        tag = f"sec_{chrom}"
        self.delete(tag)

        start  = self._sector_start[chrom]
        extent = self._sector_extent[chrom]
        genes  = self._done.get(chrom, 0)
        is_cur = (chrom == self._current_chrom and self._active)

        if genes > 0:
            intensity = 0.12 + 0.88*(genes / self._max_genes)
            col = (_blend(C["cyan"], (intensity-0.5)*2, C["teal"])
                   if intensity > 0.5
                   else _blend(C["teal"], intensity*2, C["panel"]))
            fill_col    = _blend(col, intensity*0.65, C["panel"])
            outline_col = _ca(col, _hx(intensity*200))
            self.create_arc(cx-r_outer, cy-r_outer, cx+r_outer, cy+r_outer,
                            start=start, extent=extent,
                            style="pieslice", fill=fill_col,
                            outline="", tags=tag)
            self.create_arc(cx-r_outer, cy-r_outer, cx+r_outer, cy+r_outer,
                            start=start, extent=extent,
                            style="arc", outline=outline_col,
                            width=3, tags=tag)
            # Ripple — fade suave con 40 pasos
            if chrom in self._ripple:
                rf = self._ripple[chrom]
                if rf < 1.0:
                    rp  = r_outer + rf * 50
                    al  = int(200 * (1 - rf))
                    self.create_arc(cx-rp, cy-rp, cx+rp, cy+rp,
                                    start=start, extent=extent,
                                    style="arc",
                                    outline=_ca(col, f"{al:02x}"),
                                    width=2, tags=tag)
            # Actualizar nodo de borde → color completado
            self.itemconfigure(f"node_{chrom}", fill=C["emerald"])
            if chrom in self._labeled_chroms:
                self.itemconfigure(f"lbl_{chrom}", fill=C["teal"])

        elif is_cur:
            pa = 0.15 + 0.12*math.sin(self._pulse_phase*4)
            self.create_arc(cx-r_outer, cy-r_outer, cx+r_outer, cy+r_outer,
                            start=start, extent=extent, style="pieslice",
                            fill=_ca(C["amber"], _hx(pa*255)),
                            outline="", tags=tag)
            self.create_arc(cx-r_outer, cy-r_outer, cx+r_outer, cy+r_outer,
                            start=start, extent=extent,
                            style="arc", outline=C["amber"],
                            width=2, tags=tag)

    def _draw_sweep(self):
        """Línea de barrido + estela — solo en tag 'sweep'."""
        self.delete("sweep")
        if not self._active:
            return
        cx = self._cx; cy = self._cy; R = self._R; r_inner = self._r_inner
        r_outer = R - 2
        sweep_rad = math.radians(self._angle_float)

        # Estela de 90 grados, opacidad decreciente suave
        trail_steps = 30
        for i in range(trail_steps):
            t_rad = math.radians(self._angle_float - (i+1)*3.0)
            alpha = int(55 * (1 - i/trail_steps))
            self.create_line(cx+r_inner*math.cos(t_rad),
                             cy+r_inner*math.sin(t_rad),
                             cx+r_outer*math.cos(t_rad),
                             cy+r_outer*math.sin(t_rad),
                             fill=_ca(C["cyan"], f"{alpha:02x}"),
                             width=2 if i < 5 else 1,
                             tags="sweep")

        # Línea principal con glow multicapa
        for bw, ba in [(10,"06"),(7,"0f"),(5,"22"),(3,"55"),(1,"ff")]:
            self.create_line(cx+r_inner*math.cos(sweep_rad),
                             cy+r_inner*math.sin(sweep_rad),
                             cx+r_outer*math.cos(sweep_rad),
                             cy+r_outer*math.sin(sweep_rad),
                             fill=_ca(C["cyan"], ba), width=bw,
                             capstyle="round", tags="sweep")

        # Punta brillante
        tip_x = cx + r_outer*math.cos(sweep_rad)
        tip_y = cy + r_outer*math.sin(sweep_rad)
        for tr, tc in [(9, _ca(C["cyan"],"22")), (6, _ca(C["cyan"],"55")),
                       (4, C["cyan"]), (2, C["white"])]:
            self.create_oval(tip_x-tr, tip_y-tr, tip_x+tr, tip_y+tr,
                             fill=tc, outline="", tags="sweep")

    def _draw_center(self):
        """Texto del centro — tag 'center', redibujado cuando cambia."""
        self.delete("center")
        cx = self._cx; cy = self._cy
        n_done = len(self._done)
        # Truncado de nombres largos (scaffolds suelen ser largos: "ATCQ01000001.1")
        def _fit_name(name, max_chars=10):
            s = str(name)
            if len(s) <= max_chars:
                return s
            # Truncado con elipsis al final
            return s[:max_chars-1] + "…"
        # Tamaño de fuente del contador adaptado al número de dígitos:
        # "24/24" ok a 11pt; "1478/1478" cabe a 7pt en el círculo interno.
        counter = f"{n_done}/{self.N}"
        cnt_size = 11 if len(counter) <= 6 else (9 if len(counter) <= 9 else 7)
        if self._active and self._current_chrom:
            chrom_disp = _fit_name(self._current_chrom, max_chars=11)
            chr_size   = 10 if len(chrom_disp) <= 6 else (8 if len(chrom_disp) <= 9 else 7)
            self.create_text(cx, cy-14, text="SCANNING",
                             font=("Courier New", 7, "bold"),
                             fill=C["amber"], tags="center")
            self.create_text(cx, cy-2,
                             text=f"CHR {chrom_disp}",
                             font=("Courier New", chr_size, "bold"),
                             fill=C["amber"], tags="center")
            self.create_text(cx, cy+11,
                             text=f"{self._done.get(self._current_chrom, 0):,}g",
                             font=("Courier New", 8),
                             fill=_ca(C["amber"], "bb"), tags="center")
        elif not self._active and n_done > 0:
            self.create_text(cx, cy-8, text="COMPLETE",
                             font=("Courier New", 7, "bold"),
                             fill=C["emerald"], tags="center")
            self.create_text(cx, cy+5,
                             text=counter,
                             font=("Courier New", cnt_size, "bold"),
                             fill=C["teal"], tags="center")
        else:
            self.create_text(cx, cy-5,
                             text=counter,
                             font=("Courier New", cnt_size, "bold"),
                             fill=C["cyan"], tags="center")
            self.create_text(cx, cy+8, text="CHR",
                             font=("Courier New", 7, "bold"),
                             fill=_ca(C["cyan"], "77"), tags="center")

    def _animate(self):
        visible = self.winfo_ismapped()

        if self._active:
            # Aceleración suave de la velocidad angular
            self._angle_vel  = min(self._angle_vel + 0.12, 2.2)
        else:
            self._angle_vel = max(self._angle_vel - 0.08, 0.0)

        self._angle_float  = (self._angle_float + self._angle_vel) % 360
        self._pulse_phase += 0.07

        # Avanzar ripple (0 → 1 en ~40 frames a 16ms = 640ms)
        for c in list(self._ripple.keys()):
            self._ripple[c] += 0.025
            if self._ripple[c] >= 1.0:
                del self._ripple[c]
            else:
                self._dirty_chroms.add(c)

        if visible:
            # Sectores sucios
            if self._all_dirty:
                for c in self.CHROMS:
                    self._update_sector(c)
                self._all_dirty = False
            else:
                for c in self._dirty_chroms:
                    self._update_sector(c)

            # Dibujar sweep y cromosoma activo encima
            if self._current_chrom:
                self._dirty_chroms.add(self._current_chrom)
            self._dirty_chroms.clear()

            self._draw_sweep()
            self._draw_center()

        rate = (self.FPS_ACTIVE if self._active
                else (self.FPS_IDLE if visible else self.FPS_HIDDEN))
        self.after(rate, self._animate)


# ══════════════════════════════════════════════════════════════════════════════
#  WIDGET: ActivityMatrix  — 60 fps, dirty-cell tracking, calculus panel cache
# ══════════════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════════════════
#  WIDGET: DNAHelixBar
# ══════════════════════════════════════════════════════════════════════════════

class DNAHelixBar(tk.Canvas):
    _RUNG_COLS = [
        (C["cyan"],    C["amber"]),
        (C["teal"],    C["violet"]),
        (C["amber"],   C["teal"]),
        (C["violet"],  C["cyan"]),
    ]

    def __init__(self, parent, height=36, **kw):
        super().__init__(parent, height=height,
                         bg=C["void"], highlightthickness=0, **kw)
        self._value = 0.0; self._phase = 0.0
        self.bind("<Configure>", lambda e: self._draw())
        self._animate()

    def set_value(self, value, total):
        self._value = max(0.0, min(1.0, value/max(total,1)))
        self._draw()

    def _draw(self):
        self.delete("all")
        w = self.winfo_width() or 600; h = self.winfo_height() or 36
        if w < 20: return
        cy  = h / 2
        amp = cy - 5.0
        T   = max(w / 5.8, 46)
        fw  = w * self._value
        ph  = self._phase

        # ── Fondo ────────────────────────────────────────────────
        self.create_rectangle(0, 0, w, h, fill=C["void"], outline="")

        # ── Borde luminoso superior e inferior ───────────────────
        if fw > 2:
            self.create_line(0, 0, fw, 0,
                             fill=_ca(C["cyan"], "44"), width=1)
            self.create_line(0, h-1, fw, h-1,
                             fill=_ca(C["teal"], "44"), width=1)
        self.create_line(fw, 0, w, 0,
                         fill=_ca(C["border_dd"], "33"), width=1)
        self.create_line(fw, h-1, w, h-1,
                         fill=_ca(C["border_dd"], "33"), width=1)

        # ── Franjas de fondo animadas (efecto cinta) ─────────────
        half_T      = T / 2
        phase_shift = (ph / (2*math.pi)) * T
        stripe_x    = -(phase_shift % half_T)
        while stripe_x < w:
            sx = int(stripe_x); sw = max(2, int(T * 0.14))
            is_active = (stripe_x + sw/2) < fw
            col_s = C["teal"] if is_active else C["border_dd"]
            alp_s = "0b" if is_active else "06"
            self.create_rectangle(sx, 1, sx+sw, h-1,
                                   fill=_ca(col_s, alp_s), outline="")
            stripe_x += half_T

        # ── Eje central con pulso cromático ──────────────────────
        pulse_axis = 0.06 + 0.03 * math.sin(ph * 2.1)
        self.create_line(0, cy, w, cy,
                         fill=_ca(C["teal"], _hx(pulse_axis*255)),
                         width=1, dash=(3, 10))

        # ── Rungs (peldaños) con nucleótidos ─────────────────────
        rung_step   = T / 3.2
        phase_offset = (ph / (2*math.pi)) * T
        n_rungs     = int(w / rung_step) + 4

        for i in range(-2, n_rungs):
            xr = i*rung_step - (phase_offset % rung_step)
            if xr < -rung_step or xr > w + rung_step:
                continue
            xi = int(xr)
            a  = (xr / T) * 2 * math.pi + ph
            y1 = cy + amp * math.sin(a)
            y2 = cy - amp * math.sin(a)
            ym = (y1 + y2) / 2
            col_a, col_b = self._RUNG_COLS[abs(i) % 4]
            active = 0 < xr < fw

            if active:
                # glow multicapa
                mid_col = _blend(col_a, 0.5, col_b)
                for gw, ga in [(13,"04"),(9,"0c"),(5,"1a"),(3,"44"),(1.5,"77")]:
                    self.create_line(xi, int(y1), xi, int(y2),
                                     fill=_ca(mid_col, ga), width=gw,
                                     capstyle="round")
                # rung bicolor
                self.create_line(xi, int(y1), xi, int(ym),
                                 fill=col_a, width=2, capstyle="round")
                self.create_line(xi, int(ym), xi, int(y2),
                                 fill=col_b, width=2, capstyle="round")
                # puentes de hidrógeno (puntos centrales)
                n_hb = 3 if abs(i) % 4 in (1, 3) else 2
                for k in range(n_hb):
                    hb_y = int(y1 + (y2 - y1) * (k+1) / (n_hb+1))
                    hb_col = _blend(col_a, 0.4, col_b)
                    self.create_oval(xi-2, hb_y-2, xi+2, hb_y+2,
                                     fill=_ca(hb_col, "77"), outline="")
                    self.create_oval(xi-1, hb_y-1, xi+1, hb_y+1,
                                     fill=hb_col, outline="")
                # nucleótidos en los extremos
                for col_n, yn in [(col_a, y1), (col_b, y2)]:
                    for nr, na in [(7,"08"),(5,"1a"),(3.5,"44"),(2.5,"77")]:
                        self.create_oval(
                            xi-nr, int(yn)-nr, xi+nr, int(yn)+nr,
                            fill=_ca(col_n, na), outline="")
                    self.create_oval(xi-3, int(yn)-3, xi+3, int(yn)+3,
                                     fill=col_n, outline=_ca(col_n,"88"), width=1)
                    self.create_oval(xi-1, int(yn)-1, xi+1, int(yn)+1,
                                     fill=C["white"], outline="")
            else:
                # modo inactivo: esqueleto atenuado
                self.create_line(xi, int(y1), xi, int(y2),
                                 fill=_ca(C["border_d"], "33"), width=1)
                for yn in [y1, y2]:
                    self.create_oval(xi-1.5, int(yn)-1.5, xi+1.5, int(yn)+1.5,
                                     fill=_ca(C["border_dd"], "88"), outline="")

        # ── Hélices dobles continuas con glow degradado ──────────
        STEP = 2
        segs1_act=[]; segs2_act=[]
        segs1_dim=[]; segs2_dim=[]
        for xi in range(0, int(w) + STEP, STEP):
            a  = (xi / T) * 2 * math.pi + ph
            y1 = cy + amp * math.sin(a)
            y2 = cy - amp * math.sin(a)
            if xi <= fw:
                segs1_act.extend([xi, y1])
                segs2_act.extend([xi, y2])
            else:
                segs1_dim.extend([xi, y1])
                segs2_dim.extend([xi, y2])

        # segmentos inactivos
        if len(segs1_dim) >= 4:
            self.create_line(*segs1_dim, fill=_ca(C["border_d"], "33"),
                             width=1, smooth=True, joinstyle="round")
            self.create_line(*segs2_dim, fill=_ca(C["border_d"], "33"),
                             width=1, smooth=True, joinstyle="round")

        # segmentos activos con 6 capas de glow
        if len(segs1_act) >= 4:
            for bw, ba in [(12,"04"),(8,"0a"),(5,"18"),(3,"44"),(2,"88"),(1,"dd")]:
                self.create_line(*segs1_act, fill=_ca(C["cyan"], ba),
                                 width=bw, smooth=True, joinstyle="round")
                self.create_line(*segs2_act, fill=_ca(C["teal"], ba),
                                 width=bw, smooth=True, joinstyle="round")

        # ── Backbone dots (fosfodisester) ────────────────────────
        bb_step = T / 6.0
        for xi_f in range(0, int(min(fw, w)), max(1, int(bb_step))):
            a  = (xi_f / T) * 2 * math.pi + ph
            y1 = cy + amp * math.sin(a)
            y2 = cy - amp * math.sin(a)
            # punto entre nucleótidos a lo largo del backbone
            self.create_oval(xi_f-1, int(y1)-1, xi_f+1, int(y1)+1,
                             fill=_ca(C["cyan"], "33"), outline="")
            self.create_oval(xi_f-1, int(y2)-1, xi_f+1, int(y2)+1,
                             fill=_ca(C["teal"], "33"), outline="")

        # ── Partículas flotantes de lectura (gene reading) ───────
        if fw > 20:
            n_particles = min(8, max(3, int(fw / 80)))
            for pi in range(n_particles):
                px = (fw * (0.1 + 0.8*(pi/(n_particles)))) + \
                     12*math.sin(ph*1.5 + pi*2.1)
                px = max(4, min(px, fw - 4))
                a_p = (px / T) * 2 * math.pi + ph
                # partícula viaja entre las dos hélices
                t_blend = 0.5 + 0.45*math.sin(ph*0.8 + pi*3.7)
                py = cy + amp * math.sin(a_p) * (1 - 2*t_blend)
                p_alpha = 0.25 + 0.35*math.sin(ph*0.5 + pi*1.3)
                for pr, palp in [(4, _hx(p_alpha*30)),
                                  (2.5, _hx(p_alpha*80)),
                                  (1.2, _hx(p_alpha*180))]:
                    self.create_oval(px-pr, py-pr, px+pr, py+pr,
                                     fill=_ca(C["emerald"], palp), outline="")

        # ── Marcador de progreso (frente de avance) ──────────────
        if 6 < fw < w - 6:
            fx  = int(fw)
            a_f = (fw / T) * 2 * math.pi + ph
            y1f = cy + amp * math.sin(a_f)
            y2f = cy - amp * math.sin(a_f)
            y_lo, y_hi = min(y1f, y2f), max(y1f, y2f)

            # barra vertical de progreso con glow emerald
            for gw, ga in [(18,"03"),(12,"08"),(8,"14"),(4,"33"),(2,"77"),(1,"dd")]:
                self.create_line(fx, int(y_lo)-5, fx, int(y_hi)+5,
                                 fill=_ca(C["emerald"], ga), width=gw,
                                 capstyle="round")

            # chevron derecho multi-capa
            for dx, alp in [(5,"77"),(9,"44"),(14,"22"),(20,"0c")]:
                mid_y = (y_lo + y_hi) / 2
                self.create_line(fx+dx, int(mid_y-7),
                                 fx,    int(mid_y),
                                 fx+dx, int(mid_y+7),
                                 fill=_ca(C["emerald"], alp), width=1.2)

            # nodos donde la hélice cruza el marcador
            for col_f, yf in [(C["cyan"], y1f), (C["teal"], y2f)]:
                for nr2, na2 in [(9,"08"),(6,"1a"),(4,"44"),(2.5,"88")]:
                    self.create_oval(fx-nr2, int(yf)-nr2,
                                     fx+nr2, int(yf)+nr2,
                                     fill=_ca(col_f, na2), outline="")
                self.create_oval(fx-3, int(yf)-3, fx+3, int(yf)+3,
                                 fill=col_f, outline="")
                self.create_oval(fx-1, int(yf)-1, fx+1, int(yf)+1,
                                 fill=C["white"], outline="")

        # ── Bordes laterales ─────────────────────────────────────
        self.create_line(0, 0, 0, h, fill=_ca(C["cyan"], "55"), width=2)
        if fw >= w - 2:
            self.create_line(w-1, 0, w-1, h,
                             fill=_ca(C["emerald"], "88"), width=2)

    def _animate(self):
        self._phase = (self._phase + 0.060) % (2 * math.pi)
        self._draw()
        rate = 45 if (self._value > 0.001 and self._value < 0.999) else 300
        self.after(rate, self._animate)


# ══════════════════════════════════════════════════════════════════════════════
#  WIDGET: HelixProgressBar  ·  NucleotideMatrix
# ══════════════════════════════════════════════════════════════════════════════

class HelixProgressBar(tk.Canvas):
    def __init__(self, parent, color=C["cyan"], height=10, **kw):
        super().__init__(parent, height=height,
                         bg=C["panel2"], highlightthickness=0, **kw)
        self.color = color; self._value = 0.0; self._phase = 0.0
        self.bind("<Configure>", lambda e: self._draw())
        self._animate()

    def set_value(self, value, total):
        self._value = value/max(total,1); self._draw()

    def _draw(self):
        self.delete("all")
        w = self.winfo_width() or 200; h = self.winfo_height() or 10
        self.create_rectangle(0, 0, w, h, fill=C["bg2"], outline="")
        self.create_rectangle(0, 0, w, h, fill="",
                               outline=_ca(self.color,"22"))
        for t in [0.25, 0.5, 0.75]:
            self.create_line(int(w*t), 0, int(w*t), h,
                             fill=_ca(C["cyan"],"18"), width=1)
        fw = int(w * self._value)
        if fw > 2:
            col_t = _blend(self.color, 0.08, C["bg2"])
            self.create_rectangle(0, 0, fw, h, fill=col_t, outline="")
            steps = min(fw, 4)
            step_w = fw // max(steps, 1)
            for i in range(steps):
                alpha_v = 0.15 + 0.55 * (i / max(steps-1, 1))
                self.create_rectangle(
                    i*step_w, 0, min((i+1)*step_w, fw), h,
                    fill=_ca(self.color, _hx(alpha_v*255)), outline="")
            self.create_rectangle(max(0, fw-8), 0, fw, h,
                                   fill=_ca(self.color,"cc"), outline="")
            self.create_rectangle(max(0, fw-2), 0, fw, h,
                                   fill=C["emerald"], outline="")
        n_nodes = max(2, fw//14)
        if fw > 0:
            for j in range(n_nodes+1):
                xp = int(j * fw / max(n_nodes, 1))
                yp = int(h/2 + (h/2-2)*math.sin(self._phase + j*math.pi/3))
                self.create_oval(xp-2, yp-2, xp+2, yp+2,
                                 fill=_ca(self.color,"99"), outline="")

    def _animate(self):
        visible = self.winfo_ismapped()
        if visible:
            self._phase += 0.14; self._draw()
        self.after(70 if visible else 500, self._animate)


class NucleotideMatrix(tk.Canvas):
    def __init__(self, parent, cols=16, rows=3, color=C["cyan"], **kw):
        super().__init__(parent, width=cols*10+2, height=rows*10+2,
                         bg=C["panel2"], highlightthickness=0, **kw)
        self.cols = cols; self.rows = rows; self.color = color; self._fill = 0.0
        self._draw()

    def set_fill(self, v):
        self._fill = max(0.0, min(1.0, v)); self._draw()

    def _draw(self):
        self.delete("all")
        total = self.cols*self.rows; on = round(self._fill*total)
        for i in range(total):
            x = (i%self.cols)*10+5; y = (i//self.cols)*10+5
            if i < on:
                self.create_oval(x-4,y-4,x+4,y+4,
                                 fill=_ca(self.color,"22"), outline="")
                self.create_oval(x-2,y-2,x+2,y+2,
                                 fill=self.color, outline="")
            else:
                self.create_oval(x-2,y-2,x+2,y+2,
                                 fill=C["border_dd"], outline="")


# ══════════════════════════════════════════════════════════════════════════════
#  UI PRIMITIVES
# ══════════════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════════════════
#  WIDGET: ActivityMatrix  —  STANDBY / Pipeline activity monitor  v6-ULTRA
# ══════════════════════════════════════════════════════════════════════════════

class ActivityMatrix(tk.Frame):
    """
    Monitor de actividad del pipeline — v8 fluido.
    Mejoras vs v7:
      • random importado a nivel de módulo (cero GC por frame)
      • Matriz de celdas: solo redibuja las celdas que cambiaron (_dirty_cells)
      • Panel de cálculos: items de texto creados UNA vez con tag por fila,
        actualizados con itemconfigure() — cero delete/recreate
      • Escáner: movimiento por inercia con lerp suave
      • Barra inferior: sub-pixel precision con lerp
      • Beacon pulsante en esquina: independiente del redibujado principal
    """
    COLS = 28
    ROWS = 5
    CELL = 7
    GAP  = 1
    STEP = CELL + GAP
    FPS_ACTIVE  = 16   # ~60 fps durante pipeline
    FPS_STANDBY = 33   # ~30 fps en reposo — animación idle visible
    FPS_IDLE    = 80   # cuando no está mapeado
    FPS_HIDDEN  = 500  # minimizado

    def __init__(self, parent, **kw):
        super().__init__(parent, bg=C["bg"], **kw)
        M_W = 6 + self.COLS * self.STEP + 20
        M_H = 6 + self.ROWS * self.STEP + 20
        C_W = 340
        self._M_W = M_W; self._M_H = M_H; self._C_W = C_W
        self._GX = 4; self._GY = 4

        # ── Dos canvas ────────────────────────────────────────────
        self._matrix = tk.Canvas(self, width=M_W, height=M_H,
                                 bg=C["bg"], highlightthickness=0)
        self._matrix.pack(side="left", padx=(0, 2))
        self._calcs  = tk.Canvas(self, width=C_W, height=M_H,
                                 bg=C["bg"], highlightthickness=0)
        self._calcs.pack(side="left", fill="x", expand=True)

        # ── Estado de la matriz ───────────────────────────────────
        self._cells         = [[0.0]*self.COLS for _ in range(self.ROWS)]
        self._flicker       = [[0.0]*self.COLS for _ in range(self.ROWS)]
        self._dirty_cells   = set()   # (r,c) que cambiaron
        self._cell_items    = {}      # (r,c) → canvas item ids

        # ── Estado general ────────────────────────────────────────
        self._phase         = 0.0
        self._scan_x_target = 0.0    # posición objetivo del scanner
        self._scan_x        = 0.0    # posición actual (lerp)
        self._prog_target   = 0.0    # fracción de progreso objetivo
        self._prog_current  = 0.0    # fracción actual (lerp)
        self._active        = False
        self._chrom         = ""
        self._chrom_idx     = 0
        self._chrom_total   = 0
        self._genes_total   = 0
        self._genes_chrom   = 0
        self._windows_done  = 0
        self._windows_total = 1
        self._ticker_msg    = "STANDBY"
        self._last_col      = 0
        self._comp_lines:   list = []
        self._comp_scroll   = 0.0
        self._calcs_dirty   = True   # forzar redibujado completo del panel

        # Métricas estadísticas
        self._math_n_ig    = 0;   self._math_n_meg   = 0
        self._math_n_seg   = 0;   self._math_welch_t = 0.0
        self._math_welch_p = 1.0; self._math_mw_u    = 0.0
        self._math_mw_p    = 1.0; self._math_cliffs  = 0.0
        self._math_chi2    = 0.0; self._math_p_chi2  = 1.0
        self._math_mu_ig   = 0.0; self._math_mu_meg  = 0.0
        self._math_fdr     = 1.0

        self._row_cols = [
            C["teal"], C["teal"], C["cyan"], C["cyan"], C["violet"],
        ]
        # Onda idle — siempre activa aunque no haya pipeline
        self._idle_wave  = 0.0   # posición de la ola (0..COLS)
        self._idle_phase = 0.0   # fase para pulso vertical

        # ── Pre-dibujo del fondo estático de la matriz ────────────
        self._draw_matrix_static()
        # ── Pre-dibujo del fondo estático del panel calc ──────────
        self._draw_calcs_static()
        # ── Crear items de celda una sola vez ─────────────────────
        self._create_cell_items()
        self._animate()

    # ── API pública ────────────────────────────────────────────────
    def set_active(self, v):
        self._active = v
        if v:
            # ── Boot-up: sembrar todas las celdas con gradiente inicial ──────
            # Permite que el modo-pipeline (flicker sobre celdas > 0.1) sea
            # visible de inmediato sin esperar a set_window_progress().
            for r in range(self.ROWS):
                row_bias = 0.08 * r
                for c in range(self.COLS):
                    col_frac  = c / max(self.COLS - 1, 1)
                    seed_val  = 0.18 + 0.42 * col_frac + row_bias
                    seed_val += _random.uniform(-0.06, 0.06)
                    self._cells[r][c]   = max(0.12, min(seed_val, 0.95))
                    self._flicker[r][c] = _random.uniform(0.0, 0.18)
                    self._dirty_cells.add((r, c))
            self._ticker_msg  = "SCANNING"
            self._calcs_dirty = True
        else:
            self._ticker_msg = "COMPLETE"
            self._push_comp("─── PIPELINE COMPLETE ───", C["emerald"])
            self._calcs_dirty = True

    def set_chrom(self, chrom, idx, total):
        self._chrom       = chrom
        self._chrom_idx   = idx
        self._chrom_total = total
        row = (idx - 1) % self.ROWS
        for c in range(self.COLS):
            if self._cells[row][c] != 0.0:
                self._cells[row][c] = 0.0
                self._dirty_cells.add((row, c))
        self._scan_x_target = 0.0
        self._last_col      = 0
        self._push_comp(f"▶ Chr {chrom}  [{idx}/{total}]  scanning...", C["cyan"])
        self._calcs_dirty = True

    def set_window_progress(self, done, total):
        self._windows_done  = done
        self._windows_total = max(total, 1)
        frac = done / self._windows_total
        col  = min(int(frac * self.COLS), self.COLS - 1)
        self._scan_x_target = frac * self.COLS
        self._prog_target   = frac
        for r in range(self.ROWS):
            for c in range(col + 1):
                old = self._cells[r][c]
                new = max(old, 0.15 + 0.85*(c / self.COLS))
                if abs(new - old) > 0.005:
                    self._cells[r][c] = new
                    self._dirty_cells.add((r, c))
        self._last_col = col

    def update_genes(self, n):
        self._genes_chrom = n
        self._genes_total += n
        self._ticker_msg  = f"CHR {self._chrom} · {n:,}g"
        self._push_comp(
            f"  ✔ Chr {self._chrom}: {n:,} genes  (Σ {self._genes_total:,})",
            C["teal"])
        self._calcs_dirty = True

    def update_math_stats(self, stats: dict):
        for attr, key in [
            ("_math_n_ig",    "n_ig"),   ("_math_n_meg",   "n_meg"),
            ("_math_n_seg",   "n_seg"),  ("_math_welch_t", "welch_t"),
            ("_math_welch_p", "welch_p"),("_math_mw_u",    "mw_u"),
            ("_math_mw_p",    "mw_p"),   ("_math_cliffs",  "cliffs"),
            ("_math_chi2",    "chi2"),   ("_math_p_chi2",  "p_chi2"),
            ("_math_mu_ig",   "mu_ig"),  ("_math_mu_meg",  "mu_meg"),
            ("_math_fdr",     "fdr"),
        ]:
            if key in stats:
                setattr(self, attr, stats[key])
        self._calcs_dirty = True

    def reset(self):
        self._cells         = [[0.0]*self.COLS for _ in range(self.ROWS)]
        self._flicker       = [[0.0]*self.COLS for _ in range(self.ROWS)]
        self._dirty_cells   = set(
            (r,c) for r in range(self.ROWS) for c in range(self.COLS))
        self._scan_x        = 0.0; self._scan_x_target = 0.0
        self._prog_current  = 0.0; self._prog_target   = 0.0
        self._genes_total   = 0;   self._genes_chrom   = 0
        self._chrom         = "";  self._chrom_idx     = 0; self._chrom_total = 0
        self._ticker_msg    = "STANDBY"
        self._comp_lines    = []
        self._comp_scroll   = 0.0
        self._math_n_ig     = 0;   self._math_n_meg    = 0; self._math_n_seg = 0
        self._math_welch_t  = 0.0; self._math_welch_p  = 1.0
        self._math_mw_u     = 0.0; self._math_mw_p     = 1.0
        self._math_cliffs   = 0.0; self._math_chi2     = 0.0; self._math_p_chi2 = 1.0
        self._math_mu_ig    = 0.0; self._math_mu_meg   = 0.0; self._math_fdr    = 1.0
        self._calcs_dirty   = True

    def push_computation(self, text, color=None):
        self._push_comp(text, color or C["txt_dim"])

    def _push_comp(self, text, color):
        self._comp_lines.append({"t": text, "c": color, "age": 0.0})
        if len(self._comp_lines) > 80:
            self._comp_lines = self._comp_lines[-80:]
        self._calcs_dirty = True

    # ── Pre-render estático de la matriz ──────────────────────────
    def _draw_matrix_static(self):
        cv = self._matrix
        W  = self._M_W; H = self._M_H
        cv.create_rectangle(0, 0, W, H, fill=C["panel"],
                            outline="", tags="static")
        cv.create_rectangle(0, 0, W, H, fill="",
                            outline=_ca(C["cyan"], "18"),
                            width=1, tags="static")
        cv.create_rectangle(0, 0, W, 2,
                            fill=_ca(C["cyan"], "22"),
                            outline="", tags="static")
        # Marcadores de fila
        for r in range(self.ROWS):
            y_mid = self._GY + r*self.STEP + self.CELL//2
            cv.create_oval(self._GX-6, y_mid-1.5,
                           self._GX-2, y_mid+1.5,
                           fill=_ca(self._row_cols[r], "55"),
                           outline="", tags="static")

    # ── Crear items de celda (rect. y glow) UNA VEZ ──────────────
    def _create_cell_items(self):
        """
        Crea un rectangle por celda. Se actualiza con itemconfigure()
        cada frame en lugar de delete+create.
        """
        cv = self._matrix
        GX = self._GX; GY = self._GY
        for r in range(self.ROWS):
            for c in range(self.COLS):
                x0 = GX + c*self.STEP; y0 = GY + r*self.STEP
                x1 = x0 + self.CELL;  y1 = y0 + self.CELL
                # Fondo de celda (siempre visible)
                item = cv.create_rectangle(
                    x0, y0, x1, y1,
                    fill=C["border_dd"], outline="",
                    tags=f"cell_{r}_{c}")
                self._cell_items[(r, c)] = item
        # Inicialmente todas dirty
        self._dirty_cells = set(
            (r,c) for r in range(self.ROWS) for c in range(self.COLS))

    def _update_dirty_cells(self):
        """Actualiza solo las celdas que cambiaron desde el último frame."""
        cv    = self._matrix
        GX    = self._GX; GY = self._GY
        phase = self._phase

        for (r, c) in self._dirty_cells:
            x0 = GX + c*self.STEP; y0 = GY + r*self.STEP
            x1 = x0 + self.CELL;  y1 = y0 + self.CELL
            v     = self._cells[r][c]
            fk    = self._flicker[r][c]
            v_eff = min(1.0, v + fk)
            base  = self._row_cols[r]

            if v_eff < 0.02:
                fill = C["border_dd"]
            else:
                bright = 0.12 + 0.88 * v_eff
                fill   = _blend(base, bright, C["panel"])

            cv.itemconfigure(self._cell_items[(r, c)], fill=fill)

            # Glow y detalles — solo para celdas brillantes
            cv.delete(f"cell_glow_{r}_{c}")     # limpiar glow anterior
            if v_eff > 0.25:
                for pad_g, ga in [(2,"06"),(1,"12")]:
                    cv.create_rectangle(
                        x0-pad_g, y0-pad_g, x1+pad_g, y1+pad_g,
                        fill=_ca(base, _hx(v_eff*int(ga,16))),
                        outline="", tags=f"cell_glow_{r}_{c}")
            if v_eff > 0.55:
                cv.create_rectangle(x0, y0, x0+2, y0+2,
                                    fill=_ca(C["emerald"], "cc"),
                                    outline="",
                                    tags=f"cell_glow_{r}_{c}")
            if v_eff > 0.85:
                mx, my = (x0+x1)//2, (y0+y1)//2
                cv.create_polygon(mx, my-2, mx+2, my, mx, my+2, mx-2, my,
                                  fill=C["white"], outline="",
                                  tags=f"cell_glow_{r}_{c}")

        self._dirty_cells.clear()

    def _draw_scanner(self):
        """Escáner + barra de progreso + ticker — tags 'scan' y 'bar'."""
        cv = self._matrix
        GX = self._GX; GY = self._GY
        cv.delete("scan")
        cv.delete("bar_dyn")
        cv.delete("ticker")
        cv.delete("beacon")

        if self._scan_x > 0.2:
            sx = GX + self._scan_x * self.STEP
            # Glow multicapa del escáner
            for bw, ba in [(10,"03"),(7,"08"),(4,"18"),(2,"55"),(1,"cc")]:
                cv.create_line(sx, GY-2, sx,
                               GY + self.ROWS*self.STEP + 2,
                               fill=_ca(C["emerald"], ba), width=bw,
                               capstyle="round", tags="scan")
            cv.create_polygon(sx-3, GY-2, sx+3, GY-2, sx, GY+3,
                              fill=C["emerald"], outline="", tags="scan")

        # Barra de progreso inferior (sub-pixel con lerp)
        bar_y = GY + self.ROWS*self.STEP + 4
        bar_w = self.COLS * self.STEP
        frac  = self._prog_current
        if frac > 0:
            fw = int(bar_w * frac)
            cv.create_rectangle(GX, bar_y, GX+fw, bar_y+4,
                                fill=_ca(C["teal"], "88"),
                                outline="", tags="bar_dyn")
            cv.create_rectangle(GX+fw-2, bar_y, GX+fw, bar_y+4,
                                fill=C["emerald"], outline="",
                                tags="bar_dyn")

        # Ticker texto — muestra IDLE MATRIX en standby
        ticker_text = self._ticker_msg
        if not self._active and self._windows_done == 0:
            blink_chars = ["▪▪▪▫▫▫", "▫▪▪▪▫▫", "▫▫▪▪▪▫", "▫▫▫▪▪▪", "▫▫▫▫▪▪", "▫▫▫▫▫▪"]
            idx = int(self._phase * 0.04) % len(blink_chars)
            ticker_text = f"MATRIX IDLE  {blink_chars[idx]}"
        cv.create_text(GX, bar_y+9, text=ticker_text,
                       font=("Courier New", 6, "bold"),
                       fill=_ca(C["cyan"], "99"), anchor="w",
                       tags="ticker")

        # Beacon pulsante en esquina
        W   = self._M_W
        pr  = 2.5 + 1.5*abs(math.sin(self._phase*0.055))
        col = C["emerald"] if self._active else C["txt_muted"]
        cv.create_oval(W-8-pr, 4, W-8+pr, 4+pr*2,
                       fill=_ca(col, "44" if self._active else "22"),
                       outline="", tags="beacon")
        cv.create_oval(W-8-1.5, 5.5, W-8+1.5, 8.5,
                       fill=col, outline="", tags="beacon")

    # ── Panel de cálculos — fondo estático ───────────────────────
    def _draw_calcs_static(self):
        cv = self._calcs; W = self._C_W; H = self._M_H
        cv.create_rectangle(0, 0, W, H, fill=C["panel"],
                            outline="", tags="static")
        cv.create_rectangle(0, 0, W, H, fill="",
                            outline=_ca(C["cyan"], "1a"),
                            width=1, tags="static")
        cv.create_rectangle(0, 0, W, 2,
                            fill=_ca(C["violet"], "55"),
                            outline="", tags="static")
        # Header fijo
        cv.create_rectangle(0, 0, W, 14, fill=C["panel2"],
                            outline="", tags="static")
        cv.create_text(6, 7, text="∑ STATISTICAL ENGINE  ·  REAL-TIME",
                       font=("Courier New", 6, "bold"),
                       fill=_ca(C["orchid"], "cc"),
                       anchor="w", tags="static")
        cv.create_line(0, 14, W, 14,
                       fill=_ca(C["violet"], "22"),
                       width=1, tags="static")

    def _draw_calcs_dynamic(self):
        """
        Statistical engine panel — real-time computation diagram.
        60 fps continuous redraw when active (matches ChromoScope/SysDial).
        When idle, only redraws on data events (_calcs_dirty flag).
        """
        if not self._active and not self._calcs_dirty:
            return
        # Always redraw when active — ensures animated bars/gauges are fluid
        self._calcs_dirty = True
        cv = self._calcs; W = self._C_W; H = self._M_H
        ph = self._phase
        cv.delete("dyn_calc")

        # ── Animated status dot ───────────────────────────────────────────
        dot_col = C["orchid"] if self._active else C["txt_muted"]
        ps = 3 + 1.4*abs(math.sin(ph*0.055)) if self._active else 2.5
        cv.create_oval(W-12-ps, 7-ps, W-12+ps, 7+ps,
                       fill=_ca(dot_col, "33"), outline="", tags="dyn_calc")
        cv.create_oval(W-12-1.5, 5.5, W-12+1.5, 8.5,
                       fill=dot_col, outline="", tags="dyn_calc")

        # ── Derived statistics ────────────────────────────────────────────
        n_ig  = self._math_n_ig;  n_meg = self._math_n_meg
        n_seg = self._math_n_seg; n_tot = max(n_ig + n_meg + n_seg, 1)
        win_d = self._windows_done; win_t = max(self._windows_total, 1)
        win_frac = win_d / win_t
        f_ig  = n_ig / n_tot; f_meg = n_meg / n_tot; f_seg = n_seg / n_tot
        _t = self._math_welch_t; _p_t = self._math_welch_p
        _u = self._math_mw_u;    _p_m = self._math_mw_p
        _cd = self._math_cliffs; _chi2 = self._math_chi2
        _p_c = self._math_p_chi2; _fdr  = self._math_fdr
        _mu_ig = self._math_mu_ig; _mu_m = self._math_mu_meg
        _p_t_str = f"{_p_t:.2e}" if _p_t < 0.001 else f"{_p_t:.4f}"
        _sig_t = "✱✱" if _p_t < 0.001 else "✱" if _p_t < 0.05 else "ns"
        _sig_m = "✱✱" if _p_m < 0.001 else "✱" if _p_m < 0.05 else "ns"

        col_ig  = C["teal"];  col_meg = C["cyan"]; col_seg = C["violet"]
        col_hi  = C["rose"];  col_lbl = C["txt_muted"]
        col_val = C["lavender"]; col_dim = _ca(C["cyan"], "55")
        col_sec = C["orchid"]

        y = 17; line_h = 9.5

        def sec(text, col):
            nonlocal y
            cv.create_rectangle(0, y-1, W, y+line_h+1,
                                 fill=_ca(col, "0c"), outline="", tags="dyn_calc")
            cv.create_text(4, y+1, text=text,
                           font=("Courier New", 6, "bold"),
                           fill=col, anchor="nw", tags="dyn_calc")
            y += line_h + 1

        def row(key, formula, value, vcol=None):
            nonlocal y
            cv.create_text(4,    y, text=key,
                           font=("Courier New", 6), fill=col_lbl,
                           anchor="nw", tags="dyn_calc")
            cv.create_text(52,   y, text=formula,
                           font=("Courier New", 5), fill=col_dim,
                           anchor="nw", tags="dyn_calc")
            cv.create_text(W-4,  y, text=value,
                           font=("Courier New", 6, "bold"),
                           fill=vcol or col_val, anchor="ne", tags="dyn_calc")
            y += line_h

        def mini_bar(label, value, max_val, col, show_pct=True):
            """Horizontal animated bar chart row."""
            nonlocal y
            BX = 48; BW = W - BX - 28; BH = 6
            cv.create_text(4, y+1, text=label,
                           font=("Courier New", 5), fill=col_lbl,
                           anchor="nw", tags="dyn_calc")
            # bar background
            cv.create_rectangle(BX, y+1, BX+BW, y+BH,
                                 fill=_ca(col, "1a"), outline="", tags="dyn_calc")
            # animated fill with pulse
            frac = min(value / max(max_val, 1), 1.0)
            if frac > 0:
                pulse = 0.85 + 0.15*math.sin(ph*0.08)
                fw = int(BW * frac * pulse)
                cv.create_rectangle(BX, y+1, BX+fw, y+BH,
                                     fill=_ca(col, "66"), outline="", tags="dyn_calc")
                cv.create_rectangle(BX+max(fw-3,0), y+1, BX+fw, y+BH,
                                     fill=col, outline="", tags="dyn_calc")
            if show_pct:
                pct = f"{value:,}" if isinstance(value, int) else f"{frac*100:.1f}%"
                cv.create_text(BX+BW+4, y+2, text=pct,
                               font=("Courier New", 5, "bold"),
                               fill=col, anchor="nw", tags="dyn_calc")
            y += line_h

        def p_gauge(p_val, label):
            """Mini p-value gauge: circle fill shows significance."""
            nonlocal y
            R = 4; CX = 12; CY = y + 4
            sig_col = (col_hi if p_val < 0.001 else
                       C["amber"] if p_val < 0.05 else col_lbl)
            fill_frac = max(0, 1.0 - p_val) * (0.9 + 0.1*math.sin(ph*0.07))
            cv.create_oval(CX-R, CY-R, CX+R, CY+R,
                           fill=_ca(sig_col, "22"), outline=_ca(sig_col,"55"),
                           tags="dyn_calc")
            if fill_frac > 0.05:
                # Filled arc
                extent = fill_frac * 359
                cv.create_arc(CX-R+1, CY-R+1, CX+R-1, CY+R-1,
                              start=90, extent=-extent, style="pieslice",
                              fill=sig_col, outline="", tags="dyn_calc")
            sig_str = "✱✱" if p_val < 0.001 else "✱" if p_val < 0.05 else "ns"
            cv.create_text(CX+R+3, CY, text=f"{label} {sig_str}",
                           font=("Courier New", 5, "bold"),
                           fill=sig_col, anchor="w", tags="dyn_calc")
            cv.create_text(W-4, CY, text=f"p={p_val:.2e}" if p_val<0.01 else f"p={p_val:.4f}",
                           font=("Courier New", 5), fill=sig_col,
                           anchor="e", tags="dyn_calc")
            y += line_h + 1

        def sep():
            nonlocal y
            cv.create_line(4, y+1, W-4, y+1,
                           fill=_ca(C["cyan"], "18"), tags="dyn_calc")
            y += 3

        # ── BLOCK 1: Gene count bars (animated) ───────────────────────────
        sec("▸ GENE COUNT DISTRIBUTION", _ca(col_seg, "cc"))
        mini_bar("n(IG)",  n_ig,  n_tot, col_ig)
        mini_bar("n(MEG)", n_meg, n_tot, col_meg)
        mini_bar("n(SEG)", n_seg, n_tot, col_seg)
        row("f(IG)", "IG/total",  f"{f_ig:.3f}", col_ig)
        row("μ(IG)", "mean len",  f"{_mu_ig:.0f}bp", col_ig)
        row("μ(MEG)","mean len",  f"{_mu_m:.0f}bp", col_meg)
        sep()

        # ── BLOCK 2: Welch T-test with p-gauge ────────────────────────────
        sec("▸ WELCH T-TEST", _ca(col_val, "cc"))
        row("T",  "t-statistic", f"{_t:.4f}", col_val)
        p_gauge(_p_t, "T-test")
        sep()

        # ── BLOCK 3: Mann-Whitney with gauge ──────────────────────────────
        sec("▸ MANN-WHITNEY U", _ca(col_val, "cc"))
        row("U",  "U statistic", f"{_u:.1f}", col_val)
        p_gauge(_p_m, "M-W U")
        sep()

        # ── BLOCK 4: Effect size bar (Cliff's delta) ───────────────────────
        sec("▸ EFFECT SIZE  (CLIFF'S δ)", _ca(C["rose"], "cc"))
        eff_label = ("large" if abs(_cd) > 0.474 else
                     "medium" if abs(_cd) > 0.33 else "small")
        eff_col = (col_hi if abs(_cd) > 0.474 else
                   C["amber"] if abs(_cd) > 0.33 else col_lbl)
        mini_bar(f"δ[{eff_label}]", abs(_cd), 1.0, eff_col, show_pct=False)
        cv.create_text(W-4, y-line_h,
                       text=f"{_cd:+.4f}",
                       font=("Courier New", 6, "bold"),
                       fill=eff_col, anchor="ne", tags="dyn_calc")
        sep()

        # ── BLOCK 5: Chi² + FDR ───────────────────────────────────────────
        sec("▸ CHI²  +  BH-FDR", _ca(col_seg, "cc"))
        row("χ²",  "contingency", f"{_chi2:.3f}", col_val)
        p_gauge(_p_c, "χ²")
        _fdr_str = f"{_fdr:.2e}" if _fdr < 0.001 else f"{_fdr:.4f}"
        q_col = col_hi if _fdr < 0.05 else col_lbl
        row("q(BH)", "p·n/rank",  _fdr_str, q_col)
        sep()

        # ── BLOCK 6: Window progress bar ──────────────────────────────────
        sec("▸ WINDOW PROGRESS", _ca(C["teal"], "cc"))
        mini_bar(f"Chr {self._chrom or '—'}", win_d, win_t, C["teal"])
        row("∑ genes", "cumulative", f"{self._genes_total:,}", col_hi)
        row("W(tot)",  "total wins", f"{win_t:,}")

        # ── Bottom status bar ──────────────────────────────────────────────
        bar_y = H - 12
        cv.create_rectangle(0, bar_y, W, H,
                            fill=C["void"], outline="", tags="dyn_calc")
        cv.create_line(0, bar_y, W, bar_y,
                       fill=_ca(C["orchid"], "22"), width=1, tags="dyn_calc")
        if self._active:
            bw = W - 12
            cv.create_rectangle(6, bar_y+4, 6+bw, bar_y+8,
                                fill=C["border_dd"], outline="", tags="dyn_calc")
            fw = int(bw * win_frac)
            if fw > 0:
                cv.create_rectangle(6, bar_y+4, 6+fw, bar_y+8,
                                    fill=_ca(C["orchid"], "88"),
                                    outline="", tags="dyn_calc")
                cv.create_rectangle(6+fw-2, bar_y+4, 6+fw, bar_y+8,
                                    fill=C["rose"], outline="", tags="dyn_calc")
        else:
            # Barra idle animada — pulso sinusoidal
            bw_idle = int((W - 12) * (0.5 + 0.5 * abs(math.sin(ph * 0.018))))
            blink_a = "55" if int(ph*0.028) % 2 == 0 else "28"
            cv.create_rectangle(6, bar_y+4, 6+bw_idle, bar_y+8,
                                fill=_ca(C["cyan"], blink_a),
                                outline="", tags="dyn_calc")
            cv.create_text(6, bar_y+6,
                           text="MATRIX IDLE  ·  AWAITING PIPELINE",
                           font=("Courier New", 6),
                           fill=_ca(C["orchid"], "88"),
                           anchor="w", tags="dyn_calc")

        self._calcs_dirty = False

    # ── Loop de animación principal — SIEMPRE ACTIVO ─────────────
    def _animate(self):
        visible = self.winfo_ismapped()
        self._phase      += 0.85
        self._idle_phase += 0.04

        # Envejecer entradas del log
        for entry in self._comp_lines:
            entry["age"] = entry.get("age", 0.0) + 1.0

        # Lerp escáner y barra de progreso
        self._scan_x      += (self._scan_x_target - self._scan_x)      * 0.14
        self._prog_current += (self._prog_target   - self._prog_current) * 0.10

        if self._active:
            # ── MODO PIPELINE: flicker en celdas activas ─────────────────
            for r in range(self.ROWS):
                for c in range(self.COLS):
                    if self._cells[r][c] > 0.1:
                        if _random.random() < 0.035:
                            old_fk = self._flicker[r][c]
                            new_fk = _random.uniform(0, 0.28)
                            if abs(new_fk - old_fk) > 0.02:
                                self._flicker[r][c] = new_fk
                                self._dirty_cells.add((r, c))
                        else:
                            nf = self._flicker[r][c] - 0.04
                            if nf < 0: nf = 0.0
                            if abs(nf - self._flicker[r][c]) > 0.001:
                                self._flicker[r][c] = nf
                                self._dirty_cells.add((r, c))
            self._calcs_dirty = True

        else:
            # ── MODO STANDBY: ola sinusoidal siempre visible ──────────────
            # Avanzar ola — recorre todas las columnas en bucle
            self._idle_wave = (self._idle_wave + 0.55) % (self.COLS + 8)
            wx = self._idle_wave

            for r in range(self.ROWS):
                row_offset = r * 1.8          # desfase por fila
                for c in range(self.COLS):
                    # Amplitud de la ola gaussiana centrada en wx
                    dist   = abs(c - wx + row_offset % self.COLS)
                    dist   = min(dist, self.COLS - dist)  # wrap circular
                    gauss  = math.exp(-0.5 * (dist / 3.5)**2)
                    # Pulso de brillo lento
                    pulse  = 0.18 + 0.12 * math.sin(self._idle_phase + r * 0.9)
                    target = gauss * (0.35 + pulse)
                    # Flicker suave aleatorio
                    if _random.random() < 0.04:
                        target += _random.uniform(-0.06, 0.06)
                    target = max(0.0, min(1.0, target))
                    old = self._cells[r][c]
                    # Lerp suave — no cambia bruscamente
                    new = old + (target - old) * 0.18
                    if abs(new - old) > 0.004:
                        self._cells[r][c] = new
                        self._dirty_cells.add((r, c))

            # Scan_x también baja cuando no hay pipeline
            if self._scan_x > 0.01:
                self._scan_x -= 0.04
                if self._scan_x < 0:
                    self._scan_x = 0.0

            self._calcs_dirty = True

        if visible:
            self._update_dirty_cells()
            self._draw_scanner()
            self._draw_calcs_dynamic()

        rate = (self.FPS_ACTIVE  if self._active else
                self.FPS_STANDBY if visible      else
                self.FPS_IDLE)
        self.after(rate, self._animate)



def make_panel(parent, title="", color=C["cyan"], pad=14):
    outer = tk.Frame(parent, bg=_ca(color,"44"), highlightthickness=0)
    outer.pack_propagate(True)
    bar_frame = tk.Frame(outer, bg="white", height=3)
    bar_frame.pack(fill="x", side="top")
    tk.Frame(bar_frame, bg=C["emerald"]).place(relwidth=0.35, relheight=1)
    tk.Frame(bar_frame, bg=color).place(relx=0.35, relwidth=0.65, relheight=1)
    if title:
        hdr = tk.Frame(outer, bg=C["glass"])
        hdr.pack(fill="x")
        dot = tk.Canvas(hdr, width=16, height=16,
                        bg=C["glass"], highlightthickness=0)
        dot.pack(side="left", padx=(10,0), pady=6)
        dot.create_oval(3,3,13,13, fill=C["emerald"], outline="")
        dot.create_oval(5,5,11,11, fill=color, outline="")
        tk.Label(hdr, text=f"{title.upper()}",
                 bg=C["glass"], fg=C["txt"],
                 font=("Courier New", 11, "bold"),
                 pady=6, padx=4).pack(side="left", anchor="w")
        tk.Frame(outer, bg=_ca(color,"22"), height=1).pack(fill="x")
    inner   = tk.Frame(outer, bg=C["panel"])
    inner.pack(fill="both", expand=True, padx=1, pady=(0,1))
    brk_size = 12
    for relx, rely, anchor, pts in [
        (0, 0, "nw", [(0,brk_size,0,0,brk_size,0)]),
        (1, 0, "ne", [(brk_size,0,0,0,0,brk_size)]),
        (0, 1, "sw", [(0,0,0,brk_size,brk_size,brk_size)]),
        (1, 1, "se", [(brk_size,brk_size,brk_size,0,0,0)]),
    ]:
        c = tk.Canvas(inner, width=brk_size, height=brk_size,
                      bg=C["panel"], highlightthickness=0)
        c.place(relx=relx, rely=rely, anchor=anchor)
        c.create_line(*[v for pt in pts for v in pt],
                      fill=_ca(color,"77"), width=2)
    content = tk.Frame(inner, bg=C["panel"])
    content.pack(fill="both", expand=True, padx=pad, pady=pad)
    return outer, content


def _field_label(parent, text, color, size=11):
    f = tk.Frame(parent, bg=C["panel"])
    tk.Frame(f, bg=color, width=3).pack(side="left", fill="y", pady=1)
    tk.Label(f, text=f"  {text.upper()}",
             bg=C["panel"], fg=C["txt_dim"],
             font=("Courier New", size, "bold")).pack(side="left")
    return f


def hud_label(parent, text, color=C["txt_dim"], size=10, bold=False):
    fw = "bold" if bold else "normal"
    return tk.Label(parent, text=text.upper(), bg=C["panel"], fg=color,
                    font=("Courier New", size, fw))


def hud_entry(parent, textvariable, width=22, color=C["cyan"]):
    wrapper = tk.Frame(parent, bg=C["panel"])
    left_bar = tk.Frame(wrapper, bg=color, width=3)
    left_bar.pack(side="left", fill="y")
    f = tk.Frame(wrapper, bg=_ca(color,"33"), bd=0, relief="flat")
    f.pack(side="left", fill="x", expand=True)
    e = tk.Entry(f, textvariable=textvariable, width=width,
                 bg=C["panel2"], fg=C["txt"], insertbackground=color,
                 relief="flat", bd=7, font=("Courier New",11),
                 highlightthickness=0)
    e.pack(fill="x")
    e.bind("<FocusIn>",  lambda ev: (f.configure(bg=color),
                                     left_bar.configure(bg=C["emerald"])))
    e.bind("<FocusOut>", lambda ev: (f.configure(bg=_ca(color,"33")),
                                     left_bar.configure(bg=color)))
    return wrapper, e


def hud_button(parent, text, command, color=C["cyan"], width=28):
    outer = tk.Frame(parent, bg=_ca(color,"55"), bd=0)
    btn = tk.Button(outer, text=text, command=command,
                    bg=_ca(color,"15"), fg=color,
                    activebackground=color, activeforeground="#ffffff",
                    relief="flat", bd=0, cursor="hand2",
                    font=("Courier New",11,"bold"),
                    padx=16, pady=9,
                    highlightthickness=0,
                    width=width)
    btn.pack(padx=1, pady=1)
    def on_enter(_):
        btn.configure(bg=_ca(color,"33"))
        outer.configure(bg=C["emerald"])
    def on_leave(_):
        btn.configure(bg=_ca(color,"15"))
        outer.configure(bg=_ca(color,"55"))
    btn.bind("<Enter>", on_enter)
    btn.bind("<Leave>", on_leave)
    return outer


def hud_checkbox(parent, text, variable, color=C["cyan"]):
    f = tk.Frame(parent, bg=C["panel"])
    tk.Frame(f, bg=C["emerald"], width=3).pack(side="left", fill="y", pady=3)
    cb = tk.Checkbutton(f, text=f"  {text}",
                        variable=variable,
                        bg=C["panel"], fg=C["txt"],
                        activebackground=C["panel"], activeforeground=color,
                        selectcolor=C["emerald_t"],
                        font=("Courier New",10), relief="flat")
    cb.pack(side="left")
    return f

