class TechDivider(tk.Canvas):
    def __init__(self, parent, color=C["emerald"], height=14, **kw):
        super().__init__(parent, height=height, bg=C["bg"],
                         highlightthickness=0, **kw)
        self.color = color
        self.bind("<Configure>", lambda e: self._draw())

    def _draw(self):
        self.delete("all")
        w = self.winfo_width() or 400
        h = self.winfo_height() or 14
        cy = h // 2
        for x in range(0, w//2 - 30):
            alpha = int(min(80, x * 0.35))
            self.create_line(x, cy, x+1, cy,
                             fill=_ca(self.color, f"{alpha:02x}"), width=1)
        for x in range(w//2 + 30, w):
            alpha = int(min(80, (w - x) * 0.35))
            self.create_line(x, cy, x+1, cy,
                             fill=_ca(self.color, f"{alpha:02x}"), width=1)
        cx = w // 2
        for offset, size, alpha_h in [(-12,2,"44"),(-6,3,"77"),(0,4,"cc"),(6,3,"77"),(12,2,"44")]:
            self.create_oval(cx+offset-size, cy-size,
                             cx+offset+size, cy+size,
                             fill=_ca(self.color, alpha_h), outline="")
        self.create_line(0, cy-3, w, cy-3,
                         fill=_ca(self.color,"0a"), width=1)
        self.create_line(0, cy+3, w, cy+3,
                         fill=_ca(self.color,"0a"), width=1)


