ENSEMBL_REST_API = "https://rest.ensembl.org"
# Lista de servidores REST Ensembl que el pipeline puede usar.
# Se prueba el primero que tenga la especie. La constante ENSEMBL_REST_API
# (mutable) es la que de hecho usan _ens_get y _ens_post_lookup, así que
# basta con resolverla una vez por especie en chromosomes_info y todo el
# pipeline (overlap/region, lookup/id, …) sigue funcionando.
#   • rest.ensembl.org        → vertebrados + drosophila, c. elegans, yeast
#   • rest.ensemblgenomes.org → plantas, hongos, metazoos invertebrados,
#                                protistas y bacterias
_ENSEMBL_REST_CANDIDATES = (
    "https://rest.ensembl.org",
    "https://rest.ensemblgenomes.org",
)
WINDOW_SIZE_FETCH = 1_000_000
_ENS_HEADERS = {
    "Content-Type": "application/json",
    "Accept": "application/json",
    "User-Agent": "IGFinder/2.1.1 (katia.avi@gmail.com)",
}


def natural_chrom_key(x: str):
    s = str(x)
    try:
        return (0, int(s))
    except ValueError:
        special = {"X": 1000, "Y": 1001, "MT": 1002, "M": 1002}
        return (1, special.get(s.upper(), 2000), s)


def _safe_numeric(series: pd.Series) -> pd.Series:
    return pd.to_numeric(series, errors="coerce")


def describe_series(s: pd.Series) -> Dict[str, float]:
    s = _safe_numeric(s).dropna()
    if s.empty:
        return {}
    q1 = float(s.quantile(0.25))
    q3 = float(s.quantile(0.75))
    return {
        "n":      int(s.shape[0]),
        "mean":   float(s.mean()),
        "median": float(s.median()),
        "std":    float(s.std(ddof=1)) if s.shape[0] > 1 else 0.0,
        "min":    float(s.min()),
        "q1":     q1,
        "q3":     q3,
        "max":    float(s.max()),
        "iqr":    float(q3 - q1),
    }


def cliffs_delta(x: np.ndarray, y: np.ndarray) -> float:
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    x = x[~np.isnan(x)]
    y = y[~np.isnan(y)]
    if x.size == 0 or y.size == 0:
        return float("nan")
    if _HAS_CYTHON:
        return fast_cliffs_delta(
            np.ascontiguousarray(x, dtype=np.float64),
            np.ascontiguousarray(y, dtype=np.float64))
    gt = sum(np.sum(xi > y) for xi in x)
    lt = sum(np.sum(xi < y) for xi in x)
    return (gt - lt) / (x.size * y.size)


def classify_cliffs_delta(delta: float) -> str:
    ad = abs(delta)
    if math.isnan(ad):
        return "NA"
    if ad < 0.147:
        return "negligible"
    if ad < 0.33:
        return "small"
    if ad < 0.474:
        return "medium"
    return "large"


def benjamini_hochberg(pvalues: Iterable[float]) -> List[float]:
    if _HAS_CYTHON:
        return fast_benjamini_hochberg(list(pvalues))
    pvals = np.asarray(list(pvalues), dtype=float)
    out = np.full_like(pvals, np.nan, dtype=float)
    valid_mask = ~np.isnan(pvals)
    valid = pvals[valid_mask]
    n = valid.size
    if n == 0:
        return out.tolist()
    order = np.argsort(valid)
    ranked = valid[order]
    adjusted = np.empty(n, dtype=float)
    prev = 1.0
    for i in range(n - 1, -1, -1):
        rank = i + 1
        prev = min(prev, ranked[i] * n / rank)
        adjusted[i] = min(prev, 1.0)
    restored = np.empty(n, dtype=float)
    restored[order] = adjusted
    out[valid_mask] = restored
    return out.tolist()


def has_enough_variation(x: np.ndarray, min_n: int = 2) -> bool:
    x = np.asarray(x, dtype=float)
    x = x[~np.isnan(x)]
    return x.size >= min_n and np.unique(x).size >= 2


def safe_welch_test(x: np.ndarray, y: np.ndarray) -> Dict[str, object]:
    x = np.asarray(x, dtype=float)[~np.isnan(np.asarray(x, dtype=float))]
    y = np.asarray(y, dtype=float)[~np.isnan(np.asarray(y, dtype=float))]
    if x.size < 2 or y.size < 2:
        return {
            "welch_t_stat": np.nan, "welch_p": np.nan, "welch_df": np.nan,
            "welch_warning": "Skipped Welch test: insufficient sample size.",
        }
    if not has_enough_variation(x) or not has_enough_variation(y):
        return {
            "welch_t_stat": np.nan, "welch_p": np.nan, "welch_df": np.nan,
            "welch_warning": "Skipped Welch test: nearly identical values or zero variance.",
        }
    try:
        welch = ttest_ind(x, y, equal_var=False, nan_policy="omit")
        return {
            "welch_t_stat": float(welch.statistic),
            "welch_p":      float(welch.pvalue),
            "welch_df":     float(getattr(welch, "df", np.nan)),
            "welch_warning": "",
        }
    except Exception as exc:
        return {
            "welch_t_stat": np.nan, "welch_p": np.nan, "welch_df": np.nan,
            "welch_warning": f"Welch test failed: {exc}",
        }


def set_plot_style() -> None:
    if _HAS_SNS:
        sns.set(style="whitegrid")


# ══════════════════════════════════════════════════════════════════════════════
#  ENSEMBL API — retry adaptativo + backoff exponencial (de Futurista)
# ══════════════════════════════════════════════════════════════════════════════

def _ens_get(endpoint, params=None, retries=6, raise_on_4xx=True):
    """
    GET robusto con timeout escalonado, 429 Rate-Limit y backoff.

    Behavior:
      • 2xx OK              → return parsed JSON
      • 429 Too Many Reqs   → respect Retry-After, retry up to `retries`
      • 5xx Server Error    → exponential backoff, retry up to `retries`
      • 4xx Client Error    → fail FAST (no retry — these never recover)
                              Raises requests.HTTPError with status code in msg
      • Timeout/Connection  → exponential backoff, retry up to `retries`

    Set raise_on_4xx=False to suppress 4xx errors and return None instead
    (useful for "best effort" lookups like ortholog fetch).
    """
    url = f"{ENSEMBL_REST_API}{endpoint}"
    timeouts = [30, 60, 90, 120, 150, 180]
    last_status = None
    last_body   = ""
    for att in range(retries):
        try:
            r = requests.get(url, headers=_ENS_HEADERS, params=params,
                             timeout=timeouts[min(att, len(timeouts) - 1)])
            if r.ok:
                return r.json()
            if r.status_code == 429:
                wait = int(r.headers.get("Retry-After", 30))
                logging.warning("Rate-limit 429 on %s → waiting %ds",
                                endpoint, wait)
                time.sleep(wait)
                continue
            if r.status_code in (500, 502, 503, 504):
                wait = 2 ** att * 5
                logging.warning("Server error %d on %s (attempt %d) → "
                                "waiting %ds",
                                r.status_code, endpoint, att + 1, wait)
                time.sleep(wait)
                continue
            # 4xx — client error, never retries
            last_status = r.status_code
            try:
                last_body = r.text[:200]
            except Exception:
                last_body = ""
            if raise_on_4xx:
                raise requests.HTTPError(
                    f"Ensembl GET {r.status_code} on {endpoint}: "
                    f"{last_body[:120]}",
                    response=r)
            return None
        except (requests.Timeout, requests.ConnectionError) as e:
            wait = 2 ** att * 4
            logging.warning("Timeout/connection attempt %d: %s → waiting %ds",
                            att + 1, e, wait)
            time.sleep(wait)
        except requests.HTTPError:
            # Already wrapped above — propagate
            raise
        except requests.RequestException as e:
            logging.warning("Unexpected error attempt %d: %s", att + 1, e)
            time.sleep(2 ** att)
    raise requests.HTTPError(
        f"Ensembl GET failed after {retries} attempts: {endpoint}  "
        f"(last status {last_status})")


def _ens_post_lookup(ids, retries=4, log_fn=None):
    """POST robusto para batch lookup con retry y rate-limit.

    Si se pasa `log_fn`, los fallos (429, timeout, agotamiento de reintentos)
    se reportan al panel LOG de la GUI, no solo al logger de Python. Esto evita
    que un lookup que falla en silencio deje el pipeline sin datos sin que el
    usuario se entere.
    """
    url = f"{ENSEMBL_REST_API}/lookup/id"
    for att in range(retries):
        try:
            _timeout = min(30 + att * 30, 120)  # escalonado: 30→60→90→120s
            r = requests.post(url, headers=_ENS_HEADERS,
                              json={"ids": ids}, params={"expand": 1},
                              timeout=_timeout)
            if r.ok:
                return r.json()
            if r.status_code == 429:
                wait = int(r.headers.get("Retry-After", 30))
                logging.warning("Rate-limit 429 POST lookup → waiting %ds", wait)
                if log_fn:
                    log_fn(f"  ⏳ Rate-limit (429) — esperando {wait}s "
                           f"(intento {att+1}/{retries})", "warn")
                time.sleep(wait)
                continue
            if log_fn:
                log_fn(f"  ⚠ Lookup HTTP {r.status_code} "
                       f"(intento {att+1}/{retries})", "warn")
            time.sleep(2 ** att)
        except Exception as e:
            logging.warning("Batch POST exception %d: %s", att+1, e)
            if log_fn:
                log_fn(f"  ⚠ Lookup excepción (intento {att+1}/{retries}): "
                       f"{type(e).__name__}", "warn")
            time.sleep(2 ** att)
    if log_fn:
        log_fn(f"  ✖ Lote de {len(ids)} IDs perdido tras {retries} intentos.",
               "err")
    return {}


def overlapping_features(species: str, region: str, feature: str = "gene") -> list:
    """Genes solapantes con una región. Nunca lanza — retorna [] si falla."""
    try:
        result = _ens_get(f"/overlap/region/{species}/{region}", {"feature": feature})
        return result if isinstance(result, list) else []
    except Exception as e:
        logging.warning("Window %s discarded after retries: %s", region, e)
        return []


def get_info_batch(genes_chunk: list) -> list:
    """Lookup detallado en lotes de 50."""
    all_info: list = []
    ids = [g["id"] for g in genes_chunk if g.get("id")]
    for i in range(0, len(ids), 50):
        chunk = ids[i:i+50]
        try:
            data = _ens_post_lookup(chunk)
            all_info.extend(data.values())
        except Exception as exc:
            logging.warning("Error al obtener batch info: %s", exc)
            time.sleep(2)
        time.sleep(0.08)
    return all_info


def genes_in_chrom(species: str, chrom, length: int) -> list:
    """Recupera genes de un cromosoma en ventanas de WINDOW_SIZE_FETCH."""
    all_genes: list = []
    for start in range(1, length, WINDOW_SIZE_FETCH):
        end = min(start + WINDOW_SIZE_FETCH - 1, length)
        region = f"{chrom}:{start}-{end}"
        genes = overlapping_features(species, region, "gene")
        all_genes.extend(genes)
        time.sleep(0.15)
    return all_genes


def chromosomes_info(species: str) -> Tuple[Dict[str, dict], dict]:
    """Info del ensamblado genómico.

    Soporta tanto ensamblados a nivel de cromosoma (homo_sapiens, mus_musculus,
    danio_rerio, …) como ensamblados a nivel de scaffold/supercontig/contig
    (stegastes_partitus, muchos peces no-modelo, insectos, etc.).

    Auto-resuelve el servidor REST: prueba primero rest.ensembl.org (vertebrados
    + modelos clave) y, si la especie no aparece allí, cae a
    rest.ensemblgenomes.org (plantas, hongos, metazoos invertebrados, protistas
    y bacterias). Una vez resuelto, fija ENSEMBL_REST_API a ese host para que
    todas las llamadas siguientes (overlap/region, lookup/id, …) usen el mismo.

    Estrategia interna: primero intenta las regiones con coord_system='chromosome'
    (idéntico al comportamiento original). Si el ensamblado no tiene
    cromosomas, recurre al conjunto completo de top-level regions, que es lo
    que la propia documentación de Ensembl indica como entradas válidas para
    los endpoints /overlap/region/.
    """
    global ENSEMBL_REST_API
    logging.info("→ Connecting to Ensembl for assembly info of %s …", species)

    # — Auto-resolución del servidor REST adecuado para la especie —
    response: dict = {}
    regions: list = []
    last_error: Optional[Exception] = None
    for base in _ENSEMBL_REST_CANDIDATES:
        ENSEMBL_REST_API = base   # _ens_get usa esta global al construir la URL
        try:
            response = _ens_get(f"/info/assembly/{species}")
            regions = response.get("top_level_region", []) or []
            if regions:
                logging.info("  ✓ Resolved on %s (%d top-level regions)",
                             base, len(regions))
                break
            logging.info("  · %s replied but reported no regions for %s",
                         base, species)
        except Exception as e:
            last_error = e
            logging.info("  · %s did not have %s (%s)",
                         base, species, type(e).__name__)
            continue
    else:
        # Ningún servidor tuvo regiones útiles — propaga el error si lo hubo
        if last_error is not None and not regions:
            raise last_error

    # — Ruta primaria: cromosomas (preserva comportamiento original) —
    chrom_lengths = {
        region["name"]: {
            "length": region["length"],
            "coord_system": region.get("coord_system", "chromosome"),
        }
        for region in regions
        if region.get("coord_system") == "chromosome"
    }
    # — Fallback: ensamblados sin cromosomas (scaffold-only, contig-only, …) —
    if not chrom_lengths and regions:
        chrom_lengths = {
            region["name"]: {
                "length": region["length"],
                "coord_system": region.get("coord_system", "scaffold"),
            }
            for region in regions
            if region.get("name") and region.get("length")
        }
        cs_seen = sorted({r.get("coord_system", "scaffold") for r in regions})
        logging.info("  (no chromosomes — using %d top-level regions: %s)",
                     len(chrom_lengths), ", ".join(cs_seen))
    return chrom_lengths, response


# ══════════════════════════════════════════════════════════════════════════════
#  UTR
# ══════════════════════════════════════════════════════════════════════════════

def load_utr_transcripts(utr_file: str, species_name: str) -> Set[str]:
    """Carga los transcritos con intrón en UTR para una especie.

    El archivo IntronDB es enorme (decenas de millones de filas, >1 GB) y tiene
    formato 'una fila por intrón': species_name, transcript_id, intron_type.
    Cargar todo con pd.read_csv agota la memoria y puede fallar en silencio
    (causa real del 'UTR IDs loaded: 0' observado). Leemos POR CHUNKS, filtrando
    especie + intrón-UTR sobre la marcha, y NORMALIZAMOS los IDs quitando la
    versión (ENST...390.2 -> ENST...390) para que el match contra Ensembl no
    falle por sufijo de versión.

    Devuelve un set de transcript_id SIN versión.
    """
    if not utr_file or not os.path.isfile(utr_file):
        return set()

    species_key = species_name.strip().lower()
    utr_transcripts: Set[str] = set()

    def _is_utr(x: str) -> bool:
        if not isinstance(x, str):
            return False
        x = x.lower().replace(" ", "")
        return "utr" in x and ("5" in x or "3" in x)

    try:
        reader = pd.read_csv(
            utr_file, sep="\t", dtype=str,
            usecols=["species_name", "transcript_id", "intron_type"],
            chunksize=500_000,
        )
    except ValueError as exc:
        # Columnas faltantes u otro problema de formato
        logging.warning("UTR file format problem: %s", exc)
        return set()
    except Exception as exc:
        logging.warning("Could not open UTR file: %s", exc)
        return set()

    n_rows_species = 0
    for chunk in reader:
        sp = chunk["species_name"].fillna("").str.strip().str.lower()
        sub = chunk[sp == species_key]
        if sub.empty:
            continue
        n_rows_species += len(sub)
        mask = sub["intron_type"].apply(_is_utr)
        ids = sub.loc[mask, "transcript_id"].dropna().astype(str)
        # Normalizar quitando la versión (todo antes del primer punto)
        utr_transcripts.update(i.split(".")[0] for i in ids)

    if n_rows_species == 0:
        logging.warning("No UTR rows found for species '%s'.", species_name)
    logging.info("Loaded %d transcripts with UTR introns (species '%s').",
                 len(utr_transcripts), species_name)
    return utr_transcripts


# ══════════════════════════════════════════════════════════════════════════════
#  Selección de cromosomas y construcción del DataFrame de transcritos
# ══════════════════════════════════════════════════════════════════════════════

def select_chromosomes(
    chrom_data: Dict[str, dict],
    chromosomes: str,
    autosomes_only: bool,
) -> Dict[str, dict]:
    selected = dict(chrom_data)
    if autosomes_only:
        autosomes = {str(i) for i in range(1, 23)}
        filtered = {k: v for k, v in selected.items() if str(k) in autosomes}
        if filtered:
            selected = filtered
            logging.info("Restricted to autosomes 1-22.")
        else:
            logging.warning("Autosome restriction: no chromosomes 1-22 found. Using all.")
    if chromosomes.strip():
        # Tolerate stray quotes/brackets/spaces around tokens (e.g. "22'" → "22",
        # "[1, 2]" → {"1","2"}). Otherwise a single stray apostrophe makes every
        # species fail with "No requested chromosomes found".
        wanted = {c.strip().strip("'\"[]() \t") for c in chromosomes.split(",")}
        wanted = {c for c in wanted if c}
        filtered = {k: v for k, v in selected.items() if str(k) in wanted}
        if not filtered:
            raise ValueError(f"No requested chromosomes found: {sorted(wanted)}")
        selected = filtered
        logging.info("Restricted to user-selected chromosomes: %s",
                     ", ".join(sorted(selected, key=natural_chrom_key)))
    return dict(sorted(selected.items(), key=lambda kv: natural_chrom_key(kv[0])))


def build_transcript_df_gui(species, chromosomes_str, autosomes_only,
                            log_fn, progress_fn, abort_fn, min_len: int = 0):
    """
    Construye el DataFrame de transcritos con callbacks para la GUI.
    Compatible con la lógica de fetch_transcript_dataframe del unified.

    `min_len` permite descartar de antemano scaffolds/contigs cuya longitud
    es menor que el tamaño mínimo de gen pedido por el usuario: ningún gen
    de >= min_len bp puede caber en un scaffold de < min_len bp, así que
    consultarlos a Ensembl es trabajo perdido. Esto acelera enormemente
    los ensamblados muy fragmentados (cientos o miles de scaffolds tiny)
    sin descartar ni un solo gen válido.
    """
    if log_fn:
        log_fn(f"[1/3] Assembly info: {species}", "info")
    chrom_data, _ = chromosomes_info(species=species)
    if not chrom_data:
        if log_fn:
            log_fn("No chromosome data returned.", "err")
        return pd.DataFrame()

    chrom_data = select_chromosomes(chrom_data, chromosomes=chromosomes_str,
                                    autosomes_only=autosomes_only)

    # ── Filtrado por longitud mínima (loss-less) ────────────────────────
    if min_len and min_len > 0:
        n_before_skip = len(chrom_data)
        chrom_data = {k: v for k, v in chrom_data.items()
                      if v.get("length", 0) >= min_len}
        n_skipped = n_before_skip - len(chrom_data)
        if n_skipped and log_fn:
            log_fn(f"  Skipped {n_skipped:,} regions shorter than "
                   f"min_len={min_len} bp (cannot contain a qualifying gene)",
                   "info")

    if not chrom_data:
        if log_fn:
            log_fn("No regions remain after length filter.", "err")
        return pd.DataFrame()

    if log_fn:
        names_preview = sorted(chrom_data.keys(), key=natural_chrom_key)
        if len(names_preview) <= 30:
            log_fn(f"  Cromosomas: {len(chrom_data)} → "
                   + ", ".join(names_preview), "info")
        else:
            # Muchos scaffolds: muestra solo los primeros para no inundar el log
            shown = ", ".join(names_preview[:10])
            log_fn(f"  Cromosomas/scaffolds: {len(chrom_data):,} "
                   f"(primeros 10: {shown}, …)", "info")

    all_genes: List[dict] = []
    total_c = len(chrom_data)

    # ── Notificar a la GUI el layout del genoma ──────────────────────────
    # ChromoScope se reconfigura con los cromosomas/scaffolds reales de la
    # especie en curso (cualquier especie de Ensembl). Esto NO altera la
    # lógica del pipeline — solo es un evento informativo para el widget.
    if progress_fn:
        progress_fn(0, total_c, "INIT", {"genome": dict(chrom_data)})

    for idx, (chrom, info) in enumerate(chrom_data.items(), 1):
        if abort_fn and abort_fn():
            break
        length = info.get("length", 0)

        # ── DOWNLOAD: fetch from Ensembl API ────────────────────────────────
        if log_fn:
            log_fn(f"  [{idx}/{total_c}] Chr {chrom} ({length/1e6:.1f} Mb) — downloading…", "dim")
        if progress_fn:
            progress_fn(idx, total_c, "SCANNING",
                        {"chrom": chrom, "genes": None, "phase": "start"})

        n_before = len(all_genes)
        gene_objects = genes_in_chrom(species, chrom, length)
        valid = [g for g in gene_objects if isinstance(g, dict) and g.get("id")]
        all_genes.extend(valid)
        n_found = len(all_genes) - n_before

        # ── MATRIX THREAD ACTIVITY: live running totals ──────────────────────
        if log_fn:
            log_fn({"n_seg": len(all_genes)}, "math_stats")

        if progress_fn:
            progress_fn(idx, total_c, "SCANNING",
                        {"chrom": chrom, "genes": n_found, "phase": "done"})
        # Sleep between scaffolds: ~0.1 s es seguro frente al rate-limit
        # de Ensembl (~15 req/s) y reduce ~5× el tiempo total para
        # ensamblados muy fragmentados sin riesgo de 429.
        time.sleep(0.1)

    if not all_genes:
        if log_fn:
            log_fn("No gene objects retrieved.", "warn")
        return pd.DataFrame()

    # Deduplicar
    seen_ids: Set[str] = set()
    unique_genes: List[dict] = []
    for g in all_genes:
        gid = g.get("id")
        if gid and gid not in seen_ids:
            seen_ids.add(gid)
            unique_genes.append(g)

    if log_fn:
        log_fn(f"[2/3] Unique IDs: {len(unique_genes):,}. Starting lookup...", "info")

    # Lookup detallado en lotes
    genes_info: list = []
    total_b = (len(unique_genes) + 49) // 50
    n_failed_batches = 0
    for i in range(0, len(unique_genes), 50):
        if abort_fn and abort_fn():
            break
        chunk = unique_genes[i:i+50]
        ids = [g["id"] for g in chunk]
        data = _ens_post_lookup(ids, log_fn=log_fn)
        if not data:
            n_failed_batches += 1
        else:
            genes_info.extend(data.values())
        b = i // 50 + 1
        if progress_fn:
            progress_fn(b, total_b, "LOOKUP")
        # Feedback frecuente: cada 5 lotes (antes cada 20) para que el usuario
        # vea avance real en cromosomas grandes (Chr 1 humano ≈ 142 lotes).
        if b % 5 == 0 and log_fn:
            log_fn(f"  Batch {b}/{total_b}  ·  {len(genes_info):,} genes "
                   f"acumulados", "dim")
        # Pausa entre lotes para respetar el rate-limit de Ensembl (~15 req/s
        # por IP). 0.08s era demasiado agresivo en cromosomas grandes y
        # disparaba cascadas de 429 que acababan perdiendo lotes. 0.25s mantiene
        # buen rendimiento sin saturar.
        time.sleep(0.25)
    if log_fn:
        if n_failed_batches:
            log_fn(f"  ⚠ {n_failed_batches}/{total_b} lotes de lookup fallaron "
                   f"(posible rate-limit de Ensembl).", "warn")
        if not genes_info:
            log_fn("  ✖ LOOKUP sin resultados — 0 genes recuperados. "
                   "El scan no producirá genes IG/MEG. Reintenta más tarde "
                   "(Ensembl puede estar limitando tu IP).", "err")

    # Construir DataFrame (lógica idéntica al unified)
    rows = []
    for gene in genes_info:
        if not isinstance(gene, dict):
            continue
        gid = gene.get("id")
        if gid is None:
            continue
        g_start = gene.get("start", 0)
        g_end   = gene.get("end",   0)
        for tx in gene.get("Transcript", []) or []:
            tid = tx.get("id")
            if tid is None:
                continue
            t_start = tx.get("start", g_start)
            t_end   = tx.get("end",   g_end)
            rows.append({
                "gene_id":           gid,
                "gene_name":         gene.get("display_name", ""),
                "transcript_id":     tid,
                "chrom":             gene.get("seq_region_name", ""),
                "strand":            gene.get("strand", 1),
                "gene_start":        int(g_start) if g_start is not None else np.nan,
                "gene_end":          int(g_end)   if g_end   is not None else np.nan,
                "transcript_start":  int(t_start) if t_start is not None else np.nan,
                "transcript_end":    int(t_end)   if t_end   is not None else np.nan,
                "exon_count":        len(tx.get("Exon", []) or []),
                "transcript_length": max(0, int(t_end) - int(t_start) + 1),
                "gene_biotype":      gene.get("biotype", "NA"),
            })

    df = pd.DataFrame(rows)
    if not df.empty:
        for col in ["gene_start", "gene_end", "transcript_start", "transcript_end",
                     "exon_count", "transcript_length"]:
            df[col] = pd.to_numeric(df[col], errors="coerce")
        df["exon_count"]        = df["exon_count"].fillna(0).astype(int)
        df["transcript_length"] = df["transcript_length"].fillna(0).astype(int)

    if log_fn:
        log_fn(f"[3/3] DataFrame: {len(df):,} rows", "ok")
    return df


# ══════════════════════════════════════════════════════════════════════════════
#  Clasificación de genes (idéntica al unified)
# ══════════════════════════════════════════════════════════════════════════════

def classify_genes_unified(
    transcripts_df: pd.DataFrame,
    utr_introns: Set[str],
    min_transcript_length: int,
    allowed_biotypes: Set[str],
):
    """Clasificación idéntica a IGFinder2.1.1_unified.py — retorna 5 DataFrames."""
    if transcripts_df.empty:
        e = pd.DataFrame()
        return e, e, e, e, e

    df = transcripts_df.copy()
    if allowed_biotypes:
        df = df[df["gene_biotype"].isin(allowed_biotypes)].copy()
        logging.info("After biotype filter: %d transcripts", len(df))
    if min_transcript_length > 0:
        df = df[df["transcript_length"] >= min_transcript_length].copy()
        logging.info("After min transcript length filter: %d transcripts", len(df))
    if df.empty:
        e = pd.DataFrame()
        return e, e, e, e, e

    # Match de UTR-introns: normalizar la versión del transcript_id de Ensembl
    # (ENST...390.2 -> ENST...390) porque los IDs de IntronDB no tienen versión.
    # Sin esto, el match daría 0 y ui-SEG quedaría vacío en silencio.
    _tid_base = df["transcript_id"].astype(str).str.split(".").str[0]
    df["has_utr_intron"] = _tid_base.isin(utr_introns)
    df["is_single_exon"] = df["exon_count"] == 1
    df["is_multi_exon"]  = df["exon_count"] > 1

    # Aviso si hay UTR-introns cargados pero NINGÚN match → posible desajuste
    # de release/versión entre IntronDB y la anotación de Ensembl consultada.
    if utr_introns and not df["has_utr_intron"].any():
        logging.warning(
            "[ui-SEG] %d UTR-intron IDs cargados pero 0 coinciden con los "
            "transcritos de Ensembl — posible desajuste de versión/release. "
            "ui-SEG quedará en 0.", len(utr_introns))

    # ui-SEG transcripts
    ui_tx = df[df["is_single_exon"] & df["has_utr_intron"]].copy()
    if not ui_tx.empty:
        ui_gene = ui_tx.groupby("gene_id", as_index=False).agg(
            gene_name=("gene_name", "first"),
            chrom=("chrom", "first"),
            strand=("strand", "first"),
            gene_start=("gene_start", "min"),
            gene_end=("gene_end", "max"),
            gene_biotype=("gene_biotype", "first"),
            n_ui_seg_transcripts=("transcript_id", "nunique"),
            representative_transcript_length=("transcript_length", "max"),
        )
    else:
        ui_gene = pd.DataFrame(columns=[
            "gene_id", "gene_name", "chrom", "strand", "gene_start", "gene_end",
            "gene_biotype", "n_ui_seg_transcripts", "representative_transcript_length",
        ])

    # IG / MEG
    df_non_ui = df[~(df["is_single_exon"] & df["has_utr_intron"])].copy()
    if df_non_ui.empty:
        e = pd.DataFrame()
        return e, e, ui_tx, ui_gene, e

    ui_gene_ids = set(ui_gene["gene_id"]) if not ui_gene.empty else set()
    rows = []
    for gid, g in df_non_ui.groupby("gene_id"):
        idx = g["transcript_length"].idxmax()
        class_label = (
            "IG"    if bool(g["is_single_exon"].all()) and not bool(g["is_multi_exon"].any())
            else "MEG" if bool(g["is_multi_exon"].any())
            else "OTHER"
        )
        rows.append({
            "gene_id":                       gid,
            "gene_name":                     g["gene_name"].iloc[0],
            "chrom":                         g["chrom"].iloc[0],
            "strand":                        g["strand"].iloc[0],
            "gene_start":                    float(g["gene_start"].min()),
            "gene_end":                      float(g["gene_end"].max()),
            "gene_biotype":                  g["gene_biotype"].iloc[0],
            "n_transcripts_used":            int(g["transcript_id"].nunique()),
            "representative_transcript_length": int(g.loc[idx, "transcript_length"]),
            "contains_ui_seg_transcript":    bool(gid in ui_gene_ids),
            "class_label":                   class_label,
        })

    gene_summary = pd.DataFrame(rows)
    ig_df  = gene_summary[gene_summary["class_label"] == "IG"].copy()
    meg_df = gene_summary[gene_summary["class_label"] == "MEG"].copy()

    logging.info("IG genes: %d",          len(ig_df))
    logging.info("MEG genes: %d",         len(meg_df))
    logging.info("ui-SEG transcripts: %d", len(ui_tx))
    logging.info("ui-SEG genes: %d",       len(ui_gene))

    return ig_df, meg_df, ui_tx, ui_gene, gene_summary


# ══════════════════════════════════════════════════════════════════════════════
#  Métricas estructurales (idénticas al unified)
# ══════════════════════════════════════════════════════════════════════════════

REQUIRED_TRANSCRIPT_COLUMNS = {
    "gene_id", "gene_name", "transcript_id", "chrom", "strand",
    "exon_count", "transcript_length", "gene_biotype",
}


def _require_columns(df: pd.DataFrame, required: Iterable[str], df_name: str) -> None:
    missing = set(required).difference(df.columns)
    if missing:
        raise ValueError(f"{df_name} is missing required columns: {', '.join(sorted(missing))}")


def compute_gene_structure_metrics(transcripts_df: pd.DataFrame) -> pd.DataFrame:
    _require_columns(transcripts_df, REQUIRED_TRANSCRIPT_COLUMNS, "transcripts_df")
    df = transcripts_df.copy()
    df["transcript_length"] = _safe_numeric(df["transcript_length"])
    df["exon_count"]        = _safe_numeric(df["exon_count"])
    df["is_single_exon"]    = df["exon_count"] == 1
    df["is_multi_exon"]     = df["exon_count"] > 1
    rows = []
    for gid, g in df.groupby("gene_id", dropna=False):
        tx_len  = g["transcript_length"].dropna()
        exon_ct = g["exon_count"].dropna()
        n_tx    = int(g["transcript_id"].nunique())
        single_count = int(g["is_single_exon"].sum())
        multi_count  = int(g["is_multi_exon"].sum())
        max_len    = float(tx_len.max())    if not tx_len.empty else np.nan
        min_len    = float(tx_len.min())    if not tx_len.empty else np.nan
        mean_len   = float(tx_len.mean())   if not tx_len.empty else np.nan
        median_len = float(tx_len.median()) if not tx_len.empty else np.nan
        std_len = (float(tx_len.std(ddof=1)) if tx_len.shape[0] > 1
                   else 0.0 if tx_len.shape[0] == 1 else np.nan)
        range_len = float(max_len - min_len) if not (np.isnan(max_len) or np.isnan(min_len)) else np.nan
        cv_len    = float(std_len / mean_len) if mean_len and not np.isnan(mean_len) else np.nan
        mean_exons   = float(exon_ct.mean())   if not exon_ct.empty else np.nan
        median_exons = float(exon_ct.median()) if not exon_ct.empty else np.nan
        max_exons    = float(exon_ct.max())    if not exon_ct.empty else np.nan
        std_exons = (float(exon_ct.std(ddof=1)) if exon_ct.shape[0] > 1
                     else 0.0 if exon_ct.shape[0] == 1 else np.nan)
        complexity = (
            float(math.log2(n_tx + 1) + math.log2(mean_exons + 1)
                  + (cv_len if not np.isnan(cv_len) else 0.0))
            if n_tx > 0 and not np.isnan(mean_exons) else np.nan
        )
        rows.append({
            "gene_id": gid, "gene_name": g["gene_name"].iloc[0],
            "chrom": g["chrom"].iloc[0], "strand": g["strand"].iloc[0],
            "gene_biotype": g["gene_biotype"].iloc[0],
            "n_transcripts": n_tx,
            "transcript_length_max": max_len, "transcript_length_mean": mean_len,
            "transcript_length_median": median_len, "transcript_length_std": std_len,
            "transcript_length_range": range_len, "isoform_length_cv": cv_len,
            "exon_count_max": max_exons, "exon_count_mean": mean_exons,
            "exon_count_median": median_exons, "exon_count_std": std_exons,
            "single_exon_transcript_count": single_count,
            "multi_exon_transcript_count": multi_count,
            "single_exon_transcript_fraction": float(single_count / n_tx) if n_tx > 0 else np.nan,
            "gene_architecture_complexity_score": complexity,
        })
    return pd.DataFrame(rows)


def summarize_metrics_by_class(
    metrics_df: pd.DataFrame, class_df: pd.DataFrame,
    class_col: str = "class_label", metrics: Optional[List[str]] = None,
) -> pd.DataFrame:
    merged = metrics_df.merge(
        class_df[["gene_id", class_col]].drop_duplicates(), on="gene_id", how="inner")
    if metrics is None:
        metrics = [
            "n_transcripts", "transcript_length_max", "transcript_length_mean",
            "transcript_length_median", "transcript_length_range", "isoform_length_cv",
            "exon_count_max", "exon_count_mean", "exon_count_median",
            "single_exon_transcript_fraction", "gene_architecture_complexity_score",
        ]
    rows = []
    for cls, g in merged.groupby(class_col):
        for metric in metrics:
            if metric in merged.columns:
                rows.append({"class_label": cls, "metric": metric,
                             **describe_series(g[metric])})
    return pd.DataFrame(rows)


def compare_classes(
    metrics_df: pd.DataFrame, class_df: pd.DataFrame,
    class_col: str = "class_label", metrics: Optional[List[str]] = None,
    class_pairs: Optional[List[Tuple[str, str]]] = None,
) -> pd.DataFrame:
    merged = metrics_df.merge(
        class_df[["gene_id", class_col]].drop_duplicates(), on="gene_id", how="inner")
    if metrics is None:
        metrics = [
            "n_transcripts", "transcript_length_max", "transcript_length_mean",
            "transcript_length_median", "transcript_length_range", "isoform_length_cv",
            "exon_count_max", "exon_count_mean", "exon_count_median",
            "single_exon_transcript_fraction", "gene_architecture_complexity_score",
        ]
    if class_pairs is None:
        class_pairs = [("IG", "MEG")]
    rows = []
    for class_a, class_b in class_pairs:
        a_df = merged[merged[class_col] == class_a].copy()
        b_df = merged[merged[class_col] == class_b].copy()
        for metric in metrics:
            if metric not in merged.columns:
                continue
            x = _safe_numeric(a_df[metric]).dropna().to_numpy()
            y = _safe_numeric(b_df[metric]).dropna().to_numpy()
            if x.size == 0 or y.size == 0:
                rows.append({
                    "metric": metric, "class_a": class_a, "class_b": class_b,
                    "n_a": int(x.size), "n_b": int(y.size),
                    "mean_a": np.nan, "mean_b": np.nan,
                    "median_a": np.nan, "median_b": np.nan,
                    "delta_mean_a_minus_b": np.nan,
                    "welch_t_stat": np.nan, "welch_p": np.nan, "welch_df": np.nan,
                    "welch_warning": "No comparison: empty group.",
                    "mannwhitney_u": np.nan, "mannwhitney_p": np.nan,
                    "mannwhitney_warning": "No comparison: empty group.",
                    "cliffs_delta": np.nan, "cliffs_delta_magnitude": "NA",
                })
                continue
            welch_res = safe_welch_test(x, y)
            try:
                mw = mannwhitneyu(x, y, alternative="two-sided")
                mw_stat, mw_p, mw_warning = float(mw.statistic), float(mw.pvalue), ""
            except Exception as exc:
                mw_stat, mw_p, mw_warning = np.nan, np.nan, f"Mann-Whitney test failed: {exc}"
            delta = cliffs_delta(x, y)
            rows.append({
                "metric": metric, "class_a": class_a, "class_b": class_b,
                "n_a": int(x.size), "n_b": int(y.size),
                "mean_a": float(np.mean(x)), "mean_b": float(np.mean(y)),
                "median_a": float(np.median(x)), "median_b": float(np.median(y)),
                "delta_mean_a_minus_b": float(np.mean(x) - np.mean(y)),
                "welch_t_stat": welch_res["welch_t_stat"],
                "welch_p": welch_res["welch_p"],
                "welch_df": welch_res["welch_df"],
                "welch_warning": welch_res["welch_warning"],
                "mannwhitney_u": mw_stat, "mannwhitney_p": mw_p,
                "mannwhitney_warning": mw_warning,
                "cliffs_delta": float(delta),
                "cliffs_delta_magnitude": classify_cliffs_delta(delta),
            })
    out = pd.DataFrame(rows)
    if not out.empty:
        out["welch_fdr_bh"]       = benjamini_hochberg(out["welch_p"].tolist())
        out["mannwhitney_fdr_bh"] = benjamini_hochberg(out["mannwhitney_p"].tolist())
    return out


def export_structure_analysis(metrics_df, class_summary_df, comparison_df, output_prefix):
    metrics_df.to_csv(f"{output_prefix}_gene_structure_metrics.tsv", sep="\t", index=False)
    if class_summary_df is not None and not class_summary_df.empty:
        class_summary_df.to_csv(f"{output_prefix}_structure_summary_by_class.tsv",
                                sep="\t", index=False)
    if comparison_df is not None and not comparison_df.empty:
        comparison_df.to_csv(f"{output_prefix}_IG_vs_MEG_structure_stats.tsv",
                             sep="\t", index=False)


# ══════════════════════════════════════════════════════════════════════════════
#  Enriquecimiento cromosómico (idéntico al unified)
# ══════════════════════════════════════════════════════════════════════════════

def prepare_enrichment_gene_table(gene_summary_df, background_mode="all"):
    if gene_summary_df.empty:
        return pd.DataFrame()
    df = gene_summary_df.copy()
    df["gene_start"] = pd.to_numeric(df["gene_start"], errors="coerce")
    df["gene_end"]   = pd.to_numeric(df["gene_end"],   errors="coerce")
    df = df.dropna(subset=["chrom", "gene_start"]).copy()
    if background_mode == "IG+MEG":
        df = df[df["class_label"].isin(["IG", "MEG"])].copy()
    return df


def sliding_window_enrichment(gene_df, window_size=1_000_000, step_size=None):
    if gene_df.empty:
        return pd.DataFrame()
    if step_size is None:
        step_size = window_size
    N = int(len(gene_df))
    K = int((gene_df["class_label"] == "IG").sum())
    results = []
    for chrom, sub in gene_df.groupby("chrom"):
        sub = sub.sort_values("gene_start").copy()
        min_pos = int(sub["gene_start"].min())
        max_pos = int(sub["gene_end"].max() if sub["gene_end"].notna().any()
                      else sub["gene_start"].max())
        window_start = min_pos
        while window_start <= max_pos:
            window_end = window_start + window_size - 1
            window_df = sub[
                (sub["gene_start"] <= window_end)
                & (sub["gene_end"].fillna(sub["gene_start"]) >= window_start)
            ].copy()
            n = int(len(window_df))
            k = int((window_df["class_label"] == "IG").sum())
            pval = float(hypergeom.sf(k - 1, N, K, n)) if n > 0 and K > 0 else 1.0
            results.append({
                "chrom": chrom, "window_start": int(window_start),
                "window_end": int(window_end), "n_genes_window": n,
                "n_IG_window": k, "total_genes_background": N,
                "total_IG_background": K,
                "ig_fraction_window": float(k / n) if n > 0 else np.nan,
                "p_value": pval,
            })
            window_start += step_size
    out = pd.DataFrame(results)
    if not out.empty:
        out["fdr_bh"] = benjamini_hochberg(out["p_value"].tolist())
    return out


def summarize_enrichment(enrichment_df, fdr_threshold=0.05):
    if enrichment_df.empty:
        return {"n_windows": 0, "n_enriched_windows": 0,
                "chromosomes_with_enrichment": []}
    enriched = enrichment_df[enrichment_df["fdr_bh"] < fdr_threshold].copy()
    return {
        "n_windows": int(len(enrichment_df)),
        "n_enriched_windows": int(len(enriched)),
        "chromosomes_with_enrichment": sorted(
            enriched["chrom"].dropna().astype(str).unique().tolist(),
            key=natural_chrom_key),
    }


def save_enrichment_outputs(enrichment_df, summary, output_prefix):
    enrichment_df.to_csv(f"{output_prefix}_chromosomal_enrichment.tsv",
                         sep="\t", index=False)
    with open(f"{output_prefix}_chromosomal_enrichment_summary.json",
              "w", encoding="utf-8") as fh:
        json.dump(summary, fh, indent=2, ensure_ascii=False)


# ══════════════════════════════════════════════════════════════════════════════
#  FUNCTIONAL ENRICHMENT  —  g:Profiler REST API  (GO + KEGG + Reactome)
#
#  Usa la API pública de g:Profiler (https://biit.cs.ut.ee/gprofiler/) que
#  acepta Ensembl gene IDs directamente y no requiere API key.
#  Realiza enriquecimiento hipergeométrico corregido por BH-FDR para IGs
#  con fondo = todos los genes del genoma escaneado (IG + MEG + uiSEG).
#
#  Salidas:
#    {prefix}_functional_enrichment_IG.tsv    — tabla completa de términos
#    {prefix}_functional_enrichment_IG.json   — resumen compacto
#    {prefix}_functional_enrichment_IG.png    — dot-plot por fuente GO/KEGG
# ══════════════════════════════════════════════════════════════════════════════

_GPROFILER_URL = "https://biit.cs.ut.ee/gprofiler/api/gost/profile/"
_GPROFILER_HEADERS = {
    "Content-Type": "application/json",
    "User-Agent"  : "IGFinder/2.1.1 (katia.avi@gmail.com)",
}

# Fuentes que se solicitan a g:Profiler (se puede ampliar)
_GPROFILER_SOURCES = ["GO:BP", "GO:MF", "GO:CC", "KEGG", "REAC", "TF", "HP"]

# Máximo de genes por petición a g:Profiler (límite práctico de la API)
_GPROFILER_CHUNK = 2000


def _gprofiler_query(
    gene_ids     : List[str],
    background   : Optional[List[str]],
    organism     : str,
    sources      : List[str] = None,
    significance : float     = 0.05,
    retries      : int       = 4,
) -> List[dict]:
    """
    Llama a g:Profiler con un lote de gene IDs de Ensembl.

    Parameters
    ----------
    gene_ids    : lista de ENSG* IDs (o gene symbols si Ensembl no disponible)
    background  : lista de IDs de fondo (None = fondo anotado de g:Profiler)
    organism    : nombre de organismo g:Profiler (ej. 'hsapiens', 'mmusculus')
    sources     : lista de fuentes (default: _GPROFILER_SOURCES)
    significance: umbral de user_threshold para pre-filtrar la respuesta
    retries     : reintentos ante error de red

    Returns
    -------
    Lista de dicts con los resultados de enriquecimiento (campo 'result' de
    la respuesta JSON de g:Profiler).
    """
    if not gene_ids:
        return []
    sources = sources or _GPROFILER_SOURCES
    payload = {
        "organism"          : organism,
        "query"             : gene_ids[:_GPROFILER_CHUNK],
        "sources"           : sources,
        "user_threshold"    : significance,
        "significance_threshold_method": "fdr",
        "domain_scope"      : "annotated",
        "measure_underrepresentation": False,
        "no_evidences"      : True,
    }
    if background and len(background) > 1:
        payload["domain_scope"] = "custom"
        payload["background"]   = background[:_GPROFILER_CHUNK * 5]

    wait = 5
    for attempt in range(retries):
        try:
            r = requests.post(
                _GPROFILER_URL,
                headers=_GPROFILER_HEADERS,
                json=payload,
                timeout=90,
            )
            if r.ok:
                data = r.json()
                return data.get("result", [])
            if r.status_code == 429:
                time.sleep(int(r.headers.get("Retry-After", wait)))
                wait = min(wait * 2, 120)
                continue
            logging.warning("[FuncEnr] g:Profiler HTTP %d attempt %d",
                            r.status_code, attempt + 1)
            time.sleep(wait)
            wait = min(wait * 2, 120)
        except (requests.Timeout, requests.ConnectionError) as exc:
            logging.warning("[FuncEnr] Network error attempt %d: %s", attempt + 1, exc)
            time.sleep(wait)
            wait = min(wait * 2, 120)
        except Exception as exc:
            logging.warning("[FuncEnr] Unexpected error: %s", exc)
            time.sleep(wait)
    logging.error("[FuncEnr] g:Profiler query failed after %d retries", retries)
    return []


def _species_to_gprofiler_organism(species: str) -> str:
    """
    Convierte el production_name de Ensembl al código de organismo de g:Profiler.

    Cubre los organismos más comunes en IGFinder. Para especies no listadas,
    g:Profiler acepta el production_name directamente como 'hsapiens' → 'homo_sapiens'
    no es válido, así que construimos el código acrónimo (primera letra del género
    + especie completa en minúsculas).
    """
    _MAP = {
        "homo_sapiens"           : "hsapiens",
        "mus_musculus"           : "mmusculus",
        "rattus_norvegicus"      : "rnorvegicus",
        "danio_rerio"            : "drerio",
        "drosophila_melanogaster": "dmelanogaster",
        "caenorhabditis_elegans" : "celegans",
        "saccharomyces_cerevisiae": "scerevisiae",
        "arabidopsis_thaliana"   : "athaliana",
        "gallus_gallus"          : "ggallus",
        "bos_taurus"             : "btaurus",
        "sus_scrofa"             : "sscrofa",
        "equus_caballus"         : "ecaballus",
        "canis_lupus_familiaris" : "clfamiliaris",
        "felis_catus"            : "fcatus",
        "xenopus_tropicalis"     : "xtropicalis",
        "oryzias_latipes"        : "olatipes",
        "tetraodon_nigroviridis" : "tnigroviridis",
        "takifugu_rubripes"      : "trubripes",
        "anopheles_gambiae"      : "agambiae",
    }
    s = species.lower().strip()
    if s in _MAP:
        return _MAP[s]
    # Construir acrónimo: primera letra del género + epiteto específico completo
    parts = s.split("_")
    if len(parts) >= 2:
        return parts[0][0] + parts[1]
    return s


def run_functional_enrichment(
    ig_df          : pd.DataFrame,
    gene_summary_df: pd.DataFrame,
    species        : str,
    sources        : Optional[List[str]] = None,
    fdr_threshold  : float = 0.05,
    log_fn         = None,
) -> pd.DataFrame:
    """
    Enriquecimiento funcional de genes IG usando g:Profiler.

    Parameters
    ----------
    ig_df           : DataFrame de genes IG (debe tener columna 'gene_id')
    gene_summary_df : DataFrame resumen de todos los genes (fondo)
    species         : production_name de Ensembl (ej. 'homo_sapiens')
    sources         : fuentes GO/KEGG/REAC a analizar (None = default)
    fdr_threshold   : umbral de corte FDR para reportar términos
    log_fn          : callable(msg, tag) para enviar mensajes al pipeline

    Returns
    -------
    DataFrame con las columnas:
        source, term_id, term_name, p_value, fdr, term_size,
        query_size, intersection_size, gene_class
    """
    def _log(msg, t="info"):
        if log_fn:
            log_fn(msg, t)
        else:
            logging.info(msg)

    if ig_df is None or ig_df.empty:
        _log("  ℹ FuncEnr: no IG genes to analyze", "warn")
        return pd.DataFrame()

    organism = _species_to_gprofiler_organism(species)
    _log(f"  → g:Profiler organism code: '{organism}'", "dim")

    # ── Construir listas de IDs ───────────────────────────────────────────
    id_col = None
    for c in ("gene_id", "Gene_ID", "ensembl_id", "stable_id"):
        if c in ig_df.columns:
            id_col = c; break
    if id_col is None:
        _log("  ⚠ FuncEnr: no gene_id column found in IG table", "warn")
        return pd.DataFrame()

    ig_ids   = ig_df[id_col].dropna().astype(str).tolist()
    bg_ids   = None
    if gene_summary_df is not None and not gene_summary_df.empty:
        bg_col = id_col if id_col in gene_summary_df.columns else (
            "gene_id" if "gene_id" in gene_summary_df.columns else None)
        if bg_col:
            bg_ids = gene_summary_df[bg_col].dropna().astype(str).tolist()

    if not ig_ids:
        _log("  ℹ FuncEnr: empty IG gene list", "warn")
        return pd.DataFrame()

    _log(f"  Querying g:Profiler: {len(ig_ids):,} IG genes  "
         f"(background: {len(bg_ids):,})" if bg_ids else
         f"  Querying g:Profiler: {len(ig_ids):,} IG genes  (annotated background)", "info")

    results_raw = _gprofiler_query(
        gene_ids=ig_ids,
        background=bg_ids,
        organism=organism,
        sources=sources,
        significance=fdr_threshold * 10,   # pre-filtro holgado; FDR real se aplica abajo
    )

    if not results_raw:
        _log("  ℹ FuncEnr: no significant terms returned (check species code)", "warn")
        return pd.DataFrame()

    # ── Parsear resultados de g:Profiler ─────────────────────────────────
    rows = []
    for term in results_raw:
        p_adj = float(term.get("p_value", 1.0))
        if p_adj > fdr_threshold:
            continue
        rows.append({
            "source"            : str(term.get("source", "")),
            "term_id"           : str(term.get("native", term.get("id", ""))),
            "term_name"         : str(term.get("name", "")),
            "p_value"           : float(term.get("p_value", 1.0)),
            "fdr"               : p_adj,
            "term_size"         : int(term.get("term_size", 0)),
            "query_size"        : int(term.get("query_size", 0)),
            "intersection_size" : int(term.get("intersection_size", 0)),
            "effective_domain_size": int(term.get("effective_domain_size", 0)),
            "recall"            : float(term.get("recall", 0.0)),
            "precision"         : float(term.get("precision", 0.0)),
            "gene_class"        : "IG",
        })

    if not rows:
        _log(f"  ℹ FuncEnr: 0 terms pass FDR < {fdr_threshold}", "warn")
        return pd.DataFrame()

    df = pd.DataFrame(rows).sort_values("fdr")
    _log(f"  ✔ FuncEnr: {len(df):,} significant terms "
         f"(FDR < {fdr_threshold})  across "
         f"{df['source'].nunique()} source(s)", "ok")
    return df


def save_functional_enrichment_outputs(
    enr_df: pd.DataFrame,
    output_prefix: str,
) -> None:
    """Guarda la tabla TSV y el JSON resumen del enriquecimiento funcional."""
    if enr_df is None or enr_df.empty:
        return
    tsv_path = f"{output_prefix}_functional_enrichment_IG.tsv"
    enr_df.to_csv(tsv_path, sep="\t", index=False)

    # Resumen compacto por fuente
    summary: dict = {}
    for src, grp in enr_df.groupby("source"):
        top5 = grp.nsmallest(5, "fdr")[["term_id", "term_name", "fdr"]].to_dict("records")
        summary[src] = {
            "n_significant": int(len(grp)),
            "top5"          : top5,
        }
    with open(f"{output_prefix}_functional_enrichment_IG.json",
              "w", encoding="utf-8") as fh:
        json.dump(summary, fh, indent=2, ensure_ascii=False)


def save_plot_functional_enrichment(
    enr_df       : pd.DataFrame,
    output_prefix: str,
    top_n        : int   = 15,
    fdr_threshold: float = 0.05,
) -> None:
    """
    Genera un dot-plot de enriquecimiento funcional por fuente GO/KEGG.

    Eje Y: términos (top_n por fuente, ordenados por -log10 FDR).
    Eje X: -log10(FDR).
    Tamaño del punto: intersection_size.
    Color: fuente (GO:BP=cian, GO:MF=teal, GO:CC=emerald, KEGG=amber, REAC=violet).
    """
    if enr_df is None or enr_df.empty:
        return

    _SOURCE_COLORS = {
        "GO:BP": _PLT_CP["cyan"],
        "GO:MF": _PLT_CP["teal"],
        "GO:CC": _PLT_CP["emerald"],
        "KEGG" : _PLT_CP["amber"],
        "REAC" : _PLT_CP["violet"],
        "TF"   : _PLT_CP["orchid"],
        "HP"   : _PLT_CP["red"],
    }

    # Top N por fuente
    frames = []
    for src, grp in enr_df.groupby("source"):
        frames.append(grp.nsmallest(min(top_n, len(grp)), "fdr"))
    if not frames:
        return
    plot_df = pd.concat(frames, ignore_index=True).copy()
    plot_df["-log10_fdr"] = -np.log10(plot_df["fdr"].clip(lower=1e-300))
    plot_df["label"] = plot_df.apply(
        lambda r: f"[{r['source']}] {r['term_name'][:45]}", axis=1)
    plot_df = plot_df.sort_values("-log10_fdr", ascending=True)

    fig_h = max(5, 0.35 * len(plot_df) + 2)
    fig, ax = plt.subplots(figsize=(12, fig_h),
                           facecolor=_PLT_CP["bg"])
    ax.set_facecolor(_PLT_CP["panel"])

    for _, row in plot_df.iterrows():
        col  = _SOURCE_COLORS.get(row["source"], _PLT_CP["cyan"])
        size = max(20, min(300, row.get("intersection_size", 5) * 12))
        ax.scatter(row["-log10_fdr"], row["label"],
                   s=size, color=col, alpha=0.82,
                   edgecolors=_PLT_CP["border"], linewidths=0.5, zorder=3)

    # Línea de corte
    fdr_line = -np.log10(fdr_threshold)
    ax.axvline(fdr_line, color=_PLT_CP["red"], lw=1.2, ls="--",
               alpha=0.7, label=f"FDR = {fdr_threshold}")

    # Estilo
    for spine in ax.spines.values():
        spine.set_color(_PLT_CP["border"])
    ax.tick_params(colors=_PLT_CP["txt_muted"], labelsize=8)
    ax.xaxis.label.set_color(_PLT_CP["txt_dim"])
    ax.yaxis.label.set_color(_PLT_CP["txt_dim"])
    ax.set_xlabel("-log₁₀(FDR)", color=_PLT_CP["txt_dim"], fontsize=10)
    ax.set_title("Functional Enrichment of Intronless Genes (g:Profiler)",
                 color=_PLT_CP["txt_dim"], fontsize=12, fontweight="bold", pad=10)
    ax.grid(axis="x", color=_PLT_CP["border"], alpha=0.3, lw=0.5)

    # Leyenda de fuentes
    legend_patches = [
        Patch(color=c, label=src)
        for src, c in _SOURCE_COLORS.items()
        if src in enr_df["source"].values
    ]
    if legend_patches:
        ax.legend(handles=legend_patches, loc="lower right",
                  framealpha=0.2, fontsize=8,
                  facecolor=_PLT_CP["panel"],
                  edgecolor=_PLT_CP["border"],
                  labelcolor=_PLT_CP["txt_muted"])

    plt.tight_layout()
    out_path = f"{output_prefix}_functional_enrichment_IG.png"
    fig.savefig(out_path, dpi=150, bbox_inches="tight",
                facecolor=_PLT_CP["bg"])
    plt.close(fig)


# ══════════════════════════════════════════════════════════════════════════════
#  ORTHOLOGY  —  Ensembl Compara REST API
#
#  Para cada gen IG, consulta la API de Ensembl Compara y recupera sus
#  ortólogos en las especies objetivo configuradas.  Construye:
#    • Una tabla larga (gene_id, species_target, homology_type, homolog_id)
#    • Una matriz binaria gene × species (presencia/ausencia de ortólogo)
#    • Un índice de conservación por gen (fracción de especies con ortólogo)
#
#  Salidas:
#    {prefix}_orthology_IG.tsv           — tabla larga de ortólogos
#    {prefix}_orthology_matrix_IG.tsv    — matriz binaria gene × species
#    {prefix}_orthology_summary_IG.json  — estadísticas resumen
#    {prefix}_orthology_heatmap_IG.png   — heatmap clusterizado
#
#  Las consultas se realizan en lotes usando el endpoint:
#    GET /homology/id/{id}?type=all&target_species={sp}&format=condensed
#  con el retry/backoff de _ens_get.
# ══════════════════════════════════════════════════════════════════════════════

# Especies objetivo por defecto para ortología (pueden ajustarse en la GUI)
_ORTHOLOGY_DEFAULT_TARGETS = [
    "mus_musculus", "rattus_norvegicus", "danio_rerio",
    "drosophila_melanogaster", "caenorhabditis_elegans",
    "gallus_gallus", "xenopus_tropicalis",
]

_ORTHOLOG_CACHE: Dict[Tuple[str,str], list] = {}   # {(gene_id|name, tgt_sp): raw_result}
_ORTHOLOG_EXON_CACHE: Dict[str, dict] = {}         # {target_gene_id: intronless-status dict}

# Rate-limit seguro para Ensembl REST: ≥0.40 s entre peticiones por hilo
_ORTH_INTER_DELAY: float = 0.40   # conservador para Ensembl rate-limit

# Tipos de homología Ensembl Compara y su peso de conservación.
# Tipos no listados aquí reciben el peso por defecto (0.5).
_HOMOLOGY_WEIGHTS: Dict[str, float] = {
    "ortholog_one2one"      : 1.00,
    "ortholog_one2many"     : 0.75,
    "ortholog_many2many"    : 0.60,
    "within_species_paralog": 0.30,   # conservado: indica familia presente
    "other_paralog"         : 0.20,
    "gene_split"            : 0.40,
    "alt_allele"            : 0.10,
}
_HOMOLOGY_FILTER_ZERO: Set[str] = set()  # No filtrar nada — todo es informativo

# Legacy alias — mantiene retrocompatibilidad con cualquier código externo
# que aún referencie _HOMOLOGY_TYPES.  DEBE ir DESPUÉS de _HOMOLOGY_WEIGHTS.
_HOMOLOGY_TYPES = _HOMOLOGY_WEIGHTS


def ensembl_test_connection(species: str = "homo_sapiens",
                            log_fn=None) -> Tuple[bool, str]:
    """
    Verifica la conectividad con Ensembl REST API ANTES de iniciar el análisis.

    Hace 3 chequeos rápidos:
      1. /info/ping        → endpoint disponible
      2. /info/assembly/sp → la especie existe en este host
      3. /lookup/symbol    → un gen conocido (TP53/ACTB) tiene datos

    Returns (success, diagnostic_message).
    En caso de éxito fija ENSEMBL_REST_API al host correcto para la especie.
    """
    global ENSEMBL_REST_API

    def _log(msg, t="info"):
        if log_fn:
            log_fn(msg, t)
        else:
            logging.info(msg)

    # 1. Ping general — ¿está vivo el servicio?
    _log(f"  ⟳ Test 1/3: /info/ping en {ENSEMBL_REST_API} …", "dim")
    try:
        ping = _ens_get("/info/ping", retries=2, raise_on_4xx=False)
        if ping is None:
            return False, ("Ping rechazado por Ensembl (4xx). "
                           "Verifica tu conexión a internet o firewall.")
        _log(f"    ✔ Ping OK", "ok")
    except Exception as exc:
        return False, (f"Sin conexión a Ensembl REST: {exc}. "
                       "Revisa internet/proxy/firewall.")

    # 2. ¿La especie existe en alguno de los hosts?
    sp_lower = (species or "").strip().lower()
    if not sp_lower:
        return False, "No species name provided."

    found_host = None
    for host in _ENSEMBL_REST_CANDIDATES:
        ENSEMBL_REST_API = host
        _log(f"  ⟳ Test 2/3: /info/assembly/{sp_lower} en {host} …", "dim")
        try:
            data = _ens_get(f"/info/assembly/{sp_lower}",
                            retries=2, raise_on_4xx=False)
            if data and isinstance(data, dict) and (
                    data.get("assembly_name") or data.get("default_coord_system_version")):
                found_host = host
                _log(f"    ✔ '{sp_lower}' encontrada en {host}  "
                     f"({data.get('assembly_name', '?')})", "ok")
                break
            else:
                _log(f"    · {sp_lower} no aparece en {host}", "dim")
        except Exception as exc:
            _log(f"    · {host} → {exc}", "dim")

    if not found_host:
        return False, (f"La especie '{sp_lower}' no se encuentra en ningún "
                       f"host Ensembl. Verifica que sea un production_name "
                       f"válido (ej: 'homo_sapiens', no 'human').")

    ENSEMBL_REST_API = found_host

    # 3. Sanity: un gen ortólogo conocido funciona?
    _log(f"  ⟳ Test 3/3: gen control vía /homology/symbol …", "dim")
    test_genes = ["TP53", "ACTB", "GAPDH", "BRCA1"]
    for tg in test_genes:
        try:
            test_data = _ens_get(
                f"/homology/symbol/{sp_lower}/{tg}",
                params={"type": "orthologues",
                        "target_species": "mus_musculus",
                        "format": "condensed"},
                retries=1, raise_on_4xx=False)
            if isinstance(test_data, dict):
                entries = test_data.get("data", [])
                if entries and entries[0].get("homologies"):
                    n_orth = len(entries[0]["homologies"])
                    _log(f"    ✔ {tg}: {n_orth} orthologs found "
                         f"(API operativa)", "ok")
                    return True, (f"Conexión Ensembl OK  ·  host: {found_host}  "
                                  f"·  control: {tg} → {n_orth} orthologs")
        except Exception:
            continue

    # Si ninguno de los genes de control devolvió datos, hay algo raro
    return True, (f"Conexión OK pero ortología vacía para genes control en "
                  f"{sp_lower}. Esto es POSIBLE si la especie es exótica.")


def _fetch_single_sp_orthologs(
    gene_id   : str,
    gene_name : str,
    species   : str,
    tgt       : str,
    retries   : int = 2,
) -> list:
    """
    Fetches orthologs for ONE (gene, target_species) pair.

    Multi-strategy approach (each fail-fast on 4xx):
      1. /homology/id/{ENSG}            (params: type=orthologues, format=full)
      2. /homology/symbol/{sp}/{NAME}   (params: type=orthologues)
      3. /homology/symbol/{sp}/{name}   (lowercase fallback)

    Uses format=full instead of condensed because condensed has known issues
    when combined with target_species filter.

    Returns list of homology dicts (may be empty).
    """
    cache_key = (gene_id or gene_name, tgt)
    if cache_key in _ORTHOLOG_CACHE:
        return _ORTHOLOG_CACHE[cache_key]

    def _parse_homologies(data, tgt_filter: str) -> list:
        """
        Parse Ensembl /homology response → list of flat dicts.
        Handles BOTH condensed and full formats.
        Filters to target species at parse time (defensive).
        """
        if not isinstance(data, dict):
            return []
        entries = data.get("data", [])
        if not entries:
            return []
        out = []
        for row in entries:
            homols = row.get("homologies", []) or []
            for h in homols:
                htype = str(h.get("type", ""))
                weight = _HOMOLOGY_WEIGHTS.get(htype, 0.5)
                tgt_info = h.get("target", {}) or {}
                tgt_id   = str(tgt_info.get("id", ""))
                tgt_sp   = str(tgt_info.get("species", "")).lower()
                # Defensive: filter to requested target species
                if tgt_filter and tgt_sp and tgt_sp != tgt_filter.lower():
                    continue
                if not tgt_id:
                    continue
                tgt_name = str(
                    tgt_info.get("display_label") or
                    tgt_info.get("label") or
                    tgt_info.get("symbol") or
                    tgt_id
                )
                # identity: try multiple field names
                identity = float(
                    tgt_info.get("perc_id") or
                    h.get("identity") or
                    h.get("dn_ds") or 0.0)
                out.append({
                    "homology_type"     : htype,
                    "target_species"    : tgt_sp or tgt_filter,
                    "target_gene_id"    : tgt_id,
                    "target_gene_name"  : tgt_name,
                    "identity"          : identity,
                    "conservation_score": weight,
                })
        return out

    # IMPORTANT: format=full is more reliable than condensed for target_species
    base_params = lambda: {
        "type"          : "orthologues",   # only orthologs (not paralogs)
        "target_species": tgt,
        "format"        : "full",
    }

    results = []
    last_error = None

    # ── Strategy 1: by Ensembl stable ID ─────────────────────────────────
    if gene_id and gene_id.startswith("ENS"):
        try:
            data = _ens_get(
                f"/homology/id/{gene_id}",
                params=base_params(), retries=retries,
                raise_on_4xx=False,   # quietly skip 4xx — gene may not exist
            )
            if data is not None:
                results = _parse_homologies(data, tgt)
        except Exception as exc:
            last_error = exc

    # ── Strategy 2: by gene symbol (uppercase — convention for human/mouse)
    if not results and gene_name and gene_name.strip():
        gname_clean = gene_name.strip().upper().replace(" ", "_")
        try:
            data = _ens_get(
                f"/homology/symbol/{species}/{gname_clean}",
                params=base_params(), retries=retries,
                raise_on_4xx=False,
            )
            if data is not None:
                results = _parse_homologies(data, tgt)
        except Exception as exc:
            last_error = exc

    # ── Strategy 3: lowercase symbol (some species need it: zebrafish, etc.)
    if not results and gene_name and gene_name.strip():
        gname_lc = gene_name.strip().lower()
        try:
            data = _ens_get(
                f"/homology/symbol/{species}/{gname_lc}",
                params=base_params(), retries=1,
                raise_on_4xx=False,
            )
            if data is not None:
                results = _parse_homologies(data, tgt)
        except Exception:
            pass

    # Cache only NON-EMPTY results — empty results re-tried on next run
    if results:
        _ORTHOLOG_CACHE[cache_key] = results
    return results


def fetch_ortholog_intronless_status(
    target_gene_id: str,
    retries        : int = 2,
) -> Optional[dict]:
    """
    Determina si un gen ortólogo conserva el estado INTRONLESS.

    Consulta /lookup/id/{gene_id}?expand=1 en Ensembl, que devuelve todos los
    transcritos del gen con su lista de exones. Aplica el MISMO criterio que la
    clasificación IG: el gen es intronless si TODOS sus transcritos son de exón
    único (y ninguno multi-exón).

    Returns
    -------
    dict con:
      target_gene_id     : el ID consultado
      is_intronless      : bool | None  (None si no se pudo resolver)
      n_transcripts      : int
      max_exon_count     : int   (máximo nº de exones entre transcritos)
      min_exon_count     : int
    o None si la consulta falla por completo.

    Cachea resultados (incluido el negativo) para no repetir la consulta.
    """
    if not target_gene_id:
        return None
    cached = _ORTHOLOG_EXON_CACHE.get(target_gene_id)
    if cached is not None:
        return cached

    try:
        data = _ens_get(
            f"/lookup/id/{target_gene_id}",
            params={"expand": 1},
            retries=retries,
            raise_on_4xx=False,
        )
    except Exception as exc:
        logging.debug("[OrthExon] lookup falló para %s: %s", target_gene_id, exc)
        return None

    if not isinstance(data, dict):
        return None

    transcripts = data.get("Transcript", []) or []
    if not transcripts:
        # Sin transcritos expandidos → no se puede determinar
        result = {
            "target_gene_id": target_gene_id,
            "is_intronless":  None,
            "n_transcripts":  0,
            "max_exon_count": 0,
            "min_exon_count": 0,
        }
        _ORTHOLOG_EXON_CACHE[target_gene_id] = result
        return result

    exon_counts = []
    for tx in transcripts:
        n_exon = len(tx.get("Exon", []) or [])
        if n_exon > 0:
            exon_counts.append(n_exon)

    if not exon_counts:
        result = {
            "target_gene_id": target_gene_id,
            "is_intronless":  None,
            "n_transcripts":  len(transcripts),
            "max_exon_count": 0,
            "min_exon_count": 0,
        }
        _ORTHOLOG_EXON_CACHE[target_gene_id] = result
        return result

    max_ex = max(exon_counts)
    min_ex = min(exon_counts)
    # Criterio IG: TODOS los transcritos de exón único (ninguno multi-exón)
    is_intronless = (max_ex == 1)

    result = {
        "target_gene_id": target_gene_id,
        "is_intronless":  bool(is_intronless),
        "n_transcripts":  len(transcripts),
        "max_exon_count": int(max_ex),
        "min_exon_count": int(min_ex),
    }
    _ORTHOLOG_EXON_CACHE[target_gene_id] = result
    return result


def fetch_orthologs_for_gene(
    gene_id       : str,
    species       : str,
    target_species: List[str],
    gene_name     : str = "",
    retries       : int = 3,
) -> List[dict]:
    """
    Recupera ortólogos de un gen IG usando Ensembl Compara.

    Estrategia dual (ID + símbolo) para máxima cobertura de genes IG.
    Cachea SOLO resultados no vacíos para permitir reintentos.

    Parameters
    ----------
    gene_id        : Ensembl stable ID (ENSG…)
    species        : especie fuente (production_name)
    target_species : lista de especies objetivo
    gene_name      : símbolo del gen (ej. IGHV1-2) — fallback si ID falla
    retries        : reintentos ante error de red

    Returns
    -------
    Lista de dicts con homology_type, target_species, target_gene_id,
    target_gene_name, identity, conservation_score.
    """
    results = []
    for tgt in target_species:
        if tgt.lower() == species.lower():
            continue
        sp_results = _fetch_single_sp_orthologs(
            gene_id=gene_id,
            gene_name=gene_name,
            species=species,
            tgt=tgt,
            retries=retries,
        )
        results.extend(sp_results)
        time.sleep(_ORTH_INTER_DELAY)
    return results


def run_orthology_analysis(
    ig_df         : pd.DataFrame,
    species       : str,
    target_species: Optional[List[str]] = None,
    max_genes     : int  = 500,
    log_fn        = None,
    abort_flag    = None,
    max_workers   : int  = 2,   # conservador: 2 hilos respetan rate-limit Ensembl
    check_intronless_conservation: bool = False,
) -> Tuple[pd.DataFrame, pd.DataFrame, dict]:
    """
    Análisis de ortología de genes IG con Ensembl Compara.
    Versión optimizada:
      • ThreadPoolExecutor (max_workers=2) para I/O paralelo
      • _omics_math.build_orthology_matrix → pivot_table O(N)
      • _omics_math.conservation_stats → numpy vectorizado
      • SIN filtro de autosomas (analiza todos los cromosomas)

    Parameters
    ----------
    ig_df         : DataFrame de genes IG — TODOS los cromosomas
    species       : especie fuente
    target_species: especies objetivo (None = _ORTHOLOGY_DEFAULT_TARGETS)
    max_genes     : cap de genes IG a consultar
    log_fn        : callable(msg, tag)
    abort_flag    : callable() → bool  o  threading.Event
    max_workers   : hilos paralelos (≤2 para respetar rate-limit de Ensembl)

    Returns
    -------
    long_df    : tabla larga  [source_gene_id, homology_type, target_species, ...]
    matrix_df  : matriz binaria  gene_id × target_species  (uint8, numpy-backed)
    summary    : dict con estadísticas (numpy vectorizado)
    """
    def _log(msg, t="info"):
        if log_fn:
            log_fn(msg, t)
        else:
            logging.info(msg)

    def _aborted():
        if abort_flag is None:
            return False
        if callable(abort_flag):
            return abort_flag()
        if hasattr(abort_flag, "is_set"):
            return abort_flag.is_set()
        return bool(abort_flag)

    targets = target_species or _ORTHOLOGY_DEFAULT_TARGETS

    if ig_df is None or ig_df.empty:
        _log("  ℹ Orthology: no IG genes to analyze", "warn")
        return pd.DataFrame(), pd.DataFrame(), {}

    id_col = next((c for c in ("gene_id","Gene_ID","ensembl_id","stable_id")
                   if c in ig_df.columns), None)
    if id_col is None:
        _log("  ⚠ Orthology: no gene_id column in IG table", "warn")
        return pd.DataFrame(), pd.DataFrame(), {}

    # Build (gene_id, gene_name) pairs for dual-strategy lookup
    name_col = next((c for c in ("gene_name", "Gene_Name", "symbol", "name")
                     if c in ig_df.columns), None)
    sub = ig_df[[id_col] + ([name_col] if name_col else [])].drop_duplicates(
        subset=[id_col]).dropna(subset=[id_col])
    gene_ids   = sub[id_col].astype(str).tolist()
    gene_names = sub[name_col].astype(str).tolist() if name_col else [""] * len(gene_ids)

    # Cap — Ensembl Compara es lento
    if len(gene_ids) > max_genes:
        _log(f"  ℹ Orthology: capping to {max_genes:,} genes "
             f"(total IG = {len(gene_ids):,}  ·  todos los cromosomas)", "warn")
        gene_ids   = gene_ids[:max_genes]
        gene_names = gene_names[:max_genes]

    # Clear stale empty-cache entries so retries work
    stale = [k for k in list(_ORTHOLOG_CACHE.keys())
             if k[0] in gene_ids and not _ORTHOLOG_CACHE[k]]
    for k in stale:
        del _ORTHOLOG_CACHE[k]

    _log(f"  Querying Ensembl Compara: {len(gene_ids):,} IG genes × "
         f"{len(targets)} species  ·  workers={max_workers}  "
         f"·  delay={_ORTH_INTER_DELAY:.2f}s/req  "
         f"·  strategy=ID+symbol", "info")
    _log(f"  Sample IDs: {gene_ids[:3]}  |  "
         f"Sample names: {gene_names[:3]}", "dim")

    # ── Fetch en paralelo (max_workers=2) ────────────────────────────────────
    gid_name_pairs = list(zip(gene_ids, gene_names))

    fetch_results = _omics_math.parallel_fetch(
        fn          = lambda pair: fetch_orthologs_for_gene(
                          pair[0], species, targets, gene_name=pair[1]),
        items       = gid_name_pairs,
        max_workers = max(1, min(max_workers, 2)),
        abort_flag  = _aborted,
        inter_delay = _ORTH_INTER_DELAY,
        log_fn      = _log,
        log_every   = 30,
    )

    if _aborted():
        _log("  ■ Orthology aborted by user", "warn")
        return pd.DataFrame(), pd.DataFrame(), {}

    # ── Construir tabla larga ─────────────────────────────────────────────────
    rows = []
    n_with_hits = 0
    for pair, orthologs in fetch_results:
        gid = pair[0] if isinstance(pair, (list, tuple)) else pair
        if orthologs:
            n_with_hits += 1
        for h in orthologs:
            rows.append({"source_gene_id": gid, **h})

    _log(f"  ℹ Orthology raw hits: {n_with_hits:,}/{len(gene_ids):,} genes "
         f"have ≥1 homolog  ·  total rows: {len(rows):,}", "dim")

    if not rows:
        _log("  ℹ Orthology: 0 homologs found across all strategies.", "warn")
        _log("    Posibles causas:", "dim")
        _log("    · Los genes IG V/D/J raramente tienen ortólogos 1:1 en Ensembl Compara", "dim")
        _log("    · Verifica que los gene_ids sean ENSG estables (no desactualizados)", "dim")
        _log("    · Las especies objetivo pueden no tener datos de Compara para IG", "dim")
        return pd.DataFrame(), pd.DataFrame(), {}

    long_df = pd.DataFrame(rows)

    # ── (Opt-in) Conservación del ESTADO INTRONLESS en cada ortólogo ─────────
    # Para cada ortólogo, consultamos sus exones en Ensembl y determinamos si
    # SIGUE siendo intronless (mismo criterio que IG: todos sus transcritos de
    # exón único). Esto responde la pregunta evolutiva central: ¿el gen perdió
    # o ganó intrones en otras especies? Es opt-in porque añade 1 llamada extra
    # por ortólogo (puede multiplicar varias veces el tiempo del análisis).
    if check_intronless_conservation and not long_df.empty:
        tgt_ids = (long_df["target_gene_id"].dropna().astype(str)
                   .unique().tolist())
        tgt_ids = [t for t in tgt_ids if t]
        _log(f"  ⬢ Conservación intronless: consultando exones de "
             f"{len(tgt_ids):,} ortólogos (1 llamada/ortólogo)…", "info")

        status_results = _omics_math.parallel_fetch(
            fn          = lambda gid: fetch_ortholog_intronless_status(gid),
            items       = tgt_ids,
            max_workers = max(1, min(max_workers, 2)),
            abort_flag  = _aborted,
            inter_delay = _ORTH_INTER_DELAY,
            log_fn      = _log,
            log_every   = 30,
        )

        # Mapear target_gene_id → estado
        status_map = {}
        for gid, st in status_results:
            if isinstance(st, dict):
                status_map[str(gid)] = st

        def _il_flag(tid):
            st = status_map.get(str(tid))
            return st.get("is_intronless") if st else None

        def _il_exons(tid):
            st = status_map.get(str(tid))
            return st.get("max_exon_count") if st else None

        long_df["ortholog_is_intronless"] = long_df["target_gene_id"].map(_il_flag)
        long_df["ortholog_max_exons"]     = long_df["target_gene_id"].map(_il_exons)

        # Resumen: fracción de ortólogos que conservan el estado intronless,
        # global y por especie.
        resolved = long_df[long_df["ortholog_is_intronless"].notna()]
        n_resolved   = int(len(resolved))
        n_conserved  = int(resolved["ortholog_is_intronless"].sum()) if n_resolved else 0
        frac_global  = (n_conserved / n_resolved) if n_resolved else 0.0

        by_species = {}
        if n_resolved:
            for sp, grp in resolved.groupby("target_species"):
                n_sp  = len(grp)
                n_con = int(grp["ortholog_is_intronless"].sum())
                by_species[str(sp)] = {
                    "n_orthologs_resolved": int(n_sp),
                    "n_intronless_conserved": n_con,
                    "fraction_conserved": (n_con / n_sp) if n_sp else 0.0,
                }

        _log(f"  ✔ Conservación intronless: {n_conserved:,}/{n_resolved:,} "
             f"ortólogos resueltos siguen siendo intronless "
             f"({frac_global:.1%} global)", "ok")

    # ── Matriz ponderada gene × species (conservation_score) ─────────────────
    _log("  Computing weighted conservation matrix …", "dim")
    matrix_df = _omics_math.build_orthology_matrix(
        long_df, gene_ids, targets, weighted=True)

    # ── Estadísticas (vectorizado) ────────────────────────────────────────────
    summary = _omics_math.conservation_stats(matrix_df)

    # Incorporar el resumen de conservación intronless si se calculó
    if check_intronless_conservation and "ortholog_is_intronless" in long_df.columns:
        resolved = long_df[long_df["ortholog_is_intronless"].notna()]
        n_res = int(len(resolved))
        n_con = int(resolved["ortholog_is_intronless"].sum()) if n_res else 0
        summary["intronless_conservation"] = {
            "n_orthologs_resolved":   n_res,
            "n_intronless_conserved": n_con,
            "fraction_conserved_global": (n_con / n_res) if n_res else 0.0,
            "by_species": by_species if n_res else {},
        }

    # ── Análisis por familia IG (IGHV/IGHD/IGHJ/IGLV/etc.) ──────────────────
    try:
        family_df = _omics_math.build_family_conservation(long_df, ig_df)
        summary["family_conservation_df"] = family_df
    except Exception as _fe:
        logging.debug("[Orthology] family analysis: %s", _fe)
        family_df = pd.DataFrame()

    _log(f"  ✔ Orthology: {summary.get('n_with_any_ortholog', n_with_hits):,} / "
         f"{len(gene_ids):,} IG genes have ≥1 homolog  "
         f"(mean conservation: {summary.get('mean_conservation', 0):.1%}  ·  "
         f"fully conserved: {summary.get('n_fully_conserved', 0):,})", "ok")

    return long_df, matrix_df, summary


def save_orthology_outputs(
    long_df  : pd.DataFrame,
    matrix_df: pd.DataFrame,
    summary  : dict,
    output_prefix: str,
) -> None:
    """Guarda tabla larga, matriz y JSON de ortología."""
    if long_df is not None and not long_df.empty:
        long_df.to_csv(f"{output_prefix}_orthology_IG.tsv",
                       sep="\t", index=False)
    if matrix_df is not None and not matrix_df.empty:
        matrix_df.to_csv(f"{output_prefix}_orthology_matrix_IG.tsv")
    if summary:
        # Filtrar valores no serializables (DataFrames, ndarrays) antes de
        # volcar a JSON. Los DataFrames del summary (p.ej. family_conservation_df)
        # ya se guardan aparte como TSV; en el JSON solo van escalares/listas.
        def _json_safe(obj):
            import numpy as _np
            if isinstance(obj, pd.DataFrame):
                return f"<DataFrame {obj.shape[0]}x{obj.shape[1]} — ver TSV>"
            if isinstance(obj, pd.Series):
                return obj.to_dict()
            if isinstance(obj, _np.ndarray):
                return obj.tolist()
            if isinstance(obj, (_np.integer,)):
                return int(obj)
            if isinstance(obj, (_np.floating,)):
                return float(obj)
            if isinstance(obj, dict):
                return {k: _json_safe(v) for k, v in obj.items()}
            if isinstance(obj, (list, tuple)):
                return [_json_safe(v) for v in obj]
            return obj
        summary_safe = _json_safe(summary)
        with open(f"{output_prefix}_orthology_summary_IG.json",
                  "w", encoding="utf-8") as fh:
            json.dump(summary_safe, fh, indent=2, ensure_ascii=False)


def save_plot_orthology_heatmap(
    matrix_df    : pd.DataFrame,
    summary      : dict,
    output_prefix: str,
) -> None:
    """
    Heatmap clusterizado de ortología: filas = genes IG, columnas = especies.

    Si seaborn está disponible, usa clustermap.  Si no, usa matshow estándar.
    Para matrices muy grandes (>300 genes) se muestra la fracción de
    conservación por especie como barplot compacto.
    """
    if matrix_df is None or matrix_df.empty:
        return

    n_genes, n_sp = matrix_df.shape
    _log_limit    = 300   # umbral para cambiar a barplot

    fig = plt.figure(figsize=(max(8, n_sp * 1.2),
                               min(max(5, n_genes * 0.18), 22)),
                     facecolor=_PLT_CP["bg"])

    if n_genes > _log_limit:
        # ── Barplot compacto de conservación por especie ──────────────────
        ax = fig.add_subplot(111)
        ax.set_facecolor(_PLT_CP["panel"])
        cons = matrix_df.mean(axis=0).sort_values(ascending=False)
        bars = ax.bar(range(len(cons)), cons.values,
                      color=_PLT_CP["cyan"], alpha=0.8,
                      edgecolor=_PLT_CP["border"], linewidth=0.5)
        ax.set_xticks(range(len(cons)))
        ax.set_xticklabels(
            [s.replace("_", "\n") for s in cons.index],
            fontsize=8, color=_PLT_CP["txt_muted"])
        ax.set_ylabel("Fraction of IG genes with ortholog",
                      color=_PLT_CP["txt_dim"], fontsize=10)
        ax.set_title(
            f"Ortholog Conservation of IG Genes across Species\n"
            f"({n_genes} IG genes, {n_sp} target species, "
            f"mean conservation: {summary.get('mean_conservation', 0):.1%})",
            color=_PLT_CP["txt_dim"], fontsize=11, pad=8)
        for spine in ax.spines.values():
            spine.set_color(_PLT_CP["border"])
        ax.tick_params(axis="y", colors=_PLT_CP["txt_muted"])
        ax.set_ylim(0, 1.05)
        ax.axhline(0.5, color=_PLT_CP["amber"], lw=1, ls="--", alpha=0.6)
        ax.grid(axis="y", color=_PLT_CP["border"], alpha=0.3, lw=0.5)

    elif _HAS_SNS:
        # ── Clustermap de seaborn ─────────────────────────────────────────
        plt.close(fig)   # clustermap crea su propio Figure
        cmap = "YlGnBu"
        # Ordenar columnas por conservación
        col_order = matrix_df.mean(axis=0).sort_values(ascending=False).index
        mat = matrix_df[col_order]
        try:
            g = sns.clustermap(
                mat, cmap=cmap, linewidths=0.0,
                figsize=(max(8, n_sp * 1.2),
                         min(max(5, n_genes * 0.18), 22)),
                col_cluster=False,
                yticklabels=n_genes <= 60,
                xticklabels=True,
                cbar_kws={"label": "Ortholog present (1=yes, 0=no)"},
            )
            g.ax_heatmap.set_title(
                "IG Gene Ortholog Conservation Heatmap",
                color="#cccccc", fontsize=11, pad=6)
            g.ax_heatmap.set_xlabel("Target species",
                                     fontsize=9, color="#aaaaaa")
            g.ax_heatmap.set_ylabel("IG genes",
                                     fontsize=9, color="#aaaaaa")
            out_path = f"{output_prefix}_orthology_heatmap_IG.png"
            g.savefig(out_path, dpi=150, bbox_inches="tight",
                      facecolor=_PLT_CP["bg"])
            plt.close("all")
            return
        except Exception:
            plt.close("all")
            fig = plt.figure(figsize=(max(8, n_sp * 1.2),
                                      min(max(5, n_genes * 0.18), 22)),
                             facecolor=_PLT_CP["bg"])

    if n_genes <= _log_limit and not _HAS_SNS:
        # ── Fallback: imshow estándar ─────────────────────────────────────
        ax = fig.add_subplot(111)
        ax.set_facecolor(_PLT_CP["panel"])
        col_order = matrix_df.mean(axis=0).sort_values(ascending=False).index
        mat = matrix_df[col_order].values
        im  = ax.imshow(mat, aspect="auto", cmap="YlGnBu",
                        vmin=0, vmax=1, interpolation="none")
        ax.set_xticks(range(n_sp))
        ax.set_xticklabels(
            [s.replace("_", "\n") for s in col_order],
            fontsize=7, color=_PLT_CP["txt_muted"])
        if n_genes <= 60:
            ax.set_yticks(range(n_genes))
            ax.set_yticklabels(matrix_df.index[:n_genes],
                               fontsize=6, color=_PLT_CP["txt_muted"])
        else:
            ax.set_yticks([])
        ax.set_title(
            "IG Gene Ortholog Conservation Heatmap\n"
            f"({n_genes} genes × {n_sp} species)",
            color=_PLT_CP["txt_dim"], fontsize=11, pad=8)
        plt.colorbar(im, ax=ax, fraction=0.02,
                     label="Ortholog present")
        for spine in ax.spines.values():
            spine.set_color(_PLT_CP["border"])

    plt.tight_layout()
    out_path = f"{output_prefix}_orthology_heatmap_IG.png"
    fig.savefig(out_path, dpi=150, bbox_inches="tight",
                facecolor=_PLT_CP["bg"])
    plt.close(fig)


