def save_tables(ig_df, meg_df, ui_tx_df, ui_gene_df, gene_summary_df, prefix):
    for path, df in {
        f"{prefix}_IG_genes.tsv":          ig_df,
        f"{prefix}_MEG_genes.tsv":         meg_df,
        f"{prefix}_uiSEG_transcripts.tsv": ui_tx_df,
        f"{prefix}_uiSEG_genes.tsv":       ui_gene_df,
        f"{prefix}_gene_summary.tsv":      gene_summary_df,
    }.items():
        df.to_csv(path, sep="\t", index=False)


def compute_stats(ig_df, meg_df, ui_gene_df):
    summary: Dict[str, object] = {
        "counts": {
            "IG_genes":    int(len(ig_df)),
            "MEG_genes":   int(len(meg_df)),
            "uiSEG_genes": int(len(ui_gene_df)),
        }
    }
    ig_len  = pd.to_numeric(ig_df.get("representative_transcript_length",
                            pd.Series(dtype=float)), errors="coerce").dropna()
    meg_len = pd.to_numeric(meg_df.get("representative_transcript_length",
                            pd.Series(dtype=float)), errors="coerce").dropna()
    summary["descriptives"] = {
        "IG_length":  describe_series(ig_len),
        "MEG_length": describe_series(meg_len),
    }
    tests: Dict[str, object] = {}
    if len(ig_len) > 1 and len(meg_len) > 1:
        welch_res = safe_welch_test(ig_len.to_numpy(), meg_len.to_numpy())
        tests["welch_t_test"] = {
            "t_statistic": welch_res["welch_t_stat"],
            "p_value":     welch_res["welch_p"],
            "df":          welch_res["welch_df"],
            "warning":     welch_res["welch_warning"],
        }
        try:
            mw = mannwhitneyu(ig_len, meg_len, alternative="two-sided")
            tests["mann_whitney_u"] = {
                "u_statistic": float(mw.statistic),
                "p_value":     float(mw.pvalue), "warning": "",
            }
        except Exception as exc:
            tests["mann_whitney_u"] = {
                "u_statistic": np.nan, "p_value": np.nan,
                "warning": f"Mann-Whitney test failed: {exc}",
            }
        tests["cliffs_delta"] = float(cliffs_delta(ig_len.to_numpy(), meg_len.to_numpy()))
    else:
        tests["length_tests"] = "Insufficient data for group comparison."
    if not ig_df.empty and not meg_df.empty:
        ig_counts  = ig_df["chrom"].value_counts()
        meg_counts = meg_df["chrom"].value_counts()
        chroms = sorted(set(ig_counts.index).union(meg_counts.index), key=natural_chrom_key)
        contingency = np.array([
            [int(ig_counts.get(c, 0))  for c in chroms],
            [int(meg_counts.get(c, 0)) for c in chroms],
        ])
        chi2, p, dof, expected = chi2_contingency(contingency)
        tests["chromosome_distribution_chi_square"] = {
            "chi2": float(chi2), "p_value": float(p), "df": int(dof),
            "min_expected": float(np.min(expected)),
            "low_expected_count_cells": int(np.sum(expected < 5)),
            "warning": ("Some expected counts are < 5; interpret with caution."
                        if np.any(expected < 5) else ""),
        }
    summary["tests"] = tests
    return summary


def save_stats_files(stats, prefix):
    with open(f"{prefix}_stats.json", "w", encoding="utf-8") as fh:
        json.dump(stats, fh, indent=2, ensure_ascii=False)
    lines = [
        "IGFinder2.1.1 statistics\n",
        f"IG genes: {stats.get('counts', {}).get('IG_genes', 0)}",
        f"MEG genes: {stats.get('counts', {}).get('MEG_genes', 0)}",
        f"ui-SEG genes: {stats.get('counts', {}).get('uiSEG_genes', 0)}\n",
    ]
    for label, desc in stats.get("descriptives", {}).items():
        lines.append(f"{label}:")
        if desc:
            for k, v in desc.items():
                lines.append(f"  {k}: {v}")
        else:
            lines.append("  No data")
        lines.append("")
    for test_name, values in stats.get("tests", {}).items():
        lines.append(f"{test_name}:")
        if isinstance(values, dict):
            for k, v in values.items():
                lines.append(f"  {k}: {v}")
        else:
            lines.append(f"  {values}")
        lines.append("")
    with open(f"{prefix}_stats.txt", "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines))


