_PLT_CP = {
    "bg":        "#ffffff",
    "panel":     "#fafbff",
    "panel2":    "#f3f0ff",
    "cyan":      "#5b21b6",   # IG  — violeta-800
    "teal":      "#be185d",   # MEG — rosa-700
    "violet":    "#0369a1",   # SEG — cielo-700
    "median_ig": "#ede9fe",
    "median_meg":"#fce7f3",
    "amber":     "#1c1433",   # títulos
    "gold":      "#3730a3",   # ticks / labels
    "rose":      "#b91c1c",
    "coral":     "#b45309",
    "txt":       "#1c1433",
    "txt_d":     "#6d28d9",
    "bd":        "#ddd6fe",
    "bd2":       "#ede9fe",
}

def _apply_plt_style(sp=None):
    """Aplica estilo base _PLT_CP a rcParams de matplotlib."""
    cp = _PLT_CP
    plt.rcParams.update({
        "figure.facecolor":   cp["bg"],
        "axes.facecolor":     cp["panel"],
        "axes.edgecolor":     cp["bd"],
        "axes.labelcolor":    cp["gold"],
        "axes.titlecolor":    cp["amber"],
        "axes.titlepad":      14, "axes.titlesize":   12,
        "axes.titleweight":   "bold", "axes.labelsize": 10,
        "axes.spines.top":    False, "axes.spines.right": False,
        "axes.axisbelow":     True,
        "xtick.color":        cp["gold"], "ytick.color":  cp["gold"],
        "xtick.labelsize":    9,           "ytick.labelsize": 9,
        "text.color":         cp["txt"],
        "legend.facecolor":   cp["panel2"],"legend.edgecolor": cp["bd"],
        "legend.labelcolor":  cp["txt"],   "legend.framealpha": 0.95,
        "grid.color":         cp["bd2"],   "grid.linestyle": "-",
        "grid.linewidth":     1.0,         "grid.alpha": 1.0,
        "font.family":        "sans-serif",
        "figure.dpi":         150,
    })
    if sp:
        plt.rcParams["figure.dpi"] = sp


def _fmt_len(x, _):
    if x >= 1e6: return f"{x/1e6:.1f} M"
    if x >= 1e3: return f"{x/1e3:.0f} k"
    return f"{int(x)}"


# ── 1 & 2 — Histogramas de longitud ──────────────────────────────────────────
def save_plot_length_hist(ig_df, meg_df, prefix):
    if ig_df.empty or meg_df.empty:
        return
    cp  = _PLT_CP
    _apply_plt_style()
    ig  = ig_df["representative_transcript_length"].dropna().values + 1
    meg = meg_df["representative_transcript_length"].dropna().values + 1
    bins = min(60, max(20, int(np.sqrt(len(ig) + len(meg)))))

    for log_x, suffix, xtitle in [
        (False, "",     "Representative transcript length (nt)"),
        (True,  "_log", "Representative transcript length (nt, log scale)"),
    ]:
        fig, ax = plt.subplots(figsize=(10, 5.5))
        fig.subplots_adjust(left=0.10, right=0.97, top=0.87, bottom=0.13)
        ax.set_facecolor(cp["panel"])
        _bins = (np.logspace(np.log10(min(ig.min(), meg.min())),
                             np.log10(max(ig.max(), meg.max())), bins)
                 if log_x else bins)
        for vals, col, lbl in [(ig, cp["cyan"], "IG"), (meg, cp["teal"], "MEG")]:
            ax.hist(vals, bins=_bins, alpha=0.60, color=col,
                    edgecolor="none", label=f"{lbl}  (n={len(vals):,})", zorder=2)
            ax.hist(vals, bins=_bins, histtype="step",
                    color=col, linewidth=1.2, alpha=0.85, zorder=3)
            med = np.median(vals)
            ax.axvline(med, color=col, lw=1.4, ls="--", alpha=0.85, zorder=4)
        if log_x:
            ax.set_xscale("log")
        ax.set_xlabel(xtitle, labelpad=10)
        ax.set_ylabel("Gene count", labelpad=10)
        ax.set_title(f"Transcript Length Distribution — IG vs MEG", pad=14)
        ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f"{int(x):,}"))
        if not log_x:
            ax.xaxis.set_major_formatter(mticker.FuncFormatter(_fmt_len))
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0)
        ax.spines["bottom"].set_color(cp["bd"]); ax.spines["left"].set_color(cp["bd"])
        ax.legend(prop={"size": 9}, loc="upper right")
        fig.tight_layout(pad=2.2)
        plt.savefig(f"{prefix}_length_hist{suffix}.png", dpi=300); plt.close(fig)


# ── 3, 4, 5, 6 — Boxplots y Violines ─────────────────────────────────────────
def save_plot_length_box_violin(ig_df, meg_df, prefix):
    if ig_df.empty or meg_df.empty:
        return
    cp  = _PLT_CP
    _apply_plt_style()

    ig_vals  = ig_df["representative_transcript_length"].dropna().values + 1
    meg_vals = meg_df["representative_transcript_length"].dropna().values + 1
    datasets = [ig_vals, meg_vals]
    labels   = ["IG", "MEG"]
    colors   = [cp["cyan"], cp["teal"]]
    positions = [1, 2]
    W = 0.55

    # ── Boxplot (lineal + log) ────────────────────────────────────────────
    for log_y, suffix in [(False, ""), (True, "_log")]:
        fig, ax = plt.subplots(figsize=(8, 6))
        fig.subplots_adjust(left=0.12, right=0.97, top=0.87, bottom=0.12)
        ax.set_facecolor(cp["panel"])

        # Franja de fondo por clase
        for pos, col in zip(positions, colors):
            ax.axvspan(pos - W*0.9, pos + W*0.9, color=col, alpha=0.06, zorder=0, lw=0)

        bp = ax.boxplot(datasets, positions=positions, patch_artist=True, widths=W,
                        showfliers=True, whis=1.5,
                        medianprops=dict(color="#ffffff", linewidth=3.0,
                                        solid_capstyle="round"),
                        whiskerprops=dict(color=cp["txt"], linewidth=1.3,
                                         linestyle=(0,(4,2))),
                        capprops=dict(color=cp["txt"], linewidth=2.0),
                        flierprops=dict(marker="o", markersize=3.5,
                                       markeredgewidth=0.5, alpha=0.50,
                                       linestyle="none"))
        for patch, col, flier in zip(bp["boxes"], colors, bp["fliers"]):
            patch.set_facecolor(col); patch.set_alpha(0.82)
            patch.set_edgecolor(col); patch.set_linewidth(0)
            flier.set_markeredgecolor(col)
            flier.set_markerfacecolor(_blend(col, 0.25, cp["bg"]))

        if log_y: ax.set_yscale("log")
        ax.set_xticks(positions)
        ax.set_xticklabels(labels, fontsize=13, fontweight="bold")
        for tick, col in zip(ax.get_xticklabels(), colors):
            tick.set_color(col)
        ylbl = "Representative transcript length (nt" + (", log scale)" if log_y else ")")
        ax.set_xlabel("Gene class", labelpad=10)
        ax.set_ylabel(ylbl, labelpad=10)
        ax.set_title(f"Boxplot{' (log scale)' if log_y else ''} — IG vs MEG", pad=14)
        ax.yaxis.set_major_formatter(mticker.FuncFormatter(_fmt_len))
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0)
        ax.spines["bottom"].set_color(cp["bd"]); ax.spines["left"].set_color(cp["bd"])

        # Anotación mediana + n
        for vals, pos, col in zip(datasets, positions, colors):
            med = np.median(vals)
            q1, q3 = np.percentile(vals, [25, 75])
            ymax = np.percentile(vals, 99)
            ax.annotate(
                "n = {:,}\nmed = {}".format(len(vals), _fmt_len(med, None)),
                xy=(pos, ymax), xytext=(pos, ymax * (1.5 if log_y else 1.04)),
                ha="center", va="bottom", fontsize=8, color=col, fontweight="bold",
                bbox=dict(boxstyle="round,pad=0.35", fc=cp["panel2"], ec=col, lw=1.2, alpha=0.95))

        fig.tight_layout(pad=2.2)
        plt.savefig(f"{prefix}_boxplot{suffix}.png", dpi=300); plt.close(fig)

    # ── Violin (lineal + log) ─────────────────────────────────────────────
    for log_y, suffix in [(False, ""), (True, "_log")]:
        fig, ax = plt.subplots(figsize=(8, 6))
        fig.subplots_adjust(left=0.12, right=0.97, top=0.87, bottom=0.12)
        ax.set_facecolor(cp["panel"])

        for pos, col in zip(positions, colors):
            ax.axvspan(pos - W*0.6, pos + W*0.6, color=col, alpha=0.05, zorder=0, lw=0)

        # Violín relleno
        vp = ax.violinplot(datasets, positions=positions,
                           showmedians=True, showextrema=True, widths=W)
        for body, col in zip(vp["bodies"], colors):
            body.set_facecolor(col); body.set_edgecolor(col)
            body.set_alpha(0.72); body.set_linewidth(0); body.set_zorder(3)

        # Contorno
        vp2 = ax.violinplot(datasets, positions=positions,
                            showmedians=False, showextrema=False, widths=W)
        for body, col in zip(vp2["bodies"], colors):
            body.set_facecolor("none"); body.set_edgecolor(col)
            body.set_alpha(0.90); body.set_linewidth(1.8); body.set_zorder(4)

        if "cmedians" in vp:
            vp["cmedians"].set_color("#ffffff"); vp["cmedians"].set_linewidth(3.0)
            vp["cmedians"].set_alpha(1.0); vp["cmedians"].set_zorder(6)
        for part in ("cmaxes","cmins","cbars"):
            if part in vp:
                vp[part].set_color(cp["txt"]); vp[part].set_linewidth(1.2)
                vp[part].set_alpha(0.45); vp[part].set_zorder(5)

        if log_y: ax.set_yscale("log")
        ax.set_xticks(positions)
        ax.set_xticklabels(labels, fontsize=13, fontweight="bold")
        for tick, col in zip(ax.get_xticklabels(), colors):
            tick.set_color(col)
        ylbl = "Representative transcript length (nt" + (", log scale)" if log_y else ")")
        ax.set_xlabel("Gene class", labelpad=10)
        ax.set_ylabel(ylbl, labelpad=10)
        ax.set_title(f"Violin Plot{' (log scale)' if log_y else ''} — IG vs MEG", pad=14)
        ax.yaxis.set_major_formatter(mticker.FuncFormatter(_fmt_len))
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0)
        ax.spines["bottom"].set_color(cp["bd"]); ax.spines["left"].set_color(cp["bd"])

        for vals, pos, col in zip(datasets, positions, colors):
            med = np.median(vals)
            ymax = np.percentile(vals, 99)
            ax.annotate(
                "n = {:,}\nmedian = {}".format(len(vals), _fmt_len(med, None)),
                xy=(pos, ymax), xytext=(pos, ymax * (1.5 if log_y else 1.04)),
                ha="center", va="bottom", fontsize=8, color=col, fontweight="bold",
                bbox=dict(boxstyle="round,pad=0.35", fc=cp["panel2"], ec=col, lw=1.2, alpha=0.95))

        fig.tight_layout(pad=2.2)
        plt.savefig(f"{prefix}_violin{suffix}.png", dpi=300); plt.close(fig)


# ── 7 — Distribución cromosómica ─────────────────────────────────────────────
def save_plot_chromosome_distribution(ig_df, meg_df, prefix):
    if ig_df.empty and meg_df.empty:
        return
    cp = _PLT_CP
    _apply_plt_style()
    chroms = sorted(
        set(ig_df.get("chrom", pd.Series(dtype=str))).union(
            set(meg_df.get("chrom", pd.Series(dtype=str)))),
        key=natural_chrom_key)
    ig_counts  = ig_df["chrom"].value_counts()
    meg_counts = meg_df["chrom"].value_counts()
    ig_vals  = np.array([int(ig_counts.get(c, 0))  for c in chroms], float)
    meg_vals = np.array([int(meg_counts.get(c, 0)) for c in chroms], float)
    xi = np.arange(len(chroms)); w = 0.42
    max_v = max(ig_vals.max(), meg_vals.max(), 1)

    fig, ax = plt.subplots(figsize=(max(10, len(chroms)*0.5), 5.5))
    fig.subplots_adjust(left=0.08, right=0.98, top=0.87, bottom=0.13)
    ax.set_facecolor(cp["panel"])

    # Franjas alternas
    for i in range(len(chroms)):
        ax.axvspan(i-0.5, i+0.5,
                   color=cp["panel2"] if i%2==0 else cp["panel"], alpha=0.35, zorder=0)

    # Barras con glow
    for alpha, scale in [(0.05, 1.8), (0.10, 1.3), (0.88, 1.0)]:
        ax.bar(xi-w/2, ig_vals,  w*scale, color=cp["cyan"],  alpha=alpha, linewidth=0, zorder=2)
        ax.bar(xi+w/2, meg_vals, w*scale, color=cp["teal"],  alpha=alpha, linewidth=0, zorder=2)

    # Etiquetas de valor
    thr = max_v * 0.03
    for idx, (iv, mv) in enumerate(zip(ig_vals, meg_vals)):
        if iv > thr:
            ax.text(idx-w/2, iv+max_v*0.014, str(int(iv)),
                    ha="center", va="bottom", fontsize=7, fontweight="bold",
                    color=cp["cyan"], fontfamily="sans-serif")
        if mv > thr:
            ax.text(idx+w/2, mv+max_v*0.014, str(int(mv)),
                    ha="center", va="bottom", fontsize=7, fontweight="bold",
                    color=cp["teal"], fontfamily="sans-serif")

    ax.set_xticks(xi)
    ax.set_xticklabels(chroms, fontsize=8, rotation=0 if len(chroms) <= 12 else 45)
    ax.set_xlabel("Chromosome", labelpad=10)
    ax.set_ylabel("Gene count", labelpad=10)
    ax.set_title("Chromosome Distribution — IG and MEG genes", pad=14)
    ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f"{int(x):,}"))
    ax.set_xlim(-0.65, len(chroms)-0.35); ax.set_ylim(0, max_v*1.22)
    ax.grid(axis="y", color=cp["bd2"], linewidth=1.0)
    ax.spines["bottom"].set_color(cp["bd"]); ax.spines["left"].set_color(cp["bd"])
    ax.legend(
        handles=[Patch(facecolor=cp["cyan"], label=f"IG  ({int(ig_vals.sum()):,})"),
                 Patch(facecolor=cp["teal"], label=f"MEG ({int(meg_vals.sum()):,})")],
        facecolor=cp["panel2"], edgecolor=cp["bd"],
        labelcolor=cp["txt"], fontsize=9, loc="upper right",
        prop={"size": 9, "weight": "bold"})
    fig.tight_layout(pad=2.2)
    plt.savefig(f"{prefix}_chromosome_distribution.png", dpi=300); plt.close(fig)


# ── 8–29 — Enrichment por cromosoma ──────────────────────────────────────────
def save_plot_chromosomal_enrichment(enrichment_df, gene_df, prefix, fdr_threshold=0.05):
    if enrichment_df.empty or gene_df.empty:
        return
    cp = _PLT_CP
    _apply_plt_style()
    gene_df = gene_df.copy()
    gene_df["gene_start"] = pd.to_numeric(gene_df["gene_start"], errors="coerce")
    gene_df["gene_end"]   = pd.to_numeric(gene_df["gene_end"],   errors="coerce")
    for chrom in sorted(enrichment_df["chrom"].dropna().unique(), key=natural_chrom_key):
        sub       = enrichment_df[enrichment_df["chrom"] == chrom].copy()
        genes_chr = gene_df[gene_df["chrom"] == chrom].copy()
        if sub.empty or genes_chr.empty:
            continue
        ig_genes = genes_chr[genes_chr["class_label"] == "IG"].copy()
        enriched = sub[sub["fdr_bh"] < fdr_threshold].copy()
        fig, ax = plt.subplots(figsize=(14, 4.0))
        fig.subplots_adjust(left=0.06, right=0.97, top=0.86, bottom=0.18)
        ax.set_facecolor(cp["panel"])
        # Ventanas enriquecidas
        for _, row in enriched.iterrows():
            ax.axvspan(row["window_start"], row["window_end"],
                       alpha=0.18, color=cp["violet"], zorder=1)
        # Genes IG
        if not ig_genes.empty:
            ax.scatter(ig_genes["gene_start"], np.ones(len(ig_genes)),
                       s=20, color=cp["cyan"],
                       edgecolors=_blend(cp["cyan"], 0.5, "#ffffff"),
                       linewidths=0.8, label=f"IG genes ({len(ig_genes)})", zorder=3)
        n_enr = len(enriched)
        n_tot = len(genes_chr)
        ax.text(0.02, 0.90,
                f"IG: {len(ig_genes)}  |  Total: {n_tot}  |  Enriched windows: {n_enr}",
                transform=ax.transAxes, fontsize=8.5, color=cp["txt_d"],
                bbox=dict(boxstyle="round,pad=0.3", fc=cp["panel2"], ec=cp["bd"], lw=0.8))
        ax.set_title(f"Chromosomal Enrichment — Chr {chrom}  ·  IG genes", pad=12)
        ax.set_xlabel("Genomic position (bp)", labelpad=9)
        ax.xaxis.set_major_formatter(
            mticker.FuncFormatter(lambda x,_: f"{x/1e6:.1f} Mb" if x>=1e6
                                  else f"{x/1e3:.0f} kb" if x>=1e3 else f"{int(x)}"))
        ax.set_yticks([])
        ax.spines["bottom"].set_color(cp["bd"]); ax.spines["left"].set_visible(False)
        ax.grid(axis="x", color=cp["bd2"], linewidth=1.0)
        if not ig_genes.empty:
            handles = [
                Line2D([0],[0], marker="o", color="none",
                       markerfacecolor=cp["cyan"],
                       markeredgecolor=_blend(cp["cyan"],0.5,"#ffffff"),
                       markersize=7, label=f"IG genes ({len(ig_genes)})"),
            ]
            if n_enr > 0:
                handles.append(Patch(facecolor=cp["violet"], alpha=0.25,
                                     edgecolor=cp["violet"],
                                     label=f"Enriched windows ({n_enr})"))
            ax.legend(handles=handles, facecolor=cp["panel2"], edgecolor=cp["bd"],
                      labelcolor=cp["txt"], fontsize=9, loc="upper right",
                      prop={"size": 9, "weight": "bold"})
        fig.tight_layout(pad=2.0)
        plt.savefig(f"{prefix}_enrichment_chr{chrom}.png", dpi=300); plt.close(fig)


# ── NUEVO 30 — Class distribution (donut + cards) ────────────────────────────
def save_plot_class_distribution(ig_df, meg_df, ui_gene_df, prefix, sp=""):
    cp = _PLT_CP
    _apply_plt_style()
    counts = [len(ig_df), len(meg_df), len(ui_gene_df)]
    labels = ["IG", "MEG", "ui-SEG"]
    colors = [cp["cyan"], cp["teal"], cp["violet"]]
    total  = max(sum(counts), 1)

    fig = plt.figure(figsize=(14, 6))
    fig.patch.set_facecolor(cp["bg"])
    sp_title = f"  ·  {sp}" if sp else ""
    fig.text(0.50, 0.97, f"Class Distribution{sp_title}",
             fontsize=13, fontweight="bold", color=cp["amber"],
             va="top", ha="center")

    gs = gridspec.GridSpec(1, 2, figure=fig, width_ratios=[0.85, 1.15],
                           wspace=0.06, left=0.02, right=0.98, top=0.88, bottom=0.04)

    # Donut
    ax_d = fig.add_subplot(gs[0])
    ax_d.set_facecolor(cp["bg"]); ax_d.set_aspect("equal"); ax_d.axis("off")
    theta = np.linspace(0, 2*math.pi, 400)
    for r, a in [(0.78, 0.05), (0.76, 0.10), (0.73, 0.18)]:
        ax_d.plot(r*np.cos(theta), r*np.sin(theta), color=cp["bd"], lw=0.8, alpha=a)
    ax_d.plot(0.26*np.cos(theta), 0.26*np.sin(theta), color=cp["bd"], lw=0.8, alpha=0.35)
    if any(c > 0 for c in counts):
        wedges, _ = ax_d.pie(
            [max(c, 0.0001) for c in counts], colors=colors,
            startangle=90, wedgeprops=dict(width=0.44, edgecolor=cp["bg"], linewidth=3))
        for w, col, cnt in zip(wedges, colors, counts):
            ang = math.radians((w.theta1 + w.theta2) / 2); pct = cnt / total * 100
            if pct > 4:
                ax_d.text(0.57*math.cos(ang), 0.57*math.sin(ang), f"{pct:.1f}%",
                          ha="center", va="center", fontsize=9, fontweight="bold",
                          color="#ffffff",
                          bbox=dict(boxstyle="round,pad=0.10", fc=col, ec="none", alpha=0.90))
    ax_d.text(0,  0.13, f"{total:,}", ha="center", va="center",
              fontsize=21, fontweight="bold", color=cp["gold"], fontfamily="sans-serif")
    ax_d.text(0, -0.10, "TOTAL GENES", ha="center", va="center",
              fontsize=7.5, color=cp["txt_d"], fontfamily="sans-serif", fontweight="bold")

    # Cards
    ax_r = fig.add_subplot(gs[1])
    ax_r.set_facecolor(cp["bg"]); ax_r.axis("off")
    ax_r.set_xlim(0, 1); ax_r.set_ylim(0, 1)
    card_h = 0.240; gap = 0.040
    total_block = 3*card_h + 2*gap
    y_start = 0.50 + total_block/2
    for i, (lbl, cnt, col) in enumerate(zip(labels, counts, colors)):
        pct = cnt / total * 100
        y_top = y_start - i*(card_h + gap); y_bot = y_top - card_h
        ax_r.add_patch(FancyBboxPatch((0.02, y_bot), 0.96, card_h,
            boxstyle="round,pad=0.010", facecolor=cp["panel"],
            edgecolor=_ca(col, "99"), linewidth=1.4, zorder=2,
            transform=ax_r.transAxes, clip_on=False))
        ax_r.add_patch(FancyBboxPatch((0.02, y_bot), 0.018, card_h,
            boxstyle="round,pad=0.003", facecolor=col, edgecolor="none",
            zorder=3, transform=ax_r.transAxes, clip_on=False))
        cy = y_top - card_h*0.32
        ax_r.text(0.08, cy, lbl, transform=ax_r.transAxes, fontsize=12,
                  fontweight="bold", color=col, va="center", zorder=4)
        ax_r.text(0.97, cy, f"{cnt:,}", transform=ax_r.transAxes, fontsize=18,
                  fontweight="bold", color=cp["gold"], ha="right", va="center", zorder=4)
        bx0=0.08; bw=0.66; bh=0.022; by_bar=y_bot+card_h*0.18
        ax_r.add_patch(FancyBboxPatch((bx0, by_bar), bw, bh,
            boxstyle="round,pad=0.003", facecolor=cp["bd2"],
            edgecolor=_ca(col,"28"), linewidth=0.7, zorder=3,
            transform=ax_r.transAxes, clip_on=False))
        fw = bw * (pct/100.0)
        if fw > 0.004:
            ax_r.add_patch(FancyBboxPatch((bx0, by_bar), fw, bh,
                boxstyle="round,pad=0.003", facecolor=col, edgecolor="none",
                alpha=0.85, zorder=4, transform=ax_r.transAxes, clip_on=False))
        ax_r.text(bx0+bw+0.025, by_bar+bh/2, f"{pct:.1f}%",
                  transform=ax_r.transAxes, fontsize=9, fontweight="bold",
                  color=col, va="center", zorder=4)

    fig.tight_layout(pad=2.0)
    plt.savefig(f"{prefix}_class_distribution.png", dpi=300); plt.close(fig)


# ── NUEVO 31 — KDE ridgeline de longitudes ───────────────────────────────────
def save_plot_transcript_length_kde(ig_df, meg_df, prefix, sp=""):
    cp = _PLT_CP
    _apply_plt_style()
    pairs = [(ig_df, "IG", cp["cyan"]), (meg_df, "MEG", cp["teal"])]
    kdes = []
    for df2, lbl, col in pairs:
        if df2.empty or "representative_transcript_length" not in df2.columns:
            continue
        lens = df2["representative_transcript_length"].dropna().values
        lens = lens[(lens > 100) & (lens < 5_000_000)].astype(float)
        if len(lens) < 5:
            continue
        log_l = np.log10(lens + 1)
        n = min(len(log_l), 8000)
        rng = np.random.default_rng(42)
        samp = rng.choice(log_l, n, replace=False)
        lo = samp.min() - 0.12; hi = samp.max() + 0.12
        xs = np.linspace(lo, hi, 500)
        bw = max(1.06 * samp.std() * len(samp)**(-0.2), 0.04)
        diff = xs[np.newaxis, :] - samp[:, np.newaxis]
        ks = np.exp(-0.5*(diff/bw)**2).sum(0)
        ks /= len(samp) * bw * np.sqrt(2*math.pi)
        kdes.append((xs, ks, log_l, lbl, col))
    if not kdes:
        return
    max_k = max(k.max() for _, k, *_ in kdes)
    spacing = max_k * 1.90
    fig, ax = plt.subplots(figsize=(12, 6))
    fig.subplots_adjust(left=0.10, right=0.92, top=0.87, bottom=0.14)
    ax.set_facecolor(cp["panel"])
    for i, (xs, ks, log_l, lbl, col) in enumerate(kdes):
        y0 = i * spacing
        for alp, sc in [(0.03, 3.0), (0.07, 1.9), (0.14, 1.25), (0.55, 1.0)]:
            ax.fill_between(xs, y0, y0 + ks*sc, color=col, alpha=alp, linewidth=0)
        ax.plot(xs, y0 + ks, color=col, linewidth=2.0, alpha=0.92, zorder=4)
        med = np.median(log_l)
        ax.axvline(med, ymin=y0/ax.get_ylim()[1] if ax.get_ylim()[1]>0 else 0,
                   color=col, lw=1.5, ls="--", alpha=0.75, zorder=5)
        n_g = len(log_l)
        ax.text(xs[-1]+0.04, y0 + ks.max()*0.50,
                ("{lbl}\nn={n_g:,}\nmed={med_kb:.1f} kb".format(lbl=lbl, n_g=n_g, med_kb=10**med/1e3)),
                fontsize=9, fontweight="bold", color=col, va="center",
                bbox=dict(boxstyle="round,pad=0.3", fc=cp["panel2"], ec=col, lw=1.0, alpha=0.95))
    ax.set_yticks([])
    ax.set_xlabel("log₁₀(transcript length + 1)", labelpad=10)
    xvals = [0, 1, 2, 3, 4, 5, 6]
    ax.set_xticks(xvals)
    ax.set_xticklabels(["1 bp","10 bp","100 bp","1 kb","10 kb","100 kb","1 Mb"])
    sp_title = f"  ·  {sp}" if sp else ""
    ax.set_title(f"Transcript Length Distribution — KDE{sp_title}", pad=14)
    ax.spines["bottom"].set_color(cp["bd"]); ax.spines["left"].set_visible(False)
    ax.grid(axis="x", color=cp["bd2"], linewidth=1.0)
    fig.tight_layout(pad=2.2)
    plt.savefig(f"{prefix}_transcript_length_kde.png", dpi=300); plt.close(fig)


# ── NUEVO 32 & 33 — Biotypes IG + MEG ────────────────────────────────────────
def save_plot_biotypes(df, label, col, prefix):
    if df.empty or "gene_biotype" not in df.columns:
        return
    cp = _PLT_CP
    _apply_plt_style()
    vc    = df["gene_biotype"].value_counts()
    total = len(df)
    n_top = min(10, len(vc))
    top   = vc.head(n_top)
    other = total - top.sum()
    pie_labels = list(top.index) + (["Other"] if other > 0 else [])
    pie_vals   = list(top.values) + ([other] if other > 0 else [])
    n_pie = len(pie_labels)
    pie_cols = [_blend(col, 0.15 + 0.85*(1 - i/max(n_pie-1,1)), cp["panel"])
                for i in range(n_pie)]
    pie_cols[0] = col

    fig = plt.figure(figsize=(14, 6))
    fig.patch.set_facecolor(cp["bg"])
    fig.text(0.50, 0.97, f"{label} Gene Biotypes  (n={total:,})",
             fontsize=13, fontweight="bold", color=cp["amber"], va="top", ha="center")
    gs = gridspec.GridSpec(1, 2, figure=fig, width_ratios=[0.9, 1.1],
                           wspace=0.04, left=0.02, right=0.98, top=0.88, bottom=0.06)

    # Pie
    ax1 = fig.add_subplot(gs[0])
    ax1.set_facecolor(cp["bg"]); ax1.set_aspect("equal"); ax1.axis("off")
    wedges, _ = ax1.pie(pie_vals, colors=pie_cols, startangle=90,
                        wedgeprops=dict(width=0.52, edgecolor=cp["bg"], linewidth=2.5))
    for w, pv in zip(wedges, pie_vals):
        pct = pv / total * 100
        if pct > 5:
            ang = math.radians((w.theta1 + w.theta2) / 2)
            ax1.text(0.65*math.cos(ang), 0.65*math.sin(ang), f"{pct:.1f}%",
                     ha="center", va="center", fontsize=8, fontweight="bold", color="#ffffff")
    ax1.text(0, 0, f"{total:,}", ha="center", va="center",
             fontsize=18, fontweight="bold", color=cp["gold"])

    # Tabla top biotipos
    ax2 = fig.add_subplot(gs[1])
    ax2.set_facecolor(cp["bg"]); ax2.axis("off")
    ax2.set_xlim(0, 1); ax2.set_ylim(0, 1)
    ax2.text(0.05, 0.95, f"Top {n_top} biotypes", fontsize=10, fontweight="bold",
             color=cp["txt"], va="top", transform=ax2.transAxes)
    # axhline ya usa coords de ejes para Y implícitamente cuando ylim=(0,1)
    # — NO se pasa `transform` porque axhline genera el suyo propio.
    ax2.axhline(0.88, xmin=0.03, xmax=0.97, color=_ca(col, "44"), lw=0.8)
    row_h = 0.078
    for i, (name, val) in enumerate(top.items()):
        pct = val / total * 100
        y_r = 0.855 - i*row_h
        bright = 0.30 + 0.70*(1 - i/max(n_top-1, 1))
        row_col = _blend(col, bright, cp["panel"])
        if i % 2 == 0:
            ax2.add_patch(FancyBboxPatch((0.02, y_r-row_h*0.72), 0.96, row_h*0.78,
                boxstyle="round,pad=0.004", facecolor=cp["panel"],
                edgecolor=_ca(col,"18"), linewidth=0.5, zorder=1,
                transform=ax2.transAxes, clip_on=False))
        cy = y_r - row_h*0.30
        ax2.scatter([0.09], [cy], s=75, color=row_col, alpha=0.92, zorder=3,
                    transform=ax2.transAxes, clip_on=False)
        ax2.text(0.09, cy, str(i+1), fontsize=6, fontweight="bold",
                 color=cp["bg"], ha="center", va="center", zorder=4,
                 transform=ax2.transAxes)
        short = (name[:18]+"…") if len(name) > 18 else name
        ax2.text(0.17, cy, short, fontsize=8, color=cp["txt_d"], va="center",
                 transform=ax2.transAxes)
        ax2.text(0.80, cy, f"{val:,}", fontsize=8, fontweight="bold",
                 color=row_col, va="center", ha="right", transform=ax2.transAxes)
        bx=0.81; by2=cy-0.013; bw2=0.16; bh2=0.014
        ax2.add_patch(plt.Rectangle((bx,by2), bw2, bh2,
            facecolor=cp["bd"], zorder=2, transform=ax2.transAxes, clip_on=False))
        ax2.add_patch(plt.Rectangle((bx,by2), bw2*(pct/100), bh2,
            facecolor=row_col, alpha=0.88, zorder=3,
            transform=ax2.transAxes, clip_on=False))

    fig.tight_layout(pad=2.0)
    lbl_slug = label.replace("-","_").replace(" ","_")
    plt.savefig(f"{prefix}_biotypes_{lbl_slug}.png", dpi=300); plt.close(fig)


# ── NUEVO 34 — Genes por cromosoma + density strip ───────────────────────────
def save_plot_genes_by_chromosome(ig_df, meg_df, prefix, sp=""):
    if ig_df.empty and meg_df.empty:
        return
    cp = _PLT_CP
    _apply_plt_style()
    all_c = sorted(
        set((ig_df["chrom"].dropna().tolist() if not ig_df.empty else []) +
            (meg_df["chrom"].dropna().tolist() if not meg_df.empty else [])),
        key=natural_chrom_key)
    if not all_c:
        return
    ig_v  = np.array([(ig_df["chrom"] == c).sum() if not ig_df.empty else 0 for c in all_c], float)
    me_v  = np.array([(meg_df["chrom"] == c).sum() if not meg_df.empty else 0 for c in all_c], float)
    xi    = np.arange(len(all_c)); w = 0.36
    max_v = max(ig_v.max(), me_v.max(), 1)

    fig = plt.figure(figsize=(max(14, len(all_c)*0.55), 6))
    fig.patch.set_facecolor(cp["bg"])
    sp_title = f"  ·  {sp}" if sp else ""
    gs = gridspec.GridSpec(2, 1, figure=fig, height_ratios=[5.0, 0.65],
                           hspace=0.06, left=0.07, right=0.98, top=0.89, bottom=0.12)
    ax = fig.add_subplot(gs[0]); ax.set_facecolor(cp["panel"])

    for i in range(len(all_c)):
        ax.axvspan(i-0.5, i+0.5,
                   color=cp["panel2"] if i%2==0 else cp["panel"], alpha=0.35, zorder=0)
    for alpha, scale in [(0.04, 1.85), (0.10, 1.30), (0.88, 1.0)]:
        ax.bar(xi-w/2, ig_v, w*scale, color=cp["cyan"],  alpha=alpha, linewidth=0, zorder=2)
        ax.bar(xi+w/2, me_v, w*scale, color=cp["teal"],  alpha=alpha, linewidth=0, zorder=2)

    thr = max_v * 0.04
    for idx, (iv, mv) in enumerate(zip(ig_v, me_v)):
        if iv > thr:
            ax.text(idx-w/2, iv+max_v*0.016, str(int(iv)),
                    ha="center", va="bottom", fontsize=7, fontweight="bold", color=cp["cyan"])
        if mv > thr:
            ax.text(idx+w/2, mv+max_v*0.016, str(int(mv)),
                    ha="center", va="bottom", fontsize=7, fontweight="bold", color=cp["teal"])

    ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f"{int(x):,}"))
    ax.set_ylabel("Gene count", labelpad=10, fontsize=10)
    ax.set_title(f"Genes by Chromosome{sp_title}", pad=12, fontsize=12, fontweight="bold")
    ax.grid(axis="y", color=cp["bd2"], linewidth=1.0)
    ax.set_xlim(-0.65, len(all_c)-0.35); ax.set_ylim(0, max_v*1.24)
    ax.set_xticks(xi); ax.set_xticklabels([])
    ax.spines["bottom"].set_visible(False)
    for j, c in enumerate(all_c):
        yoff = -0.038 if j%2==0 else -0.082
        ax.text(j, yoff, c, ha="center", va="top", fontsize=7.5, fontweight="bold",
                color=cp["gold"], transform=ax.get_xaxis_transform(), clip_on=False)
    ax.legend(
        handles=[Patch(facecolor=cp["cyan"], label=f"IG ({int(ig_v.sum()):,})"),
                 Patch(facecolor=cp["teal"], label=f"MEG ({int(me_v.sum()):,})")],
        facecolor=cp["panel2"], edgecolor=cp["bd"], labelcolor=cp["txt"],
        fontsize=9, loc="upper right", prop={"size":9,"weight":"bold"})

    # Density strip
    ax2 = fig.add_subplot(gs[1]); ax2.set_facecolor(cp["panel2"])
    ax2.set_xlim(-0.65, len(all_c)-0.35); ax2.set_ylim(0,1); ax2.axis("off")
    max_tot = max((ig_v+me_v).max(), 1)
    for j, c in enumerate(all_c):
        tot_j = ig_v[j]+me_v[j]; ig_frac = ig_v[j]/max(tot_j, 1)
        bright = 0.15 + 0.85*(tot_j/max_tot)
        r1, g1, b1 = int(0x5b), int(0x21), int(0xb6)  # cyan #5b21b6
        r2, g2, b2 = int(0xbe), int(0x18), int(0x5d)  # teal #be185d
        r = int((r1*ig_frac + r2*(1-ig_frac))*bright)
        g = int((g1*ig_frac + g2*(1-ig_frac))*bright)
        b = int((b1*ig_frac + b2*(1-ig_frac))*bright)
        bar_col = f"#{r:02x}{g:02x}{b:02x}"
        ax2.add_patch(plt.Rectangle((j-0.44, 0.10), 0.88, 0.80,
            facecolor=bar_col, edgecolor=_ca(cp["cyan"],"22"), linewidth=0.4, zorder=2))
    ax2.text(len(all_c)/2, 0.02,
             "DENSITY  (color = IG/MEG ratio  ·  brightness = gene count)",
             ha="center", va="bottom", fontsize=7.5, fontweight="bold", color=cp["txt_d"])
    fig.tight_layout(pad=2.0)
    plt.savefig(f"{prefix}_genes_by_chromosome.png", dpi=300); plt.close(fig)


