class IGFinder2Beta(tk.Tk):

    def __init__(self):
        super().__init__()
        self.title("IGFinder 2.0  ·  Intronless Gene Architecture Analyzer")
        self.configure(bg=C["bg"])
        self.geometry("1200x780")
        self.minsize(1050, 640)

        self._results     = None
        self._running     = False
        self._current_tab = "scan"
        self._log_q       = queue.Queue()
        self._res_q       = queue.Queue()
        self._prog_q      = queue.Queue()
        self._runner      = None
        self._mpl_canvas  = None

        # ── OMICS module state — MUST be initialized in __init__ ─────────────
        # Tkinter's __getattr__ delegates to self.tk for any attribute not found
        # on the instance; class-level declarations are unreliable across Python
        # versions when mixed with tkinter's Misc.__getattr__. Explicit
        # instance attributes here guarantee they exist before any lambda
        # callback or self.after() fires.
        # ── Thread-safety lock — protege escrituras a _omics_data / _results
        #    desde el GUI thread (callbacks after()) y desde los runners
        self._state_lock         = threading.Lock()
        self._omics_data         = {}        # resultado del OmicsRunner
        self._omics_runner       = None      # instancia OmicsRunner activa
        self._omics_res_q        = queue.Queue()
        self._omics_prog_q       = queue.Queue()
        self._omics_log_q        = queue.Queue()
        self._omics_current_sub  = "go"
        self._go_mpl_canvas      = None
        self._orth_mpl_canvas    = None
        self._go_source_vars     = {}
        self._go_fdr_var         = None
        self._go_topn_var        = None
        self._orth_cons_var      = None
        self._orth_mode_var      = None
        self._orth_species_vars  = {}        # species selector del panel Orthology
        self._orth_sp_catalog    = {}        # production_name → display_name
        self._cs_last_error      = None      # último error en Cross Species refresh
        self._orth_fetching      = False     # guard fetch_all_species
        self._OMICS_POLL_MS      = 5000   # instance attr — avoids tkinter __getattr__

        self._setup_styles()
        self._build_ui()
        self._animate_elite()
        self._poll()

        # ── Mostrar progreso NTv3 en la barra de estado inferior ─────────
        # Igual que Ferretería muestra la carga del modelo en su status_bar.
        self._ntv3_sb_poll()


    # ── Propiedades de acceso seguro a estado compartido ─────────────────────
    @property
    def _safe_omics(self) -> dict:
        """Acceso thread-safe a _omics_data. Nunca lanza, nunca devuelve None."""
        with self._state_lock:
            return dict(getattr(self, "_omics_data", None) or {})

    @property
    def _safe_results(self) -> dict:
        """Acceso thread-safe a _results. Nunca lanza, nunca devuelve None."""
        return dict(getattr(self, "_results", None) or {})

    def _set_omics_data(self, data: dict) -> None:
        """Escritura thread-safe a _omics_data."""
        with self._state_lock:
            self._omics_data = data

    def _update_omics_data(self, partial: dict) -> None:
        """Actualización thread-safe (merge) de _omics_data."""
        with self._state_lock:
            if not isinstance(getattr(self, "_omics_data", None), dict):
                self._omics_data = {}
            self._omics_data.update(partial)


    def _force_redraw(self, canvas=None):
        """
        Fuerza el repintado de un canvas matplotlib de forma SEGURA.

        IMPORTANTE (macOS): NO usar self.update() aquí. Llamar update() desde
        dentro de un callback de after()/_poll() re-entra recursivamente al
        event loop de Tk; con el backend Cocoa eso corrompe el render de TODA
        la ventana (pantalla negra completa), sobre todo con las animaciones
        de ChromoScope/ActivityMatrix activas. Solo usamos update_idletasks()
        (procesa tareas pendientes sin re-entrar al loop) y draw_idle() del
        canvas, que matplotlib resuelve en el siguiente ciclo idle de forma
        segura.
        """
        # 1. Pedir el render del canvas matplotlib (diferido, seguro)
        if canvas is not None:
            try:
                canvas.draw_idle()
            except Exception:
                pass
        # 2. Procesar SOLO tareas idle pendientes (geometría, repintados).
        #    No re-entra al event loop → seguro dentro de callbacks.
        try:
            self.update_idletasks()
        except Exception:
            pass
        # 3. macOS: invalidar la región del canvas con un <Expose> sintético.
        #    Esto pide a Cocoa repintar ESE widget sin tocar el resto de la
        #    ventana y sin mover la geometría. Es no-intrusivo y no recursivo.
        if _IS_MACOS and canvas is not None:
            try:
                widget = canvas.get_tk_widget()
                if widget.winfo_exists():
                    widget.event_generate("<Expose>")
                    widget.update_idletasks()
            except Exception:
                pass

    def _ntv3_sb_poll(self):
        """
        Actualiza la barra de estado inferior con el progreso de NTv3.
        Se llama cada 300 ms hasta que el modelo está listo o en error.
        Replica exactamente el patrón de Ferretería Santander PRO.
        """
        st = ntv3_status()
        if st["ready"]:
            self._prog_label.configure(
                text="NTv3 READY", fg=C["emerald"])
            self._sb_accent.configure(bg=C["emerald"])
            # Volver a READY tras 3 s
            self.after(3000, lambda: self._prog_label.configure(
                text="READY", fg=C["txt_muted"]))
            self.after(3000, lambda: self._sb_accent.configure(bg=C["txt_muted"]))
        elif st["error"]:
            self._prog_label.configure(text="NTv3 ERR", fg=C["red"])
            self._sb_accent.configure(bg=C["red"])
            try:
                short = (st["error"] or "")[:60]
                self._phase_lbl.configure(
                    text=f"NTv3: {short}", fg=C["red"])
            except Exception:
                pass
        else:
            # Todavía cargando — mensajes rotativos en _phase_lbl
            import math
            t = time.time()
            msgs = [
                f"NTv3 · Cargando modelo '{_NTV3_DEFAULT_PATH}'...",
                f"NTv3 · Leyendo pesos del modelo...",
                f"NTv3 · Moviendo a {_ntv3_detect_device().upper()}...",
                f"NTv3 · Verificando arquitectura del transformer...",
                f"NTv3 · Nucleotide Transformer v3 iniciando...",
            ]
            idx = int(t * 0.5) % len(msgs)
            self._prog_label.configure(text="NTv3…", fg=C["violet"])
            self._sb_accent.configure(bg=C["violet"])
            try:
                self._phase_lbl.configure(text=msgs[idx], fg=C["violet"])
            except Exception:
                pass
            self.after(300, self._ntv3_sb_poll)

