    # ──────────────────────────────────────────────────────────────────────
    #  Helper: envoltorio scrollable para pestañas
    # ──────────────────────────────────────────────────────────────────────
    def _make_scrollable_tab(self, parent):
        """
        Envuelve una pestaña en un contenedor con barra de scroll vertical
        lateral, pensado para laptops pequeñas donde el contenido se corta.

        Devuelve una tupla (wrap, inner):
          * wrap  — frame externo que se empaqueta en `panels_host` y que
                    se registra en `self._all_panels` para que `_switch_tab`
                    lo muestre / oculte.
          * inner — frame interno donde cada `_build_*_tab` construye su
                    contenido. Equivale al `tk.Frame` original (mismo bg,
                    mismas convenciones de pack/grid), por lo que la lógica
                    y la interfaz de las pestañas no cambia.

        Comportamiento:
          * Si el contenido cabe en el área visible, el `inner` se expande
            hasta la altura del canvas (los widgets con `expand=True` siguen
            ocupando todo el espacio disponible, igual que antes).
          * Si el contenido excede la altura visible, se activa la barra de
            scroll lateral y el usuario puede deslizar la vista verticalmente.
          * La rueda del ratón también desplaza el contenido cuando el
            cursor está sobre la pestaña (bind/unbind en <Enter>/<Leave>
            para no interferir entre pestañas, y sin tocar Treeview/Text/
            Listbox para que conserven su propio scroll interno).
        """
        wrap = tk.Frame(parent, bg=C["bg"])
        canvas = tk.Canvas(wrap, bg=C["bg"], highlightthickness=0, bd=0)
        vsb = ttk.Scrollbar(wrap, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vsb.set)
        vsb.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)

        inner = tk.Frame(canvas, bg=C["bg"])
        win_id = canvas.create_window((0, 0), window=inner, anchor="nw")

        def _sync(_e=None):
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
                req_h = inner.winfo_reqheight()
                canvas_h = canvas.winfo_height()
                if canvas_h > 1:
                    target_h = max(req_h, canvas_h)
                    bbox = canvas.bbox(win_id)
                    if bbox is not None:
                        cur_h = bbox[3] - bbox[1]
                        if abs(cur_h - target_h) > 1:
                            canvas.itemconfig(win_id, height=target_h)
            except Exception:
                pass

        def _on_canvas_configure(event):
            # Mantener el ancho del contenido igual al ancho visible y
            # resincronizar la altura (contenido expande o activa scroll).
            try:
                canvas.itemconfig(win_id, width=event.width)
            except Exception:
                pass
            _sync()

        inner.bind("<Configure>", _sync)
        canvas.bind("<Configure>", _on_canvas_configure)

        # ── Rueda del ratón (Win/Mac: <MouseWheel>, Linux: Button-4/5) ──
        def _on_mousewheel(event):
            w = event.widget
            try:
                cls_name = w.winfo_class() if hasattr(w, "winfo_class") else ""
            except Exception:
                cls_name = ""
            # No interferir con widgets que ya manejan su propio scroll
            if cls_name in ("Treeview", "Text", "Listbox"):
                return
            try:
                if getattr(event, "num", 0) == 4:
                    canvas.yview_scroll(-3, "units")
                elif getattr(event, "num", 0) == 5:
                    canvas.yview_scroll(3, "units")
                else:
                    delta = getattr(event, "delta", 0) or 0
                    step = -1 if delta > 0 else 1
                    canvas.yview_scroll(step * 3, "units")
            except Exception:
                pass

        def _bind_wheel(_e=None):
            canvas.bind_all("<MouseWheel>", _on_mousewheel)
            canvas.bind_all("<Button-4>",   _on_mousewheel)
            canvas.bind_all("<Button-5>",   _on_mousewheel)

        def _unbind_wheel(_e=None):
            canvas.unbind_all("<MouseWheel>")
            canvas.unbind_all("<Button-4>")
            canvas.unbind_all("<Button-5>")

        wrap.bind("<Enter>", _bind_wheel)
        wrap.bind("<Leave>", _unbind_wheel)

        return wrap, inner

    def _build_ui(self):
        # ── 1. Top gradient band ──────────────────────────────────────────
        top_band = tk.Canvas(self, height=3, bg=C["bg"], highlightthickness=0)
        top_band.pack(fill="x")
        def _draw_tband(e, c=top_band):
            w = c.winfo_width() or 1; c.delete("all")
            t = w // 3
            c.create_rectangle(0,   0, t,   3, fill=C["teal"],   outline="")
            c.create_rectangle(t,   0, 2*t, 3, fill=C["orchid"], outline="")
            c.create_rectangle(2*t, 0, w,   3, fill=C["rose"],   outline="")
        top_band.bind("<Configure>", _draw_tband)

        # ── 2. Titlebar ───────────────────────────────────────────────────
        self._build_titlebar()

        # ── 3. Body = sidebar + main ──────────────────────────────────────
        body = tk.Frame(self, bg=C["bg2"])
        body.pack(fill="both", expand=True)

        self._build_sidebar(body)

        main = tk.Frame(body, bg=C["bg"])
        main.pack(side="left", fill="both", expand=True)

        self._build_tab_bar(main)

        panels_host = tk.Frame(main, bg=C["bg"])
        panels_host.pack(fill="both", expand=True)

        # ── Create all tab panel frames ───────────────────────────────────
        # Cada pestaña queda envuelta en un contenedor con barra de scroll
        # lateral (ver _make_scrollable_tab). `self._tab_X` sigue siendo el
        # frame interno donde se construye el contenido, así los métodos
        # `_build_*_tab` existentes funcionan exactamente igual que antes.
        self._tab_cfg_wrap,     self._tab_cfg     = self._make_scrollable_tab(panels_host)  # SCAN
        self._tab_res_wrap,     self._tab_res     = self._make_scrollable_tab(panels_host)  # RESULTS
        self._tab_plt_wrap,     self._tab_plt     = self._make_scrollable_tab(panels_host)  # PLOTS
        self._tab_monitor_wrap, self._tab_monitor = self._make_scrollable_tab(panels_host)  # MONITOR
        self._tab_log_wrap,     self._tab_log     = self._make_scrollable_tab(panels_host)  # LOG
        self._tab_omics_wrap,   self._tab_omics   = self._make_scrollable_tab(panels_host)  # OMICS ★
        self._tab_cross_wrap,   self._tab_cross   = self._make_scrollable_tab(panels_host)  # CROSS SPECIES ★
        # CONFIG ya trae su propio scroll interno (_build_advanced_config_tab);
        # se conserva tal cual para no duplicar la scrollbar.
        self._tab_config      = tk.Frame(panels_host, bg=C["bg"])                           # CONFIG
        self._tab_config_wrap = self._tab_config

        # En _all_panels se registran los wraps externos (lo que pack/unpack
        # muestra u oculta). Para CONFIG el wrap coincide con el frame mismo.
        self._all_panels = [
            ("scan",    self._tab_cfg_wrap),
            ("results", self._tab_res_wrap),
            ("plots",   self._tab_plt_wrap),
            ("monitor", self._tab_monitor_wrap),
            ("log",     self._tab_log_wrap),
            ("omics",   self._tab_omics_wrap),
            ("cross",   self._tab_cross_wrap),
            ("config",  self._tab_config_wrap),
        ]

        # ── Build all tab contents ────────────────────────────────────────
        self._build_scan_tab()
        self._build_results_tab()
        self._build_plots_tab()
        self._build_monitor_tab()
        self._build_log_tab()
        self._build_advanced_config_tab()
        self._build_omics_tab()   # ★ new OMICS tab
        # ★ CROSS SPECIES — pestaña independiente (el builder lo añade el
        #   parche OMICS al final del archivo). Si por alguna razón el parche
        #   no se aplicó, no rompe: simplemente queda una pestaña vacía.
        self._build_cross_species_tab()

        # ── Show the default panel ────────────────────────────────────────
        self._switch_tab("scan")

        # ── 4. Status bar ─────────────────────────────────────────────────
        self._build_status_bar()

        # ── 5. Atajos de teclado globales ─────────────────────────────────
        # Estos funcionan en cualquier pestaña:
        #   Ctrl+B       — colapsar/expandir sidebar
        #   F11          — colapsar/expandir header del OMICS
        #   Ctrl+0       — reset layout completo del OMICS
        try:
            self.bind_all("<Control-b>", lambda e: (
                self._toggle_sidebar(), "break")[1])
            self.bind_all("<Control-B>", lambda e: (
                self._toggle_sidebar(), "break")[1])
        except Exception:
            pass

    def _build_titlebar(self):
        """Encabezado horizontal — ADN + título + dos líneas descriptivas apiladas."""
        TB  = C["void"]
        BG2 = C["bg2"]
        BG  = C["bg"]

        # Banda tricolor 3px
        band = tk.Canvas(self, height=3, bg=TB, highlightthickness=0)
        band.pack(fill="x")
        def _draw_band(e, c=band):
            w = c.winfo_width() or 1; c.delete("all")
            q = w // 4
            c.create_rectangle(0,   0,   q, 3, fill=C["teal"],    outline="")
            c.create_rectangle(q,   0, 2*q, 3, fill=C["orchid"],  outline="")
            c.create_rectangle(2*q, 0, 3*q, 3, fill=C["rose"],    outline="")
            c.create_rectangle(3*q, 0,   w, 3, fill=C["lavender"],outline="")
        band.bind("<Configure>", _draw_band)

        # ── FILA ÚNICA HORIZONTAL ─────────────────────────────────────────
        row = tk.Frame(self, bg=TB, height=42)
        row.pack(fill="x"); row.pack_propagate(False)

        # ADN horizontal (110×38)
        dna_c = tk.Canvas(row, width=110, height=38, bg=TB, highlightthickness=0)
        dna_c.pack(side="left", padx=(8, 0), pady=2)

        _rung_cols = [C["lavender"],C["violet"],C["orchid"],C["blush"],
                      C["violet"],C["lavender"],C["orchid"],C["violet"],
                      C["lavender"],C["blush"],C["orchid"],C["lavender"],
                      C["violet"],C["orchid"]]

        def _redraw_dna(event=None, c=dna_c):
            c.delete("all")
            W = c.winfo_width() or 110
            CY, AMP = 19, 13
            N = 14
            XL, XR = 4, W - 4
            STP = (XR - XL) / max(N - 1, 1)
            pa, pb = [], []
            for i in range(N):
                x = XL + i * STP
                t = i / max(N - 1, 1)
                pa.append((x, CY - AMP * math.sin(t * math.pi * 3.0)))
                pb.append((x, CY + AMP * math.sin(t * math.pi * 3.0)))
            for i in range(N - 1):
                x0,y0=pa[i]; x1,y1=pa[i+1]
                c.create_line(x0,y0,(x0+x1)/2,(y0+y1)/2,x1,y1,
                              fill=_ca(C["cyan"],"cc"), width=2, smooth=True)
            for i in range(N - 1):
                x0,y0=pb[i]; x1,y1=pb[i+1]
                c.create_line(x0,y0,(x0+x1)/2,(y0+y1)/2,x1,y1,
                              fill=_ca(C["teal"],"cc"), width=2, smooth=True)
            for i,(a,b) in enumerate(zip(pa, pb)):
                rc = _rung_cols[i % len(_rung_cols)]
                c.create_line(a[0],a[1],b[0],b[1], fill=_ca(rc,"66"), width=1)
                c.create_oval(a[0]-3,a[1]-3,a[0]+3,a[1]+3,
                              fill=C["cyan"], outline=_ca(C["lavender"],"44"))
                c.create_oval(b[0]-3,b[1]-3,b[0]+3,b[1]+3,
                              fill=C["teal"], outline=_ca(C["rose"],"44"))

        dna_c.bind("<Configure>", _redraw_dna)

        # Separador vertical fino
        tk.Frame(row, bg=_ca(C["orchid"],"44"), width=1).pack(
            side="left", fill="y", padx=(8, 0), pady=5)

