    def _toggle_sidebar(self):
        """
        Colapsa/expande el sidebar lateral global.
          • Expandido: 190 px (ancho completo con todas las nav items)
          • Colapsado: 38  px (solo el botón ▶ visible — los nav items
            siguen funcionando con tooltips)
        Atajo: Ctrl+B
        """
        try:
            collapsed = bool(self._sidebar_collapsed.get())
        except Exception:
            collapsed = False
        new_collapsed = not collapsed
        try:
            self._sidebar_collapsed.set(new_collapsed)
        except Exception:
            pass

        sb = getattr(self, "_sidebar_frame", None)
        if sb is None:
            return

        target_w = 38 if new_collapsed else self._sidebar_full_width
        try:
            sb.configure(width=target_w)
        except Exception:
            pass

        # Actualizar label del botón
        try:
            arrow = "▶" if new_collapsed else "◀  Collapse  (Ctrl+B)"
            self._sidebar_coll_lbl.configure(text=arrow)
        except Exception:
            pass

