        def _nav_item(label, tab_id, col=None):
            col = col or C["cyan"]
            f = tk.Frame(sb, bg=C["bg2"], cursor="hand2"); f.pack(fill="x")
            accent = tk.Frame(f, bg=C["bg2"], width=3); accent.pack(side="left", fill="y")
            dot = tk.Canvas(f, width=6, height=6, bg=C["bg2"], highlightthickness=0)
            dot.pack(side="left", padx=(6, 0), pady=7)
            dot.create_oval(1, 1, 5, 5, fill=C["txt_muted"], outline="", tags="dot")
            lbl = tk.Label(f, text=label, bg=C["bg2"], fg=C["txt_muted"],
                           font=("Courier New", 10), anchor="w")
            lbl.pack(side="left", fill="x", expand=True, padx=(5, 4))
            def _on_click(tid=tab_id, frame=f, d=dot, l=lbl, a=accent):
                self._switch_nav(tid, frame, d, l, a)
            for w in [f, dot, lbl]:
                w.bind("<Button-1>", lambda e, fn=_on_click: fn())
            def _hover_enter(e, frame=f, l=lbl, c=col):
                frame.configure(bg=_ca(c, "0a")); l.configure(fg=c, bg=_ca(c, "0a"))
            def _hover_leave(e, tid=tab_id, frame=f, l=lbl):
                if self._current_tab != tid:
                    frame.configure(bg=C["bg2"]); l.configure(fg=C["txt_muted"], bg=C["bg2"])
            f.bind("<Enter>", _hover_enter); f.bind("<Leave>", _hover_leave)
            lbl.bind("<Enter>", _hover_enter); lbl.bind("<Leave>", _hover_leave)
            self._nav_buttons[tab_id] = (f, dot, lbl, accent)

