        # + barra de progreso pulsante mientras carga el modelo.
        tk.Frame(sb, bg=C["border_dd"], height=1).pack(fill="x")

        ntv3_card = tk.Frame(sb, bg=C["panel"],
                             highlightthickness=1,
                             highlightbackground=_ca(C["violet"], "44"))
