        self._omics_cards_f = cards_f

        def _stat_card(parent, col, icon, title, var_name):
            card = tk.Frame(parent,
                            bg=_ca(col, "0a"),
                            highlightthickness=1,
                            highlightbackground=_ca(col, "33"),
                            height=58)
            card.pack(side="left", expand=True, fill="x", padx=4)
            card.pack_propagate(False)
            inner = tk.Frame(card, bg=_ca(col, "0a"))
            inner.pack(fill="both", expand=True, padx=8, pady=4)
            # Icon + title row
            top = tk.Frame(inner, bg=_ca(col, "0a"))
            top.pack(fill="x")
            tk.Label(top, text=icon, bg=_ca(col, "0a"), fg=col,
                     font=("Courier New", 11)).pack(side="left")
            tk.Label(top, text=title, bg=_ca(col, "0a"), fg=_ca(col, "cc"),
                     font=("Courier New", 7, "bold")).pack(side="left", padx=3)
            # Value label
            lbl = tk.Label(inner, text="—",
                           bg=_ca(col, "0a"), fg=col,
                           font=("Courier New", 14, "bold"))
            lbl.pack(anchor="w", pady=(0, 0))
            setattr(self, var_name, lbl)

        _stat_card(cards_f, C["emerald"], "⬡", "ENRICHED TERMS",  "_ocard_terms")
        _stat_card(cards_f, C["teal"],    "◈", "SOURCES",         "_ocard_sources")
        _stat_card(cards_f, C["orchid"],  "◉", "IG ORTHOLOGS",    "_ocard_orthologs")
        _stat_card(cards_f, C["cyan"],    "◆", "MEAN CONSERV.",   "_ocard_conservation")

