    def _make_tree(self, parent):
        cols = ("gene_id","gene_name","chrom","strand","gene_biotype",
                "representative_transcript_length","n_transcripts_used",
                "gene_start","gene_end","class_label")
        frame = tk.Frame(parent, bg=C["bg"]); frame.pack(fill="both", expand=True)
        tree  = ttk.Treeview(frame, columns=cols, show="headings", height=18)
        vsb   = ttk.Scrollbar(frame, orient="vertical",   command=tree.yview)
        hsb   = ttk.Scrollbar(frame, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        for c in cols:
            tree.heading(c, text=c.replace("_"," ").upper(), anchor="w")
            tree.column(c, width=160, anchor="w", minwidth=90)
        vsb.pack(side="right", fill="y"); hsb.pack(side="bottom", fill="x")
        tree.pack(fill="both", expand=True)
        tree.tag_configure("odd",  background=C["panel"])
        tree.tag_configure("even", background=C["panel2"])
        return tree

    def _populate_tree(self, tree, df):
        """Puebla un TreeView por lotes (no congela el hilo -> no pantalla negra)."""
        tree.delete(*tree.get_children())
        if df is None or df.empty:
            return
        cols = list(tree["columns"])
        rows = list(df.head(2000).iterrows())
        BATCH = 200

        def _insert_batch(start=0):
            end = min(start + BATCH, len(rows))
            for i in range(start, end):
                _, row = rows[i]
                vals = [str(row.get(c, "")) for c in cols]
                try:
                    tree.insert("", "end", values=vals,
                                tags=("even" if i % 2 == 0 else "odd",))
                except Exception:
                    return
            if end < len(rows):
                self.after(1, lambda: _insert_batch(end))

        _insert_batch(0)

