    def _init_viz_params(self):
        """Initialize all visualization parameter tk variables."""
        self._vp = {}
        D = self._VIZ_DEFAULTS
        for k, v in D.items():
            if isinstance(v, bool):
                self._vp[k] = tk.BooleanVar(value=v)
            elif isinstance(v, int):
                self._vp[k] = tk.IntVar(value=v)
            elif isinstance(v, float):
                self._vp[k] = tk.DoubleVar(value=v)
            elif isinstance(v, str):
                self._vp[k] = tk.StringVar(value=v)

    def _reset_viz_params(self):
        """Reset all parameters to defaults."""
        D = self._VIZ_DEFAULTS
        for k, v in D.items():
            if k in self._vp:
                self._vp[k].set(v)

    def _get_vp(self, key):
        """Get a visualization parameter value, with fallback to default."""
        try:
            return self._vp[key].get()
        except (KeyError, tk.TclError):
            return self._VIZ_DEFAULTS.get(key)

    def _toggle_config_panel(self):
        if self._cfg_expanded:
            self._cfg_panel.pack_forget()
            self._cfg_toggle_btn.configure(text="  ⚙  PLOT CONFIGURATION  ▼  ")
            self._cfg_expanded = False
        else:
            self._cfg_panel.pack(fill="x", padx=8, pady=(2,4),
                                 before=self._plot_frame)
            self._cfg_toggle_btn.configure(text="  ⚙  PLOT CONFIGURATION  ▲  ")
            self._cfg_expanded = True

    def _build_config_sections(self):
        """Build the 5 parameter sections inside the config panel."""
        panel = self._cfg_panel
        panel.configure(bg=C["panel"], highlightthickness=1,
                        highlightbackground=_ca(C["violet"],"55"))

        # Container for horizontal section cards
        container = tk.Frame(panel, bg=C["panel"])
        container.pack(fill="x", padx=6, pady=6)

        # Helper: create a section card
        def _section(parent, title, color, col_idx):
            f = tk.Frame(parent, bg=C["panel2"],
                         highlightthickness=1,
                         highlightbackground=_ca(color,"44"))
            f.grid(row=0, column=col_idx, sticky="nsew", padx=3, pady=2)
            parent.grid_columnconfigure(col_idx, weight=1)
            # Title bar
            tb = tk.Frame(f, bg=_ca(color,"18"))
            tb.pack(fill="x")
            tk.Frame(tb, bg=color, width=3).pack(side="left", fill="y")
            tk.Label(tb, text=f"  {title}  ", bg=_ca(color,"18"), fg=color,
                     font=("Courier New",11,"bold")).pack(side="left", pady=3)
            # Content area
            cf = tk.Frame(f, bg=C["panel2"])
            cf.pack(fill="both", expand=True, padx=6, pady=5)
            return cf

        # Helper: labeled parameter row
        def _param(parent, label, var, width=8, tip=""):
            row = tk.Frame(parent, bg=C["panel2"])
            row.pack(fill="x", pady=2)
            tk.Label(row, text=label, bg=C["panel2"],
                     fg=C["txt_dim"], font=("Courier New",10),
                     width=14, anchor="w").pack(side="left")
            if isinstance(var, tk.BooleanVar):
                tk.Checkbutton(row, variable=var,
                               bg=C["panel2"], fg=C["txt"],
                               activebackground=C["panel2"],
                               selectcolor=C["emerald_t"],
                               relief="flat",
                               font=("Courier New",10)).pack(side="left")
            elif isinstance(var, tk.StringVar) and tip == "optionmenu":
                om = tk.OptionMenu(row, var, "all", "IG+MEG")
                om.config(bg=C["glass"], fg=C["cyan"],
                          activebackground=C["cyan_t"],
                          activeforeground=C["cyan"],
                          relief="flat", bd=0,
                          font=("Courier New",10),
                          highlightthickness=0, width=width-2)
                om["menu"].config(bg=C["panel"], fg=C["txt"],
                                  font=("Courier New",10))
                om.pack(side="left")
            else:
                e = tk.Entry(row, textvariable=var, width=width,
                             bg=_ca(C["cyan"],"0a"), fg=C["txt"],
                             insertbackground=C["cyan"],
                             relief="flat", bd=3,
                             font=("Courier New",11),
                             highlightthickness=1,
                             highlightbackground=_ca(C["cyan"],"22"))
                e.pack(side="left")
            return row

        vp = self._vp

        # ── Section 1: ENRICHMENT ──────────────────────────────────────────
        s1 = _section(container, "ENRICHMENT", C["violet"], 0)
        _param(s1, "Window size",   vp["enr_window_size"],    10)
        _param(s1, "Step size",     vp["enr_step_size"],      10)
        _param(s1, "FDR threshold", vp["enr_fdr_threshold"],  8)
        _param(s1, "Background",    vp["enr_background"],     8, "optionmenu")
        _param(s1, "Marker size",   vp["enr_marker_size"],    6)
        _param(s1, "Highlight α",   vp["enr_highlight_alpha"],6)

        # ── Section 2: BOXPLOT / VIOLIN ────────────────────────────────────
        s2 = _section(container, "BOXPLOT / VIOLIN", C["teal"], 1)
        _param(s2, "Whiskers IQR",  vp["box_whiskers"],      6)
        _param(s2, "Box width",     vp["box_width"],          6)
        _param(s2, "Violin width",  vp["vln_width"],          6)
        _param(s2, "Show fliers",   vp["box_show_fliers"])
        _param(s2, "Show jitter",   vp["box_show_jitter"])
        _param(s2, "Jitter pts",    vp["box_jitter_points"],  6)
        _param(s2, "Jitter width",  vp["box_jitter_width"],   6)

        # ── Section 3: HISTOGRAM ───────────────────────────────────────────
        s3 = _section(container, "HISTOGRAM", C["cyan"], 2)
        _param(s3, "Bins",          vp["hist_bins"],          6)
        _param(s3, "Fill alpha",    vp["hist_alpha"],         6)
        _param(s3, "Show median",   vp["hist_show_median"])
        _param(s3, "Bar width",     vp["chrom_bar_width"],    6)
        _param(s3, "Show values",   vp["chrom_show_values"])

        # ── Section 4: STATISTICS ──────────────────────────────────────────
        s4 = _section(container, "STATISTICAL TESTS", C["amber"], 3)
        _param(s4, "α level",       vp["stat_significance"],  6)
        _param(s4, "Annotations",   vp["stat_show_overlay"])
        _param(s4, "Welch t-test",  vp["stat_welch"])
        _param(s4, "Mann-Whitney",  vp["stat_mannwhitney"])
        _param(s4, "Cliff's δ",    vp["stat_cliffs_delta"])
        _param(s4, "Chi² chrom",    vp["stat_chi2"])

        # ── Section 5: DISPLAY ─────────────────────────────────────────────
        s5 = _section(container, "DISPLAY", C["emerald"], 4)
        _param(s5, "Show grid",     vp["disp_show_grid"])
        _param(s5, "Grid alpha",    vp["disp_grid_alpha"],    6)
        _param(s5, "DPI",           vp["disp_dpi"],           6)
        _param(s5, "Annotations",   vp["disp_show_annotations"])

    # ──────────────────────────────────────────────────────────────────────────
    #  Helpers: ◀ / ▶ navigation across all 37 modes
    # ──────────────────────────────────────────────────────────────────────────
    _CHROM_ORDER = [str(i) for i in range(1,23)] + ["X","Y","MT"]
    _ALL_MODES = [
        "Boxplot", "Boxplot (Log-scale)",
        "Violin Plot", "Violin Plot (Log-scale)",
        "Length Histogram", "Length Histogram (Log-scale)",
        "Transcript Length KDE",
        "Chromosome Distribution",
        "Class Distribution (Donut)",
        "Genes by Chromosome",
        "Biotypes — IG", "Biotypes — MEG",
    ] + [f"IG Enrichment — Chr {c}" for c in _CHROM_ORDER]

    def _nav_prev_mode(self):
        cur = self._plot_var.get()
        modes = self._ALL_MODES
        idx = modes.index(cur) if cur in modes else 0
        self._plot_var.set(modes[(idx - 1) % len(modes)])

    def _nav_next_mode(self):
        cur = self._plot_var.get()
        modes = self._ALL_MODES
        idx = modes.index(cur) if cur in modes else 0
        self._plot_var.set(modes[(idx + 1) % len(modes)])

    # ──────────────────────────────────────────────────────────────────────────
    #  TEST: genera datos sintéticos y renderiza el modo seleccionado
    # ──────────────────────────────────────────────────────────────────────────
    def _make_demo_results(self):
        """Crea DataFrames sintéticos que cubren todos los campos usados por los plots."""
        rng = np.random.default_rng(42)
        chroms = [str(i) for i in range(1, 23)] + ["X", "Y"]

        biotypes_ig  = ["protein_coding", "lncRNA", "pseudogene",
                        "processed_pseudogene", "snRNA", "snoRNA",
                        "miRNA", "misc_RNA", "rRNA", "IG_V_gene"]
        biotypes_meg = ["protein_coding", "lncRNA", "processed_pseudogene",
                        "snRNA", "snoRNA", "miRNA", "ribozyme",
                        "vault_RNA", "scRNA", "TEC"]

        def _make_df(n, biotypes, label):
            chrom_choice = rng.choice(chroms, n,
                                      p=np.array([10,9,8,7,7,6,6,5,5,5,
                                                  5,5,4,4,4,4,4,3,3,3,
                                                  3,3,5,1], dtype=float) /
                                        np.array([10,9,8,7,7,6,6,5,5,5,
                                                  5,5,4,4,4,4,4,3,3,3,
                                                  3,3,5,1], dtype=float).sum())
            lengths = (10 ** rng.normal(3.8, 0.55, n)).astype(int).clip(200, 900_000)
            gene_starts = rng.integers(1_000, 200_000_000, n)
            return pd.DataFrame({
                "gene_id":   [f"ENSG{i:011d}" for i in range(n)],
                "gene_name": [f"{label}{i}"   for i in range(n)],
                "chrom":     chrom_choice,
                "strand":    rng.choice(["+", "-"], n),
                "gene_start": gene_starts,
                "gene_end":   gene_starts + lengths,
                "gene_biotype":
                    rng.choice(biotypes, n,
                               p=np.array([30,20,15,10,8,6,4,3,2,2],
                                          dtype=float) /
                                 np.array([30,20,15,10,8,6,4,3,2,2],
                                          dtype=float).sum()),
                "representative_transcript_length": lengths,
                "n_transcripts": rng.integers(1, 12, n),
                "class_label":   label,
            })

        ig  = _make_df(620,  biotypes_ig,  "IG")
        meg = _make_df(310,  biotypes_meg, "MEG")
        ui  = _make_df(180,  biotypes_ig,  "ui-SEG")

        # Generar gene_summary y enrichment sintéticos
        gene_summary = pd.concat([ig, meg, ui], ignore_index=True)
        enr_gene_df = gene_summary.copy()
        enr_gene_df["gene_start"] = pd.to_numeric(
            enr_gene_df["gene_start"], errors="coerce")
        enr_gene_df["gene_end"] = pd.to_numeric(
            enr_gene_df["gene_end"], errors="coerce")
        enr_df = sliding_window_enrichment(
            enr_gene_df, window_size=1_000_000, step_size=1_000_000)
        return {
            "ig": ig, "meg": meg, "ui": ui,
            "species": "demo_species",
            "gene_summary": gene_summary,
            "enrichment_df": enr_df,
            "enr_gene_df": enr_gene_df,
        }

    def _render_test(self):
        """Renderiza el modo de visualización seleccionado con datos de prueba."""
        demo = self._make_demo_results()
        ig   = demo["ig"];  meg = demo["meg"]
        ui   = demo["ui"];  sp  = demo["species"]
        self._plt_base_style()
        # Mismo dispatch que _render_plot — paridad total entre RENDER y TEST.
        dispatch = {
            "Boxplot":                       self._plot_boxplot,
            "Boxplot (Log-scale)":           self._plot_boxplot_log,
            "Violin Plot":                   self._plot_violin,
            "Violin Plot (Log-scale)":       self._plot_violin_log,
            "Length Histogram":              self._plot_length_histogram,
            "Length Histogram (Log-scale)":  self._plot_length_histogram_log,
            "Transcript Length KDE":         self._plot_transcript_len,
            "Chromosome Distribution":       self._plot_chrom_dist,
            "Class Distribution (Donut)":    self._plot_class_dist,
            "Genes by Chromosome":           self._plot_by_chrom,
        }
        mode = self._plot_var.get()
        if mode.startswith("──"):
            return
        try:
            if mode.startswith("IG Enrichment"):
                chrom = mode.split("Chr ")[-1]
                fig = self._plot_enrichment_gui(
                    demo.get("enrichment_df", pd.DataFrame()),
                    demo.get("enr_gene_df", pd.DataFrame()),
                    chrom, sp)
            elif mode == "Biotypes — IG":
                fig = self._plot_biotypes(ig,  sp, "IG",  self._CP["cyan"])
            elif mode == "Biotypes — MEG":
                fig = self._plot_biotypes(meg, sp, "MEG", self._CP["teal"])
            elif mode in dispatch:
                fig = dispatch[mode](ig, meg, ui, sp)
            else:
                messagebox.showinfo("Info", f"Mode '{mode}' not available.")
                return
        except Exception as e:
            logging.exception("Test plot error")
            messagebox.showerror("Test Error", str(e))
            return
        fig.tight_layout(pad=2.8)
        if self._mpl_canvas:
            try:
                old_fig = getattr(self._mpl_canvas, "figure", None)
                self._mpl_canvas.get_tk_widget().destroy()
                if old_fig is not None:
                    plt.close(old_fig)
            except Exception:
                pass
        self._mpl_canvas = FigureCanvasTkAgg(fig, master=self._plot_frame)
        self._mpl_canvas.draw()
        self._mpl_canvas.get_tk_widget().pack(fill="both", expand=True)
        # macOS: flush + nudge para evitar canvas negro
        self._force_redraw(self._mpl_canvas)
        self._test_lbl.configure(
            text=f"⚗ DEMO  ·  {mode}  ·  IG=620  MEG=310  ui-SEG=180")

    _CP = {
        # ══════════════════════════════════════════════════════════════════
        #  PALETA IGFinder VISUALIZATION MODE — Premium Scientific Edition
        #  Filosofía: legibilidad máxima, identidad visual, publicación
        # ══════════════════════════════════════════════════════════════════

        # ── Fondos — blancos limpios, panel con tinte violeta imperceptible ─
        "bg":      "#ffffff",   # blanco puro
        "panel":   "#fafbff",   # blanco con tinte violeta casi invisible
        "panel2":  "#f3f0ff",   # violeta muy pálido — cajas de anotación

        # ── Colores de clase — tríada joya: violeta · rosa · azul ─────────
        #    Seleccionados por: contraste WCAG-AA, armonía, colorblind-safe
        "cyan":    "#5b21b6",   # IG  — violeta-800 (joya profunda, autoridad)
        "teal":    "#be185d",   # MEG — rosa-700    (cálido, vibrante, distinto)
        "violet":  "#0369a1",   # SEG — cielo-700   (frío, científico, claro)

        # ── Acento mediana — contraste máximo sobre las cajas de color ────
        "median_ig":  "#ede9fe",  # lavanda pálido — mediana sobre violeta
        "median_meg": "#fce7f3",  # rosa pálido    — mediana sobre rosa
        "median_seg": "#e0f2fe",  # celeste pálido — mediana sobre azul

        # ── Tipografía — máximo contraste, identidad de marca ─────────────
        "amber":   "#1c1433",   # near-black violeta → títulos (impacto total)
        "gold":    "#3730a3",   # índigo-800         → labels de eje (readable)

        # ── Alertas estadísticas ───────────────────────────────────────────
        "rose":    "#b91c1c",   # rojo-700  → p < 0.001 / outliers extremos
        "coral":   "#b45309",   # ámbar-700 → p < 0.05  / elementos de aviso

        # ── Infraestructura: texto, bordes, grid ──────────────────────────
        "txt":     "#1c1433",   # near-black violeta — máximo contraste
        "txt_d":   "#6d28d9",   # violeta-700 — texto secundario / anotaciones
        "bd":      "#ddd6fe",   # violeta-200 — spines y bordes (suaves, elegantes)
        "bd2":     "#ede9fe",   # violeta-100 — grid (casi invisible, no distrae)
    }

    def _plt_base_style(self):
        cp = self._CP
        plt.rcParams.update({
            "figure.facecolor":   cp["bg"],
            "axes.facecolor":     cp["panel"],
            "axes.edgecolor":     cp["bd"],
            "axes.labelcolor":    cp["gold"],
            "axes.titlecolor":    cp["amber"],
            "axes.titlepad":      14,  "axes.titlesize":   12,
            "axes.titleweight":   "bold", "axes.labelsize": 10,
            "axes.spines.top":    False,  "axes.spines.right": False,
            "axes.spines.bottom": True,   "axes.spines.left":  True,
            "axes.axisbelow":     True,
            "xtick.color":        cp["gold"],  "ytick.color":    cp["gold"],
            "xtick.labelsize":    9,            "ytick.labelsize": 9,
            "xtick.direction":    "out",        "ytick.direction": "out",
            "xtick.major.size":   5,            "ytick.major.size": 5,
            "xtick.major.width":  1.2,          "ytick.major.width": 1.2,
            "text.color":         cp["txt"],
            "legend.facecolor":   cp["panel2"], "legend.edgecolor": cp["bd"],
            "legend.labelcolor":  cp["txt"],    "legend.framealpha": 0.95,
            "legend.fontsize":    9,            "legend.title_fontsize": 9,
            "grid.color":         cp["bd2"],    "grid.linestyle":  "-",
            "grid.linewidth":     1.0,          "grid.alpha":       1.0,
            "axes.axisbelow":     True,
            "font.family":        "sans-serif",
            "figure.dpi":         self._get_vp("disp_dpi"),
        })

    def _render_plot(self):
        if not self._results:
            messagebox.showinfo("No data","Run the pipeline first."); return
        ig  = self._results.get("ig",  pd.DataFrame())
        meg = self._results.get("meg", pd.DataFrame())
        ui  = self._results.get("ui",  pd.DataFrame())
        sp  = self._results.get("species","")
        self._plt_base_style()
        mode = self._plot_var.get()
        if mode.startswith("──"):
            return
        # Modos con firma estándar (ig, meg, ui, sp) → dispatch directo.
        dispatch = {
            "Boxplot":                       self._plot_boxplot,
            "Boxplot (Log-scale)":           self._plot_boxplot_log,
            "Violin Plot":                   self._plot_violin,
            "Violin Plot (Log-scale)":       self._plot_violin_log,
            "Length Histogram":              self._plot_length_histogram,
            "Length Histogram (Log-scale)":  self._plot_length_histogram_log,
            "Transcript Length KDE":         self._plot_transcript_len,
            "Chromosome Distribution":       self._plot_chrom_dist,
            "Class Distribution (Donut)":    self._plot_class_dist,
            "Genes by Chromosome":           self._plot_by_chrom,
        }
        try:
            if mode.startswith("IG Enrichment"):
                chrom = mode.split("Chr ")[-1]
                enr_df = self._results.get("enrichment_df", pd.DataFrame())
                enr_gene_df = self._results.get("enr_gene_df", pd.DataFrame())
                fig = self._plot_enrichment_gui(
                    enr_df, enr_gene_df, chrom, sp)
            elif mode == "GO/KEGG Enrichment":
                func_df = self._results.get("func_enrichment_df", pd.DataFrame())
                fig = self._plot_go_enrichment_gui(func_df, sp)
            elif mode == "Orthology Heatmap":
                orth_mat = self._results.get("orthology_matrix_df", pd.DataFrame())
                orth_sum = self._results.get("orthology_summary", {})
                fig = self._plot_orthology_gui(orth_mat, orth_sum, sp)
            elif mode == "Biotypes — IG":
                # Firma especial: (df, sp, label, color)
                fig = self._plot_biotypes(ig,  sp, "IG",  self._CP["cyan"])
            elif mode == "Biotypes — MEG":
                fig = self._plot_biotypes(meg, sp, "MEG", self._CP["teal"])
            elif mode in dispatch:
                fig = dispatch[mode](ig, meg, ui, sp)
            else:
                messagebox.showinfo("Info", f"Mode '{mode}' not available.")
                return
        except Exception as e:
            logging.exception("Plot error")
            messagebox.showerror("Plot Error",str(e)); return
        fig.tight_layout(pad=2.8)
        if self._mpl_canvas:
            try:
                old_fig = getattr(self._mpl_canvas, "figure", None)
                self._mpl_canvas.get_tk_widget().destroy()
                if old_fig is not None:
                    plt.close(old_fig)
            except Exception:
                pass
        self._mpl_canvas = FigureCanvasTkAgg(fig, master=self._plot_frame)
        self._mpl_canvas.draw()
        self._mpl_canvas.get_tk_widget().pack(fill="both", expand=True)
        # macOS: flush + nudge para evitar canvas negro al terminar
        self._force_redraw(self._mpl_canvas)

    def _plot_class_dist(self, ig, meg, ui, sp):
        cp = self._CP
        counts=[len(ig),len(meg),len(ui)]; labels=["IG","MEG","ui-SEG"]
        colors=[cp["teal"],cp["cyan"],cp["violet"]]; total=max(sum(counts),1)

        # ── Figura: proporción 14×6 para dar espacio horizontal a las cards ─
        fig=plt.figure(figsize=(14,6),facecolor=cp["bg"])

        # Título general arriba, fuera de los axes
        fig.text(0.50,0.97,f"CLASS DISTRIBUTION  ·  {sp.upper()}",
                 fontsize=11,fontweight="bold",color=cp["teal"],
                 fontfamily="monospace",va="top",ha="center")

        # GridSpec: donut izq (40%) | cards der (60%)
        gs=gridspec.GridSpec(1,2,figure=fig,width_ratios=[0.85,1.15],wspace=0.06,
                             left=0.02,right=0.98,top=0.88,bottom=0.04)

        # ── Panel izquierdo: Donut ────────────────────────────────────────────
        ax_d=fig.add_subplot(gs[0])
        ax_d.set_facecolor(cp["bg"]); ax_d.set_aspect("equal"); ax_d.axis("off")
        theta=np.linspace(0,2*math.pi,400)
        for r,a in [(0.78,0.05),(0.76,0.10),(0.73,0.18)]:
            ax_d.plot(r*np.cos(theta),r*np.sin(theta),color=cp["teal"],lw=0.8,alpha=a)
        ax_d.plot(0.26*np.cos(theta),0.26*np.sin(theta),color=cp["bd"],lw=0.8,alpha=0.35)
        for i in range(48):
            ang=math.radians(i*7.5); r0=0.71; r1=0.79 if i%4==0 else 0.74
            ax_d.plot([r0*math.cos(ang),r1*math.cos(ang)],
                      [r0*math.sin(ang),r1*math.sin(ang)],
                      color=cp["bd"],lw=1.2 if i%4==0 else 0.6)
        if any(c>0 for c in counts):
            wedges,_=ax_d.pie([max(c,0.0001) for c in counts],colors=colors,
                              startangle=90,wedgeprops=dict(width=0.44,edgecolor=cp["bg"],linewidth=3))
            for w,col in zip(wedges,colors):
                w.set_path_effects([mpe.withStroke(linewidth=20,foreground=col+"10"),
                                    mpe.withStroke(linewidth=11,foreground=col+"22"),mpe.Normal()])
            for w,col,cnt in zip(wedges,colors,counts):
                ang=math.radians((w.theta1+w.theta2)/2); pct=cnt/total*100
                if pct>5:
                    ax_d.text(0.57*math.cos(ang),0.57*math.sin(ang),f"{pct:.1f}%",
                              ha="center",va="center",fontsize=9,fontweight="bold",
                              color=cp["bg"],fontfamily="monospace",
                              bbox=dict(boxstyle="round,pad=0.10",fc=col,ec="none",alpha=0.90))
        else:
            ax_d.pie([1],colors=[cp["bd"]],startangle=90,
                     wedgeprops=dict(width=0.44,edgecolor=cp["bg"],linewidth=2))
        # Centro del donut: total + label
        ax_d.text(0,0.13,f"{total:,}",ha="center",va="center",fontsize=21,
                  fontweight="bold",color="#bb88ff",fontfamily="monospace",
                  path_effects=[mpe.withStroke(linewidth=5,foreground=cp["bg"]),mpe.Normal()])
        ax_d.text(0,-0.10,"TOTAL GENES",ha="center",va="center",fontsize=7.5,
                  color=_ca(cp["gold"],"88"),fontfamily="monospace",fontweight="bold")

        # ── Panel derecho: 3 cards apiladas ──────────────────────────────────
        ax_r=fig.add_subplot(gs[1])
        ax_r.set_facecolor(cp["bg"]); ax_r.axis("off")
        ax_r.set_xlim(0,1); ax_r.set_ylim(0,1)

        # 3 cards uniformes con separación consistente
        card_h=0.240; gap=0.040
        total_block=3*card_h+2*gap
        y_start=0.50+total_block/2   # centrado vertical

        for i,(lbl,cnt,col) in enumerate(zip(labels,counts,colors)):
            pct=cnt/total*100
            y_top_card=y_start - i*(card_h+gap)
            y_bot_card=y_top_card - card_h

            # Fondo de la card
            ax_r.add_patch(FancyBboxPatch((0.02,y_bot_card),0.96,card_h,
                boxstyle="round,pad=0.010",facecolor=cp["panel"],
                edgecolor=_ca(col,"99"),linewidth=1.4,zorder=2,
                transform=ax_r.transAxes,clip_on=False))
            # Barra de acento izquierda (5% de ancho)
            ax_r.add_patch(FancyBboxPatch((0.02,y_bot_card),0.018,card_h,
                boxstyle="round,pad=0.003",facecolor=col,edgecolor="none",
                zorder=3,transform=ax_r.transAxes,clip_on=False))

            # Nombre de clase — izquierda, tamaño equilibrado
            cx_lbl=0.08; cy_lbl=y_top_card-card_h*0.32
            ax_r.text(cx_lbl,cy_lbl,lbl,transform=ax_r.transAxes,
                      fontsize=12,fontweight="bold",color=col,
                      fontfamily="monospace",va="center",zorder=4)

            # Número de genes — derecha, tamaño moderado para que quepa
            ax_r.text(0.97,cy_lbl,f"{cnt:,}",transform=ax_r.transAxes,
                      fontsize=18,fontweight="bold",color="#cc99ff",
                      fontfamily="monospace",ha="right",va="center",zorder=4,
                      path_effects=[mpe.withStroke(linewidth=4,foreground=col+"30"),
                                    mpe.Normal()])

            # Barra de progreso — fila inferior de cada card
            bx0=0.08; bw=0.66; bh=0.022
            by_bar=y_bot_card+card_h*0.18
            ax_r.add_patch(FancyBboxPatch((bx0,by_bar),bw,bh,
                boxstyle="round,pad=0.003",facecolor=cp["bd2"],
                edgecolor=_ca(col,"28"),linewidth=0.7,zorder=3,
                transform=ax_r.transAxes,clip_on=False))
            fw=bw*(pct/100.0)
            if fw>0.004:
                ax_r.add_patch(FancyBboxPatch((bx0,by_bar),fw,bh,
                    boxstyle="round,pad=0.003",facecolor=col,edgecolor="none",
                    alpha=0.85,zorder=4,transform=ax_r.transAxes,clip_on=False))
            # Porcentaje junto a la barra
            ax_r.text(bx0+bw+0.025,by_bar+bh/2,f"{pct:.1f}%",
                      transform=ax_r.transAxes,fontsize=9,fontweight="bold",
                      color=col,fontfamily="monospace",va="center",zorder=4)

        return fig

    def _plot_transcript_len(self, ig, meg, ui, sp):
        cp = self._CP
        def _gaussian_kde(data, n_pts=500):
            if len(data)>8000:
                rng=np.random.default_rng(42); data=rng.choice(data,8000,replace=False)
            lo=data.min()-0.12; hi=data.max()+0.12; xs=np.linspace(lo,hi,n_pts)
            bw=max(1.06*data.std()*len(data)**(-0.2),0.04)
            diff=xs[np.newaxis,:]-data[:,np.newaxis]
            ks=np.exp(-0.5*(diff/bw)**2).sum(0); ks/=len(data)*bw*np.sqrt(2*math.pi)
            return xs,ks
        def _fmt_bp(v):
            if v>=1e6: return f"{v/1e6:.2f} Mb"
            if v>=1e3: return f"{v/1e3:.0f} kb"
            return f"{v:.0f} bp"

        # Figura más alta y con más margen para evitar recortes
        fig,ax=plt.subplots(figsize=(14,6.5),facecolor=cp["bg"])
        fig.subplots_adjust(left=0.10,right=0.92,top=0.88,bottom=0.14)
        ax.set_facecolor(cp["panel"])

        pairs=[(ig,"IG",cp["teal"]),(meg,"MEG",cp["cyan"])]; kdes=[]
        for df2,lbl,col in pairs:
            if df2.empty or "representative_transcript_length" not in df2.columns: continue
            lens=df2["representative_transcript_length"].dropna().values
            lens=lens[(lens>100)&(lens<5_000_000)].astype(float)
            if len(lens)<5: continue
            log_l=np.log10(lens+1); xs,ks=_gaussian_kde(log_l)
            kdes.append((xs,ks,log_l,lbl,col))
        if not kdes:
            ax.text(0.5,0.5,"No transcript length data available",
                    ha="center",va="center",transform=ax.transAxes,
                    color=cp["txt_d"],fontsize=12); return fig

        # Espaciado vertical: 1.9× la densidad máxima para que no se solapen
        max_k=max(k.max() for _,k,*_ in kdes); spacing=max_k*1.90

        for i,(xs,ks,log_l,lbl,col) in enumerate(kdes):
            y0=i*spacing

            # Capas de relleno con glows suaves
            for alp,sc in [(0.03,3.0),(0.07,1.9),(0.14,1.25),(0.50,1.0)]:
                ax.fill_between(xs,y0,y0+ks*sc,color=col,alpha=alp,linewidth=0)
            # Curva principal
            ax.plot(xs,y0+ks,color=col,lw=2.0,
                    path_effects=[mpe.withStroke(linewidth=8,foreground=col+"22"),mpe.Normal()])
            # Línea base
            ax.axhline(y0,color=col,lw=0.5,alpha=0.20,xmin=0.02,xmax=0.98)

            p10,p25,p50,p75,p90=np.percentile(log_l,[10,25,50,75,90])
            idx_med=np.argmin(np.abs(xs-p50)); ks_med=ks[idx_med]

            # Relleno P10-P90
            mask90=(xs>=p10)&(xs<=p90)
            if mask90.any():
                ax.fill_between(xs[mask90],y0,y0+ks[mask90],color=col,alpha=0.10,linewidth=0)
            # Relleno IQR
            mask_iqr=(xs>=p25)&(xs<=p75)
            if mask_iqr.any():
                ax.fill_between(xs[mask_iqr],y0,y0+ks[mask_iqr],color=col,alpha=0.28,linewidth=0)

            # Línea mediana
            ax.vlines(p50,y0,y0+ks_med*1.10,color=cp["amber"],lw=1.8,alpha=0.96,
                      path_effects=[mpe.withStroke(linewidth=6,foreground=cp["amber"]+"30"),mpe.Normal()])

            # Anotación mediana — texto compacto, flecha corta
            x_rng=xs.max()-xs.min()
            ax.annotate(f"median={_fmt_bp(10**p50-1)}",
                        xy=(p50, y0+ks_med*1.12),
                        xytext=(p50+x_rng*0.06, y0+ks.max()*0.82),
                        fontsize=8,color=cp["amber"],fontfamily="monospace",
                        arrowprops=dict(arrowstyle="->",color=cp["amber"],
                                        lw=0.9,shrinkA=1,shrinkB=2),
                        bbox=dict(boxstyle="round,pad=0.25",fc=cp["panel2"],
                                  ec=cp["amber"],lw=0.9),zorder=10)

            # Etiqueta IQR dentro de la curva
            ax.text((p25+p75)/2, y0+ks_med*0.14,
                    f"IQR {_fmt_bp(10**p25-1)}–{_fmt_bp(10**p75-1)}",
                    ha="center",fontsize=7,color=col,fontfamily="monospace",alpha=0.90)

            # P10 / P90 — líneas punteadas + texto bajo la baseline
            for px,ltxt in [(p10,f"P10\n{_fmt_bp(10**p10-1)}"),(p90,f"P90\n{_fmt_bp(10**p90-1)}")]:
                yp=ks[np.argmin(np.abs(xs-px))]
                ax.vlines(px,y0,y0+yp*0.32,color=_ca(col,"66"),lw=0.8,linestyle=":")
                ax.text(px, y0-max_k*0.09, ltxt,
                        ha="center",va="top",fontsize=6.5,
                        color=_ca(col,"cc"),fontfamily="monospace")

            # Etiqueta de clase — lado izquierdo con fondo oscuro
            ax.text(xs.min()-0.08, y0+ks.max()*0.50, lbl,
                    ha="right",va="center",fontsize=13,fontweight="bold",
                    color=col,fontfamily="monospace",
                    path_effects=[mpe.withStroke(linewidth=5,foreground=cp["bg"]),mpe.Normal()])
            # n = X — lado derecho enmarcado
            ax.text(xs.max()+0.06, y0+ks.max()*0.30,
                    f"n={len(log_l):,}",
                    ha="left",va="center",fontsize=8,color=col,
                    fontfamily="monospace",fontweight="bold",
                    bbox=dict(boxstyle="round,pad=0.22",fc=cp["panel"],
                              ec=_ca(col,"55"),lw=0.7))

        # Eje X con ticks bien espaciados
        x_vals=np.concatenate([k[0] for k in kdes])
        lo_x=x_vals.min()-0.30; hi_x=x_vals.max()+0.55
        ax.set_xlim(lo_x,hi_x)
        ticks=[t for t in [2,2.5,3,3.5,4,4.5,5,5.5,6] if lo_x<=t<=hi_x]
        ax.set_xticks(ticks)
        ax.set_xticklabels([_fmt_bp(10**t-1) for t in ticks],fontsize=8.5,color="#200a50")
        ax.set_yticks([]); ax.spines["left"].set_visible(False)
        ax.spines["bottom"].set_color(cp["bd"])
        ax.set_xlabel("Transcript length  (log₁₀ scale)",labelpad=9,fontsize=10)
        ax.set_title(f"TRANSCRIPT LENGTH DISTRIBUTION  ·  {sp.upper()}",
                     pad=12,fontsize=11,fontweight="bold")
        ax.legend(handles=[
            Line2D([0],[0],color=cp["amber"],lw=1.8,label="Median"),
            Patch(facecolor=cp["teal"],alpha=0.28,label="IQR 25–75% (IG)"),
            Patch(facecolor=cp["cyan"],alpha=0.28,label="IQR 25–75% (MEG)"),
            Patch(facecolor=cp["teal"],alpha=0.10,label="P10–P90 (IG)"),
            Patch(facecolor=cp["cyan"],alpha=0.10,label="P10–P90 (MEG)"),],
            facecolor=cp["panel2"],edgecolor=cp["bd"],
            labelcolor="#4020aa",fontsize=8,loc="upper right",framealpha=0.93)
        return fig

    def _plot_biotypes(self, df, sp, label, color):
        cp = self._CP
        # Figura 14×6 con márgenes calibrados
        fig=plt.figure(figsize=(14,6),facecolor=cp["bg"])
        # GridSpec: lollipop (izq 60%) | tabla ranking (der 40%)
        gs=gridspec.GridSpec(1,2,figure=fig,width_ratios=[1.55,1.0],wspace=0.08,
                             left=0.14,right=0.97,top=0.88,bottom=0.11)

        # ── Panel izquierdo: Lollipop chart ──────────────────────────────────
        ax=fig.add_subplot(gs[0]); ax.set_facecolor(cp["panel"])
        if df.empty or "gene_biotype" not in df.columns or len(df)==0:
            ax.text(0.5,0.5,"No biotype data available",ha="center",va="center",
                    transform=ax.transAxes,color=cp["txt_d"],fontsize=12); return fig

        vc=df["gene_biotype"].value_counts().head(10); total=max(vc.sum(),1)
        n_items=len(vc); y_pos=np.arange(n_items); max_v=float(vc.max())

        # Franjas alternas de fondo
        for i in y_pos:
            ax.axhspan(i-0.48,i+0.48,
                       color=cp["panel2"] if i%2==0 else cp["panel"],alpha=0.40,zorder=0)

        for i,(name,val) in enumerate(vc.items()):
            pct=val/total*100
            # Barra glow multicapa
            for alp,lw in [(0.05,9),(0.12,4.5),(0.80,1.6)]:
                ax.plot([0,val],[i,i],color=color,lw=lw,alpha=alp,
                        solid_capstyle="round",zorder=2)
            # Dot endpoint con halo
            for s2,alp in [(500,0.03),(260,0.08),(130,0.18),(50,0.88)]:
                ax.scatter([val],[i],s=s2,color=color,alpha=alp,zorder=4,linewidth=0)
            ax.scatter([val],[i],s=16,color=cp["bg"],alpha=1.0,zorder=5,linewidth=0)
            # Número de conteo — tamaño calibrado
            ax.text(val+max_v*0.020,i,f"{val:,}",va="center",fontsize=8.5,
                    fontweight="bold",color="#9966ff",fontfamily="monospace",zorder=6)
            # Porcentaje — alineado al borde derecho
            ax.text(max_v*1.38,i,f"{pct:.1f}%",va="center",ha="right",fontsize=8,
                    fontweight="bold",color=color,fontfamily="monospace")

        ax.set_yticks(y_pos)
        ax.set_yticklabels(vc.index,fontsize=8.5,fontfamily="monospace",color="#341480")
        ax.invert_yaxis()
        ax.set_xlim(-max_v*0.03, max_v*1.48)
        ax.xaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_:f"{int(x):,}"))
        ax.tick_params(axis='x',labelsize=8,labelcolor="#0d0425")
        ax.set_xlabel("Gene count",labelpad=8,fontsize=9)
        ax.set_title(f"BIOTYPE BREAKDOWN — {label}  ·  {sp.upper()}",
                     pad=12,fontsize=11,fontweight="bold",color=color)
        ax.grid(axis="x",zorder=0,alpha=0.22,color=_ca(color,"30"))
        ax.spines["left"].set_visible(False)

        # ── Panel derecho: Tabla de ranking ──────────────────────────────────
        ax2=fig.add_subplot(gs[1]); ax2.set_facecolor(cp["bg"])
        ax2.axis("off"); ax2.set_xlim(0,1); ax2.set_ylim(0,1)

        # Cabecera del panel
        ax2.text(0.05,0.97,f"TOP BIOTYPES — {label}",fontsize=9,fontweight="bold",
                 color=color,fontfamily="monospace",va="top",transform=ax2.transAxes)
        # axhline genera su propio transform — no se pasa `transform=`.
        ax2.axhline(0.91,xmin=0.03,xmax=0.97,color=_ca(color,"55"),lw=1.0)

        # Encabezados de columna
        ax2.text(0.06,0.885,"#",fontsize=7.5,fontweight="bold",
                 color=_ca(color,"88"),fontfamily="monospace",va="top",transform=ax2.transAxes)
        ax2.text(0.18,0.885,"BIOTYPE",fontsize=7.5,fontweight="bold",
                 color=_ca(color,"88"),fontfamily="monospace",va="top",transform=ax2.transAxes)
        ax2.text(0.77,0.885,"N",fontsize=7.5,fontweight="bold",
                 color=_ca(color,"88"),fontfamily="monospace",va="top",ha="right",
                 transform=ax2.transAxes)
        ax2.axhline(0.868,xmin=0.03,xmax=0.97,color=_ca(color,"28"),lw=0.6)

        # Filas de la tabla — espaciado preciso para 10 ítems
        n_rows=min(len(vc),10); row_h=0.078
        for i,(name,val) in enumerate(vc.head(n_rows).items()):
            pct=val/total*100; y_r=0.855 - i*row_h
            brightness=0.32+0.68*(1-i/max(n_rows-1,1))
            row_col=_blend(color,brightness,cp["panel"])

            # Fondo alterno de fila
            if i%2==0:
                ax2.add_patch(FancyBboxPatch(
                    (0.02, y_r-row_h*0.72), 0.96, row_h*0.78,
                    boxstyle="round,pad=0.004",facecolor=cp["panel"],
                    edgecolor=_ca(color,"18"),linewidth=0.5,zorder=1,
                    transform=ax2.transAxes,clip_on=False))

            # Badge de número
            cy_badge=y_r-row_h*0.30
            ax2.scatter([0.09],[cy_badge],s=75,color=row_col,alpha=0.92,zorder=3,
                        linewidth=0,transform=ax2.transAxes,clip_on=False)
            ax2.text(0.09,cy_badge,str(i+1),fontsize=6,fontweight="bold",
                     color=cp["bg"],fontfamily="monospace",
                     ha="center",va="center",zorder=4,transform=ax2.transAxes)

            # Nombre del biotipo — truncado a 16 chars
            short=(name[:16]+"…") if len(name)>16 else name
            ax2.text(0.17,cy_badge,short,fontsize=7.5,color="#5530cc",
                     fontfamily="monospace",va="center",transform=ax2.transAxes)

            # Conteo alineado a la derecha
            ax2.text(0.78,cy_badge,f"{val:,}",fontsize=7.5,fontweight="bold",
                     color=row_col,fontfamily="monospace",
                     va="center",ha="right",transform=ax2.transAxes)

            # Mini barra proporcional
            bx=0.79; by2=cy_badge-0.012; bw2=0.17; bh2=0.013
            ax2.add_patch(plt.Rectangle((bx,by2),bw2,bh2,
                facecolor=cp["bd"],zorder=2,transform=ax2.transAxes,clip_on=False))
            ax2.add_patch(plt.Rectangle((bx,by2),bw2*(pct/100),bh2,
                facecolor=row_col,alpha=0.88,zorder=3,
                transform=ax2.transAxes,clip_on=False))

        # Pie con totales
        y_foot=0.855-n_rows*row_h-0.018
        ax2.axhline(y_foot,xmin=0.03,xmax=0.97,color=_ca(color,"33"),lw=0.6)
        ax2.text(0.05,y_foot-0.025,
                 f"Total genes:    {len(df):,}\n"
                 f"Unique biotypes: {df['gene_biotype'].nunique()}",
                 fontsize=7.5,fontweight="bold",color=_ca(color,"bb"),
                 fontfamily="monospace",va="top",
                 transform=ax2.transAxes,linespacing=1.7)
        return fig

    def _plot_by_chrom(self, ig, meg, ui, sp):
        cp = self._CP
        def _chr_sort(c):
            try:    return (0, int(c))
            except: return (1, c)
        all_c=sorted(set((ig["chrom"].dropna().tolist() if not ig.empty else [])+
                         (meg["chrom"].dropna().tolist() if not meg.empty else [])),
                     key=_chr_sort)
        if not all_c:
            fig,ax=plt.subplots(figsize=(14,6),facecolor=cp["bg"])
            ax.text(0.5,0.5,"No chromosomal data available",ha="center",va="center",
                    transform=ax.transAxes,color=cp["txt_d"],fontsize=12); return fig

        xi=np.arange(len(all_c)); w=0.36
        ic={c:(ig["chrom"]==c).sum() for c in all_c} if not ig.empty else {}
        mc={c:(meg["chrom"]==c).sum() for c in all_c} if not meg.empty else {}
        ig_v=np.array([ic.get(c,0) for c in all_c],dtype=float)
        me_v=np.array([mc.get(c,0) for c in all_c],dtype=float)
        max_v=max(ig_v.max(),me_v.max(),1)

        # Figura horizontal más ancha para acomodar todos los cromosomas
        fig=plt.figure(figsize=(14,6),facecolor=cp["bg"])
        # GridSpec: barra principal arriba + density strip abajo
        gs=gridspec.GridSpec(2,1,figure=fig,height_ratios=[5.0,0.65],hspace=0.06,
                             left=0.07,right=0.98,top=0.89,bottom=0.12)

        ax=fig.add_subplot(gs[0]); ax.set_facecolor(cp["panel"])

        # Franjas de columnas alternas
        for i in range(len(all_c)):
            ax.axvspan(i-0.5,i+0.5,
                       color=cp["panel2"] if i%2==0 else cp["panel"],alpha=0.35,zorder=0)

        # Barras con capas de glow
        for alpha,scale in [(0.04,1.85),(0.10,1.30),(0.88,1.0)]:
            ax.bar(xi-w/2,ig_v,w*scale,color=cp["teal"],alpha=alpha,linewidth=0,zorder=2)
            ax.bar(xi+w/2,me_v,w*scale,color=cp["cyan"],alpha=alpha,linewidth=0,zorder=2)

        # Etiquetas de conteo sobre barras — font 7 para que quepan sin solaparse
        threshold=max_v*0.04
        for idx,(iv,mv) in enumerate(zip(ig_v,me_v)):
            if iv>threshold:
                ax.text(idx-w/2, iv+max_v*0.016, str(int(iv)),
                        ha="center",va="bottom",fontsize=7,fontweight="bold",
                        color=cp["teal"],fontfamily="monospace")
            if mv>threshold:
                ax.text(idx+w/2, mv+max_v*0.016, str(int(mv)),
                        ha="center",va="bottom",fontsize=7,fontweight="bold",
                        color=cp["cyan"],fontfamily="monospace")

        # Ejes y formato
        ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_:f"{int(x):,}"))
        ax.tick_params(axis='y',labelsize=8.5,labelcolor="#1a0840")
        ax.set_ylabel("Gene count",labelpad=10,fontsize=9)
        ax.set_title(f"GENES BY CHROMOSOME  ·  {sp.upper()}",pad=12,fontsize=11,fontweight="bold")
        ax.grid(axis="y",zorder=0,alpha=0.25,color=_ca(cp["gold"],"28"))
        ax.set_xlim(-0.65,len(all_c)-0.35); ax.set_ylim(0,max_v*1.24)
        ax.set_xticks(xi); ax.set_xticklabels([])
        ax.spines["bottom"].set_visible(False)

        # Etiquetas de cromosoma — dos alturas alternas, fuente pequeña pero legible
        for j,c in enumerate(all_c):
            yoff = -0.038 if j%2==0 else -0.082
            ax.text(j, yoff, c, ha="center", va="top", fontsize=7.5,
                    fontweight="bold", fontfamily="monospace",
                    color="#28106a",
                    transform=ax.get_xaxis_transform(), clip_on=False)

        # Leyenda compacta
        ax.legend(
            handles=[Patch(facecolor=cp["teal"],label=f"IG ({int(ig_v.sum()):,})"),
                     Patch(facecolor=cp["cyan"],label=f"MEG ({int(me_v.sum()):,})")],
            facecolor=cp["panel2"],edgecolor=cp["bd"],
            labelcolor=cp["txt"],fontsize=8.5,loc="upper right",
            framealpha=0.92,handlelength=1.2,handletextpad=0.5,
            prop={"family":"monospace","size":8.5,"weight":"bold"})

        # ── Density strip ─────────────────────────────────────────────────────
        ax2=fig.add_subplot(gs[1]); ax2.set_facecolor(cp["panel2"])
        ax2.set_xlim(-0.65,len(all_c)-0.35); ax2.set_ylim(0,1); ax2.axis("off")
        for j,c in enumerate(all_c):
            total_j=ig_v[j]+me_v[j]; ig_frac=ig_v[j]/max(total_j,1)
            bright=0.15+0.85*(total_j/max(ig_v+me_v))
            base_col=_blend(cp["teal"],ig_frac,cp["cyan"])
            bar_col=_blend(base_col,bright,cp["panel2"])
            ax2.add_patch(plt.Rectangle((j-0.44,0.10),0.88,0.80,
                facecolor=bar_col,edgecolor=_ca(cp["teal"],"22"),linewidth=0.4,zorder=2))
        ax2.text(len(all_c)/2,0.02,
                 "DENSITY  (color = IG/MEG ratio,  brightness = gene count)",
                 ha="center",va="bottom",fontsize=7.5,fontweight="bold",
                 color=_ca(cp["gold"],"99"),fontfamily="monospace")
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  VIOLIN PLOT — IG vs MEG (longitud de transcrito en escala lineal)
    # ══════════════════════════════════════════════════════════════════════════
    def _plot_violin(self, ig, meg, ui, sp):
        cp = self._CP
        col_map  = {"IG": cp["cyan"], "MEG": cp["teal"]}
        med_map  = {"IG": cp["median_ig"], "MEG": cp["median_meg"]}

        datasets, labels, colors, med_cols = [], [], [], []
        for df2, lbl in [(ig,"IG"),(meg,"MEG")]:
            if df2.empty or "representative_transcript_length" not in df2.columns: continue
            vals = df2["representative_transcript_length"].dropna().values
            vals = vals[vals > 0]
            if len(vals) < 5: continue
            datasets.append(vals); labels.append(lbl)
            colors.append(col_map[lbl]); med_cols.append(med_map[lbl])

        fig, ax = plt.subplots(figsize=(14, 6.5), facecolor=cp["bg"])
        fig.subplots_adjust(left=0.11, right=0.97, top=0.87, bottom=0.12)
        ax.set_facecolor(cp["panel"])

        if not datasets:
            ax.text(0.5,0.5,"No data available",ha="center",va="center",
                    transform=ax.transAxes,color=cp["txt_d"],fontsize=12)
            return fig

        positions = list(range(1, len(datasets)+1))
        W = self._get_vp("vln_width")

        # ── Capa de fondo por clase
        for pos, col in zip(positions, colors):
            ax.axvspan(pos - W*0.60, pos + W*0.60,
                       color=col, alpha=0.05, zorder=0, lw=0)

        # ── Violín principal (relleno sólido)
        vp = ax.violinplot(datasets, positions=positions,
                           showmedians=True, showextrema=True, widths=W)

        for body, col in zip(vp["bodies"], colors):
            body.set_facecolor(col)
            body.set_edgecolor(col)
            body.set_alpha(0.72)
            body.set_linewidth(0)
            body.set_zorder(3)

        # ── Violín fantasma (contorno)
        vp2 = ax.violinplot(datasets, positions=positions,
                            showmedians=False, showextrema=False, widths=W)
        for body, col in zip(vp2["bodies"], colors):
            body.set_facecolor("none")
            body.set_edgecolor(col)
            body.set_alpha(0.90)
            body.set_linewidth(1.8)
            body.set_zorder(4)

        # ── Estadísticos: mediana blanca, cbars opacos
        if "cmedians" in vp:
            vp["cmedians"].set_color("#ffffff")
            vp["cmedians"].set_linewidth(3.0)
            vp["cmedians"].set_alpha(1.0)
            vp["cmedians"].set_zorder(6)
        for part in ("cmaxes","cmins","cbars"):
            if part in vp:
                vp[part].set_color(cp["txt"])
                vp[part].set_linewidth(1.2)
                vp[part].set_alpha(0.45)
                vp[part].set_zorder(5)

        # ── Jitter
        if self._get_vp("vln_show_jitter"):
            _jw = self._get_vp("vln_jitter_width")
            _jp = self._get_vp("vln_jitter_points")
            for i,(vals,pos,col) in enumerate(zip(datasets,positions,colors)):
                rng = np.random.default_rng(42+i)
                sample = rng.choice(vals, min(len(vals),_jp), replace=False)
                jitter = rng.uniform(-_jw, _jw, len(sample))
                ax.scatter(np.full_like(sample, pos, dtype=float)+jitter,
                           sample, s=4, color="#ffffff", alpha=0.55,
                           linewidths=0.8, edgecolors=col, zorder=7)

        # ── Anotaciones
        for vals, pos, col, lbl in zip(datasets, positions, colors, labels):
            med  = np.median(vals)
            ymax = np.percentile(vals, 99)
            ax.annotate(
                "n = {:,}\nmedian = {:.1f} kb".format(len(vals), med/1e3),
                xy=(pos, ymax), xytext=(pos, ymax*1.04),
                ha="center", va="bottom", fontsize=8.5,
                color=col, fontweight="bold",
                bbox=dict(boxstyle="round,pad=0.35", fc=cp["panel2"],
                          ec=col, lw=1.2, alpha=0.95))

        ax.set_xticks(positions)
        for tick_lbl, col in zip(
                ax.set_xticklabels(labels, fontsize=13, fontweight="bold"),
                colors):
            tick_lbl.set_color(col)

        ax.set_xlabel("Gene class", labelpad=10, fontsize=10, color=cp["gold"])
        ax.set_ylabel("Representative transcript length (nt)", labelpad=10, fontsize=10)
        ax.set_title(f"Violin Plot — IG vs MEG  ·  {sp}",
                     pad=14, fontsize=13, fontweight="bold", color=cp["amber"])
        ax.yaxis.set_major_formatter(
            mticker.FuncFormatter(lambda x,_: f"{x/1e6:.1f} M" if x>=1e6
                                  else f"{x/1e3:.0f} k" if x>=1e3 else f"{int(x)}"))
        ax.tick_params(axis="y", labelsize=9, labelcolor=cp["gold"])
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0, alpha=1.0)
        ax.spines["bottom"].set_color(cp["bd"]); ax.spines["bottom"].set_linewidth(1.2)
        ax.spines["left"].set_color(cp["bd"]);   ax.spines["left"].set_linewidth(1.2)
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  BOXPLOT — IG vs MEG (longitud de transcrito en escala lineal)
    # ══════════════════════════════════════════════════════════════════════════
    def _plot_boxplot(self, ig, meg, ui, sp):
        cp = self._CP
        col_map    = {"IG": cp["cyan"],       "MEG": cp["teal"]}
        med_map    = {"IG": cp["median_ig"],  "MEG": cp["median_meg"]}

        datasets, labels, colors, med_cols = [], [], [], []
        for df2, lbl in [(ig,"IG"),(meg,"MEG")]:
            if df2.empty or "representative_transcript_length" not in df2.columns: continue
            vals = df2["representative_transcript_length"].dropna().values
            vals = vals[vals > 0]
            if len(vals) < 5: continue
            datasets.append(vals); labels.append(lbl)
            colors.append(col_map[lbl]); med_cols.append(med_map[lbl])

        fig, ax = plt.subplots(figsize=(14, 6.5), facecolor=cp["bg"])
        fig.subplots_adjust(left=0.11, right=0.97, top=0.87, bottom=0.12)
        ax.set_facecolor(cp["panel"])

        if not datasets:
            ax.text(0.5,0.5,"No data available",ha="center",va="center",
                    transform=ax.transAxes,color=cp["txt_d"],fontsize=12)
            return fig

        positions = list(range(1, len(datasets)+1))
        W = self._get_vp("box_width")

        # Capa de glow: sombra difusa detrás de cada caja
        for pos, col in zip(positions, colors):
            for a, sc in [(0.06, 1.55),(0.10, 1.25)]:
                ax.bar(pos, ax.get_ylim()[1] if ax.get_ylim()[1]>0 else 1,
                       width=W*sc, color=col, alpha=a, zorder=1,
                       bottom=ax.get_ylim()[0] if ax.get_ylim()[0]<0 else 0)

        bp = ax.boxplot(datasets, positions=positions,
                        patch_artist=True, widths=W,
                        showfliers=self._get_vp("box_show_fliers"),
                        whis=self._get_vp("box_whiskers"),
                        medianprops=dict(color="#ffffff", linewidth=2.8,
                                         solid_capstyle="round"),
                        whiskerprops=dict(color=cp["txt"], linewidth=1.3,
                                          linestyle=(0,(4,2))),
                        capprops=dict(color=cp["txt"], linewidth=2.0),
                        flierprops=dict(marker="o", markersize=4,
                                        markeredgewidth=0.6, alpha=0.55,
                                        linestyle="none"))

        for patch, col, mcol, flier in zip(bp["boxes"], colors, med_cols, bp["fliers"]):
            patch.set_facecolor(col)
            patch.set_alpha(0.82)
            patch.set_edgecolor(col)
            patch.set_linewidth(0)
            flier.set_markeredgecolor(col)
            flier.set_markerfacecolor(_blend(col, 0.25, cp["bg"]))

        # Franja de color en fondo por cada clase
        for pos, col in zip(positions, colors):
            ax.axvspan(pos - W*0.90, pos + W*0.90,
                       color=col, alpha=0.06, zorder=0, lw=0)

        # Jitter
        if self._get_vp("box_show_jitter"):
            _jw = self._get_vp("box_jitter_width")
            _jp = self._get_vp("box_jitter_points")
            for vals, pos, col in zip(datasets, positions, colors):
                rng = np.random.default_rng(7+pos)
                sample = rng.choice(vals, min(len(vals), _jp), replace=False)
                jitter = rng.uniform(-_jw, _jw, len(sample))
                ax.scatter(np.full_like(sample, pos, dtype=float)+jitter,
                           sample, s=3, color=col, alpha=0.28,
                           linewidths=0, zorder=5)

        # Anotaciones enriquecidas
        if self._get_vp("disp_show_annotations"):
            for vals, pos, col in zip(datasets, positions, colors):
                med = np.median(vals)
                q1, q3 = np.percentile(vals, [25, 75])
                ymax = np.percentile(vals, 99)
                ax.annotate(
                    ("n = {:,}\nmed = {:.1f} kb\nIQR  {:.1f}–{:.1f} kb".format(len(vals), med/1e3, q1/1e3, q3/1e3)),
                    xy=(pos, ymax), xytext=(pos, ymax*1.04),
                    ha="center", va="bottom", fontsize=8,
                    color=col, fontweight="bold",
                    bbox=dict(boxstyle="round,pad=0.35", fc=cp["panel2"],
                              ec=col, lw=1.2, alpha=0.95))

        # Etiquetas de eje X coloreadas por clase
        ax.set_xticks(positions)
        lbl_colors = [col_map.get(l, cp["txt"]) for l in labels]
        ax.set_xticklabels(labels, fontsize=13, fontweight="bold", color=cp["txt"])
        for tick_lbl, col in zip(ax.get_xticklabels(), lbl_colors):
            tick_lbl.set_color(col)

        ax.set_xlabel("Gene class", labelpad=10, fontsize=10, color=cp["gold"])
        ax.set_ylabel("Representative transcript length (nt)", labelpad=10, fontsize=10)
        ax.set_title(f"Boxplot — IG vs MEG  ·  {sp}",
                     pad=14, fontsize=13, fontweight="bold", color=cp["amber"])
        ax.yaxis.set_major_formatter(
            mticker.FuncFormatter(lambda x,_: f"{x/1e6:.1f} M" if x>=1e6
                                  else f"{x/1e3:.0f} k" if x>=1e3 else f"{int(x)}"))
        ax.tick_params(axis="y", labelsize=9, labelcolor=cp["gold"])
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0, alpha=1.0)
        ax.spines["bottom"].set_color(cp["bd"]); ax.spines["bottom"].set_linewidth(1.2)
        ax.spines["left"].set_color(cp["bd"]);   ax.spines["left"].set_linewidth(1.2)
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  CHROMOSOME DISTRIBUTION — barras agrupadas IG / MEG por cromosoma
    # ══════════════════════════════════════════════════════════════════════════
    def _plot_chrom_dist(self, ig, meg, ui, sp):
        cp = self._CP
        def _chr_sort(c):
            try:    return (0, int(c))
            except: return (1, c)

        all_c = sorted(set(
            (ig["chrom"].dropna().tolist() if not ig.empty else []) +
            (meg["chrom"].dropna().tolist() if not meg.empty else [])),
            key=_chr_sort)
        if not all_c:
            fig, ax = plt.subplots(figsize=(14, 6), facecolor=cp["bg"])
            ax.text(0.5,0.5,"No chromosomal data",ha="center",va="center",
                    transform=ax.transAxes, color=cp["txt_d"], fontsize=12)
            return fig

        ig_v  = np.array([(ig["chrom"]==c).sum() if not ig.empty else 0 for c in all_c], float)
        me_v  = np.array([(meg["chrom"]==c).sum() if not meg.empty else 0 for c in all_c], float)
        xi    = np.arange(len(all_c))
        w     = self._get_vp("chrom_bar_width")

        fig, ax = plt.subplots(figsize=(14, 6), facecolor=cp["bg"])
        fig.subplots_adjust(left=0.08, right=0.98, top=0.88, bottom=0.13)
        ax.set_facecolor(cp["panel"])

        # Franjas alternas de columna
        for i in range(len(all_c)):
            ax.axvspan(i-0.5, i+0.5,
                       color=cp["panel2"] if i%2==0 else cp["panel"],
                       alpha=0.30, zorder=0)

        # Barras IG (izquierda) y MEG (derecha) con glow
        for alpha, scale in [(0.04,1.8),(0.10,1.25),(0.88,1.0)]:
            ax.bar(xi-w/2, ig_v, w*scale, color=cp["cyan"],
                   alpha=alpha, linewidth=0, zorder=2)
            ax.bar(xi+w/2, me_v, w*scale, color=cp["teal"],
                   alpha=alpha, linewidth=0, zorder=2)

        # Etiquetas de valor encima de cada barra (sólo si valor > umbral)
        max_v = max(ig_v.max(), me_v.max(), 1)
        thr   = max_v * 0.03
        for idx,(iv,mv) in enumerate(zip(ig_v, me_v)):
            if iv > thr:
                ax.text(idx-w/2, iv+max_v*0.014, str(int(iv)),
                        ha="center", va="bottom", fontsize=7, fontweight="bold",
                        color=cp["cyan"], fontfamily="monospace")
            if mv > thr:
                ax.text(idx+w/2, mv+max_v*0.014, str(int(mv)),
                        ha="center", va="bottom", fontsize=7, fontweight="bold",
                        color=cp["teal"], fontfamily="monospace")

        ax.set_xticks(xi)
        ax.set_xticklabels(all_c, fontsize=7.5, fontfamily="monospace",
                           color=cp["txt"], rotation=0)
        ax.set_xlabel("Chromosome", labelpad=9, fontsize=10)
        ax.set_ylabel("Gene count",  labelpad=9, fontsize=10)
        ax.set_title(f"Chromosome Distribution — IG and MEG  ·  {sp}",
                     pad=12, fontsize=11, fontweight="bold")
        ax.yaxis.set_major_formatter(
            mticker.FuncFormatter(lambda x,_: f"{int(x):,}"))
        ax.tick_params(axis="y", labelsize=9, labelcolor=cp["gold"])
        ax.tick_params(axis="x", labelsize=8, labelcolor=cp["gold"], pad=3)
        ax.set_xlim(-0.65, len(all_c)-0.35)
        ax.set_ylim(0, max_v * 1.22)
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0, alpha=1.0)
        ax.spines["bottom"].set_color(cp["bd"])
        ax.spines["left"].set_color(cp["bd"])
        ax.legend(
            handles=[Patch(facecolor=cp["cyan"], label=f"IG  ({int(ig_v.sum()):,})"),
                     Patch(facecolor=cp["teal"], label=f"MEG ({int(me_v.sum()):,})")],
            facecolor=cp["panel2"], edgecolor=cp["bd"],
            labelcolor=cp["txt"], fontsize=9, loc="upper right",
            framealpha=0.92,
            prop={"family":"monospace","size":9,"weight":"bold"})
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  LENGTH HISTOGRAM — distribución de longitud de transcrito IG vs MEG
    # ══════════════════════════════════════════════════════════════════════════
    def _plot_length_histogram(self, ig, meg, ui, sp):
        cp = self._CP
        col_map = {"IG": cp["cyan"], "MEG": cp["teal"]}

        fig, ax = plt.subplots(figsize=(14, 6), facecolor=cp["bg"])
        fig.subplots_adjust(left=0.10, right=0.97, top=0.88, bottom=0.12)
        ax.set_facecolor(cp["panel"])

        plotted = False
        handles  = []
        for df2, lbl, col in [(ig,"IG",cp["cyan"]),(meg,"MEG",cp["teal"])]:
            if df2.empty or "representative_transcript_length" not in df2.columns:
                continue
            vals = df2["representative_transcript_length"].dropna().values
            vals = vals[vals > 0]
            if len(vals) < 5: continue

            _bins = self._get_vp("hist_bins")
            _halpha = self._get_vp("hist_alpha")
            n, bins, patches = ax.hist(vals, bins=_bins, alpha=_halpha,
                                       color=col, edgecolor="none",
                                       label=f"{lbl}  (n={len(vals):,})",
                                       zorder=2)
            # Borde glow sobre el histograma
            ax.hist(vals, bins=bins, histtype="step",
                    color=col, linewidth=1.2, alpha=0.80, zorder=3)
            # Línea vertical de mediana
            med = np.median(vals)
            ax.axvline(med, color=col, lw=1.4, linestyle="--", alpha=0.85,
                       zorder=4)
            ax.text(med, ax.get_ylim()[1]*0.98 if ax.get_ylim()[1]>0 else 0,
                    f" {lbl} med\n {med/1e3:.1f} kb",
                    va="top", ha="left", fontsize=7.5,
                    fontfamily="monospace", color=col,
                    bbox=dict(boxstyle="round,pad=0.20",
                              fc=cp["panel2"], ec=col, lw=0.7))
            handles.append(Patch(facecolor=col, alpha=0.55,
                                 edgecolor=col, label=f"{lbl}  (n={len(vals):,})"))
            plotted = True

        if not plotted:
            ax.text(0.5, 0.5, "No data available", ha="center", va="center",
                    transform=ax.transAxes, color=cp["txt_d"], fontsize=12)
            return fig

        ax.set_xlabel("Representative transcript length (nt)",
                      labelpad=9, fontsize=10)
        ax.set_ylabel("Gene count", labelpad=9, fontsize=10)
        ax.set_title(f"Transcript Length Histogram — IG vs MEG  ·  {sp}",
                     pad=12, fontsize=11, fontweight="bold")
        ax.xaxis.set_major_formatter(
            mticker.FuncFormatter(lambda x,_: f"{x/1e6:.1f}M" if x>=1e6
                                  else f"{x/1e3:.0f}k" if x>=1e3 else f"{int(x)}"))
        ax.yaxis.set_major_formatter(
            mticker.FuncFormatter(lambda x,_: f"{int(x):,}"))
        ax.tick_params(axis="both", labelsize=9, labelcolor=cp["gold"])
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0, alpha=1.0)
        ax.spines["bottom"].set_color(cp["bd"])
        ax.spines["left"].set_color(cp["bd"])
        ax.legend(handles=handles,
                  facecolor=cp["panel2"], edgecolor=cp["bd"],
                  labelcolor=cp["txt"], fontsize=9, loc="upper right",
                  framealpha=0.92,
                  prop={"family":"monospace","size":9,"weight":"bold"})
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  BOXPLOT LOG-SCALE — IG vs MEG
    # ══════════════════════════════════════════════════════════════════════════
    def _plot_boxplot_log(self, ig, meg, ui, sp):
        cp = self._CP
        col_map  = {"IG": cp["cyan"], "MEG": cp["teal"]}
        med_map  = {"IG": cp["median_ig"], "MEG": cp["median_meg"]}
        datasets, labels, colors = [], [], []
        for df2, lbl in [(ig,"IG"),(meg,"MEG")]:
            if df2.empty or "representative_transcript_length" not in df2.columns: continue
            vals = df2["representative_transcript_length"].dropna().values
            vals = vals[vals > 0]
            if len(vals) < 5: continue
            datasets.append(vals); labels.append(lbl); colors.append(col_map[lbl])
        fig, ax = plt.subplots(figsize=(14, 6), facecolor=cp["bg"])
        fig.subplots_adjust(left=0.10, right=0.97, top=0.88, bottom=0.12)
        ax.set_facecolor(cp["panel"])
        if not datasets:
            ax.text(0.5,0.5,"No data available",ha="center",va="center",
                    transform=ax.transAxes,color=cp["txt_d"],fontsize=12)
            return fig
        positions = list(range(1, len(datasets)+1))
        bp = ax.boxplot(datasets, positions=positions,
                        patch_artist=True, widths=self._get_vp("box_width"),
                        showfliers=self._get_vp("box_show_fliers"),
                        whis=self._get_vp("box_whiskers"),
                        medianprops=dict(color=cp["amber"],linewidth=2.0),
                        whiskerprops=dict(color=cp["bd"],linewidth=1.2),
                        capprops=dict(color=cp["bd"],linewidth=1.8),
                        flierprops=dict(marker="o",markersize=3,
                                        markeredgewidth=0.4,alpha=0.55))
        for patch, col, flier in zip(bp["boxes"], colors, bp["fliers"]):
            patch.set_facecolor(_blend(col, 0.30, cp["panel"]))
            patch.set_edgecolor(col)
            patch.set_linewidth(1.5)
            flier.set_markeredgecolor(col)
            flier.set_markerfacecolor("none")
        ax.set_yscale("log")
        if self._get_vp("box_show_jitter"):
            _jw = self._get_vp("box_jitter_width")
            _jp = self._get_vp("box_jitter_points")
            for vals, pos, col in zip(datasets, positions, colors):
                rng = np.random.default_rng(7+pos)
                sample = rng.choice(vals, min(len(vals), _jp), replace=False)
                jitter = rng.uniform(-_jw, _jw, len(sample))
                ax.scatter(np.full_like(sample, pos, dtype=float)+jitter,
                           sample, s=2.5, color=col, alpha=0.30,
                           linewidths=0, zorder=4)
        for vals, pos, col in zip(datasets, positions, colors):
            med = np.median(vals)
            q1, q3 = np.percentile(vals, [25, 75])
            ymax = np.percentile(vals, 99)
            ax.annotate(
                f"n={len(vals):,}  med={med/1e3:.1f} kb\nIQR={q1/1e3:.1f}–{q3/1e3:.1f} kb",
                xy=(pos, ymax), xytext=(pos, ymax*1.5),
                ha="center", va="bottom", fontsize=7.5,
                fontfamily="monospace", color=col, fontweight="bold",
                bbox=dict(boxstyle="round,pad=0.25", fc=cp["panel2"],
                          ec=col, lw=0.8))
        ax.set_xticks(positions)
        ax.set_xticklabels(labels, fontsize=13, fontweight="bold", color=cp["txt"])
        ax.set_xlabel("Gene class", labelpad=9, fontsize=10)
        ax.set_ylabel("Representative transcript length (nt, log scale)",
                      labelpad=9, fontsize=10)
        ax.set_title(f"Boxplot (log scale) — IG vs MEG  ·  {sp}",
                     pad=12, fontsize=11, fontweight="bold")
        ax.tick_params(axis="y", labelsize=9, labelcolor=cp["gold"])
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0, alpha=1.0)
        ax.spines["bottom"].set_color(cp["bd"])
        ax.spines["left"].set_color(cp["bd"])
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  VIOLIN LOG-SCALE — IG vs MEG
    # ══════════════════════════════════════════════════════════════════════════
    def _plot_violin_log(self, ig, meg, ui, sp):
        cp = self._CP
        col_map  = {"IG": cp["cyan"], "MEG": cp["teal"]}
        med_map  = {"IG": cp["median_ig"], "MEG": cp["median_meg"]}
        datasets, labels, colors = [], [], []
        for df2, lbl in [(ig,"IG"),(meg,"MEG")]:
            if df2.empty or "representative_transcript_length" not in df2.columns: continue
            vals = df2["representative_transcript_length"].dropna().values
            vals = vals[vals > 0]
            if len(vals) < 5: continue
            datasets.append(vals); labels.append(lbl); colors.append(col_map[lbl])
        fig, ax = plt.subplots(figsize=(14, 6), facecolor=cp["bg"])
        fig.subplots_adjust(left=0.10, right=0.97, top=0.88, bottom=0.12)
        ax.set_facecolor(cp["panel"])
        if not datasets:
            ax.text(0.5,0.5,"No data available",ha="center",va="center",
                    transform=ax.transAxes,color=cp["txt_d"],fontsize=12)
            return fig
        positions = list(range(1, len(datasets)+1))
        vp = ax.violinplot(datasets, positions=positions,
                           showmedians=True, showextrema=True,
                           widths=self._get_vp("vln_width"))
        for i, (body, col) in enumerate(zip(vp["bodies"], colors)):
            body.set_facecolor(col); body.set_edgecolor(col)
            body.set_alpha(0.55); body.set_linewidth(1.5)
        for part in ("cmedians","cmaxes","cmins","cbars"):
            if part in vp:
                vp[part].set_color(cp["amber"])
                vp[part].set_linewidth(1.6)
                vp[part].set_alpha(0.90)
        ax.set_yscale("log")
        if self._get_vp("vln_show_jitter"):
            _jw = self._get_vp("vln_jitter_width")
            _jp = self._get_vp("vln_jitter_points")
            for i,(vals,pos,col) in enumerate(zip(datasets,positions,colors)):
                rng = np.random.default_rng(42+i)
                sample = rng.choice(vals, min(len(vals),_jp), replace=False)
                jitter = rng.uniform(-_jw, _jw, len(sample))
                ax.scatter(np.full_like(sample, pos, dtype=float)+jitter,
                           sample, s=3, color=col, alpha=0.35,
                           linewidths=0, zorder=3)
        for vals, pos, col, lbl in zip(datasets, positions, colors, labels):
            med = np.median(vals)
            ymax = np.percentile(vals, 99)
            ax.annotate(f"n={len(vals):,}\nmedian={med/1e3:.1f} kb",
                        xy=(pos, ymax), xytext=(pos, ymax*1.5),
                        ha="center", va="bottom", fontsize=8,
                        fontfamily="monospace", color=col, fontweight="bold",
                        bbox=dict(boxstyle="round,pad=0.25", fc=cp["panel2"],
                                  ec=col, lw=0.8))
        ax.set_xticks(positions)
        ax.set_xticklabels(labels, fontsize=13, fontweight="bold", color=cp["txt"])
        ax.set_xlabel("Gene class", labelpad=9, fontsize=10)
        ax.set_ylabel("Representative transcript length (nt, log scale)",
                      labelpad=9, fontsize=10)
        ax.set_title(f"Violin Plot (log scale) — IG vs MEG  ·  {sp}",
                     pad=12, fontsize=11, fontweight="bold")
        ax.tick_params(axis="y", labelsize=9, labelcolor=cp["gold"])
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0, alpha=1.0)
        ax.spines["bottom"].set_color(cp["bd"])
        ax.spines["left"].set_color(cp["bd"])
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  LENGTH HISTOGRAM LOG-SCALE — IG vs MEG
    # ══════════════════════════════════════════════════════════════════════════
    def _plot_length_histogram_log(self, ig, meg, ui, sp):
        cp = self._CP
        fig, ax = plt.subplots(figsize=(14, 6), facecolor=cp["bg"])
        fig.subplots_adjust(left=0.10, right=0.97, top=0.88, bottom=0.12)
        ax.set_facecolor(cp["panel"])
        plotted = False; handles = []
        for df2, lbl, col in [(ig,"IG",cp["cyan"]),(meg,"MEG",cp["teal"])]:
            if df2.empty or "representative_transcript_length" not in df2.columns:
                continue
            vals = df2["representative_transcript_length"].dropna().values
            vals = vals[vals > 0] + 1
            if len(vals) < 5: continue
            bins = np.logspace(np.log10(vals.min()), np.log10(vals.max()), 61)
            n, _bins, patches = ax.hist(vals, bins=bins, alpha=0.55,
                                        color=col, edgecolor="none",
                                        label=f"{lbl}  (n={len(vals):,})",
                                        zorder=2)
            ax.hist(vals, bins=_bins, histtype="step",
                    color=col, linewidth=1.2, alpha=0.80, zorder=3)
            med = np.median(vals)
            ax.axvline(med, color=col, lw=1.4, linestyle="--", alpha=0.85, zorder=4)
            ax.text(med*1.1, ax.get_ylim()[1]*0.90 if ax.get_ylim()[1]>0 else 0,
                    f" {lbl} med\n {med/1e3:.1f} kb",
                    va="top", ha="left", fontsize=7.5,
                    fontfamily="monospace", color=col,
                    bbox=dict(boxstyle="round,pad=0.20",
                              fc=cp["panel2"], ec=col, lw=0.7))
            handles.append(Patch(facecolor=col, alpha=0.55,
                                 edgecolor=col, label=f"{lbl}  (n={len(vals):,})"))
            plotted = True
        if not plotted:
            ax.text(0.5, 0.5, "No data available", ha="center", va="center",
                    transform=ax.transAxes, color=cp["txt_d"], fontsize=12)
            return fig
        ax.set_xscale("log")
        ax.set_xlabel("Representative transcript length (nt, log scale)",
                      labelpad=9, fontsize=10)
        ax.set_ylabel("Gene count", labelpad=9, fontsize=10)
        ax.set_title(f"Transcript Length Histogram (log scale) — IG vs MEG  ·  {sp}",
                     pad=12, fontsize=11, fontweight="bold")
        ax.yaxis.set_major_formatter(
            mticker.FuncFormatter(lambda x,_: f"{int(x):,}"))
        ax.tick_params(axis="both", labelsize=9, labelcolor=cp["gold"])
        ax.grid(axis="y", color=cp["bd2"], linewidth=1.0, alpha=1.0)
        ax.spines["bottom"].set_color(cp["bd"])
        ax.spines["left"].set_color(cp["bd"])
        ax.legend(handles=handles,
                  facecolor=cp["panel2"], edgecolor=cp["bd"],
                  labelcolor=cp["txt"], fontsize=9, loc="upper right",
                  framealpha=0.92,
                  prop={"family":"monospace","size":9,"weight":"bold"})
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  CHROMOSOMAL ENRICHMENT — per-chromosome IG enrichment in GUI
    # ══════════════════════════════════════════════════════════════════════════
    def _plot_enrichment_gui(self, enrichment_df, gene_df, chrom, sp,
                             fdr_threshold=None):
        cp = self._CP
        fig, ax = plt.subplots(figsize=(14, 4.5), facecolor=cp["bg"])
        fig.subplots_adjust(left=0.06, right=0.97, top=0.86, bottom=0.16)
        ax.set_facecolor(cp["panel"])

        if enrichment_df.empty or gene_df.empty:
            ax.text(0.5, 0.5,
                    "No enrichment data available.\n"
                    "Enable 'Chromosomal Enrichment' in CONFIG and run the pipeline.",
                    ha="center", va="center", transform=ax.transAxes,
                    color=cp["txt_d"], fontsize=11, fontfamily="monospace")
            ax.set_title(f"Chromosomal Enrichment — Chr {chrom}  ·  {sp}",
                         pad=12, fontsize=11, fontweight="bold")
            return fig

        gene_df = gene_df.copy()
        gene_df["gene_start"] = pd.to_numeric(gene_df["gene_start"], errors="coerce")
        gene_df["gene_end"]   = pd.to_numeric(gene_df["gene_end"],   errors="coerce")

        sub       = enrichment_df[enrichment_df["chrom"] == chrom].copy()
        genes_chr = gene_df[gene_df["chrom"] == chrom].copy()

        if sub.empty and genes_chr.empty:
            ax.text(0.5, 0.5, f"No data for chromosome {chrom}",
                    ha="center", va="center", transform=ax.transAxes,
                    color=cp["txt_d"], fontsize=11, fontfamily="monospace")
            ax.set_title(f"Chromosomal Enrichment — Chr {chrom}  ·  {sp}",
                         pad=12, fontsize=11, fontweight="bold")
            return fig

        _fdr = fdr_threshold if fdr_threshold is not None else self._get_vp("enr_fdr_threshold")
        ig_genes = genes_chr[genes_chr["class_label"] == "IG"].copy()
        enriched = sub[sub["fdr_bh"] < _fdr].copy() if not sub.empty else pd.DataFrame()

        # ── Enriched windows (purple highlights) ─────────────────────────────
        _ha = self._get_vp("enr_highlight_alpha")
        for _, row in enriched.iterrows():
            ax.axvspan(row["window_start"], row["window_end"],
                       alpha=_ha, color=cp["violet"],
                       zorder=1)

        # ── IG gene positions ────────────────────────────────────────────────
        _ms = self._get_vp("enr_marker_size")
        if not ig_genes.empty:
            ax.scatter(ig_genes["gene_start"],
                       np.ones(len(ig_genes)),
                       s=_ms, color=cp["cyan"], marker="o",
                       edgecolors=_blend(cp["cyan"], 0.5, "#ffffff"), linewidths=0.8,
                       label="IG genes", zorder=3)

        # ── Stats annotation ────────────────────────────────────────────────
        n_ig = len(ig_genes)
        n_enr = len(enriched)
        n_genes_chr = len(genes_chr)
        stats_txt = (f"IG genes: {n_ig}  |  Total genes: {n_genes_chr}  |  "
                     f"Enriched windows: {n_enr}")
        ax.text(0.02, 0.92, stats_txt,
                transform=ax.transAxes, fontsize=8,
                fontfamily="monospace", color=cp["txt_d"],
                bbox=dict(boxstyle="round,pad=0.3",
                          fc=cp["panel2"], ec=cp["bd"],
                          lw=0.7))

        ax.set_yticks([])
        ax.set_xlabel("Genomic position (bp)", labelpad=9, fontsize=10)
        ax.xaxis.set_major_formatter(
            mticker.FuncFormatter(lambda x,_: f"{x/1e6:.1f} Mb" if x>=1e6
                                  else f"{x/1e3:.0f} kb" if x>=1e3
                                  else f"{int(x)}"))
        ax.tick_params(axis='x', labelsize=8.5, labelcolor=cp["txt"])
        ax.set_title(f"Chromosomal Enrichment — Chr {chrom}  ·  {sp}",
                     pad=12, fontsize=11, fontweight="bold")

        if not ig_genes.empty:
            legend_handles = [
                Line2D([0],[0], marker="o", color="none",
                       markerfacecolor=cp["cyan"],
                       markeredgecolor=_blend(cp["cyan"], 0.5, "#ffffff"),
                       markersize=7, label=f"IG genes ({n_ig})"),
            ]
            if n_enr > 0:
                legend_handles.append(
                    Patch(facecolor=cp["violet"], alpha=0.25,
                          edgecolor=cp["violet"],
                          label=f"Enriched windows ({n_enr})"))
            ax.legend(handles=legend_handles,
                      facecolor=cp["panel2"],
                      edgecolor=cp["bd"],
                      labelcolor=cp["txt"], fontsize=9,
                      loc="upper right", framealpha=0.92,
                      prop={"family":"monospace","size":9,"weight":"bold"})

        ax.spines["bottom"].set_color(cp["bd"])
        ax.spines["left"].set_color(cp["bd"])
        ax.grid(axis="x", alpha=0.45, color=cp["bd2"])
        return fig

    def _build_log_tab(self):
        tab = self._tab_log
        ctrl = tk.Frame(tab, bg=C["bg2"])
        ctrl.pack(fill="x", padx=8, pady=(8,0))
        tk.Frame(ctrl, bg=C["emerald"], width=4).pack(side="left", fill="y", pady=2)
        hud_label(ctrl, "Execution Log",
                  C["txt_dim"], size=10).pack(side="left", padx=(10,14))
        for label, color in [("OK",C["emerald"]),("WARN",C["amber"]),
                              ("ERR",C["red"]),("INFO",C["txt_dim"])]:
            pill = tk.Frame(ctrl, bg=_blend(color, 0.08, C["bg2"]),
                            highlightthickness=1,
                            highlightbackground=_ca(color,"55"))
            pill.pack(side="left", padx=(0,5))
            tk.Label(pill, text=f" {label} ",
                     bg=_blend(color, 0.08, C["bg2"]),
                     fg=color,
                     font=("Courier New",10,"bold"),
                     pady=3).pack()
        tk.Button(ctrl, text="  CLR  ", command=self._clear_log,
                  bg=C["panel2"], fg=C["txt_dim"],
                  activebackground=C["border_d"], activeforeground=C["txt"],
                  relief="flat", bd=0, cursor="hand2",
                  font=("Courier New",11,"bold"),
                  padx=8, pady=5).pack(side="right", padx=8)
        TechDivider(tab, color=C["emerald"], height=12).pack(
            fill="x", padx=8, pady=(4,4))
        log_frame = tk.Frame(tab, bg=C["bg"])
        log_frame.pack(fill="both", expand=True, padx=8, pady=(0,8))
        term_bar = tk.Frame(log_frame, bg="#1a1a1a", height=30)
        term_bar.pack(fill="x")
        term_bar.pack_propagate(False)
        for dot_col in [C["red"], C["amber"], C["emerald"]]:
            d = tk.Canvas(term_bar, width=12, height=12, bg="#1a1a1a",
                          highlightthickness=0)
            d.pack(side="left", padx=(8,0), pady=8)
            d.create_oval(1,1,13,13, fill=dot_col, outline="")
        tk.Label(term_bar, text="  IGFinder · Execution Terminal",
                 bg="#1a1a1a", fg="#555555",
                 font=("Courier New",11,"bold")).pack(side="left", padx=6)
        self._log_text = tk.Text(
            log_frame,
            bg="#000000",
            fg=C["txt"],
            font=("Courier New", 11),
            state="disabled", wrap="none", relief="flat",
            highlightthickness=1, highlightbackground=C["border"],
            padx=18, pady=12, spacing1=2, spacing3=2)
        vsb = ttk.Scrollbar(log_frame, command=self._log_text.yview)
        self._log_text.configure(yscrollcommand=vsb.set)
        vsb.pack(side="right", fill="y")
        self._log_text.pack(fill="both", expand=True)
        self._log_text.tag_configure("ok",
                                     foreground=C["emerald"],
                                     font=("Courier New",11,"bold"),
                                     background="#001a0a")
        self._log_text.tag_configure("warn",
                                     foreground=C["amber"],
                                     font=("Courier New",11),
                                     background="#1a1000")
        self._log_text.tag_configure("err",
                                     foreground=C["red"],
                                     font=("Courier New",11,"bold"),
                                     background="#1a0000")
        self._log_text.tag_configure("info",
                                     foreground="#88ddee",
                                     font=("Courier New",11))
        self._log_text.tag_configure("dim",
                                     foreground=C["txt_muted"],
                                     font=("Courier New",11))
        # ── Tag especial OMICS — fondo violeta oscuro, texto esmeralda ────
        self._log_text.tag_configure("omics",
                                     foreground=C["emerald"],
                                     font=("Courier New",11),
                                     background="#0d1a1a")
        self._log_text.tag_configure("omics_hdr",
                                     foreground=C["emerald"],
                                     font=("Courier New",11,"bold"),
                                     background="#001a12")
        self._log_text.tag_configure("omics_ok",
                                     foreground=C["cyan"],
                                     font=("Courier New",11,"bold"),
                                     background="#001a12")
        self._log_text.tag_configure("omics_warn",
                                     foreground=C["amber"],
                                     font=("Courier New",11),
                                     background="#1a1200")
        self._log_text.tag_configure("omics_err",
                                     foreground=C["red"],
                                     font=("Courier New",11,"bold"),
                                     background="#1a0000")

    def _clear_log(self):
        self._log_text.configure(state="normal")
        self._log_text.delete("1.0","end")
        self._log_text.configure(state="disabled")

    def _append_log(self, msg, tag="info"):
        ts = datetime.datetime.now().strftime("%H:%M:%S")
        # Main log tab
        self._log_text.configure(state="normal")
        self._log_text.insert("end", f"[{ts}]  {msg}\n", tag)
        self._log_text.see("end"); self._log_text.configure(state="disabled")
        # Monitor tab live feed
        try:
            self._monitor_log.configure(state="normal")
            self._monitor_log.insert("end", f"[{ts}]  {msg}\n", tag)
            # Keep last 120 lines
            lines = int(self._monitor_log.index("end-1c").split(".")[0])
            if lines > 120:
                self._monitor_log.delete("1.0", f"{lines-120}.0")
            self._monitor_log.see("end")
            self._monitor_log.configure(state="disabled")
        except AttributeError:
            pass

    def _animate_elite(self):
        v = 0.05
        if self._running:
            v = 0.5 + 0.4*math.sin(time.time()*3)
        elif self._results:
            v = 1.0
        self._elite.set_sys(v)
        self._sys_canvas.set_value(v)
        if self._results:
            total = (len(self._results.get("ig",[])) +
                     len(self._results.get("meg",[])) +
                     len(self._results.get("ui",[])))
            self._elite.set_ig( len(self._results.get("ig",[])) / max(total,1))
            self._elite.set_meg(len(self._results.get("meg",[])) / max(total,1))
            self._elite.set_seg(len(self._results.get("ui",[])) / max(total,1))
        self.after(100 if self._running else 300, self._animate_elite)

    def _browse_utr(self):
        fp = filedialog.askopenfilename(
            title="Select UTR file",
            filetypes=[("TSV / TXT","*.tsv *.txt"),("All","*.*")])
        if fp: self._var_utr.set(fp)

    def _browse_outdir(self):
        d = filedialog.askdirectory(title="Select output directory")
        if d: self._var_outdir.set(d)

    # ══════════════════════════════════════════════════════════════════════════

    def _refresh_plot_dropdown(self, res: dict):
        """
        Actualiza el OptionMenu de VISUALIZATION MODE con los cromosomas
        que realmente tienen datos de enrichment en el resultado actual.
        Si enrichment_df está vacío, usa chroms_done como fallback.
        """
        try:
            enr_df = res.get("enrichment_df", pd.DataFrame())
            if not enr_df.empty and "chrom" in enr_df.columns:
                chroms = sorted(
                    enr_df["chrom"].dropna().unique().tolist(),
                    key=natural_chrom_key)
            else:
                # Fallback: inferir cromosomas de los genes IG
                ig = res.get("ig", pd.DataFrame())
                chroms = sorted(
                    ig["chrom"].dropna().unique().tolist()
                    if not ig.empty and "chrom" in ig.columns else [],
                    key=natural_chrom_key)

            base_modes = [
                "Boxplot",
                "Boxplot (Log-scale)",
                "Violin Plot",
                "Violin Plot (Log-scale)",
                "Length Histogram",
                "Length Histogram (Log-scale)",
                "Chromosome Distribution",
                "── IG Enrichment per Chromosome ──",
            ]
            enr_modes = [f"IG Enrichment — Chr {c}" for c in chroms]

            # Añadir modos GO y Orthology solo si los datos están disponibles
            extra_modes: List[str] = []
            if self._results:
                if not self._results.get("func_enrichment_df",
                                         pd.DataFrame()).empty:
                    extra_modes.append("GO/KEGG Enrichment")
                if not self._results.get("orthology_matrix_df",
                                         pd.DataFrame()).empty:
                    extra_modes.append("Orthology Heatmap")

            all_modes  = base_modes + enr_modes + extra_modes

            # Reasignar menú al widget existente
            menu = self._plot_menu["menu"]
            menu.delete(0, "end")
            for m in all_modes:
                menu.add_command(
                    label=m,
                    command=lambda v=m: self._plot_var.set(v))

            # Si el modo actual ya no existe, resetear a Boxplot
            if self._plot_var.get() not in all_modes:
                self._plot_var.set("Boxplot")

            self._append_log(
                f"[Plots] Dropdown actualizado: {len(enr_modes)} "
                f"cromosomas disponibles para Enrichment", "info")
        except Exception as e:
            self._append_log(f"[Plots] refresh_dropdown error: {e}", "warn")

    # ══════════════════════════════════════════════════════════════════════════
    #  GUI PLOT — GO/KEGG FUNCTIONAL ENRICHMENT (dot-plot interactivo)
    # ══════════════════════════════════════════════════════════════════════════

    def _plot_go_enrichment_gui(self, func_df: pd.DataFrame, sp: str,
                                 top_n: int = 15):
        """
        Dot-plot de enriquecimiento funcional embebido en la pestaña OMICS.
        Usa la paleta oscura de IGFinder (bg=#1a1840) para coherencia visual.

        Eje X  : -log₁₀(FDR)  — punto más a la derecha = más significativo
        Eje Y  : términos funcionales (top_n por fuente, ordenados por significancia)
        Tamaño : intersection_size (genes IG en ese término)
        Color  : fuente (GO:BP=lila, GO:MF=rosa, GO:CC=esmeralda, KEGG=ámbar, REAC=orquídea)
        """
        # ── Paleta oscura ─────────────────────────────────────────────────────
        BG     = C["bg"]
        PANEL  = C["panel"]
        TXT    = C["txt_dim"]
        BORDER = C["border_dd"]
        GRID   = "rgba(123,104,200,.15)"
        TITLE  = C["lavender"]
        AXIS   = C["txt_muted"]
        _SRC   = {
            "GO:BP": C["cyan"],      # lila vibrante
            "GO:MF": C["teal"],      # rosa lavanda
            "GO:CC": C["emerald"],   # esmeralda suave
            "KEGG" : "#d97706",      # ámbar
            "REAC" : C["orchid"],    # orquídea
            "TF"   : C["lavender"],  # lavanda
            "HP"   : C["red"],       # rojo coral
        }

        if func_df is None or func_df.empty:
            fig, ax = plt.subplots(figsize=(10, 4), facecolor=BG)
            ax.set_facecolor(PANEL)
            ax.text(0.5, 0.5,
                    "⬡  No hay datos de enriquecimiento funcional.\n"
                    "   Haz clic en  ▶ RUN OMICS  para iniciar el análisis.",
                    ha="center", va="center", transform=ax.transAxes,
                    color=C["amber"], fontsize=11, fontfamily="monospace",
                    multialignment="center")
            ax.axis("off")
            for sp_ in ax.spines.values(): sp_.set_visible(False)
            return fig

        # ── Construir dataset del plot ────────────────────────────────────────
        frames = []
        for src, grp in func_df.groupby("source"):
            frames.append(grp.nsmallest(min(top_n, len(grp)), "fdr"))
        if not frames:
            fig, ax = plt.subplots(figsize=(10, 4), facecolor=BG)
            ax.text(0.5, 0.5, "No hay términos para mostrar con estos filtros.",
                    ha="center", va="center", transform=ax.transAxes,
                    color=C["amber"], fontsize=11)
            ax.axis("off")
            return fig

        plot_df = pd.concat(frames, ignore_index=True).copy()
        plot_df["-log10_fdr"] = -np.log10(
            plot_df["fdr"].clip(lower=1e-300))
        # Label: [FUENTE] nombre_término
        plot_df["label"] = plot_df.apply(
            lambda r: f"[{r['source']:<6s}]  {str(r['term_name'])[:52]}", axis=1)
        # Ordenar: más significativo abajo (primero en renderizar, queda arriba en Y)
        plot_df = plot_df.sort_values("-log10_fdr", ascending=True).reset_index(drop=True)

        # ── Figura (tamaño NATIVO grande — el viewer OMICS provee scroll/zoom) ─
        # Más espacio por fila y ancho generoso para que las etiquetas se
        # lean cómodamente. _OmicsScrollableCanvas permite scrollear y
        # hacer zoom sin compresión visual.
        fig_h = max(6.0, 0.38 * len(plot_df) + 2.5)
        fig_w = 14.0   # ancho generoso — habrá scroll horizontal si hace falta
        fig, ax = plt.subplots(figsize=(fig_w, fig_h), facecolor=BG, dpi=110)
        ax.set_facecolor(PANEL)

        # ── Bandas alternas de fondo para legibilidad ─────────────────────────
        for i in range(len(plot_df)):
            ax.axhspan(i - 0.5, i + 0.5,
                       color="#302c62" if i % 2 == 0 else PANEL,
                       zorder=0)

        # ── Línea de referencia FDR=0.05 ─────────────────────────────────────
        fdr_ref = -np.log10(0.05)
        max_x   = plot_df["-log10_fdr"].max()
        ax.axvline(fdr_ref, color=C["red"], lw=1.2, ls="--",
                   alpha=0.55, zorder=1)
        ax.text(fdr_ref + max_x * 0.01, len(plot_df) - 0.5,
                "FDR=0.05", color=C["red"], fontsize=7,
                fontfamily="monospace", va="top", alpha=0.8)

        # ── Dots con glow ─────────────────────────────────────────────────────
        for i, row in plot_df.iterrows():
            col  = _SRC.get(row["source"], C["cyan"])
            n_g  = max(0, int(row.get("intersection_size") or 0))
            size = max(35, min(450, n_g * 16))
            xval = float(row["-log10_fdr"])

            # Halo externo (glow)
            ax.scatter(xval, row["label"], s=size * 4.5,
                       color=col, alpha=0.10, zorder=2)
            ax.scatter(xval, row["label"], s=size * 2.0,
                       color=col, alpha=0.18, zorder=2)
            # Dot principal
            ax.scatter(xval, row["label"], s=size,
                       color=col, alpha=0.90,
                       edgecolors=C["border_d"], linewidths=0.5,
                       zorder=3)
            # Valor numérico junto al punto
            ax.text(xval + max_x * 0.012, row["label"],
                    f"{xval:.1f}", color=col, fontsize=7,
                    va="center", fontfamily="monospace", alpha=0.85)

        # ── Estilo de ejes ────────────────────────────────────────────────────
        for sp_ in ax.spines.values():
            sp_.set_color(BORDER)
        ax.tick_params(colors=AXIS, labelsize=8)
        ax.set_yticks(range(len(plot_df)))
        ax.set_yticklabels(plot_df["label"], fontsize=8,
                           fontfamily="monospace", color=TXT)
        ax.set_xlim(left=0)
        ax.set_xlabel("-log₁₀ (FDR adj. p-value)",
                      color=AXIS, fontsize=9, fontfamily="monospace")
        ax.grid(axis="x", color=BORDER, alpha=0.25, lw=0.5)

        # ── Título ────────────────────────────────────────────────────────────
        n_src = func_df["source"].nunique()
        ax.set_title(
            f"Functional Enrichment of Intronless Genes   ·   {sp.replace('_', ' ').title()}\n"
            f"{len(func_df):,} significant terms  (FDR < 0.05)  ·  "
            f"{n_src} source{'s' if n_src>1 else ''}  ·  g:Profiler",
            color=TITLE, fontsize=11, fontweight="bold",
            fontfamily="monospace", pad=12)

        # ── Leyenda de fuentes ────────────────────────────────────────────────
        patches = [Patch(facecolor=c, label=s, edgecolor=BORDER)
                   for s, c in _SRC.items()
                   if s in func_df["source"].values]
        if patches:
            leg = ax.legend(handles=patches, loc="lower right",
                            framealpha=0.7, fontsize=8,
                            facecolor=C["panel2"], edgecolor=C["border"],
                            labelcolor=TXT)

        plt.tight_layout(pad=1.5)
        return fig

    # ══════════════════════════════════════════════════════════════════════════
    #  GUI PLOT — ORTHOLOGY HEATMAP (Ensembl Compara)
    # ══════════════════════════════════════════════════════════════════════════

    # ══════════════════════════════════════════════════════════════════════════
    #  GUI PLOT — ORTHOLOGY (refactor modular: contexto + paneles A–F sueltos)
    #  Cada panel se puede dibujar de forma INDEPENDIENTE en su propia figura
    #  (sub-secciones sub-independientes) o combinarse en el dashboard 3×2.
    # ══════════════════════════════════════════════════════════════════════════

    # Metadatos de los 6 paneles de ortología — usados por la UI y el refresh.
    _ORTH_PANELS = [
        ("heatmap", "A", "Genes × Species Heatmap",
         "Ward-clustered conservation matrix", "orchid",   False),
        ("upset",   "B", "UpSet Co-occurrence Sets",
         "Top shared-ortholog species combinations", "cyan", False),
        ("family",  "C", "Conservation by IG Gene Family",
         "Per-family fraction with ortholog", "emerald",    False),
        ("violin",  "D", "Score Distribution per Species",
         "Violin + strip of per-gene scores", "blush",      False),
        ("radial",  "E", "Radial Conservation Map",
         "Polar mean conservation by species", "violet",    True),   # polar
        ("cdf",     "F", "Empirical CDF + Quartiles",
         "Cumulative distribution of gene scores", "amber",  False),
    ]

    def _orth_compute_context(self, matrix_df, summary, sp,
                              long_df=None, family_df=None):
        """
        Calcula TODOS los valores compartidos por los paneles A–F y arma la
        paleta. Devuelve un dict `ctx` que cada `_orth_draw_X(ax, ctx)`
        desempaqueta. Centralizar esto evita recomputar y mantiene los
        paneles perfectamente consistentes entre sí.
        """
        BG     = C["bg"]
        PANEL  = C["panel"]
        TXT    = C["txt_dim"]
        AX     = C["txt_muted"]
        BORDER = C["border_dd"]
        TITLE  = C["lavender"]
        ORCHID = C["orchid"]
        CYAN   = C["cyan"]
        TEAL   = C["teal"]
        AMBER  = "#d97706"
        EMERALD= C["emerald"]
        BLUSH  = C.get("blush",   "#f472b6")
        VIOLET = C.get("violet",  "#a78bfa")

        _LINEAGE_COLOR = {
            "homo_sapiens":        "#a78bfa",
            "pan_troglodytes":     "#8b5cf6",
            "gorilla_gorilla":     "#7c3aed",
            "macaca_mulatta":      "#6d28d9",
            "mus_musculus":        "#38bdf8",
            "rattus_norvegicus":   "#0ea5e9",
            "bos_taurus":          "#4ade80",
            "sus_scrofa":          "#22c55e",
            "equus_caballus":      "#16a34a",
            "ovis_aries":          "#15803d",
            "canis_lupus_familiaris": "#fb923c",
            "felis_catus":         "#f97316",
            "gallus_gallus":       "#facc15",
            "anolis_carolinensis": "#f87171",
            "xenopus_tropicalis":  "#ef4444",
            "danio_rerio":         "#34d399",
            "oryzias_latipes":     "#10b981",
            "takifugu_rubripes":   "#059669",
            "tetraodon_nigroviridis": "#047857",
            "drosophila_melanogaster": "#c084fc",
            "caenorhabditis_elegans":  "#a855f7",
            "saccharomyces_cerevisiae": "#94a3b8",
            "arabidopsis_thaliana":     "#84cc16",
            "monodelphis_domestica":   "#fbbf24",
            "ornithorhynchus_anatinus": "#facc15",
        }
        def _sp_col(sp_name): return _LINEAGE_COLOR.get(sp_name, ORCHID)

        if family_df is None or (hasattr(family_df, "empty") and family_df.empty):
            family_df = (summary or {}).get("family_conservation_df", pd.DataFrame())

        arr      = matrix_df.values.astype("float32")
        n_genes  = len(matrix_df)
        n_sp     = len(matrix_df.columns)
        row_mean = arr.mean(axis=1)
        col_mean = arr.mean(axis=0)
        sp_order = matrix_df.mean(axis=0).sort_values(ascending=False).index.tolist()
        mat_s    = matrix_df[sp_order]
        mean_c   = (summary or {}).get("mean_conservation",  float(col_mean.mean()))
        n_any    = (summary or {}).get("n_with_any_ortholog", int((row_mean > 0).sum()))
        n_full   = (summary or {}).get("n_fully_conserved",  int((row_mean >= 0.9).sum()))
        bar_colors = [_sp_col(s) for s in sp_order]

        return dict(
            BG=BG, PANEL=PANEL, TXT=TXT, AX=AX, BORDER=BORDER, TITLE=TITLE,
            ORCHID=ORCHID, CYAN=CYAN, TEAL=TEAL, AMBER=AMBER, EMERALD=EMERALD,
            BLUSH=BLUSH, VIOLET=VIOLET, _sp_col=_sp_col,
            matrix_df=matrix_df, summary=summary or {}, sp=sp,
            long_df=long_df, family_df=family_df,
            arr=arr, n_genes=n_genes, n_sp=n_sp, row_mean=row_mean,
            col_mean=col_mean, sp_order=sp_order, mat_s=mat_s,
            mean_c=mean_c, n_any=n_any, n_full=n_full, bar_colors=bar_colors,
        )

    # ── PANEL A · Heatmap ────────────────────────────────────────────────────
    def _orth_draw_A(self, ax, ctx, standalone=False):
        import matplotlib.colors as mcolors
        from matplotlib.patches import Rectangle
        (BG, PANEL, TXT, AX, BORDER, ORCHID, CYAN, TEAL) = (
            ctx["BG"], ctx["PANEL"], ctx["TXT"], ctx["AX"], ctx["BORDER"],
            ctx["ORCHID"], ctx["CYAN"], ctx["TEAL"])
        _sp_col = ctx["_sp_col"]
        n_sp, sp_order, mat_s, row_mean = (
            ctx["n_sp"], ctx["sp_order"], ctx["mat_s"], ctx["row_mean"])

        ax.set_facecolor(PANEL)
        for s in ax.spines.values(): s.set_color(BORDER)
        ax.tick_params(colors=AX, labelsize=8)

        MAX_HMAP = 60
        if ctx["n_genes"] > MAX_HMAP:
            top_idx = np.argsort(row_mean)[::-1][:MAX_HMAP]
            hmat    = mat_s.iloc[top_idx]
        else:
            hmat = mat_s
        try:
            from scipy.cluster.hierarchy import linkage, leaves_list
            from scipy.spatial.distance import pdist
            d   = pdist(hmat.values.astype(float), metric="euclidean")
            lnk = linkage(d, method="ward")
            hmat = hmat.iloc[leaves_list(lnk)]
        except Exception:
            pass
        try:
            cmap = mcolors.LinearSegmentedColormap.from_list(
                "IG_orth_w",
                [(0.00, mcolors.to_rgba(PANEL)),
                 (0.05, mcolors.to_rgba(_ca(TEAL,   "55"))),
                 (0.35, mcolors.to_rgba(TEAL)),
                 (0.65, mcolors.to_rgba(CYAN)),
                 (1.00, mcolors.to_rgba(C["lavender"]))])
        except Exception:
            cmap = plt.cm.viridis

        nh = len(hmat)
        im = ax.imshow(hmat.values.astype(float),
                       aspect="auto", cmap=cmap,
                       vmin=0, vmax=1, interpolation="nearest")
        ax.set_xticks(range(n_sp))
        ax.set_xticklabels(
            [s.replace("_", "\n") for s in sp_order],
            fontsize=6.5, color=TXT, fontfamily="monospace", ha="center")
        for i, sp_n in enumerate(sp_order):
            ax.add_patch(Rectangle(
                (i - 0.5, -1.5), 1, 0.7,
                facecolor=_sp_col(sp_n), edgecolor="none",
                clip_on=False, zorder=5))
        if nh <= 50:
            ax.set_yticks(range(nh))
            ax.set_yticklabels(hmat.index.tolist(),
                               fontsize=5.5, color=AX, fontfamily="monospace")
        else:
            ax.set_yticks([])
            ax.set_ylabel(f"Top {nh} IG genes", color=AX, fontsize=8)
        for xi in range(n_sp - 1):
            ax.axvline(xi + 0.5, color=BG, lw=0.5)

        cb = ax.figure.colorbar(im, ax=ax, fraction=0.022, pad=0.02,
                                orientation="vertical")
        cb.set_label("Conservation score", color=AX, fontsize=7)
        cb.ax.tick_params(colors=AX, labelsize=6.5)
        for s in cb.ax.spines.values(): s.set_color(BORDER)
        cb.set_ticks([0, 0.3, 0.6, 1.0])
        cb.set_ticklabels(["—", "paralog", "1:n", "1:1"], fontsize=6)
        ax.set_title(
            f"A  ·  Top {nh} Genes × Species Heatmap  (Ward-clustered, weighted)",
            color=ORCHID, fontsize=10, fontweight="bold",
            fontfamily="monospace", pad=10)

    # ── PANEL B · UpSet ──────────────────────────────────────────────────────
    def _orth_draw_B(self, ax, ctx, standalone=False):
        (BG, PANEL, TXT, AX, BORDER, CYAN) = (
            ctx["BG"], ctx["PANEL"], ctx["TXT"], ctx["AX"],
            ctx["BORDER"], ctx["CYAN"])
        _sp_col = ctx["_sp_col"]
        n_sp, sp_order, mat_s = ctx["n_sp"], ctx["sp_order"], ctx["mat_s"]

        ax.set_facecolor(PANEL)
        for s in ax.spines.values(): s.set_color(BORDER)
        ax.tick_params(colors=AX, labelsize=8)

        binmat = (mat_s.values >= 0.5).astype(int)
        TOP_SP = min(6, n_sp)
        fp = binmat[:, :TOP_SP]
        from collections import Counter
        fp_strings = ["".join(map(str, row)) for row in fp]
        fp_counter = Counter(fp_strings)
        top_sets = fp_counter.most_common(12)

        if not top_sets:
            ax.axis("off")
            ax.text(0.5, 0.5, "No data", ha="center", va="center",
                    transform=ax.transAxes, color=AX)
        else:
            n_sets = len(top_sets)
            n_top  = TOP_SP
            x = np.arange(n_sets)
            counts = [c for _, c in top_sets]
            ax.bar(x, counts, color=CYAN, alpha=0.85,
                   edgecolor=BG, linewidth=0.4, zorder=3)
            for i, c in enumerate(counts):
                ax.text(i, c + max(counts) * 0.02, f"{c}",
                        ha="center", va="bottom", fontsize=7,
                        color=TXT, fontfamily="monospace", fontweight="bold")
            ax.set_ylim(-(n_top + 1.5), max(counts) * 1.18)
            for set_idx, (fp_str, _) in enumerate(top_sets):
                for sp_idx, ch in enumerate(fp_str):
                    y_pos = -(sp_idx + 1)
                    if ch == "1":
                        ax.plot(set_idx, y_pos, "o",
                                color=_sp_col(sp_order[sp_idx]),
                                markersize=8, zorder=5)
                    else:
                        ax.plot(set_idx, y_pos, "o", color=BORDER,
                                markersize=4, alpha=0.4, zorder=4)
                present_idx = [i for i, ch in enumerate(fp_str) if ch == "1"]
                if len(present_idx) > 1:
                    ax.plot([set_idx, set_idx],
                            [-(min(present_idx) + 1), -(max(present_idx) + 1)],
                            color=_ca(CYAN, "aa"), lw=1.5, zorder=4)
            ax.set_yticks([-(i + 1) for i in range(n_top)] +
                          list(np.linspace(0, max(counts), 5)))
            sp_labels = [s.replace("_", "\n")[:14] for s in sp_order[:n_top]]
            ax.set_yticklabels(
                sp_labels + [f"{int(v)}" for v in np.linspace(0, max(counts), 5)],
                fontsize=6, color=AX, fontfamily="monospace")
            ax.axhline(0, color=BORDER, lw=0.7)
            ax.set_xticks(x)
            ax.set_xticklabels([f"S{i+1}" for i in range(n_sets)],
                               fontsize=6.5, color=AX, fontfamily="monospace")
            ax.set_xlim(-0.6, n_sets - 0.4)
        ax.set_title("B  ·  UpSet — Top Species Co-occurrence Sets",
                     color=CYAN, fontsize=10, fontweight="bold",
                     fontfamily="monospace", pad=10)

    # ── PANEL C · Family bars ──────────────────────────────────────────────
    def _orth_draw_C(self, ax, ctx, standalone=False):
        (BG, PANEL, TXT, AX, BORDER, CYAN, TEAL, AMBER, EMERALD) = (
            ctx["BG"], ctx["PANEL"], ctx["TXT"], ctx["AX"], ctx["BORDER"],
            ctx["CYAN"], ctx["TEAL"], ctx["AMBER"], ctx["EMERALD"])
        sp_order = ctx["sp_order"]
        long_df, family_df, summary = ctx["long_df"], ctx["family_df"], ctx["summary"]

        ax.set_facecolor(PANEL)
        for s in ax.spines.values(): s.set_color(BORDER)
        ax.tick_params(colors=AX, labelsize=8)

        if family_df is None or family_df.empty:
            family_df = summary.get("family_conservation_df", pd.DataFrame())

        if (family_df is not None and not family_df.empty and
                long_df is not None and not long_df.empty):
            import re as _re
            _FAM_RE = _re.compile(
                r"^(IGH[VDJACE]|IGL[VJCE]|IGK[VJC]|IG[HJKL][A-Z]?)", _re.IGNORECASE)
            df = long_df.copy()
            type_totals = df.groupby("homology_type")["source_gene_id"].nunique()
            type_totals = type_totals.sort_values(ascending=False)
            htypes = type_totals.index.tolist()[:5]
            HTYPE_COLORS = {
                "ortholog_one2one":       C["lavender"],
                "ortholog_one2many":      CYAN,
                "ortholog_many2many":     TEAL,
                "within_species_paralog": AMBER,
                "other_paralog":          C["amber"] if "amber" in C else AMBER,
            }
            sp_in_fam = [s for s in sp_order if s in family_df.columns]
            fam_plot  = family_df[sp_in_fam] if sp_in_fam else family_df
            fam_names = fam_plot.index.tolist()
            nf = len(fam_names)
            ns_f = len(fam_plot.columns)
            x_f = np.arange(ns_f)
            _FAM_COLORS = {
                "IGHV": "#a78bfa", "IGHD": "#8b5cf6",
                "IGHJ": "#7c3aed", "IGHA": "#6d28d9",
                "IGHG": "#38bdf8", "IGHM": "#0ea5e9",
                "IGLV": "#4ade80", "IGLJ": "#22c55e", "IGLC": "#16a34a",
                "IGKV": "#fb923c", "IGKJ": "#f97316", "IGKC": "#ea580c",
                "OTHER": AX,
            }
            width = max(0.7 / nf, 0.05)
            offsets = np.linspace(-(nf-1)*width/2, (nf-1)*width/2, nf)
            for fname, offset in zip(fam_names, offsets):
                vals = fam_plot.loc[fname].values
                fcolor = _FAM_COLORS.get(fname[:4].upper(),
                         _FAM_COLORS.get(fname[:3].upper(), AX))
                ax.bar(x_f + offset, vals, width=width * 0.9,
                       color=fcolor, alpha=0.88, edgecolor=BG, linewidth=0.4,
                       label=fname, zorder=3)
            ax.set_xticks(x_f)
            ax.set_xticklabels(
                [s.replace("_", "\n") for s in fam_plot.columns],
                fontsize=6.5, color=TXT, fontfamily="monospace", ha="center")
            ax.set_ylabel("Fraction with ortholog", color=AX, fontsize=8)
            ax.set_ylim(0, 1.15)
            ax.axhline(0.5, color=BORDER, lw=0.6, ls=":", alpha=0.5)
            ax.grid(axis="y", color=BORDER, alpha=0.25, lw=0.5, zorder=0)
            ax.legend(fontsize=6.5, facecolor=PANEL, edgecolor=BORDER,
                      labelcolor=TXT, framealpha=0.85,
                      ncol=min(4, nf), loc="upper right")
        else:
            ax.text(0.5, 0.5, "Family analysis unavailable",
                    ha="center", va="center", transform=ax.transAxes,
                    color=AX, fontsize=9, fontfamily="monospace")
            ax.axis("off")
        ax.set_title("C  ·  Conservation by IG Gene Family",
                     color=EMERALD, fontsize=10, fontweight="bold",
                     fontfamily="monospace", pad=10)

    # ── PANEL D · Violin / strip ───────────────────────────────────────────
    def _orth_draw_D(self, ax, ctx, standalone=False):
        (PANEL, TXT, AX, BORDER, BLUSH) = (
            ctx["PANEL"], ctx["TXT"], ctx["AX"], ctx["BORDER"], ctx["BLUSH"])
        _sp_col = ctx["_sp_col"]
        n_sp, sp_order, mat_s = ctx["n_sp"], ctx["sp_order"], ctx["mat_s"]

        ax.set_facecolor(PANEL)
        for s in ax.spines.values(): s.set_color(BORDER)
        ax.tick_params(colors=AX, labelsize=8)

        if n_sp <= 12:
            data_per_sp = [mat_s[sp_n].values for sp_n in sp_order]
            positions = np.arange(len(sp_order))
            try:
                parts = ax.violinplot(
                    data_per_sp, positions=positions,
                    widths=0.75, showmeans=False, showextrema=False,
                    showmedians=False)
                for i, body in enumerate(parts["bodies"]):
                    col = _sp_col(sp_order[i])
                    body.set_facecolor(_ca(col, "55"))
                    body.set_edgecolor(col)
                    body.set_alpha(0.7)
            except Exception:
                pass
            for i, vals in enumerate(data_per_sp):
                if len(vals) > 200:
                    sel = np.random.choice(len(vals), 200, replace=False)
                    vals_plot = vals[sel]
                else:
                    vals_plot = vals
                jitter = np.random.uniform(-0.12, 0.12, len(vals_plot))
                ax.scatter(np.full(len(vals_plot), i) + jitter, vals_plot,
                           s=4, alpha=0.4, color=_sp_col(sp_order[i]),
                           edgecolor="none", zorder=3)
                med = float(np.median(vals))
                ax.plot([i - 0.3, i + 0.3], [med, med],
                        color=C["lavender"], lw=2, zorder=5)
            ax.set_xticks(positions)
            ax.set_xticklabels(
                [s.replace("_", "\n") for s in sp_order],
                fontsize=6.5, color=TXT, fontfamily="monospace", ha="center")
        else:
            data_per_sp = [mat_s[sp_n].values for sp_n in sp_order]
            box = ax.boxplot(data_per_sp, positions=range(len(sp_order)),
                             widths=0.6, patch_artist=True, showfliers=False)
            for patch, sp_n in zip(box["boxes"], sp_order):
                patch.set_facecolor(_ca(_sp_col(sp_n), "55"))
                patch.set_edgecolor(_sp_col(sp_n))
            for med in box["medians"]: med.set_color(C["lavender"])
            ax.set_xticks(range(len(sp_order)))
            ax.set_xticklabels(
                [s.replace("_", "\n") for s in sp_order],
                fontsize=6, color=TXT, fontfamily="monospace", rotation=0)
        ax.set_ylabel("Conservation score", color=AX, fontsize=8)
        ax.set_ylim(-0.05, 1.1)
        ax.axhline(0.5, color=BORDER, lw=0.7, ls=":", alpha=0.5)
        ax.grid(axis="y", color=BORDER, alpha=0.25, lw=0.5, zorder=0)
        ax.set_title("D  ·  Score Distribution per Species  (violin + strip)",
                     color=BLUSH, fontsize=10, fontweight="bold",
                     fontfamily="monospace", pad=10)

    # ── PANEL E · Radial (polar) ───────────────────────────────────────────
    def _orth_draw_E(self, ax, ctx, standalone=False):
        (BG, PANEL, TXT, AX, BORDER, AMBER, VIOLET) = (
            ctx["BG"], ctx["PANEL"], ctx["TXT"], ctx["AX"], ctx["BORDER"],
            ctx["AMBER"], ctx["VIOLET"])
        n_sp, sp_order, col_mean = ctx["n_sp"], ctx["sp_order"], ctx["col_mean"]
        mean_c, bar_colors = ctx["mean_c"], ctx["bar_colors"]

        ax.set_facecolor(PANEL)
        theta = np.linspace(0, 2 * np.pi, n_sp, endpoint=False)
        radii = col_mean
        width = 2 * np.pi / n_sp * 0.85
        ax.bar(theta, radii, width=width, color=bar_colors, alpha=0.88,
               edgecolor=BG, linewidth=0.6, zorder=3)
        for r_ref, lbl in [(0.25, "25%"), (0.5, "50%"), (0.75, "75%")]:
            ax.plot(np.linspace(0, 2*np.pi, 100), [r_ref] * 100,
                    color=BORDER, lw=0.4, ls=":", alpha=0.6, zorder=1)
            ax.text(np.pi / 2, r_ref, lbl, color=AX, fontsize=6,
                    ha="center", fontfamily="monospace")
        ax.plot(np.linspace(0, 2*np.pi, 100), [mean_c] * 100,
                color=AMBER, lw=1.2, ls="--", alpha=0.85, zorder=2)
        ax.set_xticks(theta)
        ax.set_xticklabels([s.replace("_", "\n") for s in sp_order],
                           fontsize=6, color=TXT, fontfamily="monospace")
        ax.set_yticks([])
        ax.set_ylim(0, max(1.05, radii.max() * 1.18))
        ax.spines["polar"].set_color(BORDER)
        ax.set_title("E  ·  Radial Conservation Map",
                     color=VIOLET, fontsize=10, fontweight="bold",
                     fontfamily="monospace", pad=18)

    # ── PANEL F · CDF + quartiles ──────────────────────────────────────────
    def _orth_draw_F(self, ax, ctx, standalone=False):
        (BG, PANEL, TXT, AX, BORDER, CYAN, AMBER, EMERALD) = (
            ctx["BG"], ctx["PANEL"], ctx["TXT"], ctx["AX"], ctx["BORDER"],
            ctx["CYAN"], ctx["AMBER"], ctx["EMERALD"])
        n_genes, row_mean = ctx["n_genes"], ctx["row_mean"]
        mean_c, n_any, n_full = ctx["mean_c"], ctx["n_any"], ctx["n_full"]

        ax.set_facecolor(PANEL)
        for s in ax.spines.values(): s.set_color(BORDER)
        ax.tick_params(colors=AX, labelsize=8)

        sorted_vals = np.sort(row_mean)
        cdf_x = np.concatenate([[0], sorted_vals, [1]])
        cdf_y = np.concatenate([[0], np.arange(1, n_genes + 1) / n_genes, [1]])
        ax.fill_between(cdf_x, 0, cdf_y, color=_ca(CYAN, "33"), alpha=0.6, zorder=2)
        ax.plot(cdf_x, cdf_y, color=CYAN, lw=2.0, zorder=3)
        for q, col in [(0.25, AMBER), (0.5, C["lavender"]), (0.75, EMERALD)]:
            qv = float(np.quantile(row_mean, q))
            ax.plot([qv, qv], [0, q], color=col, lw=1.0, ls=":", alpha=0.85, zorder=4)
            ax.plot([0, qv], [q, q], color=col, lw=1.0, ls=":", alpha=0.85, zorder=4)
            ax.scatter([qv], [q], color=col, s=40, zorder=5, edgecolor=BG, lw=0.8)
            ax.annotate(f"Q{int(q*100)}={qv:.2f}", xy=(qv, q),
                        xytext=(qv + 0.04, q - 0.06), color=col, fontsize=8,
                        fontfamily="monospace", fontweight="bold")
        info = (
            f"n queried   : {n_genes:,}\n"
            f"with hits   : {n_any:,} ({n_any/max(n_genes,1):.0%})\n"
            f"≥90% cons.  : {n_full:,}\n"
            f"mean        : {mean_c:.3f}\n"
            f"median      : {float(np.median(row_mean)):.3f}\n"
            f"std         : {float(np.std(row_mean)):.3f}"
        )
        ax.text(0.97, 0.04, info, transform=ax.transAxes,
                ha="right", va="bottom", fontsize=7.5, color=TXT,
                fontfamily="monospace",
                bbox=dict(facecolor=_ca(PANEL, "ee"), edgecolor=BORDER,
                          boxstyle="round,pad=0.5", linewidth=0.7))
        ax.set_xlabel("Conservation score (mean per gene)", color=AX, fontsize=9)
        ax.set_ylabel("Cumulative fraction of IG genes", color=AX, fontsize=9)
        ax.set_xlim(-0.02, 1.02)
        ax.set_ylim(-0.02, 1.05)
        ax.grid(color=BORDER, alpha=0.25, lw=0.5, zorder=0)
        ax.set_title("F  ·  Empirical CDF + Quartiles",
                     color=AMBER, fontsize=10, fontweight="bold",
                     fontfamily="monospace", pad=10)

    # Mapa key → (método de dibujo, ¿es polar?)
    def _orth_panel_drawer(self, key):
        return {
            "heatmap": (self._orth_draw_A, False),
            "upset":   (self._orth_draw_B, False),
            "family":  (self._orth_draw_C, False),
            "violin":  (self._orth_draw_D, False),
            "radial":  (self._orth_draw_E, True),
            "cdf":     (self._orth_draw_F, False),
        }.get(key)

    def _orth_empty_fig(self, msg_title, msg_body, color):
        """Figura de estado vacío reutilizable."""
        BG, PANEL, AX = C["bg"], C["panel"], C["txt_muted"]
        fig, ax = plt.subplots(figsize=(9, 4), facecolor=BG)
        ax.set_facecolor(PANEL)
        ax.text(0.5, 0.58, msg_title, ha="center", va="center",
                transform=ax.transAxes, color=color, fontsize=15,
                fontweight="bold", fontfamily="monospace")
        ax.text(0.5, 0.40, msg_body, ha="center", va="center",
                transform=ax.transAxes, color=AX, fontsize=10,
                fontfamily="monospace", multialignment="center")
        ax.axis("off")
        fig.tight_layout()
        return fig

    def _plot_orth_panel(self, panel_key, matrix_df, summary, sp,
                         long_df=None, family_df=None):
        """
        Construye una figura INDEPENDIENTE de un único panel (A–F) para
        embeber en su propia sub-sección. Cada panel dimensiona su figura
        según la cantidad de datos para verse cómodamente.
        """
        ORCHID = C["orchid"]
        if matrix_df is None or (hasattr(matrix_df, "empty") and matrix_df.empty):
            return self._orth_empty_fig(
                "◉  No orthology data yet",
                "Run OMICS or click 🧪 TEST to populate this view.", ORCHID)

        drawer = self._orth_panel_drawer(panel_key)
        if drawer is None:
            return self._orth_empty_fig("◉  Unknown panel", panel_key, ORCHID)
        draw_fn, is_polar = drawer

        ctx = self._orth_compute_context(matrix_df, summary, sp, long_df, family_df)
        n_sp, n_genes = ctx["n_sp"], ctx["n_genes"]

        # Dimensiones por panel — pensadas para lectura individual cómoda.
        if panel_key == "heatmap":
            FW = max(9.0, n_sp * 0.95 + 3.0)
            FH = max(6.0, min(0.16 * min(n_genes, 60) + 3.0, 16.0))
        elif panel_key == "upset":
            FW = max(9.0, n_sp * 0.9 + 4.0); FH = 6.5
        elif panel_key == "family":
            FW = max(9.0, n_sp * 0.9 + 3.0); FH = 6.0
        elif panel_key == "violin":
            FW = max(9.0, n_sp * 0.95 + 2.0); FH = 6.0
        elif panel_key == "radial":
            FW = 8.0; FH = 8.0
        else:  # cdf
            FW = 9.5; FH = 6.0

        fig = plt.figure(figsize=(FW, FH), facecolor=C["bg"], dpi=110)
        if is_polar:
            ax = fig.add_subplot(111, projection="polar")
        else:
            ax = fig.add_subplot(111)
        try:
            draw_fn(ax, ctx, standalone=True)
        except Exception as exc:
            logging.warning("[OMICS] panel %s draw error: %s", panel_key, exc)
            ax.clear(); ax.axis("off")
            ax.text(0.5, 0.5, f"Render error in panel {panel_key}",
                    ha="center", va="center", transform=ax.transAxes,
                    color=C["red"], fontsize=10, fontfamily="monospace")
        try:
            fig.tight_layout(rect=(0, 0, 1, 0.97))
        except Exception:
            pass
        return fig

    def _plot_orthology_gui(self, matrix_df: pd.DataFrame,
                            summary: dict, sp: str,
                            long_df: "pd.DataFrame | None" = None,
                            family_df: "pd.DataFrame | None" = None):
        """
        Dashboard combinado 3×2 (A–F) — se conserva para exportación PNG y
        compatibilidad. La UI ahora muestra cada panel en su propia
        sub-sección vía `_plot_orth_panel`, pero esta función sigue
        construyendo la figura completa cuando se requiere todo junto.
        """
        import matplotlib.gridspec as gridspec
        TITLE = C["lavender"]

        if matrix_df is None or (hasattr(matrix_df, "empty") and matrix_df.empty):
            return self._orth_empty_fig(
                "◉  No orthology data yet",
                "Click  ▶ RUN OMICS  to fetch orthologs from\n"
                "Ensembl Compara across all selected species.",
                C["orchid"])

        ctx = self._orth_compute_context(matrix_df, summary, sp, long_df, family_df)
        n_sp, n_genes = ctx["n_sp"], ctx["n_genes"]
        n_any, mean_c, n_full = ctx["n_any"], ctx["mean_c"], ctx["n_full"]

        FW = max(15.0, n_sp * 1.1 + 6.0)
        FH = max(13.0, min(n_genes * 0.10 + 8.0, 22.0))
        fig = plt.figure(figsize=(FW, FH), facecolor=C["bg"], dpi=110)
        gs = gridspec.GridSpec(
            3, 2, figure=fig, left=0.05, right=0.97, top=0.93, bottom=0.05,
            hspace=0.42, wspace=0.22, height_ratios=[1.2, 0.95, 0.95])
        ax_A = fig.add_subplot(gs[0, 0])
        ax_B = fig.add_subplot(gs[0, 1])
        ax_C = fig.add_subplot(gs[1, 0])
        ax_D = fig.add_subplot(gs[1, 1])
        ax_E = fig.add_subplot(gs[2, 0], projection="polar")
        ax_F = fig.add_subplot(gs[2, 1])

        for draw_fn, ax in [(self._orth_draw_A, ax_A), (self._orth_draw_B, ax_B),
                            (self._orth_draw_C, ax_C), (self._orth_draw_D, ax_D),
                            (self._orth_draw_E, ax_E), (self._orth_draw_F, ax_F)]:
            try:
                draw_fn(ax, ctx)
            except Exception as exc:
                logging.warning("[OMICS] combined panel error: %s", exc)

        fig.suptitle(
            f"IG Gene Cross-Species Ortholog Conservation  ·  "
            f"{sp.replace('_', ' ').title()}\n"
            f"{n_genes:,} genes  ·  {n_sp} species  ·  "
            f"{n_any:,} ({n_any/max(n_genes,1):.0%}) with ≥1 ortholog  ·  "
            f"mean {mean_c:.2f}  ·  "
            f"{n_full:,} fully conserved (≥90%)",
            color=TITLE, fontsize=11.5, fontweight="bold",
            fontfamily="monospace", y=0.987)
        return fig
    def _run_pipeline(self):
        if self._running: return
        # ── Modo multispecies activo? ─────────────────────────────────────
        is_multi = bool(getattr(self, "_var_multispecies",
                                tk.BooleanVar(value=False)).get())
        # Saneo del input para tolerar las variantes que un usuario escribe:
        #   "Stegastes partitus"  → "stegastes_partitus"
        #   "Cottoperca_gobio"    → "cottoperca_gobio"
        #   "  HOMO_SAPIENS  "    → "homo_sapiens"
        # Ensembl REST exige el production_name en minúsculas y con guiones
        # bajos. .split() colapsa cualquier whitespace (tabs incluidos).
        sp = "_".join(self._var_species.get().lower().split())
        if not is_multi and not sp:
            messagebox.showerror("Error","Please enter a valid species ID."); return
        if is_multi:
            # Etiqueta visual; el batch usará self._multispecies_list internamente.
            sp = f"multispecies (×{len(self._multispecies_list)})"
        biotypes_raw = self._var_biotypes.get().strip()
        allowed = ([b.strip() for b in biotypes_raw.split(",") if b.strip()]
                   if biotypes_raw else [])
        try:   min_len = int(self._var_min_len.get() or 0)
        except ValueError: min_len = 0
        params = {
            "species":               sp,
            "utr_file":              self._var_utr.get().strip(),
            "autosomes_only":        self._var_debug.get(),
            "chromosomes":           self._var_chroms.get().strip(),
            "min_len":               min_len,
            "biotypes":              allowed,
            "out_dir":               self._var_outdir.get().strip(),
            "output_prefix":         self._var_prefix.get().strip() or "IGFinder2.1.1",
            "no_stats":              self._var_no_stats.get(),
            "no_structure":          self._var_no_structure.get(),
            "no_plots":              self._var_no_plots.get(),
            "enable_enrichment":     self._var_enrichment.get(),
            "window_size":           1_000_000,
            "step_size":             None,
            "enrichment_fdr":        0.05,
            "enrichment_background": "all",
            "enable_go_enrichment":  self._var_go_enrichment.get(),
            "go_fdr":                0.05,
            "go_top_n":              15,
            "go_sources":            None,
            "enable_orthology":      self._var_orthology.get(),
            "orthology_targets":     None,
            "orthology_max_genes":   500,
            "orth_check_intronless": self._var_orth_intronless.get(),
            "enable_ntv3":           self._var_ntv3.get(),
            "ntv3_batch_size":       8,
        }
        self._running = True; self._chromoscope.reset(); self._activity.reset()
        self._ig_partial        = pd.DataFrame()
        self._meg_partial       = pd.DataFrame()
        self._ui_partial        = pd.DataFrame()
        self._chroms_done_list  = []
        # Resetear stats — el widget recibirá valores reales del pipeline
        self._activity.update_math_stats({
            "n_ig": 0, "n_meg": 0, "n_seg": 0,
            "welch_t": 0.0, "welch_p": 1.0,
            "mw_u": 0.0,   "mw_p": 1.0,
            "cliffs": 0.0, "chi2": 0.0, "p_chi2": 1.0,
            "mu_ig": 0.0,  "mu_meg": 0.0, "fdr": 1.0,
        })
        self._btn_run.configure(state="disabled",
                                 text="⏳  PIPELINE RUNNING...",
                                 bg=_ca(C["border"],"88"))
        self._btn_stop.configure(state="normal",
                                  fg=C["red"],
                                  bg=_ca(C["red"],"18"))
        stop_outer = self._btn_stop.master
        stop_outer.configure(bg=_ca(C["red"],"99"))
        self._prog_bar.start(8)
        self._prog_label.configure(text="RUNNING", fg=C["emerald"])
        self._sb_accent.configure(bg=C["emerald"])
        # ── PIPELINE START: Activity takes over, Metrics/Scope go idle ─────
        # System Metrics (SysDial + EliteStatus): freeze at low value
        self._sys_canvas.set_value(0.05)           # dial freezes — shows minimal
        self._elite.set_ig(0.0)
        self._elite.set_meg(0.0)
        self._elite.set_seg(0.0)
        # ChromoScope: stays visible but STOPS sweeping until first chrom
        self._chromoscope.set_active(False)         # sweep stops
        self._chromoscope.reset()
        # Pipeline Activity: ACTIVATE — full 60fps
        self._activity.set_active(True)
        # ── Startup computation stream — Activity visible inmediatamente ────
        self._activity.set_window_progress(1, self._activity.COLS)   # scanner arranca
        self._activity.push_computation(f"▶ PIPELINE INIT — {sp}", C["teal"])
        self._activity.push_computation(f"  Species : {sp}", C["orchid"])
        self._activity.push_computation(f"  Engine  : IGFinder 2.1.1 unified", C["lavender"])
        self._activity.push_computation(f"  Monitor : 60 fps · MATRIX ACTIVE", C["cyan"])
        self._activity.push_computation(f"⊙ Connecting to Ensembl REST API...", C["teal"])
        # ChromoScope resumes only when first chrom starts scanning
        # (done in _poll when extra["phase"]=="start")
        self._switch_tab("monitor")
        self._append_log(f"─── Pipeline start: {sp} ───────────────────","dim")
        if is_multi:
            self._runner = MultiSpeciesRunner(
                params, list(self._multispecies_list),
                self._log_q, self._res_q, self._prog_q)
            # ── Refrescar el banner de Cross Species mientras corre el batch
            try:
                if hasattr(self, "_cross_update_pending"):
                    self._cross_update_pending()
            except Exception:
                pass
        else:
            self._runner = PipelineRunner(
                params, self._log_q, self._res_q, self._prog_q)
        self._runner.start()

    def _stop_pipeline(self):
        if self._runner: self._runner.stop()
        self._append_log("Abort requested — terminating current operation...","warn")
        self._btn_stop.configure(state="disabled",
                                  fg=_ca(C["red"],"55"),
                                  bg=_ca(C["red"],"18"))
        stop_outer = self._btn_stop.master
        stop_outer.configure(bg=_ca(C["red"],"44"))

    def _poll(self):
        try:
            while True:
                msg, tag = self._log_q.get_nowait()
                if tag == "math_stats" and isinstance(msg, dict):
                    self._activity.update_math_stats(msg)
                    # Also update monitor panel stat labels
                    try:
                        fmt_map = {
                            "n_ig":   lambda v: f"{int(v):,}",
                            "n_meg":  lambda v: f"{int(v):,}",
                            "n_seg":  lambda v: f"{int(v):,}",
                            "welch_t":lambda v: f"{v:.3f}",
                            "welch_p":lambda v: f"{v:.2e}",
                            "cliffs": lambda v: f"{v:.3f}",
                            "chi2":   lambda v: f"{v:.2f}",
                            "fdr":    lambda v: f"{v:.2e}",
                        }
                        for k, lbl in self._stat_labels.items():
                            if k in msg and msg[k] is not None:
                                lbl.configure(text=fmt_map[k](msg[k]))
                    except AttributeError:
                        pass
                    continue
                self._append_log(msg, tag)
                col_map = {"ok": C["emerald"], "err": C["red"],
                           "warn": C["amber"], "info": C["cyan"],
                           "dim": C["txt_muted"]}
                self._activity.push_computation(
                    msg, col_map.get(tag, C["txt_dim"]))
        except queue.Empty: pass
        try:
            while True:
                item  = self._prog_q.get_nowait()
                done  = item[0]; total = item[1]; phase = item[2]
                extra = item[3] if len(item)>3 else None
                self._dna_bar.set_value(done, total)
                self._phase_lbl.configure(text=f"{phase}  {done}/{total}")
                try:
                    self._phase_lbl_scan.configure(text=f"{phase}")
                    self._prog_pct_lbl.configure(text=f"{done}/{total}")
                    self._dna_bar_scan.set_value(done, total)
                except AttributeError:
                    pass
                if extra and extra.get("genome"):
                    # Evento INIT: reconfigura ChromoScope con el layout
                    # de cromosomas/scaffolds de la especie en curso
                    try:
                        self._chromoscope.set_genome(extra["genome"])
                    except Exception:
                        pass   # no romper el pipeline si el widget falla
                    continue
                if extra and extra.get("chrom"):
                    if extra.get("phase")=="done" and extra.get("genes") is not None:
                        self._chromoscope.set_chrom_done(extra["chrom"],extra["genes"])
                        self._activity.update_genes(extra["genes"])
                        self._activity.set_window_progress(total, total)
                    elif extra.get("phase")=="start":
                        # First chromosome: wake up ChromoScope sweep
                        if not self._chromoscope._active:
                            self._chromoscope.set_active(True)
                        self._chromoscope.set_current_chrom(extra["chrom"])
                        self._activity.set_chrom(extra["chrom"], done, total)
                        self._activity.set_window_progress(0, total)
                else:
                    self._activity.set_window_progress(done, total)
        except queue.Empty: pass
        try:
            res = self._res_q.get_nowait()
            self._running = False
            self._btn_run.configure(state="normal",
                                     text="▶   INITIATE STRUCTURAL GENOME SCAN",
                                     bg=_ca(C["cyan"],"1a"))
            self._btn_stop.configure(state="disabled",
                                      fg=_ca(C["red"],"55"),
                                      bg=_ca(C["red"],"18"))
            stop_outer = self._btn_stop.master
            stop_outer.configure(bg=_ca(C["red"],"44"))
            self._prog_bar.stop()
            self._chromoscope.set_active(False)
            self._activity.set_active(False)
            if res is None:
                self._prog_label.configure(text="ERROR", fg=C["red"])
                messagebox.showerror("Pipeline Error",
                                     "Pipeline ended with errors.\nCheck the LOG tab.")
            else:
                self._results = res
                self._prog_label.configure(text="COMPLETE", fg=C["emerald"])
                self._sb_accent.configure(bg=C["teal"])
                # Diferir TODO el trabajo pesado (build de plots, switch de tab,
                # messagebox) fuera del callback de _poll. Ejecutarlo aquí, de
                # forma anidada, re-entra al event loop de Tk y en macOS deja la
                # ventana entera en negro. Con after(0,...) el loop respira y la
                # actualización ocurre limpiamente en el siguiente ciclo idle.
                self.after(0, lambda r=res: self._finish_pipeline(r))
        except queue.Empty: pass
        self.after(200, self._poll)

    def _finish_pipeline(self, res):
        """
        Completa la actualización de UI tras un pipeline exitoso, POR ETAPAS.

        Orden CLAVE para evitar la pantalla negra en macOS:
          1. Cambiar a la pestaña RESULTS PRIMERO (ligero) + repintar
          2. SOLO DESPUÉS poblar datos pesados en etapas con after()
        SIN messagebox modal (roba foco y congela el repintado -> negro).
        """
        try:
            self._switch_tab("results")
        except Exception as exc:
            logging.warning("[FINISH] switch_tab: %s", exc)
        self._force_full_repaint()

        def _stage_results():
            try:
                self._update_results(res)
            except Exception as exc:
                logging.warning("[FINISH] _update_results: %s", exc)
            self.after(150, _stage_notify)

        def _stage_notify():
            try:
                ig  = res.get("ig",  pd.DataFrame())
                meg = res.get("meg", pd.DataFrame())
                ui  = res.get("ui",  pd.DataFrame())
                self._append_log(
                    f"✔ Pipeline completado — IG={len(ig):,}  "
                    f"MEG={len(meg):,}  ui-SEG={len(ui):,}", "ok")
            except Exception:
                pass
            try:
                self._prog_label.configure(text="COMPLETE ✔", fg=C["emerald"])
            except Exception:
                pass
            self._force_full_repaint()

        self.after(150, _stage_results)

    def _force_full_repaint(self, _tries=0):
        """Repintado COMPLETO de la ventana raíz en macOS, con reintentos.
        Seguro de llamar SOLO desde idle (no desde el callback de _poll)."""
        try:
            self.update_idletasks()
        except Exception:
            pass
        if _IS_MACOS:
            try:
                self.event_generate("<Expose>")
                self.update_idletasks()
            except Exception:
                pass
            if _tries < 4:
                self.after(180, lambda: self._force_full_repaint(_tries + 1))

    # ──────────────────────────────────────────────────────────────────────

    def _update_results(self, res):
        ig    = res.get("ig",  pd.DataFrame())
        meg   = res.get("meg", pd.DataFrame())
        ui    = res.get("ui",  pd.DataFrame())
        total = len(ig)+len(meg)+len(ui)
        self._res_ig_n.configure( text=f"{len(ig):,}")
        self._res_meg_n.configure(text=f"{len(meg):,}")
        self._res_ui_n.configure( text=f"{len(ui):,}")
        self._dot_ig.set_fill(  len(ig)  / max(total,1))
        self._dot_meg.set_fill( len(meg) / max(total,1))
        self._dot_ui.set_fill(  len(ui)  / max(total,1))
        self._bar_ig.set_value(  len(ig),  total)
        self._bar_meg.set_value( len(meg), total)
        self._bar_ui.set_value(  len(ui),  total)
        self._pill_ig.configure( text=f"{len(ig):,}")
        self._pill_meg.configure(text=f"{len(meg):,}")
        self._pill_seg.configure(text=f"{len(ui):,}")
        self._pill_status.configure(text="COMPLETE", fg=C["emerald"])
        # Update scan tab mini pills
        try:
            self._scan_pill_ig.configure(text=f"{len(ig):,}")
            self._scan_pill_meg.configure(text=f"{len(meg):,}")
            self._scan_pill_uiseg.configure(text=f"{len(ui):,}")
        except AttributeError:
            pass
        self._populate_tree(self._tree_ig,  ig)
        self._populate_tree(self._tree_meg, meg)
        self._populate_tree(self._tree_ui,  ui)
        # Actualizar dropdown de plots si hay enrichment disponible
        if self._results and self._results.get("enrichment_df") is not None:
            try:
                self._refresh_plot_dropdown(self._results)
            except Exception:
                pass
        # Actualizar pestaña OMICS si hay datos de enriquecimiento u ortología
        try:
            self._update_omics_tab(res)
        except Exception:
            pass
        # ── CRUZAR LOS GENOMAS → pestaña CROSS SPECIES ────────────────────
        # Si el resultado proviene de un SCAN multispecies (toggle ON, 18
        # genomas), cruzamos los genomas: construimos la matriz familia IG ×
        # especie y refrescamos la pestaña independiente Cross Species.
        try:
            multi = res.get("multispecies_results") if isinstance(res, dict) else None
            if multi:
                self._build_cross_from_multispecies(
                    multi, order=res.get("multispecies_order"))
        except Exception as _cs_exc:
            logging.warning("[CROSS] build from multispecies: %s", _cs_exc)

        # Forzar repintado tras actualizar todos los widgets (fix macOS negro)
        self._force_redraw()

    # ══════════════════════════════════════════════════════════════════════════
    #  CROSS SPECIES — métodos integrados directamente en la clase
    #  (antes vivían como funciones top-level en el patch externo)
    # ══════════════════════════════════════════════════════════════════════════

    def _embed_ext_fig(self, fig, frame, attr_canvas, placeholder, accent):
        """
        Incrusta una figura matplotlib en un Frame tkinter.
        Destruye el canvas previo si ya existía para evitar stacking.
        """
        if placeholder:
            try:
                placeholder.place_forget()
            except Exception:
                pass
        if fig is None:
            return
        # Fondo BLANCO + texto legible y auto-guardado (igual que el visor avanzado)
        try:
            self._omics_whiten_figure(fig)
        except Exception:
            pass
        try:
            self._omics_register_fig(attr_canvas, fig)
        except Exception:
            pass
        try:
            old = getattr(self, attr_canvas, None)
            if old is not None:
                try:
                    widget = old.get_tk_widget()
                    widget.destroy()
                except Exception:
                    pass
                try:
                    old_fig = getattr(old, 'figure', None)
                    if old_fig is not None:
                        plt.close(old_fig)
                except Exception:
                    pass
                setattr(self, attr_canvas, None)
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            canvas = FigureCanvasTkAgg(fig, master=frame)
            # draw() DESPUÉS del whiten para que el fondo blanco sea visible
            canvas.draw()
            canvas.draw_idle()
            # macOS: flush explícito para evitar canvas negro
            try:
                canvas.flush_events()
            except Exception:
                pass
            widget = canvas.get_tk_widget()
            widget.configure(bg="#ffffff")
            widget.pack(fill="both", expand=True)
            setattr(self, attr_canvas, canvas)
            try:
                frame.update_idletasks()
            except Exception:
                pass
        except Exception as exc:
            logging.warning("[OMICS_EXT] embed_ext_fig: %s", exc)


    def _build_section_cross_species(self):
        """
        Cross Species Analysis — diseño avanzado.

        Ahora es una SECCIÓN PROPIA de primera clase del acordeón OMICS:
        colapsable, redimensionable y maximizable, con botón 🧪 TEST. Dentro
        aloja un hub de métricas + controles y TRES sub-secciones independientes
        (cada una colapsable/redimensionable con su propio visor interactivo):

            ①  Species Conservation Ranking  — tabla interactiva + barras + dona
            ②  Family × Species Matrix        — heatmap / burbuja
            ③  Clade Conservation Profile     — box + strip por clado filogenético
        """
        # Construye en la pestaña independiente CROSS SPECIES si existe; si no,
        # cae al tab OMICS (retrocompatibilidad con la versión antigua).
        tab = getattr(self, "_tab_cross", None) or self._tab_omics
        COL = C["cyan"]

        # ── Sección de primera clase (contenedor autoajustable) ─────────────────
        sec = self._omics_make_section(
            tab, key="cross",
            title="CROSS SPECIES ANALYSIS",
            subtitle="3 independent sub-views · ① ranking · ② family×species matrix · ③ clade profile",
            color=COL, autosize_body=True,
            test_cmd=lambda: self._cs_test_viz())

        # ════════════════ HUB: métricas + controles compartidos ════════════════
        hub = tk.Frame(sec, bg=C["bg"])
        hub.pack(fill="x", padx=8, pady=(6, 2))

        # Tarjetas métricas
        cards = tk.Frame(hub, bg=C["bg"])
        cards.pack(fill="x", pady=(0, 6))
        _ext_mini_card(cards, C["cyan"],   "◈", "SPECIES COMPARED", "_cs_card_sp",      self)
        _ext_mini_card(cards, C["violet"], "◆", "LINEAGES COVERED",   "_cs_card_lin",     self)
        _ext_mini_card(cards, C["orchid"], "◉", "MOST CONSERVED GENE",  "_cs_card_topgene", self)
        _ext_mini_card(cards, C.get("rose", C["blush"]), "▲",
                       "UNIQUE (1 species)", "_cs_card_unique", self)

        # ── Prominent action bar (always visible at the top of the section) ─────
        # RUN launches the multispecies batch; LOAD reuses data already in memory.
        runbar = tk.Frame(hub, bg=C["bg"])
        runbar.pack(fill="x", pady=(0, 6))
        tk.Button(runbar, text="  ⬢ RUN MULTISPECIES  ",
                  command=self._cross_run_multispecies,
                  bg=_ca(C["cyan"], "1a"), fg=C["cyan"],
                  activebackground=_ca(C["cyan"], "33"), activeforeground=C["cyan"],
                  relief="flat", bd=0, cursor="hand2",
                  font=("Courier New", 9, "bold"), padx=12, pady=6,
                  highlightthickness=1, highlightbackground=_ca(C["cyan"], "66")
                  ).pack(side="left", padx=(0, 6))
        tk.Button(runbar, text="  ▶ LOAD FROM OMICS / SCAN  ",
                  command=self._build_cross_from_omics,
                  bg=_ca(C["emerald"], "1a"), fg=C["emerald"],
                  activebackground=_ca(C["emerald"], "33"), activeforeground=C["emerald"],
                  relief="flat", bd=0, cursor="hand2",
                  font=("Courier New", 9, "bold"), padx=12, pady=6,
                  highlightthickness=1, highlightbackground=_ca(C["emerald"], "55")
                  ).pack(side="left", padx=(0, 6))
        tk.Label(runbar,
                 text="RUN launches the multispecies batch  ·  LOAD uses data already in memory",
                 bg=C["bg"], fg=C["txt_muted"],
                 font=("Courier New", 8)).pack(side="left", padx=6)

        # Barra de controles (sort · clade · threshold)
        ctrl = tk.Frame(hub, bg=C["bg2"],
                        highlightthickness=1, highlightbackground=_ca(COL, "22"))
        ctrl.pack(fill="x")
        ci = tk.Frame(ctrl, bg=C["bg2"])
        ci.pack(fill="x", padx=12, pady=6)

        tk.Label(ci, text="Sort:", bg=C["bg2"], fg=C["txt_muted"],
                 font=("Courier New", 8)).pack(side="left")
        self._cs_sort_var = tk.StringVar(value="conservation")
        for val, txt in [("conservation", "Conservation"), ("n_genes", "N genes"),
                         ("phylo", "Phylogeny"), ("name", "Name")]:
            tk.Radiobutton(ci, text=txt, variable=self._cs_sort_var, value=val,
                           bg=C["bg2"], fg=COL, selectcolor=_ca(COL, "22"),
                           activebackground=C["bg2"], activeforeground=COL,
                           font=("Courier New", 8),
                           command=self._cs_refresh).pack(side="left", padx=3)

        tk.Frame(ci, bg=_ca(COL, "33"), width=1).pack(side="left", fill="y", padx=8)

        tk.Label(ci, text="Clade:", bg=C["bg2"], fg=C["txt_muted"],
                 font=("Courier New", 8)).pack(side="left")
        self._cs_clade_var = tk.StringVar(value="all")
        for val, txt in [("all", "All"), ("primates", "Primates"),
                         ("mammals", "Mammals"), ("vertebrates", "Vertebrates")]:
            tk.Radiobutton(ci, text=txt, variable=self._cs_clade_var, value=val,
                           bg=C["bg2"], fg=C["orchid"],
                           selectcolor=_ca(C["orchid"], "22"),
                           activebackground=C["bg2"], activeforeground=C["orchid"],
                           font=("Courier New", 8),
                           command=self._cs_refresh).pack(side="left", padx=2)

        tk.Frame(ci, bg=_ca(COL, "33"), width=1).pack(side="left", fill="y", padx=8)

        tk.Label(ci, text="Min %:", bg=C["bg2"], fg=C["txt_muted"],
                 font=("Courier New", 8)).pack(side="left")
        self._cs_thresh_var = tk.DoubleVar(value=0.0)
        self._cs_thresh_lbl = tk.Label(ci, text="0 %", bg=C["bg2"], fg=COL,
                                        font=("Courier New", 8, "bold"), width=5)
        self._cs_thresh_lbl.pack(side="right")
        tk.Scale(ci, from_=0.0, to=1.0, resolution=0.05, orient="horizontal",
                 variable=self._cs_thresh_var, bg=C["bg2"], fg=COL,
                 troughcolor=_ca(COL, "22"), highlightthickness=0,
                 sliderrelief="flat", length=140, showvalue=False,
                 command=lambda v: (
                     self._cs_thresh_lbl.configure(text=f"{float(v)*100:.0f} %"),
                     self._cs_refresh())).pack(side="right", padx=4)

        # ════════════════ SUB-SECCIÓN ① · RANKING (tabla + barras) ══════════════
        rank_body = self._omics_make_section(
            sec, key="cross_rank",
            title="Species Conservation Ranking",
            subtitle="Interactive table + horizontal bars + lineage donut",
            color=C["cyan"], body_height=460, min_h=240, badge="①")

        two = tk.Frame(rank_body, bg=C["panel"])
        two.pack(fill="both", expand=True, padx=4, pady=4)
        two.grid_columnconfigure(0, weight=0)
        two.grid_columnconfigure(1, weight=1)
        two.grid_rowconfigure(0, weight=1)

        # Columna izquierda: tabla de especies
        left_f = tk.Frame(two, bg=C["panel"],
                          highlightthickness=1, highlightbackground=_ca(COL, "2a"))
        left_f.grid(row=0, column=0, sticky="nsew", padx=(0, 5))
        left_f.configure(width=440)
        left_f.grid_propagate(False)

        lhdr = tk.Frame(left_f, bg=_ca(COL, "0d"))
        lhdr.pack(fill="x")
        tk.Frame(lhdr, bg=COL, width=3).pack(side="left", fill="y")
        tk.Label(lhdr, text="  Species × IG Gene Conservation",
                 bg=_ca(COL, "0d"), fg=COL,
                 font=("Courier New", 9, "bold")).pack(side="left", padx=6, pady=5)
        self._cs_tree_count = tk.Label(lhdr, text="", bg=_ca(COL, "0d"),
                                        fg=_ca(COL, "66"), font=("Courier New", 8))
        self._cs_tree_count.pack(side="right", padx=8)

        tk.Frame(left_f, bg=_ca(COL, "22"), height=1).pack(fill="x")

        tw_wrap = tk.Frame(left_f, bg=C["panel"])
        tw_wrap.pack(fill="both", expand=True, padx=4, pady=4)

        _cs_cols = ("species", "lineage", "n_genes", "n_orthologs",
                    "conservation", "stays_ig", "bar")
        stl = ttk.Style()
        stl.configure("CS.Treeview", background=C["panel"], foreground=C["txt_dim"],
                      fieldbackground=C["panel"], rowheight=23,
                      font=("Courier New", 8))
        stl.configure("CS.Treeview.Heading", background=_ca(COL, "1a"),
                      foreground=COL, font=("Courier New", 8, "bold"))
        stl.map("CS.Treeview", background=[("selected", _ca(COL, "33"))],
                foreground=[("selected", C["txt"])])

        self._cs_tree = ttk.Treeview(tw_wrap, columns=_cs_cols, show="headings",
                                      height=13, style="CS.Treeview")
        # "STAYS IG" = of this species' orthologs, how many remain intronless
        # (i.e. stay an Intronless Gene). Requires the "Check if each ortholog
        # stays intronless" option in the orthology step; otherwise shows "—".
        for col, w, anch, head in [
            ("species", 148, "w", "SPECIES"), ("lineage", 78, "center", "LINEAGE"),
            ("n_genes", 52, "center", "GENES"), ("n_orthologs", 60, "center", "ORTHOLOGS"),
            ("conservation", 72, "center", "CONS %"),
            ("stays_ig", 86, "center", "STAYS IG"), ("bar", 84, "w", "COVERAGE"),
        ]:
            self._cs_tree.heading(col, text=head,
                                   command=lambda c=col: self._cs_col_sort(c))
            self._cs_tree.column(col, width=w, anchor=anch, stretch=False)

        cs_sb = ttk.Scrollbar(tw_wrap, orient="vertical",
                              command=self._cs_tree.yview)
        self._cs_tree.configure(yscrollcommand=cs_sb.set)
        self._cs_tree.pack(side="left", fill="both", expand=True)
        cs_sb.pack(side="right", fill="y")
        for lin, col_hex in _LINEAGE_COLORS.items():
            self._cs_tree.tag_configure(lin, foreground=col_hex)

        # Columna derecha: barplot interactivo (visor con zoom/scroll/pan)
        right_f = tk.Frame(two, bg=C["panel"],
                           highlightthickness=1, highlightbackground=_ca(COL, "22"))
        right_f.grid(row=0, column=1, sticky="nsew")
        self._cs_plot_frame  = right_f
        self._cs_plot_canvas = None
        self._cs_plot_ph = tk.Label(
            right_f,
            text="◈  The per-species comparison chart\n"
                 "   appears after running OMICS or 🧪 TEST.",
            bg=C["panel"], fg=_ca(COL, "44"),
            font=("Courier New", 9), justify="center")
        self._cs_plot_ph.place(relx=0.5, rely=0.5, anchor="center")

        # ════════════════ SUB-SECCIÓN ② · MATRIZ FAMILIA × ESPECIE ══════════════
        mat_body = self._omics_make_section(
            sec, key="cross_matrix",
            title="Family × Species Matrix",
            subtitle="Fraction of genes with ≥1 ortholog per family and species",
            color=C["teal"], body_height=420, min_h=220, badge="②")

        # Barra de modo (heatmap / burbuja)
        mbar = tk.Frame(mat_body, bg=_ca(C["teal"], "0d"))
        mbar.pack(fill="x")
        tk.Label(mbar, text="  Modo:", bg=_ca(C["teal"], "0d"), fg=C["teal"],
                 font=("Courier New", 8, "bold")).pack(side="left", padx=(6, 2), pady=3)
        self._cs_hmap_mode = tk.StringVar(value="heatmap")
        for mv, ml in [("heatmap", "Heatmap"), ("bubble", "Burbuja")]:
            tk.Radiobutton(mbar, text=ml, variable=self._cs_hmap_mode, value=mv,
                           bg=_ca(C["teal"], "0d"), fg=C["teal"],
                           selectcolor=_ca(C["teal"], "1a"),
                           activebackground=_ca(C["teal"], "0d"),
                           activeforeground=C["teal"], font=("Courier New", 8),
                           command=self._cs_refresh).pack(side="left", padx=3)

        self._cs_hmap_outer = tk.Frame(mat_body, bg=C["panel"])
        self._cs_hmap_outer.pack(fill="both", expand=True)
        self._cs_hmap_canvas = None
        self._cs_hmap_ph = tk.Label(
            self._cs_hmap_outer,
            text="◉  Family × species matrix\n   appears after running OMICS or 🧪 TEST.",
            bg=C["panel"], fg=_ca(C["teal"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_hmap_ph.place(relx=0.5, rely=0.5, anchor="center")

        # ════════════════ SUB-SECCIÓN ③ · PERFIL POR CLADO (avanzado) ═══════════
        clade_body = self._omics_make_section(
            sec, key="cross_clade",
            title="Clade Conservation Profile",
            subtitle="Conservation distribution per phylogenetic clade · box + strip + mean",
            color=C["violet"], body_height=440, min_h=240, badge="③")
        self._cs_clade_frame  = tk.Frame(clade_body, bg=C["panel"])
        self._cs_clade_frame.pack(fill="both", expand=True)
        self._cs_clade_canvas = None
        self._cs_clade_ph = tk.Label(
            self._cs_clade_frame,
            text="◆  Clade conservation profile\n"
                 "   appears after running OMICS or 🧪 TEST.",
            bg=C["panel"], fg=_ca(C["violet"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_clade_ph.place(relx=0.5, rely=0.5, anchor="center")

        # ════════════════ SUB-SECCIÓN ④ · IG REPERTOIRE SPECIALIZATION ══════════
        # Métricas IG-especializadas: heavy/light, κ:λ, V/D/J/C, Shannon,
        # core / lineage-specific families, Jaccard inter-especies.
        # Fuente: self._omics_data["cross_specialized"] (rellenado por
        # _build_cross_from_multispecies a partir del SCAN multispecies).
        spec_body = self._omics_make_section(
            sec, key="cross_specialized",
            title="IG Repertoire Specialization",
            subtitle="Heavy/light · κ:λ · V/D/J/C · Shannon entropy · core / lineage-specific · Jaccard",
            color=C["orchid"], body_height=540, min_h=260, badge="④")

        # Layout: tabla a la izquierda, Jaccard heatmap a la derecha.
        spec_two = tk.Frame(spec_body, bg=C["panel"])
        spec_two.pack(fill="both", expand=True, padx=4, pady=4)
        spec_two.grid_columnconfigure(0, weight=0)
        spec_two.grid_columnconfigure(1, weight=1)
        spec_two.grid_rowconfigure(0, weight=1)

        # ── Columna izquierda: tabla de especies × métricas ────────────────────
        sl_f = tk.Frame(spec_two, bg=C["panel"],
                        highlightthickness=1,
                        highlightbackground=_ca(C["orchid"], "33"))
        sl_f.grid(row=0, column=0, sticky="nsew", padx=(0, 5))
        sl_f.configure(width=600)
        sl_f.grid_propagate(False)

        slhdr = tk.Frame(sl_f, bg=_ca(C["orchid"], "0d"))
        slhdr.pack(fill="x")
        tk.Frame(slhdr, bg=C["orchid"], width=3).pack(side="left", fill="y")
        tk.Label(slhdr, text="  IG-Specialized Metrics per Species",
                 bg=_ca(C["orchid"], "0d"), fg=C["orchid"],
                 font=("Courier New", 9, "bold")).pack(side="left", padx=6, pady=5)
        self._cs_spec_count = tk.Label(
            slhdr, text="", bg=_ca(C["orchid"], "0d"),
            fg=_ca(C["orchid"], "88"), font=("Courier New", 8))
        self._cs_spec_count.pack(side="right", padx=8)

        tk.Frame(sl_f, bg=_ca(C["orchid"], "22"), height=1).pack(fill="x")

        spec_tw_wrap = tk.Frame(sl_f, bg=C["panel"])
        spec_tw_wrap.pack(fill="both", expand=True, padx=4, pady=4)

        _spec_cols = ("species", "lineage", "n_total", "vh", "vk", "vl",
                      "kl_ratio", "n_iso", "shannon", "cls")
        stl2 = ttk.Style()
        stl2.configure("CSpec.Treeview", background=C["panel"],
                       foreground=C["txt_dim"], fieldbackground=C["panel"],
                       rowheight=22, font=("Courier New", 8))
        stl2.configure("CSpec.Treeview.Heading",
                       background=_ca(C["orchid"], "1a"),
                       foreground=C["orchid"],
                       font=("Courier New", 8, "bold"))
        stl2.map("CSpec.Treeview",
                 background=[("selected", _ca(C["orchid"], "33"))],
                 foreground=[("selected", C["txt"])])

        self._cs_spec_tree = ttk.Treeview(
            spec_tw_wrap, columns=_spec_cols, show="headings",
            height=14, style="CSpec.Treeview")
        for col_id, w, anch, head in [
            ("species",  152, "w",      "SPECIES"),
            ("lineage",  72,  "center", "LINEAGE"),
            ("n_total",  46,  "center", "IG"),
            ("vh",       40,  "center", "IGHV"),
            ("vk",       40,  "center", "IGKV"),
            ("vl",       40,  "center", "IGLV"),
            ("kl_ratio", 56,  "center", "κ:λ"),
            ("n_iso",    44,  "center", "ISOT"),
            ("shannon",  56,  "center", "H′"),
            ("cls",      120, "w",      "CLASS"),
        ]:
            self._cs_spec_tree.heading(col_id, text=head)
            self._cs_spec_tree.column(col_id, width=w, anchor=anch, stretch=False)

        spec_sb = ttk.Scrollbar(spec_tw_wrap, orient="vertical",
                                command=self._cs_spec_tree.yview)
        self._cs_spec_tree.configure(yscrollcommand=spec_sb.set)
        self._cs_spec_tree.pack(side="left", fill="both", expand=True)
        spec_sb.pack(side="right", fill="y")
        for lin, col_hex in _LINEAGE_COLORS.items():
            self._cs_spec_tree.tag_configure(lin, foreground=col_hex)

        # ── Columna derecha: Jaccard inter-especies (heatmap) + cards ──────────
        sr_f = tk.Frame(spec_two, bg=C["panel"],
                        highlightthickness=1,
                        highlightbackground=_ca(C["orchid"], "22"))
        sr_f.grid(row=0, column=1, sticky="nsew")

        # Mini-cards informativos arriba (core / lineage-specific / V-gene total)
        spec_cards = tk.Frame(sr_f, bg=C["panel"])
        spec_cards.pack(fill="x", padx=4, pady=4)

        def _spec_card(parent, color, glyph, label, attr_name):
            f = tk.Frame(parent, bg=_ca(color, "10"),
                         highlightthickness=1,
                         highlightbackground=_ca(color, "33"))
            f.pack(side="left", fill="both", expand=True, padx=2)
            tk.Label(f, text=f"{glyph}  {label}",
                     bg=_ca(color, "10"), fg=color,
                     font=("Courier New", 7, "bold"),
                     anchor="w").pack(fill="x", padx=6, pady=(4, 0))
            v = tk.Label(f, text="—", bg=_ca(color, "10"), fg=color,
                         font=("Courier New", 12, "bold"), anchor="w")
            v.pack(fill="x", padx=6, pady=(0, 4))
            setattr(self, attr_name, v)

        _spec_card(spec_cards, C["emerald"], "◉", "CORE FAMILIES",   "_cs_card_core")
        _spec_card(spec_cards, C["amber"],   "▲", "LINEAGE-SPEC.",   "_cs_card_linspec")
        _spec_card(spec_cards, C["cyan"],    "◆", "V-GENES TOTAL",   "_cs_card_vtotal")

        # Encabezado Jaccard
        jhdr = tk.Frame(sr_f, bg=_ca(C["orchid"], "0d"))
        jhdr.pack(fill="x", pady=(4, 0))
        tk.Frame(jhdr, bg=C["orchid"], width=3).pack(side="left", fill="y")
        tk.Label(jhdr, text="  Repertoire Jaccard  ·  inter-species similarity",
                 bg=_ca(C["orchid"], "0d"), fg=C["orchid"],
                 font=("Courier New", 9, "bold")).pack(side="left", padx=6, pady=5)
        tk.Frame(sr_f, bg=_ca(C["orchid"], "22"), height=1).pack(fill="x")

        # Frame para el heatmap Jaccard
        self._cs_jacc_frame  = tk.Frame(sr_f, bg=C["panel"])
        self._cs_jacc_frame.pack(fill="both", expand=True, padx=4, pady=4)
        self._cs_jacc_canvas = None
        self._cs_jacc_ph = tk.Label(
            self._cs_jacc_frame,
            text="◎  Inter-species Jaccard\n"
                 "   appears after running the multispecies batch or 🧪 TEST.",
            bg=C["panel"], fg=_ca(C["orchid"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_jacc_ph.place(relx=0.5, rely=0.5, anchor="center")

        # ════════════════ SUB-SECCIÓN ⑤ · COMPOSICIÓN V/D/J/C · H/K/L ═══════════
        # Barras horizontales apiladas: composición del locus IG por especie.
        # Selector que alterna entre eje de SEGMENTOS (V/D/J/C) y eje de CADENAS
        # (IGH/IGK/IGL). Ambas vistas son críticas para diagnóstico repertorial.
        comp_body = self._omics_make_section(
            sec, key="cross_composition",
            title="Repertoire Composition",
            subtitle="Stacked bars · V/D/J/C  ·  IGH/IGK/IGL  ·  per species",
            color=C["teal"], body_height=480, min_h=240, badge="⑤")

        # Barra de modo (segmentos vs cadenas)
        comp_ctrl = tk.Frame(comp_body, bg=_ca(C["teal"], "0d"))
        comp_ctrl.pack(fill="x")
        tk.Label(comp_ctrl, text="  Eje:", bg=_ca(C["teal"], "0d"),
                 fg=C["teal"], font=("Courier New", 8, "bold")
                 ).pack(side="left", padx=(6, 2), pady=3)
        self._cs_comp_mode = tk.StringVar(value="segments")
        for mv, ml in [("segments", "V / D / J / C"),
                       ("chains",   "IGH / IGK / IGL")]:
            tk.Radiobutton(comp_ctrl, text=ml, variable=self._cs_comp_mode,
                           value=mv, bg=_ca(C["teal"], "0d"), fg=C["teal"],
                           selectcolor=_ca(C["teal"], "1a"),
                           activebackground=_ca(C["teal"], "0d"),
                           activeforeground=C["teal"], font=("Courier New", 8),
                           command=lambda: self._cs_refresh_specialized()
                           ).pack(side="left", padx=3)

        self._cs_comp_frame  = tk.Frame(comp_body, bg=C["panel"])
        self._cs_comp_frame.pack(fill="both", expand=True)
        self._cs_comp_canvas = None
        self._cs_comp_ph = tk.Label(
            self._cs_comp_frame,
            text="▦  Repertoire composition  V/D/J/C  ·  IGH/IGK/IGL\n"
                 "   appears after running the multispecies batch or 🧪 TEST.",
            bg=C["panel"], fg=_ca(C["teal"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_comp_ph.place(relx=0.5, rely=0.5, anchor="center")

        # ════════════════ SUB-SECCIÓN ⑥ · ISOTIPOS (REGIÓN CONSTANTE) ═══════════
        # Heatmap log-color de IGHM/IGHD/IGHG/IGHA/IGHE/IGKC/IGLC por especie.
        # Permite identificar de un vistazo qué isotipos están conservados a lo
        # largo de los clados (IgM universal, IgD ausente en aves/reptiles, etc.).
        iso_body = self._omics_make_section(
            sec, key="cross_isotype",
            title="Constant-Region Isotype Map",
            subtitle="IGHM · IGHD · IGHG · IGHA · IGHE · IGKC · IGLC  ·  log-color",
            color=C["amber"], body_height=400, min_h=200, badge="⑥")
        self._cs_iso_frame  = tk.Frame(iso_body, bg=C["panel"])
        self._cs_iso_frame.pack(fill="both", expand=True)
        self._cs_iso_canvas = None
        self._cs_iso_ph = tk.Label(
            self._cs_iso_frame,
            text="◈  Isotype diversity  (constant region)\n"
                 "   appears after running the multispecies batch or 🧪 TEST.",
            bg=C["panel"], fg=_ca(C["amber"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_iso_ph.place(relx=0.5, rely=0.5, anchor="center")

        # ════════════════ SUB-SECCIÓN ⑦ · κ:λ + CADENAS ═════════════════════════
        # DOS plots de cadena ligera en grid 2×1:
        #   Panel A — dot-plot del sesgo κ:λ por especie (log-scale, referencias)
        #   Panel B — scatter log-log H vs L con diagonales 1:1/2:1/1:2.
        kl_body = self._omics_make_section(
            sec, key="cross_chains",
            title="Light Chain Bias & Heavy↔Light Landscape",
            subtitle="κ:λ per species  ·  log-log scatter heavy vs light chain",
            color=C["lavender"], body_height=720, min_h=280, badge="⑦")

        # Layout 2 columnas
        kl_two = tk.Frame(kl_body, bg=C["panel"])
        kl_two.pack(fill="both", expand=True, padx=4, pady=4)
        kl_two.grid_columnconfigure(0, weight=1)
        kl_two.grid_columnconfigure(1, weight=1)
        kl_two.grid_rowconfigure(0, weight=1)

        # Panel A: κ:λ dot-plot
        kla_f = tk.Frame(kl_two, bg=C["panel"],
                         highlightthickness=1,
                         highlightbackground=_ca(C["lavender"], "33"))
        kla_f.grid(row=0, column=0, sticky="nsew", padx=(0, 4))
        tk.Label(kla_f, text="  ◉  κ : λ bias per species",
                 bg=_ca(C["lavender"], "10"), fg=C["lavender"],
                 font=("Courier New", 9, "bold"), anchor="w"
                 ).pack(fill="x")
        tk.Frame(kla_f, bg=_ca(C["lavender"], "22"), height=1).pack(fill="x")
        self._cs_kl_frame  = tk.Frame(kla_f, bg=C["panel"])
        self._cs_kl_frame.pack(fill="both", expand=True)
        self._cs_kl_canvas = None
        self._cs_kl_ph = tk.Label(
            self._cs_kl_frame,
            text="◉  κ : λ  ·  dot-plot log-scale\n"
                 "   with mammalian references",
            bg=C["panel"], fg=_ca(C["lavender"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_kl_ph.place(relx=0.5, rely=0.5, anchor="center")

        # Panel B: scatter H vs L
        klb_f = tk.Frame(kl_two, bg=C["panel"],
                         highlightthickness=1,
                         highlightbackground=_ca(C["lavender"], "33"))
        klb_f.grid(row=0, column=1, sticky="nsew")
        tk.Label(klb_f, text="  ◎  Espacio repertorial  IGH ↔ (IGK + IGL)",
                 bg=_ca(C["lavender"], "10"), fg=C["lavender"],
                 font=("Courier New", 9, "bold"), anchor="w"
                 ).pack(fill="x")
        tk.Frame(klb_f, bg=_ca(C["lavender"], "22"), height=1).pack(fill="x")
        self._cs_chain_frame  = tk.Frame(klb_f, bg=C["panel"])
        self._cs_chain_frame.pack(fill="both", expand=True)
        self._cs_chain_canvas = None
        self._cs_chain_ph = tk.Label(
            self._cs_chain_frame,
            text="◎  Heavy vs light chain\n"
                 "   diagonals 1:1  ·  2:1  ·  1:2",
            bg=C["panel"], fg=_ca(C["lavender"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_chain_ph.place(relx=0.5, rely=0.5, anchor="center")

        # ════════════════ SUB-SECCIÓN ⑧ · PCoA + DENDROGRAMA UPGMA ══════════════
        # Dos visualizaciones complementarias de la distancia Jaccard:
        #   Panel A — PCoA 2D: ordenación con elipses por clado, distancia visual ≈ Jaccard.
        #   Panel B — UPGMA dendrograma: cluster jerárquico del repertorio.
        ord_body = self._omics_make_section(
            sec, key="cross_ordination",
            title="Repertoire Ordination & Hierarchy",
            subtitle="PCoA 2D (Jaccard)  ·  UPGMA dendrogram",
            color=C["sage"], body_height=720, min_h=320, badge="⑧")

        ord_two = tk.Frame(ord_body, bg=C["panel"])
        ord_two.pack(fill="both", expand=True, padx=4, pady=4)
        ord_two.grid_columnconfigure(0, weight=1)
        ord_two.grid_columnconfigure(1, weight=1)
        ord_two.grid_rowconfigure(0, weight=1)

        # Panel A: PCoA
        pcoa_f = tk.Frame(ord_two, bg=C["panel"],
                          highlightthickness=1,
                          highlightbackground=_ca(C["sage"], "33"))
        pcoa_f.grid(row=0, column=0, sticky="nsew", padx=(0, 4))
        tk.Label(pcoa_f, text="  ◆  PCoA 2D  ·  distancia Jaccard",
                 bg=_ca(C["sage"], "10"), fg=C["sage"],
                 font=("Courier New", 9, "bold"), anchor="w"
                 ).pack(fill="x")
        tk.Frame(pcoa_f, bg=_ca(C["sage"], "22"), height=1).pack(fill="x")
        self._cs_pcoa_frame  = tk.Frame(pcoa_f, bg=C["panel"])
        self._cs_pcoa_frame.pack(fill="both", expand=True)
        self._cs_pcoa_canvas = None
        self._cs_pcoa_ph = tk.Label(
            self._cs_pcoa_frame,
            text="◆  PCoA ordination  +  clade ellipses\n"
                 "   requiere ≥3 especies",
            bg=C["panel"], fg=_ca(C["sage"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_pcoa_ph.place(relx=0.5, rely=0.5, anchor="center")

        # Panel B: dendrograma
        dend_f = tk.Frame(ord_two, bg=C["panel"],
                          highlightthickness=1,
                          highlightbackground=_ca(C["sage"], "33"))
        dend_f.grid(row=0, column=1, sticky="nsew")
        tk.Label(dend_f, text="  ⌘  UPGMA  ·  hierarchical clustering",
                 bg=_ca(C["sage"], "10"), fg=C["sage"],
                 font=("Courier New", 9, "bold"), anchor="w"
                 ).pack(fill="x")
        tk.Frame(dend_f, bg=_ca(C["sage"], "22"), height=1).pack(fill="x")
        self._cs_dend_frame  = tk.Frame(dend_f, bg=C["panel"])
        self._cs_dend_frame.pack(fill="both", expand=True)
        self._cs_dend_canvas = None
        self._cs_dend_ph = tk.Label(
            self._cs_dend_frame,
            text="⌘  Dendrograma UPGMA\n"
                 "   agrupamiento por similitud de repertorio",
            bg=C["panel"], fg=_ca(C["sage"], "44"),
            font=("Courier New", 9), justify="center")
        self._cs_dend_ph.place(relx=0.5, rely=0.5, anchor="center")

        # ════════════════ SUB-SECCIÓN ⑨ · DIVERSIDAD + INNOVACIÓN POR CLADO ═════
        # Dos plots independientes:
        #   Panel A — Scatter H′ vs richness (curva de máxima entropía teórica)
        #   Panel B — Barras dobles por clado: NÚCLEO vs INNOVACIONES
        div_body = self._omics_make_section(
            sec, key="cross_diversity_innov",
            title="Diversity & Clade Innovation",
            subtitle="Shannon H′ vs richness  ·  clade core vs innovations",
            color=C.get("rose", C["blush"]), body_height=720, min_h=280, badge="⑨")

        di_two = tk.Frame(div_body, bg=C["panel"])
        di_two.pack(fill="both", expand=True, padx=4, pady=4)
        di_two.grid_columnconfigure(0, weight=1)
        di_two.grid_columnconfigure(1, weight=1)
        di_two.grid_rowconfigure(0, weight=1)

        ROSE = C.get("rose", C["blush"])

        # Panel A: diversidad
        div_f = tk.Frame(di_two, bg=C["panel"],
                         highlightthickness=1,
                         highlightbackground=_ca(ROSE, "33"))
        div_f.grid(row=0, column=0, sticky="nsew", padx=(0, 4))
        tk.Label(div_f, text="  ▲  Diversity  H′  ·  Shannon vs richness",
                 bg=_ca(ROSE, "10"), fg=ROSE,
                 font=("Courier New", 9, "bold"), anchor="w"
                 ).pack(fill="x")
        tk.Frame(div_f, bg=_ca(ROSE, "22"), height=1).pack(fill="x")
        self._cs_div_frame  = tk.Frame(div_f, bg=C["panel"])
        self._cs_div_frame.pack(fill="both", expand=True)
        self._cs_div_canvas = None
        self._cs_div_ph = tk.Label(
            self._cs_div_frame,
            text="▲  Shannon entropy vs family richness\n"
                 "   with theoretical H_max curve",
            bg=C["panel"], fg=_ca(ROSE, "44"),
            font=("Courier New", 9), justify="center")
        self._cs_div_ph.place(relx=0.5, rely=0.5, anchor="center")

        # Panel B: innovación
        inv_f = tk.Frame(di_two, bg=C["panel"],
                         highlightthickness=1,
                         highlightbackground=_ca(ROSE, "33"))
        inv_f.grid(row=0, column=1, sticky="nsew")
        tk.Label(inv_f, text="  ★  Core vs Innovation per clade",
                 bg=_ca(ROSE, "10"), fg=ROSE,
                 font=("Courier New", 9, "bold"), anchor="w"
                 ).pack(fill="x")
        tk.Frame(inv_f, bg=_ca(ROSE, "22"), height=1).pack(fill="x")
        self._cs_innov_frame  = tk.Frame(inv_f, bg=C["panel"])
        self._cs_innov_frame.pack(fill="both", expand=True)
        self._cs_innov_canvas = None
        self._cs_innov_ph = tk.Label(
            self._cs_innov_frame,
            text="★  Clade core families  vs  exclusive innovations\n"
                 "   requiere ≥2 clados en la lista",
            bg=C["panel"], fg=_ca(ROSE, "44"),
            font=("Courier New", 9), justify="center")
        self._cs_innov_ph.place(relx=0.5, rely=0.5, anchor="center")


    # ══════════════════════════════════════════════════════════════════════════════
    #  SECCIÓN 2: CONSERVATION SCORE DISTRIBUTION
    # ══════════════════════════════════════════════════════════════════════════════

    def _build_section_conservation_dist(self):
        """
        Sección de distribución de scores de conservación:
        Histogram / CDF / Boxplot / Violin
        """
        tab = self._tab_omics
        COL = C["lavender"]

        _ext_section_header(
            tab, "◆", "DISTRIBUCIÓN DE SCORES DE CONSERVACIÓN",
            "Per-gene histogram  ·  Cumulative distribution (CDF)  ·  Boxplot / Violin  ·  Percentiles",
            COL)

        body = tk.Frame(tab, bg=C["bg"])
        body.pack(fill="x", padx=12, pady=(8, 4))

        # Controles
        ctrl = tk.Frame(body, bg=C["bg2"],
                        highlightthickness=1,
                        highlightbackground=_ca(COL, "22"))
        ctrl.pack(fill="x", pady=(0, 6))
        ci = tk.Frame(ctrl, bg=C["bg2"])
        ci.pack(fill="x", padx=12, pady=5)

        # Tipo de vista
        tk.Label(ci, text="View:", bg=C["bg2"], fg=C["txt_muted"],
                 font=("Courier New", 8)).pack(side="left")
        self._dist_view_var = tk.StringVar(value="histcdf")
        for val, txt in [("histcdf",  "Hist + CDF"),
                         ("cdf",      "CDF only"),
                         ("boxplot",  "Boxplot"),
                         ("violin",   "Violin")]:
            tk.Radiobutton(ci, text=txt, variable=self._dist_view_var,
                           value=val, bg=C["bg2"], fg=COL,
                           selectcolor=_ca(COL, "22"),
                           activebackground=C["bg2"], activeforeground=COL,
                           font=("Courier New", 8),
                           command=self._dist_refresh).pack(side="left", padx=3)

        tk.Frame(ci, bg=_ca(COL, "33"), width=1).pack(side="left", fill="y", padx=8)

        # Bins
        tk.Label(ci, text="Bins:", bg=C["bg2"], fg=C["txt_muted"],
                 font=("Courier New", 8)).pack(side="left")
        self._dist_bins_var = tk.IntVar(value=20)
        self._dist_bins_lbl = tk.Label(ci, text="20", bg=C["bg2"], fg=COL,
                                        font=("Courier New", 8, "bold"), width=3)
        self._dist_bins_lbl.pack(side="right", padx=(0, 4))
        tk.Scale(ci, from_=5, to=50, resolution=5,
                 orient="horizontal", variable=self._dist_bins_var,
                 bg=C["bg2"], fg=COL, troughcolor=_ca(COL, "22"),
                 highlightthickness=0, sliderrelief="flat",
                 length=120, showvalue=False,
                 command=lambda v: (
                     self._dist_bins_lbl.configure(text=str(int(float(v)))),
                     self._dist_refresh()
                 )).pack(side="right", padx=4)

        # Canvas
        self._dist_outer = tk.Frame(body, bg=C["panel"],
                                     highlightthickness=1,
                                     highlightbackground=_ca(COL, "22"))
        self._dist_outer.pack(fill="x", pady=(0, 10))
        self._dist_outer.configure(height=320)
        self._dist_outer.pack_propagate(False)

        self._dist_mpl_canvas = None
        self._dist_ph = tk.Label(
            self._dist_outer,
            text="◆  Score distribution\n   appears after running OMICS.",
            bg=C["panel"], fg=_ca(COL, "44"),
            font=("Courier New", 9), justify="center")
        self._dist_ph.place(relx=0.5, rely=0.5, anchor="center")


    # ══════════════════════════════════════════════════════════════════════════════
    #  SECCIÓN 3: IG FAMILY BROWSER
    # ══════════════════════════════════════════════════════════════════════════════

    def _build_section_family_browser(self):
        """
        Browser de familias IG:
        Tabla con IGHV/IGHD/IGHJ/IGLV/IGKV... + chart de barras horizontal.
        """
        tab = self._tab_omics
        COL = C["amber"]   # rosa hielo

        _ext_section_header(
            tab, "▲", "IG GENE FAMILY BROWSER",
            "Per-family breakdown IGHV / IGHD / IGHJ / IGLV / IGLC / IGKV  ·  Conservation per segment",
            COL)

        body = tk.Frame(tab, bg=C["bg"])
        body.pack(fill="x", padx=12, pady=(8, 4))

        # Tarjetas
        cards = tk.Frame(body, bg=C["bg"])
        cards.pack(fill="x", pady=(0, 8))

        _ext_mini_card(cards, C["amber"],   "▲", "FAMILIAS",   "_fam_card_n",    self)
        _ext_mini_card(cards, C["violet"],  "◆", "IGHV GENES", "_fam_card_ighv", self)
        _ext_mini_card(cards, C["orchid"],  "◉", "IGLV GENES", "_fam_card_iglv", self)
        _ext_mini_card(cards, C["cyan"],    "◈", "IGKV GENES", "_fam_card_igkv", self)

        # Dos columnas
        two = tk.Frame(body, bg=C["bg"])
        two.pack(fill="x", pady=(0, 8))
        two.grid_columnconfigure(0, weight=0)
        two.grid_columnconfigure(1, weight=1)

        # Tabla
        left = tk.Frame(two, bg=C["panel"],
                        highlightthickness=1,
                        highlightbackground=_ca(COL, "2a"))
        left.grid(row=0, column=0, sticky="nsew", padx=(0, 5))
        left.configure(width=430)
        left.grid_propagate(False)

        fhdr = tk.Frame(left, bg=_ca(COL, "0d"))
        fhdr.pack(fill="x")
        tk.Frame(fhdr, bg=COL, width=3).pack(side="left", fill="y")
        tk.Label(fhdr, text="  Per-family breakdown",
                 bg=_ca(COL, "0d"), fg=COL,
                 font=("Courier New", 9, "bold")).pack(side="left", padx=6, pady=5)
        tk.Frame(fhdr, bg=_ca(COL, "22"), height=1).pack(fill="x")

        fw_wrap = tk.Frame(left, bg=C["panel"])
        fw_wrap.pack(fill="both", expand=True, padx=4, pady=4)

        fam_cols = ("family", "n_genes", "n_orthologs", "mean_cons", "best_sp", "bar")
        stl = ttk.Style()
        stl.configure("FAM.Treeview",
                      background=C["panel"], foreground=C["txt_dim"],
                      fieldbackground=C["panel"],
                      rowheight=22, font=("Courier New", 8))
        stl.configure("FAM.Treeview.Heading",
                      background=_ca(COL, "1a"), foreground=COL,
                      font=("Courier New", 8, "bold"))

        self._fam_tree = ttk.Treeview(fw_wrap, columns=fam_cols,
                                       show="headings", height=12,
                                       style="FAM.Treeview")
        for col, w, anch, head in [
            ("family",    74,  "w",      "FAMILIA"),
            ("n_genes",   54,  "center", "GENES"),
            ("n_orthologs",64, "center", "CON ORTH"),
            ("mean_cons", 72,  "center", "CONS MEDIA"),
            ("best_sp",   100, "w",      "MEJOR ESPECIE"),
            ("bar",       90,  "w",      "COBERTURA"),
        ]:
            self._fam_tree.heading(col, text=head)
            self._fam_tree.column(col, width=w, anchor=anch, stretch=False)

        fam_sb = ttk.Scrollbar(fw_wrap, orient="vertical",
                               command=self._fam_tree.yview)
        self._fam_tree.configure(yscrollcommand=fam_sb.set)
        self._fam_tree.pack(side="left", fill="both", expand=True)
        fam_sb.pack(side="right", fill="y")

        for fam, col_hex in _FAMILY_COLORS.items():
            self._fam_tree.tag_configure(fam, foreground=col_hex)

        # Gráfico
        right = tk.Frame(two, bg=C["panel"],
                         highlightthickness=1,
                         highlightbackground=_ca(COL, "22"))
        right.grid(row=0, column=1, sticky="nsew")

        self._fam_chart_frame  = right
        self._fam_chart_canvas = None
        self._fam_chart_ph = tk.Label(
            right,
            text="▲  Family chart\n   appears after running OMICS.",
            bg=C["panel"], fg=_ca(COL, "44"),
            font=("Courier New", 9), justify="center")
        self._fam_chart_ph.place(relx=0.5, rely=0.5, anchor="center")


    # ══════════════════════════════════════════════════════════════════════════════
    #  SECCIÓN 4: STATISTICAL REPORT & EXPORT CENTER
    # ══════════════════════════════════════════════════════════════════════════════

    def _build_section_stat_report(self):
        """
        Resumen estadístico + centro de exportación.
        """
        tab = self._tab_omics
        COL = C["rose"]

        _ext_section_header(
            tab, "⚡", "REPORTE ESTADÍSTICO & EXPORTACIONES",
            "Welch T · Mann-Whitney U · Chi² · FDR · Percentiles  ·  Exportar CSV / PNG / TXT",
            COL)

        body = tk.Frame(tab, bg=C["bg"])
        body.pack(fill="x", padx=12, pady=(8, 0))

        row = tk.Frame(body, bg=C["bg"])
        row.pack(fill="x", pady=(0, 6))

        # ── Panel texto estadístico ───────────────────────────────────────────────
        txt_f = tk.Frame(row, bg=C["panel"],
                         highlightthickness=1,
                         highlightbackground=_ca(COL, "2a"))
        txt_f.pack(side="left", fill="both", expand=True, padx=(0, 8))

        thdr = tk.Frame(txt_f, bg=_ca(COL, "0d"))
        thdr.pack(fill="x")
        tk.Frame(thdr, bg=COL, width=3).pack(side="left", fill="y")
        tk.Label(thdr, text="  Statistical Summary",
                 bg=_ca(COL, "0d"), fg=COL,
                 font=("Courier New", 9, "bold")).pack(side="left", padx=6, pady=5)
        btn_upd = tk.Frame(thdr, bg=_ca(COL, "22"),
                           highlightthickness=1,
                           highlightbackground=_ca(COL, "44"),
                           cursor="hand2")
        btn_upd.pack(side="right", padx=6, pady=5)
        lbl_upd = tk.Label(btn_upd, text=" ⟳ Actualizar ",
                           bg=_ca(COL, "22"), fg=COL,
                           font=("Courier New", 7, "bold"))
        lbl_upd.pack(pady=2, padx=2)
        for w in (btn_upd, lbl_upd):
            w.bind("<Button-1>", lambda e: self._stat_text_update())

        self._stat_text = tk.Text(
            txt_f, height=14, width=58,
            bg=C["panel"], fg=C["txt_dim"],
            font=("Courier New", 8), relief="flat",
            state="disabled", insertbackground=COL,
            highlightthickness=0,
            selectbackground=_ca(COL, "33"),
            selectforeground=C["txt"])
        self._stat_text.pack(fill="both", expand=True, padx=8, pady=6)

        # Tags de color
        self._stat_text.tag_configure("hdr",
                                       foreground=COL,
                                       font=("Courier New", 9, "bold"))
        self._stat_text.tag_configure("ok",  foreground=C["sage"])
        self._stat_text.tag_configure("val", foreground=C["lavender"])
        self._stat_text.tag_configure("dim", foreground=C["txt_muted"])
        self._stat_text.tag_configure("sp",  foreground=C["orchid"],
                                       font=("Courier New", 8, "italic"))

        # ── Panel de exportes ─────────────────────────────────────────────────────
        exp_f = tk.Frame(row, bg=C["panel"],
                         highlightthickness=1,
                         highlightbackground=_ca(COL, "2a"))
        exp_f.pack(side="right", fill="y")

        ehdr = tk.Frame(exp_f, bg=_ca(COL, "0d"))
        ehdr.pack(fill="x")
        tk.Frame(ehdr, bg=COL, width=3).pack(side="left", fill="y")
        tk.Label(ehdr, text="  Export Center",
                 bg=_ca(COL, "0d"), fg=COL,
                 font=("Courier New", 9, "bold")).pack(side="left", padx=6, pady=5)

        inner_exp = tk.Frame(exp_f, bg=C["panel"])
        inner_exp.pack(fill="both", expand=True, padx=8, pady=6)

        def eb(label, col, cmd):
            f = tk.Frame(inner_exp, bg=_ca(col, "1a"),
                         highlightthickness=1,
                         highlightbackground=_ca(col, "33"),
                         cursor="hand2")
            f.pack(fill="x", pady=2)
            l = tk.Label(f, text=f"  {label}",
                         bg=_ca(col, "1a"), fg=col,
                         font=("Courier New", 8, "bold"), anchor="w")
            l.pack(fill="x", pady=5, padx=8)
            for w in (f, l):
                w.bind("<Button-1>", lambda e, fn=cmd: fn())
                w.bind("<Enter>", lambda e, ff=f, ll=l, c=col:
                       (ff.configure(bg=_ca(c, "33")), ll.configure(bg=_ca(c, "33"))))
                w.bind("<Leave>", lambda e, ff=f, ll=l, c=col:
                       (ff.configure(bg=_ca(c, "1a")), ll.configure(bg=_ca(c, "1a"))))

        eb("⬡  GO/KEGG Enrichment TSV",   C["emerald"], self._omics_export_go)
        eb("◉  Orthology Matrix TSV",      C["orchid"],  self._omics_export_orth)
        eb("◈  Cross Species CSV",         C["cyan"],    lambda: self._export_cs_csv())
        eb("▲  Family Summary CSV",        C["amber"],   lambda: self._export_fam_csv())
        eb("◆  Todas las figuras PNG",     C["lavender"],lambda: self._export_all_pngs())
        eb("📋  Reporte completo TXT",      C["rose"],    lambda: self._export_full_report())

        # Watermark al fondo
        tk.Label(body,
                 text="IGFinder 2.1.1  ·  g:Profiler  ·  Ensembl Compara  ·  OMICS Extension v1.0",
                 bg=C["bg"], fg=_ca(C["cyan"], "33"),
                 font=("Courier New", 8)).pack(anchor="e", pady=(4, 14))


    # ══════════════════════════════════════════════════════════════════════════════
    #  GRÁFICOS MATPLOTLIB
    # ══════════════════════════════════════════════════════════════════════════════

    def _plot_cs_barplot(self, matrix_df, sort_by="conservation", clade="all",
                         threshold=0.0):
        """
        Figura con dos sub-paneles:
          Panel A — barras horizontales por especie (% conservación)
          Panel B — dona de clados
        """
        if matrix_df is None or matrix_df.empty:
            return None

        arr          = matrix_df.values.astype("float32")
        species_list = list(matrix_df.columns)
        per_sp_mean  = arr.mean(axis=0)
        per_sp_n     = (arr > 0).sum(axis=0)
        n_genes      = len(matrix_df)

        cat = getattr(self, "_orth_sp_catalog", {})

        # Construir registros
        records = []
        for i, sp in enumerate(species_list):
            info    = cat.get(sp, {})
            lineage = info.get("lineage", "other")
            records.append(dict(
                raw=sp,
                name=sp.replace("_", " ").title(),
                lineage=lineage,
                mean=float(per_sp_mean[i]),
                n=int(per_sp_n[i]),
            ))

        # Filtros
        _CLADE_MAP = {
            "all":          None,
            "primates":     {"primates"},
            "mammals":      {"primates","rodents","ungulates","carnivores",
                            "marsupials","monotremes"},
            "vertebrates":  {"primates","rodents","ungulates","carnivores",
                            "marsupials","monotremes","birds","reptiles",
                            "fish","amphibians"},
        }
        cset = _CLADE_MAP.get(clade)
        if cset:
            records = [r for r in records if r["lineage"] in cset]
        records = [r for r in records if r["mean"] >= threshold]
        if not records:
            return None

        # Ordenamiento
        _PHYLO = {"fish":0,"amphibians":1,"reptiles":2,"birds":3,
                  "marsupials":4,"monotremes":5,"rodents":6,"ungulates":7,
                  "carnivores":8,"primates":9}
        key_fn = {
            "conservation": lambda r: r["mean"],
            "n_genes":      lambda r: r["n"],
            "phylo":        lambda r: _PHYLO.get(r["lineage"], 5),
            "name":         lambda r: r["name"],
        }.get(sort_by, lambda r: r["mean"])
        records.sort(key=key_fn)

        names  = [r["name"]    for r in records]
        means  = [r["mean"]    for r in records]
        counts = [r["n"]       for r in records]
        colors = [_LINEAGE_COLORS.get(r["lineage"], "#5248a0") for r in records]

        # Figura
        n = len(records)
        fig_h = max(4.5, n * 0.42 + 1.5)
        fig = _mpl_dark_fig(width=10, height=fig_h)
        gs  = gridspec.GridSpec(
            1, 2, figure=fig, width_ratios=[2.8, 1],
            wspace=0.32, left=0.18, right=0.97,
            top=0.91, bottom=0.10)

        # ── Panel A: barras ───────────────────────────────────────────────────────
        ax_a = fig.add_subplot(gs[0])
        _mpl_style_ax(ax_a)

        y = np.arange(n)
        ax_a.barh(y, means, color=colors, height=0.68, alpha=0.88, zorder=3)

        for i, (val, cnt) in enumerate(zip(means, counts)):
            if val >= 0.04:
                ax_a.text(val + 0.012, i, f"{val:.1%}  n={cnt:,}",
                          va="center", ha="left", fontsize=6.5,
                          color=_MPL_TXT, zorder=4)

        ax_a.set_yticks(y)
        ax_a.set_yticklabels(names, fontsize=7.5, color=_MPL_TXT,
                              fontstyle="italic")
        ax_a.set_xlim(0, 1.22)
        ax_a.set_xlabel("Mean conservation score", fontsize=8)
        ax_a.set_title("Conservation per Species", fontsize=9, pad=6)
        ax_a.axvline(0.5, color="#f8d0ee", lw=1, ls="--", alpha=0.5, zorder=2)
        ax_a.text(0.5, -0.8, "50 %", color="#f8d0ee", fontsize=6.5, ha="center")

        # ── Panel B: dona de linajes ───────────────────────────────────────────────
        from collections import Counter
        ax_b = fig.add_subplot(gs[1])
        ax_b.set_facecolor(_MPL_PANEL)
        lin_ct = Counter(r["lineage"] for r in records)
        lbls   = list(lin_ct.keys())
        szs    = list(lin_ct.values())
        cols_p = [_LINEAGE_COLORS.get(l, "#5248a0") for l in lbls]

        wedges, texts, autotexts = ax_b.pie(
            szs, labels=lbls, colors=cols_p,
            autopct="%1.0f%%", startangle=90,
            pctdistance=0.72,
            wedgeprops={"width": 0.55,
                        "edgecolor": _MPL_BG, "linewidth": 1.5})
        for t in texts:
            t.set_color(_MPL_TXTS)
            t.set_fontsize(7)
        for at in autotexts:
            at.set_color("#f0e8ff")
            at.set_fontsize(6.5)
        ax_b.set_title("Lineages", fontsize=9, color=_MPL_TXT, pad=6)

        fig.suptitle(
            f"Cross Species Analysis  ·  {n} species  ·  {n_genes:,} IG genes",
            fontsize=10, color=C["cyan"], y=0.97,
            fontfamily="monospace")

        return fig


    def _plot_cs_heatmap(self, fam_df, mode="heatmap"):
        """Heatmap o burbuja de familia IG × especie."""
        if fam_df is None or fam_df.empty:
            return None

        data  = fam_df.values
        rows  = list(fam_df.index)
        cols  = list(fam_df.columns)
        nr, nc = len(rows), len(cols)

        fig_h  = max(3.5, nr * 0.55 + 1.5)
        fig    = _mpl_dark_fig(width=max(12, nc * 0.65 + 2.5), height=fig_h)
        ax     = fig.add_subplot(111)
        _mpl_style_ax(ax)

        if mode == "heatmap":
            cmap = matplotlib.colors.LinearSegmentedColormap.from_list(
                "igf_heatmap",
                [_MPL_BG, "#5248a0", "#da70d6", "#f0b8e8", "#f0e8ff"])
            im = ax.imshow(data, cmap=cmap, aspect="auto", vmin=0, vmax=1, zorder=2)
            for i in range(nr):
                for j in range(nc):
                    v = data[i, j]
                    if v > 0.03:
                        ax.text(j, i, f"{v:.0%}", ha="center", va="center",
                                fontsize=6, color="white" if v < 0.7 else _MPL_BG,
                                zorder=3)
            cb = fig.colorbar(im, ax=ax, fraction=0.02, pad=0.015)
            cb.ax.tick_params(colors=_MPL_TXTS, labelsize=7)
            cb.set_label("Conserved fraction", color=_MPL_TXT, fontsize=7)

        else:  # bubble
            for i in range(nr):
                for j in range(nc):
                    v = data[i, j]
                    if v > 0.01:
                        sz = (v ** 0.65) * 900
                        col = matplotlib.cm.get_cmap("magma")(0.2 + v * 0.7)
                        ax.scatter(j, i, s=sz, color=[col], alpha=0.75,
                                   edgecolors=_MPL_GRID, linewidths=0.5, zorder=3)

        ax.set_xticks(np.arange(nc))
        ax.set_xticklabels([c.replace("_"," ")[:12] for c in cols],
                            rotation=45, ha="right",
                            fontsize=7, color=_MPL_TXTS, fontstyle="italic")
        ax.set_yticks(np.arange(nr))
        ax.set_yticklabels(rows, fontsize=8, color=C["orchid"],
                            fontfamily="monospace")
        ax.tick_params(colors=_MPL_TXTS)

        fig.suptitle(
            f"IG Family × Species Conservation Matrix  ·  {mode.capitalize()}",
            fontsize=9, color=C["teal"], y=1.01, fontfamily="monospace")
        fig.tight_layout(rect=[0, 0, 1, 0.98])
        return fig


    def _plot_dist(self, matrix_df, bins=20, view="histcdf"):
        """Histogram / CDF / Boxplot / Violin of conservation scores."""
        if matrix_df is None or matrix_df.empty:
            return None

        arr       = matrix_df.values.astype("float32")
        gene_means = arr.mean(axis=1)
        n_genes    = len(gene_means)

        fig = _mpl_dark_fig(width=11, height=3.8)

        if view == "histcdf":
            gs = gridspec.GridSpec(1, 2, figure=fig, wspace=0.28,
                                   left=0.08, right=0.97, top=0.87, bottom=0.14)
            ax1 = fig.add_subplot(gs[0])
            _mpl_style_ax(ax1)
            n_arr, bins_arr, patches = ax1.hist(
                gene_means, bins=bins, color=C["cyan"],
                alpha=0.8, edgecolor=_MPL_BG, linewidth=0.5, zorder=3)
            # Colorear por valor
            norm = matplotlib.colors.Normalize(vmin=bins_arr[0], vmax=bins_arr[-1])
            cmap_h = matplotlib.cm.get_cmap("magma")
            for patch, xval in zip(patches, bins_arr[:-1]):
                patch.set_facecolor(cmap_h(norm(xval + (bins_arr[1]-bins_arr[0])/2)))
            m = gene_means.mean()
            ax1.axvline(m, color=C["gold"], lw=1.5, ls="--", label=f"mean={m:.3f}", zorder=4)
            ax1.legend(fontsize=7, facecolor=_MPL_PANEL, edgecolor=_MPL_GRID,
                       labelcolor=_MPL_TXT)
            ax1.set_xlabel("Mean conservation score (per gene)", fontsize=8)
            ax1.set_ylabel("N genes", fontsize=8)
            ax1.set_title("Distribution", fontsize=9, pad=5)

            ax2 = fig.add_subplot(gs[1])
            _mpl_style_ax(ax2)
            sv  = np.sort(gene_means)
            cdf = np.arange(1, n_genes + 1) / n_genes
            ax2.plot(sv, cdf, color=C["orchid"], lw=2.2, zorder=3)
            ax2.fill_between(sv, cdf, alpha=0.13, color=C["orchid"], zorder=2)
            ax2.axhline(0.5, color=C["gold"], lw=1, ls=":", alpha=0.6)
            for q, qcol in [(0.25, C["lavender"]), (0.75, C["teal"])]:
                idx = np.searchsorted(cdf, q)
                if idx < len(sv):
                    ax2.axvline(sv[idx], color=qcol, lw=1, ls=":",
                                alpha=0.7, label=f"Q{int(q*100)}={sv[idx]:.2f}")
            ax2.legend(fontsize=7, facecolor=_MPL_PANEL, edgecolor=_MPL_GRID,
                       labelcolor=_MPL_TXT)
            ax2.set_xlabel("Conservation score", fontsize=8)
            ax2.set_ylabel("Cumulative fraction", fontsize=8)
            ax2.set_title("Cumulative Distribution (CDF)", fontsize=9, pad=5)

        elif view == "cdf":
            ax = fig.add_subplot(111)
            _mpl_style_ax(ax)
            sv  = np.sort(gene_means)
            cdf = np.arange(1, n_genes + 1) / n_genes
            ax.plot(sv, cdf, color=C["orchid"], lw=2.5, zorder=3)
            ax.fill_between(sv, cdf, alpha=0.15, color=C["orchid"], zorder=2)
            ax.axhline(0.5, color=C["gold"], lw=1, ls="--", alpha=0.7)
            for q, qc, ql in [
                (0.25, C["lavender"], "Q25"),
                (0.50, "#ffd700",     "Mediana"),
                (0.75, C["teal"],     "Q75"),
            ]:
                idx = np.searchsorted(cdf, q)
                if idx < len(sv):
                    ax.axvline(sv[idx], color=qc, lw=1.2, ls=":",
                               label=f"{ql}={sv[idx]:.3f}")
            ax.legend(fontsize=7.5, facecolor=_MPL_PANEL, edgecolor=_MPL_GRID,
                      labelcolor=_MPL_TXT)
            ax.set_xlabel("Conservation score", fontsize=8)
            ax.set_ylabel("Cumulative fraction", fontsize=8)
            ax.set_title("CDF — Conservation Scores", fontsize=9)

        elif view == "boxplot":
            ax = fig.add_subplot(111)
            _mpl_style_ax(ax)
            bp = ax.boxplot([gene_means], vert=True, patch_artist=True,
                            widths=0.4, zorder=3)
            for patch in bp["boxes"]:
                patch.set(facecolor=_ca(C["cyan"], "33"),
                          linewidth=1.5, edgecolor=C["cyan"])
            for elem in ["whiskers", "caps"]:
                for line in bp[elem]:
                    line.set(color=C["cyan"], linewidth=1.2)
            bp["medians"][0].set(color=C["gold"], linewidth=2.5)
            for fl in bp["fliers"]:
                fl.set(marker="o", color=C["rose"], alpha=0.5, markersize=4)
            ax.set_xticks([1])
            ax.set_xticklabels([f"Genes IG  (n={n_genes:,})"])
            ax.set_ylabel("Conservation score", fontsize=8)
            ax.set_title("Boxplot — Per-gene conservation", fontsize=9)
            stats = [f"Min={gene_means.min():.3f}",
                     f"Q25={np.percentile(gene_means,25):.3f}",
                     f"Med={np.median(gene_means):.3f}",
                     f"Q75={np.percentile(gene_means,75):.3f}",
                     f"Max={gene_means.max():.3f}"]
            ax.text(1.42, (gene_means.min()+gene_means.max())/2,
                    "\n".join(stats), fontsize=7, color=_MPL_TXT,
                    va="center", ha="left")

        elif view == "violin":
            ax = fig.add_subplot(111)
            _mpl_style_ax(ax)
            parts = ax.violinplot([gene_means], positions=[1],
                                  showmedians=True, showextrema=True)
            for pc in parts.get("bodies", []):
                pc.set_facecolor(_ca(C["orchid"], "44"))
                pc.set_edgecolor(C["orchid"])
                pc.set_linewidth(1.5)
            if "cmedians" in parts:
                parts["cmedians"].set_color("#ffd700")
                parts["cmedians"].set_linewidth(2)
            ax.set_xticks([1])
            ax.set_xticklabels([f"Genes IG  (n={n_genes:,})"])
            ax.set_ylabel("Conservation score", fontsize=8)
            ax.set_title("Violin — Per-gene conservation", fontsize=9)

        fig.suptitle("Distribution of Conservation Scores",
                     fontsize=10, color=C["lavender"],
                     fontfamily="monospace")
        return fig


    def _plot_family_bars(self, matrix_df, ig_df=None):
        """Barras horizontales por familia IG."""
        if matrix_df is None or matrix_df.empty:
            return None

        _FAM_RE = _re.compile(
            r"^(IGH[VDJACE]|IGL[VJCE]|IGK[VJC]|IG[HJKL][A-Z]?)",
            _re.IGNORECASE)

        fam_scores = {}
        for gid in matrix_df.index:
            m = _FAM_RE.match(str(gid))
            fam = m.group(1).upper() if m else "OTHER"
            gene_mean = float(matrix_df.loc[gid].values.mean())
            fam_scores.setdefault(fam, []).append(gene_mean)

        if not fam_scores:
            return None

        fams   = sorted(fam_scores.keys())
        means  = [float(np.mean(fam_scores[f])) for f in fams]
        counts = [len(fam_scores[f])            for f in fams]
        colors = [_FAMILY_COLORS.get(f, "#5248a0") for f in fams]

        fig_h = max(3.5, len(fams) * 0.55 + 1.5)
        fig   = _mpl_dark_fig(width=9, height=fig_h)
        ax    = fig.add_subplot(111)
        _mpl_style_ax(ax)

        y = np.arange(len(fams))
        ax.barh(y, means, color=colors, height=0.62, alpha=0.87, zorder=3)

        for i, (val, cnt) in enumerate(zip(means, counts)):
            ax.text(val + 0.012, i, f"{val:.1%}  n={cnt}",
                    va="center", ha="left", fontsize=7, color=_MPL_TXT, zorder=4)

        ax.set_yticks(y)
        ax.set_yticklabels(fams, fontsize=8.5, color=C["amber"],
                            fontfamily="monospace", fontweight="bold")
        ax.set_xlim(0, 1.3)
        ax.set_xlabel("Mean conservation score", fontsize=8)
        ax.set_title("Conservation per IG Family", fontsize=9, pad=6)
        ax.axvline(0.5, color=_ca(C["amber"], "66"), lw=1.2,
                   ls="--", alpha=0.5, zorder=2)

        fig.suptitle("IG Gene Family Browser",
                     fontsize=10, color=C["amber"],
                     fontfamily="monospace")
        fig.tight_layout(rect=[0, 0, 1, 0.93])
        return fig


    # ══════════════════════════════════════════════════════════════════════════════
    #  PLOT AVANZADO  —  Perfil de conservación por clado filogenético
    # ══════════════════════════════════════════════════════════════════════════════

    def _plot_cs_jaccard(self, jacc_df):
        """
        Heatmap simétrico de la similitud Jaccard inter-especies sobre el set
        de familias IG presentes en cada genoma. Útil para identificar parejas
        de especies con repertorios IG concordantes (típicamente del mismo clado)
        vs divergentes.
        """
        if jacc_df is None or getattr(jacc_df, "empty", True):
            return None
        arr  = jacc_df.values.astype("float32")
        sps  = list(jacc_df.index)
        n    = len(sps)
        if n == 0:
            return None

        fig_side = max(6.0, 0.36 * n + 2.5)
        fig = _mpl_dark_fig(width=fig_side, height=fig_side * 0.95)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)
        ax.set_facecolor(_MPL_PANEL)

        cmap = matplotlib.colors.LinearSegmentedColormap.from_list(
            "cs_jacc", ["#1a0f2b", "#5248a0", "#da70d6", "#ffd700"])

        im = ax.imshow(arr, cmap=cmap, vmin=0.0, vmax=1.0, aspect="equal")
        ax.set_xticks(range(n))
        ax.set_yticks(range(n))
        short = [s.replace("_", " ").title()[:18] for s in sps]
        ax.set_xticklabels(short, rotation=70, ha="right",
                           fontsize=6.5, color=_MPL_TXT, fontstyle="italic")
        ax.set_yticklabels(short, fontsize=6.5, color=_MPL_TXT, fontstyle="italic")
        ax.set_title("IG family Jaccard  ·  inter-species similarity",
                     fontsize=9, color=_MPL_TXT, pad=6)

        # Anotar la diagonal y los valores >= 0.85 para identificar parejas top
        if n <= 30:
            for i in range(n):
                for j in range(n):
                    v = arr[i, j]
                    if i == j:
                        continue
                    if v >= 0.85:
                        ax.text(j, i, f"{v:.2f}", ha="center", va="center",
                                fontsize=5.5, color=C["gold"])

        cb = fig.colorbar(im, ax=ax, fraction=0.035, pad=0.02)
        cb.set_label("Jaccard", color=_MPL_TXT, fontsize=7.5)
        cb.ax.tick_params(colors=_MPL_TXTS, labelsize=6.5)

        fig.tight_layout()
        return fig


    # ─────────────────────────────────────────────────────────────────────────────
    #  PLOTS AVANZADOS — Composición, isotipos, sesgo κ:λ, paisaje del repertorio
    # ─────────────────────────────────────────────────────────────────────────────

    def _plot_cs_vdjc_composition(self, spec, mode="segments"):
        """
        Barras horizontales apiladas mostrando la composición del repertorio IG
        de cada especie.

        mode = "segments" → V / D / J / C   (eje funcional del locus)
        mode = "chains"   → IGH / IGK / IGL (eje de cadenas)

        Ordena por nº total de genes IG (descendente). Útil para identificar de
        un vistazo especies VH-rich, κ-only, sin segmentos D, etc.
        """
        if not spec:
            return None
        per_sp = spec.get("per_species") or {}
        if not per_sp:
            return None

        sps = sorted(per_sp.keys(),
                     key=lambda s: -per_sp[s].get("n_total", 0))
        # Limita a 60 especies para legibilidad (extra van en una nota)
        overflow = max(0, len(sps) - 60)
        sps = sps[:60]

        if mode == "chains":
            comp = ["n_heavy", "n_kappa", "n_lambda"]
            comp_lbl = ["IGH", "IGK", "IGL"]
            comp_col = ["#da70d6", "#ffd700", "#80d8e8"]
            ttl = "Composition by CHAIN  ·  IGH / IGK / IGL"
        else:
            comp = ["n_v", "n_d", "n_j", "n_c"]
            comp_lbl = ["V", "D", "J", "C"]
            comp_col = ["#da70d6", "#b18fe8", "#80d8e8", "#ffd700"]
            ttl = "Composition by SEGMENT  ·  V / D / J / C"

        n = len(sps)
        fig_h = max(3.5, 0.24 * n + 1.2)
        fig = _mpl_dark_fig(width=11, height=fig_h)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)

        y = np.arange(n)
        # Tomar valores absolutos y normalizarlos por especie para que cada barra
        # llegue a 100% — facilita comparar PROPORCIONES (la pestaña ranking ya
        # muestra magnitudes absolutas).
        raw = np.zeros((n, len(comp)), dtype="float64")
        for i, sp in enumerate(sps):
            m = per_sp.get(sp, {})
            for k, key in enumerate(comp):
                raw[i, k] = float(m.get(key, 0))
        row_sum = raw.sum(axis=1, keepdims=True)
        row_sum[row_sum == 0] = 1.0
        pct = raw / row_sum * 100.0

        left = np.zeros(n)
        for k, (lbl, col) in enumerate(zip(comp_lbl, comp_col)):
            ax.barh(y, pct[:, k], left=left, color=col, height=0.74,
                    alpha=0.92, zorder=3,
                    label=lbl, edgecolor=_MPL_BG, linewidth=0.5)
            # Anotaciones dentro de cada segmento si ocupa ≥10%
            for i, v in enumerate(pct[:, k]):
                if v >= 10:
                    ax.text(left[i] + v / 2, i, f"{v:.0f}",
                            ha="center", va="center", fontsize=5.5,
                            color="#1a0f2b", fontweight="bold", zorder=4)
            left += pct[:, k]

        # Etiquetas con conteo total a la derecha
        totals = raw.sum(axis=1).astype(int)
        for i, t in enumerate(totals):
            ax.text(102, i, f"  n={t:,}", va="center", ha="left",
                    fontsize=6.5, color=_MPL_TXTS)

        ax.set_yticks(y)
        short = [s.replace("_", " ").title()[:24] for s in sps]
        ax.set_yticklabels(short, fontsize=7, color=_MPL_TXT, fontstyle="italic")
        ax.invert_yaxis()
        ax.set_xlim(0, 118)
        ax.set_xticks([0, 25, 50, 75, 100])
        ax.set_xlabel("Repertoire fraction (%)", fontsize=8)
        ax.set_title(ttl, fontsize=9.5, color=C["orchid"], pad=6,
                     fontfamily="monospace")
        leg = ax.legend(loc="lower right", fontsize=7, framealpha=0.85,
                        facecolor=_MPL_PANEL, edgecolor=_MPL_GRID, ncol=len(comp_lbl))
        for t in leg.get_texts(): t.set_color(_MPL_TXT)

        if overflow:
            fig.text(0.99, 0.01,
                     f"+ {overflow} additional species not shown",
                     ha="right", color=_MPL_TXTS, fontsize=6.5, fontstyle="italic")

        fig.tight_layout()
        return fig


    def _plot_cs_isotype(self, spec):
        """
        Heatmap de la región constante (isotipos) por especie:
        IGHM · IGHD · IGHG · IGHA · IGHE · IGKC · IGLC.

        Es lo que define funcionalmente las clases de Ig: la presencia/ausencia
        de cada isotipo es altamente diagnóstica del clado (peces sin IgD/IgG,
        aves con IgY en vez de IgG, mamíferos placentarios con todo el set, etc.).
        """
        if not spec:
            return None
        iso_df = spec.get("isotype_df")
        if iso_df is None or getattr(iso_df, "empty", True):
            return None

        arr  = iso_df.values.astype("float32")
        rows = list(iso_df.index)
        cols = list(iso_df.columns)
        nr, nc = len(rows), len(cols)
        if nr == 0 or nc == 0:
            return None

        fig_w = max(9.0, nc * 0.36 + 2.5)
        fig_h = max(3.0, nr * 0.55 + 1.5)
        fig = _mpl_dark_fig(width=fig_w, height=fig_h)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)

        # Normalización: log1p para no aplastar isotipos raros (IgE)
        arr_log = np.log1p(arr)
        cmap = matplotlib.colors.LinearSegmentedColormap.from_list(
            "cs_iso", ["#1a0f2b", "#5248a0", "#da70d6", "#ffd700"])

        im = ax.imshow(arr_log, cmap=cmap, aspect="auto",
                       vmin=0, vmax=max(1.0, arr_log.max()))
        ax.set_xticks(range(nc))
        ax.set_yticks(range(nr))
        short = [c.replace("_", " ").title()[:18] for c in cols]
        ax.set_xticklabels(short, rotation=70, ha="right",
                           fontsize=6.5, color=_MPL_TXT, fontstyle="italic")
        ax.set_yticklabels(rows, fontsize=8, color=C["orchid"], fontweight="bold")
        ax.set_title("CONSTANT Region Diversity  ·  isotypes per species",
                     fontsize=9.5, color=C["orchid"], pad=6,
                     fontfamily="monospace")

        # Anotar el conteo real (no log) cuando el panel es manejable
        if nc <= 30 and nr <= 10:
            for i in range(nr):
                for j in range(nc):
                    v = int(arr[i, j])
                    if v > 0:
                        ax.text(j, i, f"{v}", ha="center", va="center",
                                fontsize=5.5, color="#f0e8ff", fontweight="bold")

        cb = fig.colorbar(im, ax=ax, fraction=0.035, pad=0.02)
        cb.set_label("log(1 + n)", color=_MPL_TXT, fontsize=7.5)
        cb.ax.tick_params(colors=_MPL_TXTS, labelsize=6.5)
        fig.tight_layout()
        return fig


    def _plot_cs_kappa_lambda(self, spec, cat=None):
        """
        Dot-plot del sesgo κ:λ por especie con escala logarítmica.

        Cada especie es un punto coloreado por clado; las barras horizontales
        muestran el rango del clado. Referencias verticales: humano (~1.5),
        ratón (~20), pez óseo típico (sólo λ). Especies κ-only aparecen en el
        extremo derecho; λ-only en el izquierdo.
        """
        if not spec:
            return None
        per_sp = spec.get("per_species") or {}
        if not per_sp:
            return None

        # Construir registros: (sp, lineage, log_kl, marker)
        recs = []
        for sp, m in per_sp.items():
            n_k = int(m.get("n_kappa", 0))
            n_l = int(m.get("n_lambda", 0))
            if n_k == 0 and n_l == 0:
                continue
            if n_k > 0 and n_l == 0:
                log_kl = +3.5   # κ-only, fuera de escala (extremo derecho)
                tag    = "κ-only"
            elif n_l > 0 and n_k == 0:
                log_kl = -3.5
                tag    = "λ-only"
            else:
                log_kl = float(np.log10(n_k / n_l))
                tag    = "κ/λ"
            lin = (cat or {}).get(sp, {}).get("lineage") or _infer_lineage(sp)
            recs.append((sp, lin, log_kl, tag, n_k, n_l))

        if not recs:
            return None

        # Ordenar por log_kl ascendente (más λ-dominante arriba)
        recs.sort(key=lambda r: r[2])

        n = len(recs)
        fig_h = max(3.5, 0.22 * n + 1.5)
        fig = _mpl_dark_fig(width=10, height=fig_h)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)

        y = np.arange(n)
        for i, (sp, lin, log_kl, tag, nk, nl) in enumerate(recs):
            col = _LINEAGE_COLORS.get(lin, "#5248a0")
            marker = "X" if tag != "κ/λ" else "o"
            ax.scatter([log_kl], [i], s=60, c=col, marker=marker,
                       edgecolor=_MPL_BG, linewidth=0.8, zorder=4,
                       alpha=0.95)
            if tag != "κ/λ":
                ax.text(log_kl + (0.15 if log_kl > 0 else -0.15), i,
                        tag, ha="left" if log_kl > 0 else "right",
                        va="center", fontsize=6, color=col,
                        fontweight="bold")
            else:
                ax.text(log_kl + 0.12, i, f"  {nk}:{nl}", ha="left",
                        va="center", fontsize=6, color=_MPL_TXTS)

        # Línea vertical en log_kl = 0 (equilibrio)
        ax.axvline(0, color="#f8d0ee", lw=1.2, ls="--", alpha=0.6, zorder=2)
        ax.text(0, n + 0.5, "κ:λ = 1:1", color="#f8d0ee", fontsize=7,
                ha="center", fontstyle="italic")
        # Referencias mamíferos típicos (log10 valores)
        refs = [(np.log10(1.5),  "human≈1.5",  "#a8e8d0"),
                (np.log10(20.0), "mouse≈20:1",  "#ffd700"),
                (np.log10(0.05), "cow≈1:20",   "#ffb3d1")]
        for x, lab, lc in refs:
            ax.axvline(x, color=lc, lw=0.8, ls=":", alpha=0.5, zorder=1)
            ax.text(x, -0.7, lab, color=lc, fontsize=6, ha="center",
                    fontstyle="italic")

        ax.set_yticks(y)
        short = [r[0].replace("_", " ").title()[:24] for r in recs]
        ax.set_yticklabels(short, fontsize=7, color=_MPL_TXT, fontstyle="italic")
        ax.set_xlim(-4, 4)
        ax.set_xticks([-3, -2, -1, 0, 1, 2, 3])
        ax.set_xticklabels(["10⁻³", "10⁻²", "10⁻¹", "1",
                            "10¹", "10²", "10³"], fontsize=7)
        ax.set_xlabel("log₁₀(κ / λ)", fontsize=8)
        ax.set_title("Light-chain bias  ·  κ : λ per species",
                     fontsize=9.5, color=C["orchid"], pad=8,
                     fontfamily="monospace")

        fig.tight_layout()
        return fig


    def _plot_cs_pcoa(self, spec, cat=None):
        """
        PCoA 2D del repertorio IG entre especies a partir de la distancia
        Jaccard. Cada punto = una especie, coloreado por clado. Las elipses
        (centroide + std) muestran la cohesión del clado.
        """
        if not spec:
            return None
        coords = spec.get("pcoa_coords")
        if coords is None or getattr(coords, "empty", True):
            return None

        sps = list(coords.index)
        if len(sps) < 3:
            return None

        xs = coords["PCo1"].values
        ys = coords["PCo2"].values
        var = spec.get("pcoa_variance") or (0.0, 0.0)

        # Asignar clado a cada punto
        cat = cat or {}
        clades = [
            (cat.get(sp, {}) or {}).get("lineage") or _infer_lineage(sp)
            for sp in sps
        ]
        cols = [_LINEAGE_COLORS.get(c, "#5248a0") for c in clades]

        fig = _mpl_dark_fig(width=8.5, height=6.5)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)

        # Elipses por clado (centroide + std). Sólo para clados con ≥3 puntos.
        from collections import defaultdict
        pts_by_clade = defaultdict(list)
        for x, y, c in zip(xs, ys, clades):
            pts_by_clade[c].append((x, y))

        for clade, pts in pts_by_clade.items():
            if len(pts) < 3:
                continue
            arr_c = np.asarray(pts)
            cx, cy = arr_c.mean(axis=0)
            sx, sy = arr_c.std(axis=0) * 1.4 + 1e-6
            col = _LINEAGE_COLORS.get(clade, "#5248a0")
            from matplotlib.patches import Ellipse
            e = Ellipse((cx, cy), 2 * sx, 2 * sy,
                        facecolor=_ca(col, "22"), edgecolor=col,
                        linewidth=1.0, alpha=0.45, zorder=1)
            ax.add_patch(e)
            ax.text(cx, cy, clade, color=col, fontsize=7.5,
                    fontweight="bold", ha="center", va="center",
                    alpha=0.85, zorder=3)

        # Puntos
        ax.scatter(xs, ys, c=cols, s=80, edgecolor=_MPL_BG,
                   linewidth=0.8, alpha=0.92, zorder=4)

        # Etiqueta de cada especie en pequeño (si <= 40)
        if len(sps) <= 40:
            for x, y, sp in zip(xs, ys, sps):
                label = sp.replace("_", " ").title()[:18]
                ax.annotate(label, (x, y), xytext=(4, 3),
                            textcoords="offset points", fontsize=5.5,
                            color=_MPL_TXTS, fontstyle="italic",
                            alpha=0.85, zorder=5)

        ax.axhline(0, color=_MPL_GRID, lw=0.6, ls=":", alpha=0.6)
        ax.axvline(0, color=_MPL_GRID, lw=0.6, ls=":", alpha=0.6)
        ax.set_xlabel(f"PCo1  ({var[0]*100:.1f}% var.)",
                      fontsize=8, color=_MPL_TXT)
        ax.set_ylabel(f"PCo2  ({var[1]*100:.1f}% var.)",
                      fontsize=8, color=_MPL_TXT)
        ax.set_title(
            f"IG repertoire PCoA  ·  Jaccard distance  ·  {len(sps)} species",
            fontsize=10, color=C["orchid"], pad=6, fontfamily="monospace")

        fig.tight_layout()
        return fig


    def _plot_cs_dendrogram(self, spec, cat=None):
        """
        Dendrograma UPGMA construido a partir de la distancia Jaccard entre
        repertorios. Cuando el árbol del repertorio refleja la filogenia real,
        es señal de que la composición familiar IG conserva señal evolutiva.
        """
        if not spec:
            return None
        link = spec.get("upgma_linkage")
        sps  = spec.get("species_order") or []
        if link is None or len(sps) < 3:
            return None

        try:
            from scipy.cluster.hierarchy import dendrogram as _dendro
        except Exception:
            return None

        cat = cat or {}
        short_labels = [s.replace("_", " ").title()[:24] for s in sps]

        n = len(sps)
        fig_w = max(8.0, 0.28 * n + 3.5)
        fig = _mpl_dark_fig(width=fig_w, height=5.6)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)

        ddata = _dendro(link, labels=short_labels,
                        leaf_rotation=80, leaf_font_size=7,
                        color_threshold=0.5, ax=ax,
                        above_threshold_color="#b18fe8")
        # Colorear las hojas según clado
        leaves = ddata.get("ivl", [])
        leaf_to_idx = {lbl: i for i, lbl in enumerate(leaves)}
        xt = ax.get_xticklabels()
        for txt in xt:
            lbl = txt.get_text()
            idx = leaf_to_idx.get(lbl, -1)
            if 0 <= idx < len(sps):
                sp = sps[short_labels.index(lbl)] if lbl in short_labels else None
                if sp:
                    lin = (cat.get(sp, {}) or {}).get("lineage") or _infer_lineage(sp)
                    txt.set_color(_LINEAGE_COLORS.get(lin, "#da70d6"))
                    txt.set_fontstyle("italic")

        ax.set_title("UPGMA dendrogram  ·  clustering by Jaccard similarity",
                     fontsize=10, color=C["orchid"], pad=6,
                     fontfamily="monospace")
        ax.set_ylabel("Distance (1 − Jaccard)", fontsize=8, color=_MPL_TXT)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)

        fig.tight_layout()
        return fig


    def _plot_cs_diversity(self, spec, cat=None):
        """
        Scatter de DIVERSIDAD: Shannon entropy (H′) vs riqueza familiar
        (n. de familias IG distintas). Cada punto = una especie, coloreado por
        clado. Curva de referencia: H′_max = log2(richness), la entropía
        máxima posible para esa riqueza (repartición uniforme).
        """
        if not spec:
            return None
        per_sp = spec.get("per_species") or {}
        if not per_sp:
            return None

        cat = cat or {}
        sps  = list(per_sp.keys())
        rich = np.asarray([per_sp[s].get("richness", 0)        for s in sps])
        shn  = np.asarray([per_sp[s].get("shannon_entropy", 0) for s in sps])
        cols = [
            _LINEAGE_COLORS.get(
                (cat.get(s, {}) or {}).get("lineage") or _infer_lineage(s),
                "#5248a0")
            for s in sps
        ]

        if rich.size == 0:
            return None

        fig = _mpl_dark_fig(width=8.5, height=5.5)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)

        # Curva de máxima entropía teórica H_max = log2(richness)
        rmax = max(2, int(rich.max()) + 1)
        rx   = np.arange(1, rmax + 1)
        ax.plot(rx, np.log2(rx), color="#f8d0ee", lw=1.0, ls="--", alpha=0.5,
                label="max H′ (uniform)")

        ax.scatter(rich, shn, c=cols, s=70, edgecolor=_MPL_BG, linewidth=0.7,
                   alpha=0.92, zorder=4)

        # Etiquetas si pocos puntos
        if len(sps) <= 35:
            for x, y, sp in zip(rich, shn, sps):
                label = sp.replace("_", " ").title()[:18]
                ax.annotate(label, (x, y), xytext=(4, 3),
                            textcoords="offset points", fontsize=5.5,
                            color=_MPL_TXTS, fontstyle="italic", alpha=0.85)

        ax.set_xlabel("Family richness  (no. distinct IG families)",
                      fontsize=8, color=_MPL_TXT)
        ax.set_ylabel("Shannon entropy  H′  (base 2)",
                      fontsize=8, color=_MPL_TXT)
        ax.set_title("Repertoire diversity  ·  H′ vs richness",
                     fontsize=10, color=C["orchid"], pad=6,
                     fontfamily="monospace")
        leg = ax.legend(loc="lower right", fontsize=7, framealpha=0.85,
                        facecolor=_MPL_PANEL, edgecolor=_MPL_GRID)
        for t in leg.get_texts(): t.set_color(_MPL_TXT)

        fig.tight_layout()
        return fig


    def _plot_cs_chain_scatter(self, spec, cat=None):
        """
        Scatter log-log: cadena pesada (IGH) vs cadenas ligeras (IGK + IGL).

        Diagonales de referencia: 1:1, 2:1, 1:2 (combinaciones VH:VL típicas).
        Cada punto = una especie, color por clado, tamaño por nº total IG.
        """
        if not spec:
            return None
        per_sp = spec.get("per_species") or {}
        if not per_sp:
            return None

        cat = cat or {}
        sps    = list(per_sp.keys())
        n_h    = np.asarray([per_sp[s].get("n_heavy", 0) for s in sps], dtype=float)
        n_l    = np.asarray([per_sp[s].get("n_kappa", 0) + per_sp[s].get("n_lambda", 0)
                             for s in sps], dtype=float)
        n_tot  = np.asarray([per_sp[s].get("n_total", 0) for s in sps], dtype=float)
        cols   = [
            _LINEAGE_COLORS.get(
                (cat.get(s, {}) or {}).get("lineage") or _infer_lineage(s),
                "#5248a0")
            for s in sps
        ]

        # log + epsilon para evitar log(0)
        eps = 0.5
        xh = n_h + eps
        xl = n_l + eps

        fig = _mpl_dark_fig(width=8.5, height=6.0)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)
        ax.set_xscale("log")
        ax.set_yscale("log")

        # Diagonales de referencia 1:1, 2:1, 1:2
        lims_lo = max(eps, min(xh.min(), xl.min()) * 0.7)
        lims_hi = max(xh.max(), xl.max()) * 1.4
        xs = np.array([lims_lo, lims_hi])
        for ratio, ls, lab in [(1.0, "--", "1:1"),
                               (2.0, ":",  "2:1 (H:L)"),
                               (0.5, ":",  "1:2 (H:L)")]:
            ax.plot(xs, xs * ratio, color="#f8d0ee", lw=0.8, ls=ls, alpha=0.5)
            ax.text(lims_hi, lims_hi * ratio, f"  {lab}",
                    color="#f8d0ee", fontsize=6.5, va="center", ha="left",
                    alpha=0.7)

        # Sizes: escala suave por log(n_total + 1)
        sizes = 30 + 25 * np.log1p(n_tot)
        ax.scatter(xl, xh, c=cols, s=sizes, edgecolor=_MPL_BG, linewidth=0.7,
                   alpha=0.92, zorder=4)

        if len(sps) <= 35:
            for x, y, sp in zip(xl, xh, sps):
                label = sp.replace("_", " ").title()[:18]
                ax.annotate(label, (x, y), xytext=(5, 3),
                            textcoords="offset points", fontsize=5.5,
                            color=_MPL_TXTS, fontstyle="italic", alpha=0.85)

        ax.set_xlim(lims_lo, lims_hi)
        ax.set_ylim(lims_lo, lims_hi)
        ax.set_xlabel("Light chain  ·  IGK + IGL  (log)",
                      fontsize=8, color=_MPL_TXT)
        ax.set_ylabel("Heavy chain  ·  IGH  (log)",
                      fontsize=8, color=_MPL_TXT)
        ax.set_title("Repertoire space  ·  heavy vs light chain",
                     fontsize=10, color=C["orchid"], pad=6,
                     fontfamily="monospace")

        fig.tight_layout()
        return fig


    def _plot_cs_innovation(self, spec):
        """
        Barras dobles: para cada clado, cuántas familias son NÚCLEO del clado
        (presentes en ≥80% de sus miembros) y cuántas son INNOVACIONES
        (familias exclusivas, ausentes en cualquier otro clado del set).
        """
        if not spec:
            return None
        cs = spec.get("clade_summary") or {}
        if not cs:
            return None

        items = []
        for clade, info in cs.items():
            n_core   = len(info.get("core_in_clade", []) or [])
            n_innov  = len(info.get("innovations",   []) or [])
            n_sps    = info.get("n_species", 0)
            items.append((clade, n_sps, n_core, n_innov))

        # Ordenar por innovaciones desc, luego por core desc
        items.sort(key=lambda r: (-r[3], -r[2]))
        # Filtrar clados con 0 actividad para no inundar el plot
        items = [r for r in items if (r[2] + r[3]) > 0] or items
        if not items:
            return None

        clades = [r[0] for r in items]
        n_sp   = [r[1] for r in items]
        cores  = [r[2] for r in items]
        inno   = [r[3] for r in items]

        n = len(clades)
        fig_h = max(3.0, 0.36 * n + 1.4)
        fig = _mpl_dark_fig(width=10, height=fig_h)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)

        y = np.arange(n)
        bar_h = 0.36
        cols  = [_LINEAGE_COLORS.get(c, "#5248a0") for c in clades]

        # Núcleo (más claro / patrón)
        bars_core = ax.barh(y - bar_h / 2, cores, height=bar_h,
                            color=cols, alpha=0.5, edgecolor=_MPL_BG, lw=0.6,
                            zorder=3, label="Clade core families (≥80%)")
        # Innovación (sólido)
        bars_inn  = ax.barh(y + bar_h / 2, inno, height=bar_h,
                            color=cols, alpha=0.95, edgecolor=_MPL_BG, lw=0.6,
                            zorder=4, label="Innovations (exclusive)")

        # Anotaciones
        for i, (c, ino) in enumerate(zip(cores, inno)):
            if c > 0:
                ax.text(c + 0.2, i - bar_h / 2, f"{c}", va="center",
                        fontsize=6.5, color=_MPL_TXTS)
            if ino > 0:
                ax.text(ino + 0.2, i + bar_h / 2, f"{ino}", va="center",
                        fontsize=6.5, color=C["gold"], fontweight="bold")

        ax.set_yticks(y)
        ax.set_yticklabels([f"{c}  (n={s})" for c, s in zip(clades, n_sp)],
                           fontsize=8, color=_MPL_TXT, fontweight="bold")
        ax.invert_yaxis()
        ax.set_xlabel("No. IG families", fontsize=8, color=_MPL_TXT)
        ax.set_title("Innovation and core per clade  ·  exclusive vs shared IG families",
                     fontsize=10, color=C["orchid"], pad=6,
                     fontfamily="monospace")
        leg = ax.legend(loc="lower right", fontsize=7, framealpha=0.85,
                        facecolor=_MPL_PANEL, edgecolor=_MPL_GRID)
        for t in leg.get_texts(): t.set_color(_MPL_TXT)

        fig.tight_layout()
        return fig


    def _cs_refresh_specialized(self):
        """
        Refresca la sub-sección 'IG Repertoire Specialization' a partir de
        self._omics_data['cross_specialized']. Operación idempotente — si no hay
        datos, deja los placeholders.
        """
        try:
            data = getattr(self, "_omics_data", {}) or {}
            spec = data.get("cross_specialized") or {}
            if not spec:
                return

            per_sp   = spec.get("per_species") or {}
            core     = spec.get("core_families") or []
            lin_spec = spec.get("lineage_specific") or []
            jacc_df  = spec.get("jaccard")

            cat = getattr(self, "_orth_sp_catalog", {}) or {}

            # ── Cards ────────────────────────────────────────────────────────
            try:
                if hasattr(self, "_cs_card_core"):
                    self._cs_card_core.configure(text=str(len(core)))
                if hasattr(self, "_cs_card_linspec"):
                    self._cs_card_linspec.configure(text=str(len(lin_spec)))
                if hasattr(self, "_cs_card_vtotal"):
                    v_tot = sum(int(v.get("v_gene_count", 0)) for v in per_sp.values())
                    self._cs_card_vtotal.configure(text=f"{v_tot:,}")
            except Exception as _exc:
                logging.debug("[CS_refresh] silenced: %s", _exc)
            # ── Tabla de métricas por especie ────────────────────────────────
            try:
                tree = getattr(self, "_cs_spec_tree", None)
                if tree is not None:
                    tree.delete(*tree.get_children())
                    # Ordenar por nº total de genes IG (desc)
                    rows = sorted(per_sp.items(),
                                  key=lambda kv: kv[1].get("n_total", 0),
                                  reverse=True)
                    for sp, m in rows:
                        lin   = cat.get(sp, {}).get("lineage") or _infer_lineage(sp)
                        disp  = sp.replace("_", " ").title()[:28]
                        n_tot = int(m.get("n_total", 0))
                        n_hv  = int((per_sp.get(sp) or {}).get("n_v", 0)) if False else 0
                        # IGHV / IGKV / IGLV — calculados desde per_species via counts
                        # Fallback rápido: usamos las cuentas crudas del raw matrix
                        raw_df = data.get("cross_raw_matrix_df")
                        n_ighv = n_igkv = n_iglv = 0
                        if raw_df is not None and not getattr(raw_df, "empty", True):
                            try:
                                if "IGHV" in raw_df.index and sp in raw_df.columns:
                                    n_ighv = int(raw_df.at["IGHV", sp])
                                if "IGKV" in raw_df.index and sp in raw_df.columns:
                                    n_igkv = int(raw_df.at["IGKV", sp])
                                if "IGLV" in raw_df.index and sp in raw_df.columns:
                                    n_iglv = int(raw_df.at["IGLV", sp])
                            except Exception as _exc:
                                logging.debug("[CS_refresh] silenced: %s", _exc)
                        kl = m.get("kappa_lambda_ratio", 0.0)
                        if kl == float("inf"):
                            kl_txt = "κ-only"
                        elif kl == 0.0 and m.get("n_lambda", 0) > 0:
                            kl_txt = "λ-only"
                        elif kl == 0.0:
                            kl_txt = "—"
                        else:
                            kl_txt = f"{kl:.2f}"
                        n_iso = int(m.get("n_c_isotypes", 0))
                        sh    = float(m.get("shannon_entropy", 0.0))
                        cls   = str(m.get("repertoire_class", "—"))[:24]
                        tree.insert("", "end", tags=(lin,), values=(
                            disp, lin, f"{n_tot:,}",
                            f"{n_ighv:,}", f"{n_igkv:,}", f"{n_iglv:,}",
                            kl_txt, f"{n_iso}", f"{sh:.2f}", cls))
                    if hasattr(self, "_cs_spec_count"):
                        self._cs_spec_count.configure(text=f"{len(rows)} species")
            except Exception as _exc_tab:
                logging.warning("[OMICS_EXT] cs_specialized table: %s", _exc_tab)

            # ── Heatmap Jaccard inter-especies ───────────────────────────────
            try:
                if jacc_df is not None and not getattr(jacc_df, "empty", True):
                    fig_j = self._plot_cs_jaccard(jacc_df)
                    self._embed_mpl_figure(
                        fig_j, self._cs_jacc_frame, "_cs_jacc_mpl",
                        getattr(self, "_cs_jacc_ph", None), accent=C["orchid"])
            except Exception as _exc_j:
                logging.warning("[OMICS_EXT] cs_specialized jaccard: %s", _exc_j)

            # ── ⑤ Composición V/D/J/C  ·  IGH/IGK/IGL ────────────────────────
            try:
                if hasattr(self, "_cs_comp_frame"):
                    mode = "segments"
                    try:
                        mode = self._cs_comp_mode.get()
                    except Exception as _exc:
                        logging.debug("[CS_refresh] silenced: %s", _exc)
                    fig_c = self._plot_cs_vdjc_composition(spec, mode=mode)
                    self._embed_mpl_figure(
                        fig_c, self._cs_comp_frame, "_cs_comp_mpl",
                        getattr(self, "_cs_comp_ph", None), accent=C["teal"])
            except Exception as _exc_c:
                logging.warning("[OMICS_EXT] cs_specialized composition: %s", _exc_c)

            # ── ⑥ Heatmap de isotipos (región constante) ─────────────────────
            try:
                if hasattr(self, "_cs_iso_frame"):
                    fig_i = self._plot_cs_isotype(spec)
                    self._embed_mpl_figure(
                        fig_i, self._cs_iso_frame, "_cs_iso_mpl",
                        getattr(self, "_cs_iso_ph", None), accent=C["amber"])
            except Exception as _exc_i:
                logging.warning("[OMICS_EXT] cs_specialized isotype: %s", _exc_i)

            # ── ⑦ Sesgo κ:λ  +  scatter H ↔ L ────────────────────────────────
            try:
                if hasattr(self, "_cs_kl_frame"):
                    fig_k = self._plot_cs_kappa_lambda(spec, cat=cat)
                    self._embed_mpl_figure(
                        fig_k, self._cs_kl_frame, "_cs_kl_mpl",
                        getattr(self, "_cs_kl_ph", None), accent=C["lavender"])
            except Exception as _exc_k:
                logging.warning("[OMICS_EXT] cs_specialized kappa-lambda: %s", _exc_k)
            try:
                if hasattr(self, "_cs_chain_frame"):
                    fig_ch = self._plot_cs_chain_scatter(spec, cat=cat)
                    self._embed_mpl_figure(
                        fig_ch, self._cs_chain_frame, "_cs_chain_mpl",
                        getattr(self, "_cs_chain_ph", None), accent=C["lavender"])
            except Exception as _exc_ch:
                logging.warning("[OMICS_EXT] cs_specialized chain: %s", _exc_ch)

            # ── ⑧ PCoA  +  Dendrograma UPGMA ─────────────────────────────────
            try:
                if hasattr(self, "_cs_pcoa_frame"):
                    fig_p = self._plot_cs_pcoa(spec, cat=cat)
                    self._embed_mpl_figure(
                        fig_p, self._cs_pcoa_frame, "_cs_pcoa_mpl",
                        getattr(self, "_cs_pcoa_ph", None), accent=C["sage"])
            except Exception as _exc_p:
                logging.warning("[OMICS_EXT] cs_specialized pcoa: %s", _exc_p)
            try:
                if hasattr(self, "_cs_dend_frame"):
                    fig_d = self._plot_cs_dendrogram(spec, cat=cat)
                    self._embed_mpl_figure(
                        fig_d, self._cs_dend_frame, "_cs_dend_mpl",
                        getattr(self, "_cs_dend_ph", None), accent=C["sage"])
            except Exception as _exc_d:
                logging.warning("[OMICS_EXT] cs_specialized dendrogram: %s", _exc_d)

            # ── ⑨ Diversidad H′  +  Innovación por clado ─────────────────────
            try:
                ROSE = C.get("rose", C["blush"])
                if hasattr(self, "_cs_div_frame"):
                    fig_dv = self._plot_cs_diversity(spec, cat=cat)
                    self._embed_mpl_figure(
                        fig_dv, self._cs_div_frame, "_cs_div_mpl",
                        getattr(self, "_cs_div_ph", None), accent=ROSE)
            except Exception as _exc_dv:
                logging.warning("[OMICS_EXT] cs_specialized diversity: %s", _exc_dv)
            try:
                ROSE = C.get("rose", C["blush"])
                if hasattr(self, "_cs_innov_frame"):
                    fig_iv = self._plot_cs_innovation(spec)
                    self._embed_mpl_figure(
                        fig_iv, self._cs_innov_frame, "_cs_innov_mpl",
                        getattr(self, "_cs_innov_ph", None), accent=ROSE)
            except Exception as _exc_iv:
                logging.warning("[OMICS_EXT] cs_specialized innovation: %s", _exc_iv)

        except Exception as _exc:
            logging.warning("[OMICS_EXT] cs_refresh_specialized: %s", _exc)


    def _plot_cs_clade(self, matrix_df, clade="all", threshold=0.0):
        """
        Perfil de conservación por CLADO (visualización comparativa avanzada).

        Para cada clado filogenético presente, dibuja en orden evolutivo
        (peces → primates):
          • Una caja (box) con la distribución de la conservación media por
            especie del clado.
          • Puntos individuales (strip / jitter) por especie, coloreados por linaje.
          • Un marcador ◆ con la media del clado y una anotación n / media±σ.
        Da una lectura inmediata de cómo decae la conservación de los genes IG
        a lo largo de la filogenia.
        """
        if matrix_df is None or (hasattr(matrix_df, "empty") and matrix_df.empty):
            return None

        arr          = matrix_df.values.astype("float32")
        species_list = list(matrix_df.columns)
        per_sp_mean  = arr.mean(axis=0)
        cat          = getattr(self, "_orth_sp_catalog", {})

        _CLADE_MAP = {
            "all":          None,
            "primates":     {"primates"},
            "mammals":      {"primates", "rodents", "ungulates", "carnivores",
                             "marsupials", "monotremes"},
            "vertebrates":  {"primates", "rodents", "ungulates", "carnivores",
                             "marsupials", "monotremes", "birds", "reptiles",
                             "fish", "amphibians"},
        }
        cset = _CLADE_MAP.get(clade)

        # Agrupar conservación media por linaje
        from collections import defaultdict
        groups = defaultdict(list)        # lineage → [(sp_name, mean), ...]
        for i, sp in enumerate(species_list):
            lineage = cat.get(sp, {}).get("lineage", "other")
            if cset and lineage not in cset:
                continue
            m = float(per_sp_mean[i])
            if m < threshold:
                continue
            groups[lineage].append((sp.replace("_", " ").title(), m))

        if not groups:
            return None

        # Orden filogenético (de basal a derivado)
        _PHYLO = ["fish", "amphibians", "reptiles", "birds", "marsupials",
                  "monotremes", "rodents", "ungulates", "carnivores", "primates",
                  "insects", "nematodes", "fungi", "plants", "tunicates",
                  "echinoderms", "other"]
        ordered = [l for l in _PHYLO if l in groups] + \
                  [l for l in groups if l not in _PHYLO]

        n_clades = len(ordered)
        fig_h = max(4.0, n_clades * 0.85 + 1.6)
        fig = _mpl_dark_fig(width=10, height=fig_h)
        ax  = fig.add_subplot(111)
        _mpl_style_ax(ax)

        rng = np.random.default_rng(11)
        yticks, ylabels = [], []
        for row, lineage in enumerate(ordered):
            vals  = np.array([v for _, v in groups[lineage]], dtype="float32")
            ccol  = _LINEAGE_COLORS.get(lineage, "#5248a0")
            y     = n_clades - 1 - row     # primates arriba
            yticks.append(y)
            ylabels.append(f"{lineage}  (n={len(vals)})")

            # Caja (solo si hay ≥2 puntos) — horizontal
            if len(vals) >= 2:
                bp = ax.boxplot(
                    vals, positions=[y], vert=False, widths=0.55,
                    patch_artist=True, showfliers=False, zorder=2,
                    medianprops=dict(color=_MPL_BG, linewidth=1.6),
                    whiskerprops=dict(color=ccol, linewidth=1.1),
                    capprops=dict(color=ccol, linewidth=1.1),
                    boxprops=dict(facecolor=_ca(ccol, "44"),
                                  edgecolor=ccol, linewidth=1.2))
            # Strip / jitter de especies
            jitter = (rng.random(len(vals)) - 0.5) * 0.26
            ax.scatter(vals, np.full(len(vals), y) + jitter, s=42,
                       color=ccol, alpha=0.92, edgecolors=_MPL_BG,
                       linewidths=0.5, zorder=4)
            # Marcador de la media del clado
            mu = float(vals.mean())
            ax.scatter([mu], [y], marker="D", s=80, color="#ffffff",
                       edgecolors=ccol, linewidths=1.6, zorder=5)
            # Anotación media±σ
            sd = float(vals.std())
            ax.text(1.02, y, f"μ={mu:.0%}  σ={sd:.0%}",
                    va="center", ha="left", fontsize=7,
                    color=ccol, transform=ax.get_yaxis_transform())

        ax.axvline(0.5, color="#f8d0ee", lw=1, ls="--", alpha=0.5, zorder=1)
        ax.set_yticks(yticks)
        ax.set_yticklabels(ylabels, fontsize=8, color=_MPL_TXT)
        ax.set_xlim(0, 1.0)
        ax.set_xlabel("Mean conservation per species", fontsize=8)
        ax.set_title("Conservation Profile per Phylogenetic Clade",
                     fontsize=9.5, pad=8)
        ax.set_ylim(-0.6, n_clades - 0.4)

        n_sp = sum(len(v) for v in groups.values())
        fig.suptitle(
            f"Clade Conservation Profile  ·  {n_clades} clades  ·  {n_sp} species",
            fontsize=10, color=C["violet"], y=0.98, fontfamily="monospace")
        fig.tight_layout(rect=[0, 0, 0.92, 0.94])
        return fig


    # ══════════════════════════════════════════════════════════════════════════════
    #  TEST  —  Datos sintéticos para previsualizar Cross Species sin pipeline
    # ══════════════════════════════════════════════════════════════════════════════

    def _cs_test_viz(self):
        """
        Puebla el catálogo de especies con linajes y genera datos de ortología
        sintéticos (reutilizando el generador de la sección Orthology), luego
        refresca TODAS las secciones de extensión para previsualizar el diseño.
        """
        # Linajes para las especies del set sintético por defecto
        _SP_LINEAGE = {
            "homo_sapiens": "primates", "pan_troglodytes": "primates",
            "gorilla_gorilla": "primates", "macaca_mulatta": "primates",
            "mus_musculus": "rodents", "rattus_norvegicus": "rodents",
            "bos_taurus": "ungulates", "sus_scrofa": "ungulates",
            "canis_lupus_familiaris": "carnivores", "felis_catus": "carnivores",
            "gallus_gallus": "birds", "anolis_carolinensis": "reptiles",
            "xenopus_tropicalis": "amphibians", "danio_rerio": "fish",
            "oryzias_latipes": "fish", "drosophila_melanogaster": "insects",
            "caenorhabditis_elegans": "nematodes",
            "monodelphis_domestica": "marsupials",
            "ornithorhynchus_anatinus": "monotremes",
        }
        if not isinstance(getattr(self, "_orth_sp_catalog", None), dict):
            self._orth_sp_catalog = {}
        for sp, lin in _SP_LINEAGE.items():
            info = self._orth_sp_catalog.get(sp, {})
            info.setdefault("lineage", lin)
            info.setdefault("display_name", sp.replace("_", " ").title())
            self._orth_sp_catalog[sp] = info

        # Generar datos sintéticos de ortología (también refresca paneles A–F)
        try:
            self._omics_test_orth_viz()
        except Exception as exc:
            logging.warning("[OMICS_EXT] cs test orth gen: %s", exc)

        # ── Generar repertorio IG sintético para las sub-secciones ④–⑨ ─────────
        # Sin esto, las nuevas visualizaciones (composición V/D/J/C, isotipos,
        # κ:λ, PCoA, dendrograma, diversidad, innovación) quedarían vacías al
        # pulsar 🧪 TEST porque no hay genes IG reales en memoria. Generamos
        # conteos por familia plausibles, modulados por clado, y los inyectamos
        # como si fueran resultado de un MultiSpeciesRunner.
        try:
            import random as _rnd
            _rnd.seed(42)
            # Familias por clado: cada clado mantiene su huella típica.
            # heavy_isotypes: combinaciones IGH-C que aparecen en cada grupo
            _CLADE_PROFILE = {
                "primates":    dict(ighv=(35, 55), ighd=(15, 30), ighj=(4, 7),
                                    igkv=(30, 50), igkj=(3, 6),  igkc=(1, 1),
                                    iglv=(25, 40), iglj=(3, 5),  iglc=(2, 5),
                                    heavy_iso=["IGHM","IGHD","IGHG","IGHA","IGHE"]),
                "rodents":     dict(ighv=(80, 130), ighd=(15, 25), ighj=(3, 5),
                                    igkv=(90, 140), igkj=(4, 6),  igkc=(1, 1),
                                    iglv=(2, 6),    iglj=(2, 4),  iglc=(2, 4),
                                    heavy_iso=["IGHM","IGHD","IGHG","IGHA","IGHE"]),
                "ungulates":   dict(ighv=(15, 30), ighd=(10, 20), ighj=(2, 4),
                                    igkv=(8, 15),  igkj=(2, 4),  igkc=(1, 1),
                                    iglv=(20, 35), iglj=(2, 4),  iglc=(2, 4),
                                    heavy_iso=["IGHM","IGHD","IGHG","IGHA","IGHE"]),
                "carnivores":  dict(ighv=(25, 45), ighd=(10, 20), ighj=(3, 5),
                                    igkv=(15, 25), igkj=(3, 5),  igkc=(1, 1),
                                    iglv=(20, 35), iglj=(2, 4),  iglc=(2, 4),
                                    heavy_iso=["IGHM","IGHD","IGHG","IGHA","IGHE"]),
                "marsupials":  dict(ighv=(20, 35), ighd=(8, 15),  ighj=(3, 5),
                                    igkv=(10, 20), igkj=(2, 4),  igkc=(1, 1),
                                    iglv=(15, 28), iglj=(2, 4),  iglc=(2, 3),
                                    heavy_iso=["IGHM","IGHG","IGHA","IGHE"]),
                "monotremes":  dict(ighv=(20, 35), ighd=(8, 15),  ighj=(2, 4),
                                    igkv=(8, 16),  igkj=(2, 4),  igkc=(1, 1),
                                    iglv=(10, 20), iglj=(2, 3),  iglc=(2, 3),
                                    heavy_iso=["IGHM","IGHG","IGHA"]),
                "birds":       dict(ighv=(50, 90), ighd=(0, 1),   ighj=(1, 2),
                                    igkv=(0, 0),   igkj=(0, 0),   igkc=(0, 0),
                                    iglv=(20, 35), iglj=(1, 2),   iglc=(1, 2),
                                    heavy_iso=["IGHM","IGHA"]),  # IgY ≈ IGHA en Ensembl
                "reptiles":    dict(ighv=(30, 60), ighd=(2, 5),   ighj=(2, 4),
                                    igkv=(8, 18),  igkj=(2, 4),   igkc=(1, 1),
                                    iglv=(15, 30), iglj=(2, 3),   iglc=(1, 2),
                                    heavy_iso=["IGHM","IGHA"]),
                "amphibians":  dict(ighv=(40, 80), ighd=(2, 5),   ighj=(2, 4),
                                    igkv=(5, 12),  igkj=(2, 3),   igkc=(1, 1),
                                    iglv=(10, 22), iglj=(2, 3),   iglc=(1, 2),
                                    heavy_iso=["IGHM"]),
                "fish":        dict(ighv=(40, 110), ighd=(2, 6),  ighj=(1, 3),
                                    igkv=(0, 0),    igkj=(0, 0),  igkc=(0, 0),
                                    iglv=(20, 50),  iglj=(2, 4),  iglc=(2, 4),
                                    heavy_iso=["IGHM"]),
                "insects":     dict(ighv=(0, 0), ighd=(0, 0), ighj=(0, 0),
                                    igkv=(0, 0), igkj=(0, 0), igkc=(0, 0),
                                    iglv=(0, 0), iglj=(0, 0), iglc=(0, 0),
                                    heavy_iso=[]),
                "nematodes":   dict(ighv=(0, 0), ighd=(0, 0), ighj=(0, 0),
                                    igkv=(0, 0), igkj=(0, 0), igkc=(0, 0),
                                    iglv=(0, 0), iglj=(0, 0), iglc=(0, 0),
                                    heavy_iso=[]),
            }

            species_list = list(_SP_LINEAGE.keys())
            per_sp_counts = {}
            for sp in species_list:
                lin = _SP_LINEAGE.get(sp, "other")
                prof = _CLADE_PROFILE.get(lin, _CLADE_PROFILE["primates"])
                c = {}
                for fam_key, range_key in [
                    ("IGHV", "ighv"), ("IGHD", "ighd"), ("IGHJ", "ighj"),
                    ("IGKV", "igkv"), ("IGKJ", "igkj"), ("IGKC", "igkc"),
                    ("IGLV", "iglv"), ("IGLJ", "iglj"), ("IGLC", "iglc"),
                ]:
                    lo, hi = prof[range_key]
                    c[fam_key] = _rnd.randint(lo, hi) if hi > 0 else 0
                for iso in prof["heavy_iso"]:
                    c[iso] = _rnd.randint(1, 4)
                per_sp_counts[sp] = c

            # Calcular métricas especializadas con la misma función
            specialized = _cross_specialized_metrics(per_sp_counts, species_list)

            # Construir matriz cruda fam × species para alimentar la tabla ④
            all_fams = sorted({fam for c in per_sp_counts.values() for fam in c})
            raw = np.zeros((len(all_fams), len(species_list)), dtype="int64")
            for i, fam in enumerate(all_fams):
                for j, sp in enumerate(species_list):
                    raw[i, j] = int(per_sp_counts[sp].get(fam, 0))
            raw_df = pd.DataFrame(raw, index=all_fams, columns=species_list)
            raw_df.index.name   = "family"
            raw_df.columns.name = "species"

            if not isinstance(getattr(self, "_omics_data", None), dict):
                self._omics_data = {}
            self._omics_data["cross_specialized"]   = specialized
            self._omics_data["cross_raw_matrix_df"] = raw_df
            self._omics_data["cross_species_order"] = list(species_list)
        except Exception as _exc_synth:
            logging.warning("[OMICS_EXT] synth repertoire: %s", _exc_synth)

        # Expandir la sección Cross Species y sus sub-secciones
        for k in ("cross", "cross_rank", "cross_matrix", "cross_clade", "cross_specialized", "cross_composition", "cross_isotype", "cross_chains", "cross_ordination", "cross_diversity_innov"):
            try:
                self._omics_expand_section(k)
            except Exception:
                pass

        # Refrescar todas las secciones de extensión
        for fn in (self._cs_refresh, self._dist_refresh,
                    self._fam_refresh, self._stat_text_update):
            try:
                fn()
            except Exception:
                pass
        try:
            self._append_log(
                "🧪 OMICS TEST — Cross Species populated with synthetic data "
                f"({len(_SP_LINEAGE)} linajes mapeados).", "ok")
        except Exception:
            pass


    # ══════════════════════════════════════════════════════════════════════════════
    #  MÉTODOS REFRESH  —  Actualizan secciones al cambiar datos o controles
    # ══════════════════════════════════════════════════════════════════════════════

    def _cs_refresh(self):
        """Actualiza la sección Cross Species completa."""
        logging.debug("[CS] _cs_refresh iniciado")
        try:
            data      = self._safe_omics
            res       = self._safe_results

            # Selección segura sin usar `or` sobre DataFrames (su valor de verdad
            # es ambiguo y lanzaría ValueError). Preferimos _omics_data y caemos
            # a _results sólo si falta o está vacío.
            def _pick_df(key):
                d = data.get(key)
                if d is None or (hasattr(d, "empty") and d.empty):
                    d = res.get(key)
                return d
            mdf       = _pick_df("orthology_matrix_df")
            long_df   = _pick_df("orthology_long_df")
            summary   = data.get("orthology_summary") or {}

            if mdf is None or (hasattr(mdf, "empty") and mdf.empty):
                logging.debug("[CS] _cs_refresh: sin orthology_matrix_df — abortando")
                return

            sort_by   = self._cs_sort_var.get()
            clade     = self._cs_clade_var.get()
            threshold = float(self._cs_thresh_var.get())
            hmap_mode = self._cs_hmap_mode.get()

            arr          = mdf.values.astype("float32")
            species_list = list(mdf.columns)
            per_sp_mean  = arr.mean(axis=0)
            per_sp_n     = (arr > 0).sum(axis=0)
            n_genes      = len(mdf)
            cat          = getattr(self, "_orth_sp_catalog", {})

            # ── Tarjetas métricas ────────────────────────────────────────────────
            try:
                if hasattr(self, "_cs_card_sp"):
                    self._cs_card_sp.configure(text=str(len(species_list)))

                if hasattr(self, "_cs_card_lin"):
                    lineages = {cat.get(sp, {}).get("lineage", "other")
                                for sp in species_list}
                    self._cs_card_lin.configure(text=str(len(lineages)))

                if hasattr(self, "_cs_card_topgene") and n_genes > 0:
                    gene_means = arr.mean(axis=1)
                    top_idx    = int(np.argmax(gene_means))
                    top_gid    = str(mdf.index[top_idx])[:14]
                    self._cs_card_topgene.configure(text=top_gid)

                if hasattr(self, "_cs_card_unique"):
                    n_unique = int(((arr > 0).sum(axis=1) == 1).sum())
                    self._cs_card_unique.configure(text=f"{n_unique:,}")
            except Exception as _exc:
                logging.debug("[CS_refresh] silenced: %s", _exc)
            # ── Treeview de especies ─────────────────────────────────────────────
            try:
                self._cs_tree.delete(*self._cs_tree.get_children())
                il_by_sp = (data.get("cross_intronless_by_species") or {})
                records = []
                for i, sp in enumerate(species_list):
                    info    = cat.get(sp, {})
                    lineage = info.get("lineage", "other")
                    mean_v  = float(per_sp_mean[i])
                    n_orth  = int(per_sp_n[i])
                    il      = il_by_sp.get(sp) or {}
                    records.append((sp, lineage, mean_v, n_orth, il))

                # Sort
                _PHYLO = {"fish":0,"amphibians":1,"reptiles":2,"birds":3,
                          "marsupials":4,"monotremes":5,"rodents":6,
                          "ungulates":7,"carnivores":8,"primates":9}
                kf = {"conservation": lambda r: -r[2],
                      "n_genes":      lambda r: -r[3],
                      "phylo":        lambda r: _PHYLO.get(r[1], 5),
                      "name":         lambda r: r[0]}.get(sort_by, lambda r: -r[2])
                records.sort(key=kf)

                # Clade filter
                _CLADE_MAP = {
                    "primates":    {"primates"},
                    "mammals":     {"primates","rodents","ungulates","carnivores",
                                   "marsupials","monotremes"},
                    "vertebrates": {"primates","rodents","ungulates","carnivores",
                                   "marsupials","monotremes","birds","reptiles",
                                   "fish","amphibians"},
                }
                cset = _CLADE_MAP.get(clade)

                shown = 0
                for sp, lineage, mean_v, n_orth, il in records:
                    if cset and lineage not in cset:
                        continue
                    if mean_v < threshold:
                        continue
                    bar_len = int(mean_v * 20)
                    bar     = "█" * bar_len + "░" * (20 - bar_len)
                    disp    = sp.replace("_", " ").title()[:28]
                    # STAYS IG: orthologs that remain intronless / resolved
                    n_res = int((il or {}).get("n_orthologs_resolved", 0) or 0)
                    n_con = int((il or {}).get("n_intronless_conserved", 0) or 0)
                    stays_txt = (f"{n_con}/{n_res} ({n_con/n_res:.0%})"
                                 if n_res > 0 else "—")
                    self._cs_tree.insert("", "end", tags=(lineage,), values=(
                        disp, lineage, f"{n_genes:,}", f"{n_orth:,}",
                        f"{mean_v:.1%}", stays_txt, bar[:20]))
                    shown += 1

                if hasattr(self, "_cs_tree_count"):
                    self._cs_tree_count.configure(text=f"{shown} species")
            except Exception as _exc:
                logging.debug("[CS_refresh] silenced: %s", _exc)
            # ── Barplot (visor interactivo: zoom/scroll/pan + autofit) ───────────
            try:
                fig = self._plot_cs_barplot(mdf, sort_by=sort_by,
                                       clade=clade, threshold=threshold)
                self._embed_mpl_figure(
                    fig, self._cs_plot_frame, "_cs_plot_mpl",
                    getattr(self, "_cs_plot_ph", None), accent=C["cyan"])
            except Exception as exc:
                logging.warning("[OMICS_EXT] cs barplot: %s", exc)

            # ── Heatmap familia × especie ────────────────────────────────────────
            fam_df = None
            try:
                try:
                    fam_df = summary.get("family_conservation_df")
                except Exception as _exc:
                    logging.debug("[CS_refresh] silenced: %s", _exc)
                if fam_df is None:
                    ig_df = res.get("ig", pd.DataFrame())
                    if long_df is not None and not long_df.empty:
                        fam_df = _omics_math.build_family_conservation(long_df, ig_df)

                if fam_df is not None and not fam_df.empty:
                    fig_h = self._plot_cs_heatmap(fam_df, mode=hmap_mode)
                    self._embed_mpl_figure(
                        fig_h, self._cs_hmap_outer, "_cs_hmap_mpl",
                        getattr(self, "_cs_hmap_ph", None), accent=C["teal"])
            except Exception as exc:
                logging.warning("[OMICS_EXT] cs heatmap: %s", exc)

            # ── Perfil de conservación por clado (visualización avanzada) ─────────
            try:
                fig_c = self._plot_cs_clade(mdf, clade=clade, threshold=threshold)
                self._embed_mpl_figure(
                    fig_c, self._cs_clade_frame, "_cs_clade_mpl",
                    getattr(self, "_cs_clade_ph", None), accent=C["violet"])
            except Exception as exc:
                logging.warning("[OMICS_EXT] cs clade: %s", exc)

            # ── Métricas IG-especializadas (tabla + Jaccard heatmap) ─────────────
            try:
                self._cs_refresh_specialized()
            except Exception as exc:
                logging.warning("[OMICS_EXT] cs specialized: %s", exc)

            # Actualizar texto estadístico
            self._stat_text_update()

            # Forzar actualización visual del tab completo
            try:
                tab = getattr(self, "_tab_cross", None) or getattr(self, "_tab_omics", None)
                if tab:
                    tab.update_idletasks()
            except Exception as _exc:
                logging.debug("[CS_refresh] silenced: %s", _exc)
            # macOS: forzar repintado de toda la ventana tras pintar plots
            try:
                self._force_redraw()
            except Exception:
                pass
            logging.debug("[CS] _cs_refresh completado")

        except Exception as exc:
            self._cs_last_error = str(exc)
            logging.warning("[CS] _cs_refresh error: %s", exc, exc_info=True)


    def _dist_refresh(self):
        """Actualiza el gráfico de distribución."""
        # Guarda: la sección puede no haberse construido todavía cuando
        # _omics_refresh_all dispara este refresh. Salir limpio si falta.
        if not (hasattr(self, "_dist_bins_var") and hasattr(self, "_dist_outer")):
            return
        try:
            data = getattr(self, "_omics_data", {}) or {}
            res  = getattr(self, "_results",    {}) or {}
            mdf  = _omics_pick_df(data, res, "orthology_matrix_df")
            if mdf is None or (hasattr(mdf, "empty") and mdf.empty):
                return
            bins = int(self._dist_bins_var.get())
            view = self._dist_view_var.get()
            fig  = self._plot_dist(mdf, bins=bins, view=view)
            self._embed_ext_fig(fig,
                           self._dist_outer, "_dist_mpl_canvas",
                           getattr(self, "_dist_ph", None),
                           C["lavender"])
        except Exception as exc:
            logging.warning("[OMICS_EXT] dist_refresh: %s", exc)


    def _fam_refresh(self):
        """Actualiza la sección Family Browser."""
        # Guarda: la sección puede no haberse construido todavía.
        if not hasattr(self, "_fam_tree"):
            return
        try:
            data = getattr(self, "_omics_data", {}) or {}
            res  = getattr(self, "_results",    {}) or {}
            mdf  = _omics_pick_df(data, res, "orthology_matrix_df")
            if mdf is None or (hasattr(mdf, "empty") and mdf.empty):
                return
            ig_df = res.get("ig", pd.DataFrame())

            _FAM_RE = _re.compile(
                r"^(IGH[VDJACE]|IGL[VJCE]|IGK[VJC]|IG[HJKL][A-Z]?)",
                _re.IGNORECASE)

            # Construir mapa familia → scores
            fam_scores = {}
            for gid in mdf.index:
                m   = _FAM_RE.match(str(gid))
                fam = m.group(1).upper() if m else "OTHER"
                fam_scores.setdefault(fam, []).append(
                    mdf.loc[gid].values.astype("float32"))

            sp_list    = list(mdf.columns)
            n_families = len(fam_scores)

            # Tarjetas
            if hasattr(self, "_fam_card_n"):
                self._fam_card_n.configure(text=str(n_families))
            if hasattr(self, "_fam_card_ighv"):
                self._fam_card_ighv.configure(text=str(len(fam_scores.get("IGHV",[]))))
            if hasattr(self, "_fam_card_iglv"):
                self._fam_card_iglv.configure(text=str(len(fam_scores.get("IGLV",[]))))
            if hasattr(self, "_fam_card_igkv"):
                self._fam_card_igkv.configure(text=str(len(fam_scores.get("IGKV",[]))))

            # Treeview
            self._fam_tree.delete(*self._fam_tree.get_children())
            for fam in sorted(fam_scores.keys()):
                rows     = np.vstack(fam_scores[fam])   # n_genes × n_sp
                g_means  = rows.mean(axis=1)
                sp_means = rows.mean(axis=0)
                mc       = float(g_means.mean())
                n_orth   = int((g_means > 0).sum())
                top_sp   = (sp_list[int(np.argmax(sp_means))].replace("_"," ")[:18]
                            if sp_list else "—")
                bar_len  = int(mc * 20)
                bar      = "█" * bar_len + "░" * (20 - bar_len)
                self._fam_tree.insert("", "end", tags=(fam,), values=(
                    fam, str(len(fam_scores[fam])), f"{n_orth}",
                    f"{mc:.1%}", top_sp, bar[:20]))

            # Gráfico
            fig = self._plot_family_bars(mdf, ig_df)
            self._embed_ext_fig(fig,
                           self._fam_chart_frame, "_fam_chart_canvas",
                           getattr(self, "_fam_chart_ph", None),
                           C["amber"])

        except Exception as exc:
            logging.warning("[OMICS_EXT] fam_refresh: %s", exc)


    def _stat_text_update(self):
        """Llena el widget Text con el resumen estadístico."""
        if not hasattr(self, "_stat_text"):
            return
        try:
            data = getattr(self, "_omics_data", {}) or {}
            res  = getattr(self, "_results",    {}) or {}
            mdf  = _omics_pick_df(data, res, "orthology_matrix_df")
            fdf  = _omics_pick_df(data, res, "func_enrichment_df")
            cat  = getattr(self, "_orth_sp_catalog", {})

            self._stat_text.configure(state="normal")
            self._stat_text.delete("1.0", "end")
            ins = self._stat_text.insert

            ins("end", "═" * 48 + "\n", "dim")
            ins("end", "  RESUMEN OMICS — IGFinder 2.1.1\n", "hdr")
            ins("end", "═" * 48 + "\n", "dim")

            if mdf is not None and not mdf.empty:
                arr        = mdf.values.astype("float32")
                gm         = arr.mean(axis=1)
                sp_means   = arr.mean(axis=0)
                n_g        = len(mdf)
                n_sp       = len(mdf.columns)

                ins("end", "\n  Ortología\n", "hdr")
                ins("end", "─" * 48 + "\n", "dim")
                ins("end", f"  Genes consultados:       {n_g:>8,}\n",    "val")
                ins("end", f"  Especies comparadas:     {n_sp:>8,}\n",   "val")
                ins("end", f"  Con ≥1 ortólogo:         {int((gm>0).sum()):>8,}\n", "ok")
                ins("end", f"  Conservación media:      {gm.mean():>8.1%}\n",       "ok")
                ins("end", f"  Totalmente conservados   {int((gm>=0.9).sum()):>8,} (≥90%)\n", "ok")
                ins("end", f"  Semi-conservados         {int((gm>=0.5).sum()):>8,} (≥50%)\n", "ok")

                ins("end", "\n  Percentiles de conservación\n", "hdr")
                ins("end", "─" * 48 + "\n", "dim")
                for pct in [10, 25, 50, 75, 90]:
                    v = float(np.percentile(gm, pct))
                    ins("end", f"    P{pct:<4} = {v:.4f}\n", "val")

                ins("end", "\n  Top 5 Especies (mayor conservación)\n", "hdr")
                ins("end", "─" * 48 + "\n", "dim")
                for idx in np.argsort(sp_means)[::-1][:5]:
                    sp   = str(mdf.columns[idx])
                    disp = sp.replace("_", " ").title()[:24]
                    ins("end", f"    {disp:<26} {sp_means[idx]:.1%}\n", "sp")

            if fdf is not None and not fdf.empty:
                ns = (int(fdf["source"].nunique())
                      if "source" in fdf.columns else 0)
                ins("end", "\n  Enriquecimiento Funcional\n", "hdr")
                ins("end", "─" * 48 + "\n", "dim")
                ins("end", f"  Términos enriquecidos:   {len(fdf):>8,}\n", "val")
                ins("end", f"  Fuentes (GO/KEGG/…):     {ns:>8}\n",        "val")

                if "fdr" in fdf.columns:
                    top_rows = fdf.nsmallest(5, "fdr")
                    ins("end", "\n  Top 5 Términos (menor FDR)\n", "hdr")
                    ins("end", "─" * 48 + "\n", "dim")
                    for _, r in top_rows.iterrows():
                        nm = str(r.get("term_name",""))[:32]
                        ins("end", f"    {nm:<34} {r.get('fdr',1):.1e}\n", "sp")

            ins("end", "\n" + "═" * 48 + "\n", "dim")
            self._stat_text.configure(state="disabled")
        except Exception:
            try:
                self._stat_text.configure(state="disabled")
            except Exception:
                pass


    # ── Ordenar columna de treeview CS ───────────────────────────────────────────

    def _cs_col_sort(self, col):
        _MAP = {
            "species":      "name",
            "lineage":      "name",
            "n_orthologs":  "n_genes",
            "conservation": "conservation",
            "n_genes":      "n_genes",
        }
        nv = _MAP.get(col, "conservation")
        self._cs_sort_var.set(nv)
        self._cs_refresh()



    # ══════════════════════════════════════════════════════════════════════════
    #  CROSS SPECIES — Alimentar desde datos en memoria (cualquier fuente)
    # ══════════════════════════════════════════════════════════════════════════

    def _build_cross_from_omics(self):
        """
        Convierte los datos de OMICS/SCAN que ya están en memoria al formato
        que Cross Species necesita (familia_IG × especie), sin requerir un
        batch multispecies completo.

        Fuentes de datos en orden de prioridad:
          1. _omics_data["orthology_matrix_df"]  — gene × target_species
             (lo produce OmicsRunner con Ensembl Compara)
          2. _results["ig"]  — ig_df de la especie activa (SCAN normal)
             → construye una matriz de una sola columna con la especie activa

        En el caso (1): la matriz gene × target_species YA es directamente
        utilizable por Cross Species — cada columna es una especie de comparación.

        En el caso (2): solo hay una especie en memoria. Se construye una
        matriz familia_IG × [especie_activa] con la riqueza relativa por familia,
        lo que permite ver composición del repertorio en el mismo visor aunque
        no haya comparación inter-especies.
        """
        data = self._safe_omics
        res  = self._safe_results

        # ── Fuente 1: matriz de ortología gene × target_species ──────────────
        orth_matrix = data.get("orthology_matrix_df")
        orth_long   = data.get("orthology_long_df")
        orth_sum    = data.get("orthology_summary") or {}
        species_src = res.get("species", "unknown")

        has_orth = (orth_matrix is not None and
                    not (hasattr(orth_matrix, "empty") and orth_matrix.empty))

        if has_orth:
            # La matriz ya tiene la forma adecuada para Cross Species:
            # filas = genes IG, columnas = especies target.
            # Populamos el catálogo de linajes para las columnas.
            if not isinstance(getattr(self, "_orth_sp_catalog", None), dict):
                self._orth_sp_catalog = {}
            for sp in orth_matrix.columns:
                info = self._orth_sp_catalog.get(sp, {})
                info.setdefault("lineage",      _infer_lineage(sp))
                info.setdefault("display_name", sp.replace("_", " ").title())
                self._orth_sp_catalog[sp] = info

            # Inyectar directamente — _cs_refresh lo usa tal cual
            if not isinstance(getattr(self, "_omics_data", None), dict):
                self._omics_data = {}
            self._omics_data["orthology_matrix_df"] = orth_matrix
            if orth_long is not None:
                self._omics_data["orthology_long_df"] = orth_long
            if orth_sum:
                self._omics_data["orthology_summary"] = orth_sum

            # ── CORRER EL ANÁLISIS (antes esta rama SOLO dibujaba) ───────────
            # Derivamos per_sp_counts {target_species: {categoría: n_ortólogos}}
            # a partir de la matriz gene × especie (un gen cuenta como presente
            # en la especie si conservation_score > 0) y calculamos las métricas
            # cross-species completas: core/linaje-específicas, Jaccard, PCoA,
            # UPGMA, V/D/J/C, isotipos, Shannon, etc. Mismas claves que la ruta
            # multispecies para que _cs_refresh dibuje TODAS las sub-secciones.
            species = list(orth_matrix.columns)
            try:
                src_ig = res.get("ig")
                if src_ig is None or getattr(src_ig, "empty", True):
                    src_ig = data.get("ig", pd.DataFrame())
                gene_cat = _gene_id_category_map(src_ig)
                per_sp_counts = {sp: {} for sp in species}
                _arr = orth_matrix.values
                _idx = [str(g) for g in orth_matrix.index]
                for jcol, sp in enumerate(species):
                    cdict = per_sp_counts[sp]
                    col = _arr[:, jcol]
                    for irow, gid in enumerate(_idx):
                        if col[irow] > 0:
                            ccat = gene_cat.get(gid, "OTHER")
                            cdict[ccat] = cdict.get(ccat, 0) + 1
                specialized = _cross_specialized_metrics(per_sp_counts, species)
            except Exception as _exc_sp:
                logging.warning("[CROSS] specialized (omics): %s", _exc_sp)
                per_sp_counts, specialized = {}, {}

            # Matriz de conteos crudos categoría × especie (export + tabla V-gene)
            raw_matrix_df = None
            try:
                _cats = sorted({c for d in per_sp_counts.values() for c in d})
                _cats = [f for f in _CROSS_FAM_ORDER if f in _cats] + \
                        sorted(c for c in _cats if c not in _CROSS_FAM_ORDER)
                if _cats:
                    _ra = np.zeros((len(_cats), len(species)), dtype="int64")
                    for jcol, sp in enumerate(species):
                        d = per_sp_counts.get(sp, {})
                        for irow, c in enumerate(_cats):
                            _ra[irow, jcol] = int(d.get(c, 0))
                    raw_matrix_df = pd.DataFrame(
                        _ra, index=_cats, columns=species)
                    raw_matrix_df.index.name   = "family"
                    raw_matrix_df.columns.name = "species"
            except Exception:
                raw_matrix_df = None

            if isinstance(orth_sum, dict):
                orth_sum["specialized"] = specialized
                if raw_matrix_df is not None:
                    orth_sum["raw_count_matrix_df"] = raw_matrix_df
                self._omics_data["orthology_summary"] = orth_sum
            self._omics_data["cross_specialized"]   = specialized
            self._omics_data["cross_raw_matrix_df"] = raw_matrix_df
            self._omics_data["cross_species_order"] = list(species)

            # ── STAYS IG: per-species intronless-conservation of orthologs ───
            # Answers "how many genes stay intronless in each species". Comes
            # from the opt-in "Check if each ortholog stays intronless" step.
            # Prefer the summary block; fall back to the long_df column. If the
            # option was OFF, this stays empty and the table shows "—".
            il_by_sp = {}
            try:
                ic = (orth_sum or {}).get("intronless_conservation") or {}
                il_by_sp = dict(ic.get("by_species") or {})
            except Exception:
                il_by_sp = {}
            if (not il_by_sp and orth_long is not None
                    and not getattr(orth_long, "empty", True)
                    and "ortholog_is_intronless" in getattr(orth_long, "columns", [])):
                try:
                    _res_il = orth_long[orth_long["ortholog_is_intronless"].notna()]
                    for _sp, _grp in _res_il.groupby("target_species"):
                        _n = int(len(_grp))
                        _c = int(_grp["ortholog_is_intronless"].sum())
                        il_by_sp[str(_sp)] = {
                            "n_orthologs_resolved":   _n,
                            "n_intronless_conserved": _c,
                            "fraction_conserved":     (_c / _n) if _n else 0.0,
                        }
                except Exception:
                    pass
            self._omics_data["cross_intronless_by_species"] = il_by_sp

            n_sp    = len(orth_matrix.columns)
            n_genes = len(orth_matrix)
            n_core  = len(specialized.get("core_families", []) or [])
            n_lin   = len(specialized.get("lineage_specific", []) or [])
            self._append_log(
                f"⬢ CROSS SPECIES — analysis from OMICS orthology  "
                f"({n_genes:,} IG genes × {n_sp} species  ·  "
                f"core={n_core}  ·  lineage-specific={n_lin}).", "ok")
            try:
                if hasattr(self, "_cross_banner"):
                    n_lineages_real = len({_infer_lineage(sp) for sp in species})
                    self._cross_banner.configure(
                        text=(f"⬢  ANALYSIS ACTIVE (OMICS orthology)  ·  {n_sp} "
                              f"species  ·  {n_lineages_real} clades  ·  "
                              f"{n_genes:,} IG genes  ·  core={n_core}  ·  "
                              f"lineage-specific={n_lin}"),
                        fg=C["emerald"])
            except Exception:
                pass

            for k in ("cross", "cross_rank", "cross_matrix", "cross_clade",
                      "cross_specialized", "cross_composition", "cross_isotype",
                      "cross_chains", "cross_ordination", "cross_diversity_innov"):
                try:
                    self._omics_expand_section(k)
                except Exception:
                    pass

            self._cs_refresh()
            return

        # ── Fuente 2: ig_df de la especie activa (SCAN normal) ───────────────
        ig_df = res.get("ig", pd.DataFrame())
        if ig_df is None or (hasattr(ig_df, "empty") and ig_df.empty):
            # Intentar desde _omics_data
            ig_df = data.get("ig", pd.DataFrame())

        if ig_df is None or (hasattr(ig_df, "empty") and ig_df.empty):
            try:
                self._append_log(
                    "⬢ CROSS SPECIES — no IG data in memory. "
                    "Run SCAN or OMICS first.", "warn")
                if hasattr(self, "_cross_banner"):
                    self._cross_banner.configure(
                        text="⬢  No IG data in memory — run SCAN or OMICS first.",
                        fg=C["amber"])
            except Exception:
                pass
            return

        # Construir matriz de una sola especie desde ig_df
        counts = _cross_family_counts(ig_df)
        if not counts:
            self._append_log(
                "⬢ CROSS SPECIES — ig_df has no recognizable IG families.", "warn")
            return

        fams = [f for f in _CROSS_FAM_ORDER if f in counts] +                sorted(f for f in counts if f not in _CROSS_FAM_ORDER)

        sp_col = species_src or "current_species"
        count_arr = np.array([[float(counts.get(f, 0))] for f in fams],
                              dtype="float32")
        row_max = count_arr.max()
        if row_max > 0:
            norm_arr = count_arr / row_max
        else:
            norm_arr = count_arr

        fam_matrix = pd.DataFrame(
            norm_arr, index=fams, columns=[sp_col])
        fam_matrix.index.name   = "family"
        fam_matrix.columns.name = "species"

        # Long format
        long_rows = [
            {"source_gene_id": fam, "source_gene_name": fam,
             "target_species": sp_col,
             "conservation_score": float(norm_arr[i, 0]),
             "n_genes": int(count_arr[i, 0])}
            for i, fam in enumerate(fams)
        ]
        long_df = pd.DataFrame(long_rows)

        summary = {
            "family_conservation_df": fam_matrix,
            "source": "single_species_scan",
            "n_genomes": 1,
            "n_families": len(fams),
            "n_ig_total": int(count_arr.sum()),
            "specialized": {},
        }

        # ── CORRER EL ANÁLISIS también para una sola especie ─────────────────
        # Con un solo genoma no hay comparación inter-especies (Jaccard/PCoA/
        # UPGMA quedan triviales), pero sí se computan las métricas de repertorio
        # por especie (V/D/J/C, H/L, κ:λ, isotipos, Shannon, riqueza) para que la
        # sub-sección de especialización deje de estar vacía.
        per_sp_counts = {sp_col: dict(counts)}
        try:
            specialized = _cross_specialized_metrics(per_sp_counts, [sp_col])
        except Exception as _exc_sp:
            logging.warning("[CROSS] specialized (single): %s", _exc_sp)
            specialized = {}
        summary["specialized"] = specialized
        try:
            raw_matrix_df = pd.DataFrame(
                count_arr.astype("int64"), index=fams, columns=[sp_col])
            raw_matrix_df.index.name   = "family"
            raw_matrix_df.columns.name = "species"
        except Exception:
            raw_matrix_df = None
        summary["raw_count_matrix_df"] = raw_matrix_df

        if not isinstance(getattr(self, "_orth_sp_catalog", None), dict):
            self._orth_sp_catalog = {}
        self._orth_sp_catalog[sp_col] = {
            "lineage":      _infer_lineage(sp_col),
            "display_name": sp_col.replace("_", " ").title(),
        }

        self._update_omics_data({
            "orthology_matrix_df": fam_matrix,
            "orthology_long_df":   long_df,
            "orthology_summary":   summary,
            "cross_specialized":   specialized,
            "cross_raw_matrix_df": raw_matrix_df,
            "cross_species_order": [sp_col],
            "cross_intronless_by_species": {},
        })

        n_fams = len(fams)
        n_ig   = int(count_arr.sum())
        self._append_log(
            f"⬢ CROSS SPECIES — loaded from SCAN  "
            f"({n_fams} IG families · {n_ig:,} genes · species: {sp_col}).", "ok")
        try:
            if hasattr(self, "_cross_banner"):
                self._cross_banner.configure(
                    text=(f"⬢  ACTIVE DATA  ·  species: {sp_col}  ·  "
                          f"{n_fams} IG families  ·  {n_ig:,} genes  "
                          f"·  (run MULTISPECIES to cross genomes)"),
                    fg=C["emerald"])
        except Exception:
            pass

        self._cs_refresh()

    def _cross_run_multispecies(self):
        """Launch the MULTISPECIES batch directly from the Cross Species tab.

        Reuses the proven _run_pipeline() flow: turns MULTISPECIES on, validates
        that a list is configured, and delegates the launch (same runner, same
        polling, and the same _build_cross_from_multispecies at the end). It does
        NOT duplicate the launch logic — so any future improvement to
        _run_pipeline is inherited here automatically.
        """
        # Do not relaunch if a pipeline is already running.
        if getattr(self, "_running", False):
            try:
                messagebox.showinfo(
                    "Cross Species",
                    "An analysis is already running. Wait for it to finish.")
            except Exception:
                pass
            return
        sp_list = list(getattr(self, "_multispecies_list", []) or [])
        if not sp_list:
            try:
                messagebox.showwarning(
                    "Cross Species",
                    "No species in the list. Configure them in "
                    "SCAN → CONFIGURE LIST before crossing genomes.")
            except Exception:
                pass
            return
        # Force MULTISPECIES ON so _run_pipeline takes the batch branch.
        try:
            if hasattr(self, "_var_multispecies"):
                self._var_multispecies.set(True)
        except Exception:
            pass
        try:
            self._append_log(
                f"⬢ CROSS SPECIES — launching multispecies batch "
                f"({len(sp_list)} genomes)…", "ok")
            if hasattr(self, "_cross_banner"):
                self._cross_banner.configure(
                    text=(f"⬢  CROSSING {len(sp_list)} genomes…  "
                          f"follow progress in MONITOR; results will "
                          f"appear here when finished."),
                    fg=C["amber"])
        except Exception:
            pass
        # Delegar al flujo de arranque ya probado (cambia a MONITOR, crea el
        # MultiSpeciesRunner, arranca el polling, etc.).
        self._run_pipeline()

