#  JUPYTER LAUNCHER
# ══════════════════════════════════════════════════════════════════════════════

_app_thread   = None
_app_instance = None

def launch():
    """
    Abre IGFinder 2.1.1 Futurista en ventana independiente desde Jupyter.

    Uso:
        %run IGFinder2_Beta.py
        launch()      # abre la ventana
        shutdown()    # cierra la ventana
    """
    global _app_thread, _app_instance
    if _app_thread is not None and _app_thread.is_alive():
        print("⚠  Window already open. Close it first or call shutdown().")
        return
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")
    def _run():
        global _app_instance
        try:
            try:
                import ctypes
                ctypes.windll.shcore.SetProcessDpiAwareness(1)
            except Exception:
                pass
            _app_instance = IGFinder2Beta()
            _app_instance.mainloop()
        except Exception as e:
            print(f"[IGFinder] Error al iniciar la ventana: {e}")
            import traceback; traceback.print_exc()
    _app_thread = threading.Thread(target=_run, daemon=True,
                                    name="IGFinder-2.0-Beta")
    _app_thread.start()
    print("▶  IGFinder 2.1.1 Futurista abierto en ventana separada.")
    print("   The Jupyter kernel is still available.")
    print("   Close the window when done, or call shutdown().")

def shutdown():
    """Cierra la ventana programáticamente."""
    global _app_instance
    if _app_instance is not None:
        try:
            _app_instance.destroy()
            print("✔  Ventana cerrada.")
        except Exception:
            print("ℹ  Window was already closed.")
        _app_instance = None
    else:
        print("ℹ  No hay ventana abierta.")


# ── Ejecución directa (no Jupyter) ───────────────────────────────────────────


