def _ext_section_header(parent, icon, title, subtitle, color):
    """
    Crea un encabezado de sección con franja de color, ícono, título y subtítulo.
    Igual al estilo del header de GO/KEGG existente.
    """
    sep = tk.Frame(parent, bg=_ca(color, "33"), height=2)
    sep.pack(fill="x", pady=(18, 0))

    hdr = tk.Frame(parent, bg=_ca(color, "0a"),
                   highlightthickness=1,
                   highlightbackground=_ca(color, "33"))
    hdr.pack(fill="x")

    # Franja vertical de acento
    tk.Frame(hdr, bg=color, width=4).pack(side="left", fill="y")

    inner = tk.Frame(hdr, bg=_ca(color, "0a"))
    inner.pack(side="left", fill="x", expand=True, padx=14, pady=10)

    tk.Label(inner, text=f"{icon}  {title}",
             bg=_ca(color, "0a"), fg=color,
             font=("Courier New", 11, "bold")).pack(anchor="w")
    tk.Label(inner, text=subtitle,
             bg=_ca(color, "0a"), fg=_ca(color, "88"),
             font=("Courier New", 8)).pack(anchor="w", pady=(2, 0))

    return hdr


def _ext_mini_card(parent, col, icon, title, attr_name, host_obj):
    """Tarjeta de métrica compacta (64 px alto)."""
    card = tk.Frame(parent, bg=_ca(col, "0d"),
                    highlightthickness=1,
                    highlightbackground=_ca(col, "2a"),
                    height=64)
    card.pack(side="left", expand=True, fill="x", padx=3)
    card.pack_propagate(False)

    inner = tk.Frame(card, bg=_ca(col, "0d"))
    inner.pack(fill="both", expand=True, padx=8, pady=5)

    top = tk.Frame(inner, bg=_ca(col, "0d"))
    top.pack(fill="x")
    tk.Label(top, text=icon,  bg=_ca(col, "0d"), fg=col,
             font=("Courier New", 10)).pack(side="left")
    tk.Label(top, text=title, bg=_ca(col, "0d"), fg=_ca(col, "99"),
             font=("Courier New", 7, "bold")).pack(side="left", padx=3)

    lbl = tk.Label(inner, text="—",
                   bg=_ca(col, "0d"), fg=col,
                   font=("Courier New", 14, "bold"))
    lbl.pack(anchor="w")
    if attr_name:
        setattr(host_obj, attr_name, lbl)
    return lbl


def _ext_action_btn(parent, label, col, cmd):
    """Botón de acción con hover, estilo igual al footer existente."""
    f = tk.Frame(parent, bg=_ca(col, "22"),
                 highlightthickness=1,
                 highlightbackground=_ca(col, "44"),
                 cursor="hand2")
    f.pack(side="left", padx=3, pady=4)
    lbl = tk.Label(f, text=f"  {label}  ",
                   bg=_ca(col, "22"), fg=col,
                   font=("Courier New", 8, "bold"))
    lbl.pack(pady=4, padx=2)
    for w in (f, lbl):
        w.bind("<Button-1>", lambda e, fn=cmd: fn())
        w.bind("<Enter>",  lambda e, ff=f, ll=lbl, c=col:
               (ff.configure(bg=_ca(c, "44")), ll.configure(bg=_ca(c, "44"))))
        w.bind("<Leave>",  lambda e, ff=f, ll=lbl, c=col:
               (ff.configure(bg=_ca(c, "22")), ll.configure(bg=_ca(c, "22"))))
    return f


def _omics_pick_df(data, res, key):
    """
    Selecciona un DataFrame desde `data` (preferente) o `res` (respaldo) sin
    usar el operador `or` sobre DataFrames — cuyo valor de verdad es ambiguo
    y lanzaría ValueError. Devuelve el primero no-vacío, o None.
    """
    d = (data or {}).get(key)
    if d is None or (hasattr(d, "empty") and d.empty):
        d = (res or {}).get(key)
    return d


