def _mpl_dark_fig(width=10, height=5):
    fig = plt.figure(figsize=(width, height), facecolor=_MPL_BG)
    fig.patch.set_facecolor(_MPL_BG)
    return fig


def _mpl_style_ax(ax):
    ax.set_facecolor(_MPL_PANEL)
    for spine in ax.spines.values():
        spine.set_color(_MPL_GRID)
        spine.set_linewidth(0.8)
    ax.tick_params(colors=_MPL_TXTS, labelsize=7.5, length=3, width=0.8)
    ax.xaxis.label.set_color(_MPL_TXT)
    ax.yaxis.label.set_color(_MPL_TXT)
    ax.title.set_color(_MPL_TXT)
    ax.grid(color=_MPL_GRID, linewidth=0.5, alpha=0.7, zorder=0)


