def _infer_lineage(species_id: str) -> str:
    """
    Devuelve el clado inferido para una especie Ensembl, incluso si no aparece
    en _MULTISPECIES_LINEAGE. Cae a "other" sólo cuando no se reconoce nada.

    Estrategia:
      1) lookup exacto en _MULTISPECIES_LINEAGE
      2) prefix match contra _LINEAGE_PREFIX_HINTS
      3) "other"
    """
    if not species_id:
        return "other"
    sp = str(species_id).lower().strip().replace(" ", "_")
    hit = _MULTISPECIES_LINEAGE.get(sp)
    if hit:
        return hit
    for pref, lin in _LINEAGE_PREFIX_HINTS:
        if sp.startswith(pref):
            return lin
    return "other"

# Detector de familia IG a partir del nombre del gen (mismo criterio que
# _omics_math.build_family_conservation).
_CROSS_FAM_RE = _re.compile(
    r"^(IGH[VDJACE]|IGL[VJCE]|IGK[VJC]|IG[HJKL][A-Z]?)", _re.IGNORECASE)

# Orden de categorías por BIOTIPO de Ensembl para presentación de genes
# intronless. Los biotipos más comunes primero; el resto se ordena alfabético.
_CROSS_FAM_ORDER = ["protein_coding", "lncRNA", "processed_pseudogene",
                    "unprocessed_pseudogene", "transcribed_pseudogene",
                    "miRNA", "snRNA", "snoRNA", "misc_RNA", "rRNA",
                    "TEC", "OTHER"]

# Normalización de biotipos de Ensembl a etiquetas compactas para el eje.
_BIOTYPE_ALIASES = {
    "protein_coding": "protein_coding",
    "lncRNA": "lncRNA",
    "lincRNA": "lncRNA",
    "processed_pseudogene": "processed_pseudogene",
    "unprocessed_pseudogene": "unprocessed_pseudogene",
    "transcribed_processed_pseudogene": "transcribed_pseudogene",
    "transcribed_unprocessed_pseudogene": "transcribed_pseudogene",
    "transcribed_unitary_pseudogene": "transcribed_pseudogene",
    "unitary_pseudogene": "unprocessed_pseudogene",
    "miRNA": "miRNA",
    "snRNA": "snRNA",
    "snoRNA": "snoRNA",
    "misc_RNA": "misc_RNA",
    "rRNA": "rRNA",
    "Mt_rRNA": "rRNA",
    "Mt_tRNA": "misc_RNA",
    "TEC": "TEC",
}


def _normalize_biotype(bt: str) -> str:
    """Mapea un gene_biotype de Ensembl a una etiqueta compacta de categoría."""
    if not bt:
        return "OTHER"
    bt = str(bt).strip()
    return _BIOTYPE_ALIASES.get(bt, bt if bt else "OTHER")


def _cross_family_counts(ig_df):
    """Cuenta genes intronless por CATEGORÍA (gene_biotype de Ensembl).

    Para genes intronless, la agrupación biológicamente relevante es el biotipo
    de Ensembl (protein_coding, lncRNA, pseudogenes, RNAs pequeños, etc.), no la
    familia de inmunoglobulina. Esta función agrupa por gene_biotype cuando está
    disponible. Si no hay columna de biotipo, intenta el prefijo del símbolo del
    gen como aproximación de familia génica; en último caso, todo a OTHER.
    """
    if ig_df is None or getattr(ig_df, "empty", True):
        return {}

    # Preferencia 1: gene_biotype (categoría funcional real de Ensembl)
    bt_col = next((c for c in ("gene_biotype", "biotype", "gene_type")
                   if c in ig_df.columns), None)
    if bt_col is not None:
        counts = {}
        for bt in ig_df[bt_col].astype(str):
            cat = _normalize_biotype(bt)
            counts[cat] = counts.get(cat, 0) + 1
        return counts

    # Preferencia 2: prefijo del símbolo del gen (familia génica aproximada).
    # Ej.: OR11H1, OR4F5 → "OR" (receptores olfativos);  HOXA1 → "HOX".
    name_col = next((c for c in ("gene_name", "Gene_Name", "symbol", "name",
                                 "display_name", "source_gene_name")
                     if c in ig_df.columns), None)
    if name_col is None:
        return {"OTHER": int(len(ig_df))}

    counts = {}
    for gname in ig_df[name_col].astype(str):
        fam = _gene_symbol_family(gname.strip())
        counts[fam] = counts.get(fam, 0) + 1
    return counts


def _gene_symbol_family(symbol: str) -> str:
    """Deriva una 'familia génica' aproximada del prefijo de un símbolo.

    Heurística: toma la parte alfabética inicial del símbolo (antes de los
    dígitos). OR11H1 → OR, HOXA1 → HOXA, TP53 → TP. Símbolos sin patrón → OTHER.
    Nota: es una aproximación; la agrupación por gene_biotype es preferible.
    """
    if not symbol or symbol.lower() in ("nan", "none", ""):
        return "OTHER"
    m = _re.match(r"^([A-Za-z]{2,})", symbol)
    if not m:
        return "OTHER"
    prefix = m.group(1).upper()
    # Limitar longitud para que prefijos largos no fragmenten en exceso.
    return prefix[:4]


def _gene_id_category_map(ig_df) -> dict:
    """Mapa {gene_id: categoría} usando la MISMA lógica que _cross_family_counts.

    Se usa para derivar per_sp_counts en la ruta de ortología (matriz gene ×
    especie), de modo que las categorías coincidan exactamente con las de la
    ruta multispecies: biotipo de Ensembl si está disponible, si no el prefijo
    del símbolo del gen, y en último caso OTHER. Devuelve {} si no hay columna
    de id reconocible (entonces el llamador cae a OTHER para todo).
    """
    if ig_df is None or getattr(ig_df, "empty", True):
        return {}
    id_col = next((c for c in ("gene_id", "Gene_ID", "source_gene_id", "id")
                   if c in ig_df.columns), None)
    if id_col is None:
        return {}
    bt_col = next((c for c in ("gene_biotype", "biotype", "gene_type")
                   if c in ig_df.columns), None)
    name_col = next((c for c in ("gene_name", "Gene_Name", "symbol", "name",
                                 "display_name", "source_gene_name")
                     if c in ig_df.columns), None)
    out = {}
    if bt_col is not None:
        for gid, bt in zip(ig_df[id_col].astype(str), ig_df[bt_col].astype(str)):
            out[gid] = _normalize_biotype(bt)
    elif name_col is not None:
        for gid, gname in zip(ig_df[id_col].astype(str),
                              ig_df[name_col].astype(str)):
            out[gid] = _gene_symbol_family(gname.strip())
    else:
        for gid in ig_df[id_col].astype(str):
            out[gid] = "OTHER"
    return out


# ── Etiquetas de segmento IG para análisis especializado ────────────────────
# Mapea cada familia IG al "tipo" funcional (V/D/J/C) y a la cadena (H/K/L).
# Se usa para descomponer el repertorio por especie en V/D/J/C y H/L.
_IG_FAMILY_TYPE = {
    "IGHV": ("H", "V"), "IGHD": ("H", "D"), "IGHJ": ("H", "J"),
    "IGHM": ("H", "C"), "IGHG": ("H", "C"), "IGHA": ("H", "C"),
    "IGHE": ("H", "C"),
    "IGKV": ("K", "V"), "IGKJ": ("K", "J"), "IGKC": ("K", "C"),
    "IGLV": ("L", "V"), "IGLJ": ("L", "J"), "IGLC": ("L", "C"),
    "IGLE": ("L", "C"),
}


def _cross_specialized_metrics(per_sp_counts, species):
    """
    Calcula métricas IG-especializadas a partir del diccionario
    {species: {family: n}}. Devuelve un dict con:

      per_species : dict[sp, dict] — métricas individuales
          n_total, n_v, n_d, n_j, n_c,
          n_heavy, n_kappa, n_lambda,
          heavy_light_ratio,         # IGH / (IGK + IGL); inf si denom=0
          kappa_lambda_ratio,        # IGK / IGL; inf si denom=0
          v_gene_count,              # IGHV + IGKV + IGLV
          c_isotypes,                # set de constantes presentes
          n_c_isotypes,              # cardinalidad
          shannon_entropy,           # Shannon (base 2) sobre familias
          richness,                  # nº familias con ≥1 gen
          repertoire_class           # etiqueta cualitativa
      core_families  : list[fam] — presentes en ≥ core_threshold de especies
      lineage_specific : list[(fam, lineages)] — presentes en 1–2 clados
      jaccard : pd.DataFrame N×N — similitud Jaccard del set de familias
      family_prevalence : dict[fam, fraction] — fracción de especies con la fam
    """
    logging.debug("[CrossSpec] calculando métricas para %d especies", len(list(species)))
    sps = list(species)
    if not sps:
        return {}

    # ── Per-species básico ─────────────────────────────────────────────────
    per_sp = {}
    for sp in sps:
        counts = dict(per_sp_counts.get(sp, {}) or {})
        n_total = int(sum(counts.values()))

        n_v = n_d = n_j = n_c = 0
        n_h = n_k = n_l = 0
        c_isotypes = set()
        for fam, n in counts.items():
            if fam == "OTHER":
                continue
            tag = _IG_FAMILY_TYPE.get(fam)
            if not tag:
                continue
            chain, seg = tag
            if   seg == "V": n_v += n
            elif seg == "D": n_d += n
            elif seg == "J": n_j += n
            elif seg == "C":
                n_c += n
                if n > 0:
                    c_isotypes.add(fam)
            if   chain == "H": n_h += n
            elif chain == "K": n_k += n
            elif chain == "L": n_l += n

        # Ratios — usar +inf con guardas explícitas
        denom_hl = n_k + n_l
        heavy_light_ratio = (n_h / denom_hl) if denom_hl > 0 else float("inf") if n_h > 0 else 0.0
        kappa_lambda_ratio = (n_k / n_l) if n_l > 0 else float("inf") if n_k > 0 else 0.0

        # Shannon (base 2) sobre familias con ≥1 gen
        vals = np.asarray([v for v in counts.values() if v > 0], dtype="float64")
        if vals.size > 0 and vals.sum() > 0:
            p = vals / vals.sum()
            shannon = float(-(p * np.log2(p)).sum())
        else:
            shannon = 0.0

        richness = int(sum(1 for v in counts.values() if v > 0))

        # Clasificación cualitativa de la composición por categoría.
        # Agnóstica al tipo de gen: describe la categoría dominante y la
        # diversidad, en vez de términos de inmunoglobulina (κ/λ).
        cls_tags = []
        if n_total == 0:
            cls_tags.append("sin-genes")
        else:
            # Categoría dominante (mayor conteo, excluyendo OTHER)
            non_other = {f: n for f, n in counts.items()
                         if f != "OTHER" and n > 0}
            if non_other:
                top_fam = max(non_other, key=non_other.get)
                top_frac = non_other[top_fam] / n_total
                if top_frac >= 0.8:
                    cls_tags.append(f"{top_fam}-dominante")
                elif top_frac >= 0.5:
                    cls_tags.append(f"{top_fam}-mayoritario")
                else:
                    cls_tags.append("mixto")
            # Diversidad de categorías
            if richness >= 6:
                cls_tags.append("alta-diversidad")
            elif richness == 1:
                cls_tags.append("monocategoría")
        repertoire_class = " · ".join(cls_tags) if cls_tags else "n/a"

        per_sp[sp] = dict(
            n_total=n_total, n_v=n_v, n_d=n_d, n_j=n_j, n_c=n_c,
            n_heavy=n_h, n_kappa=n_k, n_lambda=n_l,
            heavy_light_ratio=heavy_light_ratio,
            kappa_lambda_ratio=kappa_lambda_ratio,
            v_gene_count=n_v,
            c_isotypes=sorted(c_isotypes),
            n_c_isotypes=len(c_isotypes),
            shannon_entropy=shannon,
            richness=richness,
            repertoire_class=repertoire_class,
        )

    # ── Familias cross-species: prevalencia, core, lineage-specific ────────
    fam_universe = set()
    for sp in sps:
        for fam, n in (per_sp_counts.get(sp, {}) or {}).items():
            if n > 0 and fam != "OTHER":
                fam_universe.add(fam)

    fam_prev = {}
    fam_to_species = {}  # fam → set de especies con esa familia
    for fam in fam_universe:
        sp_with = {sp for sp in sps
                   if (per_sp_counts.get(sp, {}) or {}).get(fam, 0) > 0}
        fam_to_species[fam] = sp_with
        fam_prev[fam] = (len(sp_with) / len(sps)) if sps else 0.0

    # Core: presente en ≥80% de las especies (umbral configurable)
    core_threshold = 0.80
    core = sorted([f for f, p in fam_prev.items() if p >= core_threshold])

    # Lineage-specific: la familia aparece sólo en 1–2 clados distintos
    fam_to_lineages = {}
    for fam, sp_with in fam_to_species.items():
        lins = {_infer_lineage(sp) for sp in sp_with}
        fam_to_lineages[fam] = lins
    lineage_specific = sorted(
        [(f, sorted(l)) for f, l in fam_to_lineages.items() if 1 <= len(l) <= 2],
        key=lambda x: (len(x[1]), x[0]))

    # ── Jaccard similarity inter-especies (set de familias presentes) ───────
    sp_fam_set = {
        sp: {fam for fam, n in (per_sp_counts.get(sp, {}) or {}).items()
             if n > 0 and fam != "OTHER"}
        for sp in sps
    }
    N = len(sps)
    jac = np.zeros((N, N), dtype="float32")
    for i in range(N):
        si = sp_fam_set[sps[i]]
        for j in range(i, N):
            sj = sp_fam_set[sps[j]]
            uni = si | sj
            inter = si & sj
            v = (len(inter) / len(uni)) if uni else 0.0
            jac[i, j] = v
            jac[j, i] = v
    try:
        jac_df = pd.DataFrame(jac, index=sps, columns=sps)
        jac_df.index.name   = "species_a"
        jac_df.columns.name = "species_b"
    except Exception:
        jac_df = None

    # ── Distancia de Jaccard (1 − similitud) y PCoA 2D ──────────────────────
    # PCoA / classical MDS sobre la matriz de distancias: proyecta cada especie
    # en un plano 2D donde la distancia visual aproxima la distancia Jaccard.
    # Útil para ver clusters por clado de un vistazo, sin reducir a árbol.
    jdist = 1.0 - jac
    pcoa_coords = None
    pcoa_var = (0.0, 0.0)
    try:
        if N >= 3:
            D2 = (jdist ** 2).astype("float64")
            # Doble centrado:  B = -½ · J · D² · J , con J = I − 1/n · 11ᵀ
            J = np.eye(N) - np.ones((N, N)) / N
            B = -0.5 * (J @ D2 @ J)
            # Simétrica → eigh es exacta y rápida
            evals, evecs = np.linalg.eigh(B)
            # Orden descendente
            idx = np.argsort(evals)[::-1]
            evals = evals[idx]; evecs = evecs[:, idx]
            # Coords PCoA = evec * sqrt(evals positivos)
            pos_evals = np.clip(evals[:2], 0.0, None)
            coords = evecs[:, :2] * np.sqrt(pos_evals)
            pcoa_coords = pd.DataFrame(
                coords, index=sps, columns=["PCo1", "PCo2"])
            # Varianza explicada (sólo eigenvalues positivos suman al total)
            tot = float(np.clip(evals, 0.0, None).sum()) or 1.0
            pcoa_var = (float(pos_evals[0]) / tot,
                        float(pos_evals[1]) / tot if pos_evals.size > 1 else 0.0)
    except Exception as _exc_p:
        logging.warning("[CROSS] PCoA: %s", _exc_p)

    # ── Linkage UPGMA para dendrograma (≥3 especies, scipy disponible) ──────
    upgma_linkage = None
    try:
        if N >= 3:
            from scipy.cluster.hierarchy import linkage as _linkage
            from scipy.spatial.distance import squareform as _squareform
            # Forma condensada (vector upper-triangular) requerida por linkage
            cond = _squareform(jdist, checks=False)
            upgma_linkage = _linkage(cond, method="average")
    except Exception as _exc_d:
        logging.warning("[CROSS] UPGMA linkage: %s", _exc_d)

    # ── Subconjunto Constant-Region (isotipos): IGHM/IGHD/IGHG/IGHA/IGHE +
    #     IGKC/IGLC — la diversidad de regiones constantes es lo que define
    #     las clases funcionales de Ig (IgM, IgD, IgG, IgA, IgE, ...).
    isotype_fams = ["IGHM", "IGHD", "IGHG", "IGHA", "IGHE", "IGKC", "IGLC"]
    iso_arr = np.zeros((len(isotype_fams), N), dtype="float64")
    for i, fam in enumerate(isotype_fams):
        for j, sp in enumerate(sps):
            iso_arr[i, j] = float((per_sp_counts.get(sp, {}) or {}).get(fam, 0))
    try:
        isotype_df = pd.DataFrame(iso_arr, index=isotype_fams, columns=sps)
        isotype_df.index.name   = "isotype"
        isotype_df.columns.name = "species"
    except Exception:
        isotype_df = None

    # ── Per-clade summary: core / innovación por clado ──────────────────────
    # Agrupa especies por linaje y calcula, por clado:
    #   • core_in_clade  → familias presentes en ≥80% de las especies del clado
    #   • innovations    → familias presentes SÓLO en este clado (en ningún otro)
    #   • n_species      → tamaño del clado en la lista
    sp_by_clade = {}
    for sp in sps:
        lin = _infer_lineage(sp)
        sp_by_clade.setdefault(lin, []).append(sp)

    clade_summary = {}
    for clade, members in sp_by_clade.items():
        # Core dentro del clado
        clade_core = []
        for fam in fam_universe:
            n_present = sum(
                1 for sp in members
                if (per_sp_counts.get(sp, {}) or {}).get(fam, 0) > 0)
            if members and (n_present / len(members)) >= core_threshold:
                clade_core.append(fam)
        # Innovaciones: familias que aparecen sólo en este clado
        other_sps = [sp for sp in sps if sp not in members]
        innovations = []
        for fam in fam_universe:
            in_this = any(
                (per_sp_counts.get(sp, {}) or {}).get(fam, 0) > 0
                for sp in members)
            in_other = any(
                (per_sp_counts.get(sp, {}) or {}).get(fam, 0) > 0
                for sp in other_sps)
            if in_this and not in_other:
                innovations.append(fam)
        clade_summary[clade] = dict(
            n_species=len(members),
            members=list(members),
            core_in_clade=sorted(clade_core),
            innovations=sorted(innovations),
        )

    # ── Resumen global: pares más similares y más divergentes ───────────────
    top_similar = []
    top_distant = []
    try:
        if N >= 2:
            triu_idx = np.triu_indices(N, k=1)
            vals = jac[triu_idx]
            order_sim = np.argsort(vals)[::-1]      # más similares primero
            order_dis = np.argsort(vals)            # más distantes primero
            for k in order_sim[:5]:
                i_, j_ = triu_idx[0][k], triu_idx[1][k]
                top_similar.append((sps[i_], sps[j_], float(vals[k])))
            for k in order_dis[:5]:
                i_, j_ = triu_idx[0][k], triu_idx[1][k]
                top_distant.append((sps[i_], sps[j_], float(vals[k])))
    except Exception:
        pass

    return dict(
        per_species=per_sp,
        core_families=core,
        core_threshold=core_threshold,
        lineage_specific=lineage_specific,
        jaccard=jac_df,
        jaccard_distance=jdist,         # array N×N
        species_order=list(sps),
        family_prevalence=fam_prev,
        family_to_species=fam_to_species,
        family_to_lineages={f: sorted(l) for f, l in fam_to_lineages.items()},
        # NUEVO: extensiones para visualizaciones avanzadas
        pcoa_coords=pcoa_coords,
        pcoa_variance=pcoa_var,
        upgma_linkage=upgma_linkage,
        isotype_df=isotype_df,
        clade_summary=clade_summary,
        sp_by_clade=sp_by_clade,
        top_similar_pairs=top_similar,
        top_distant_pairs=top_distant,
    )



if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")
    app = IGFinder2Beta()
    app.mainloop()


